    // The engine's own test (KismetSystemLibrary IsValid: not null, not marked as garbage). UE4SS's
    // IsPendingKill does not see a destroyed actor in this game (test 2026-11-20 08:36: removed
    // corpses stayed "alive").
    bool object_alive(UObject* p)
    {
        if (!p) return false;
        Unreal::FUObjectItem* item = Unreal::FUObjectArray::IndexToObject(p->GetInternalIndex());
        if (!item || item->GetUObject() != p || item->IsUnreachable()) return false;
        static UObject* ksl = UObjectGlobals::StaticFindObject<UObject*>(nullptr, nullptr, STR("/Script/Engine.Default__KismetSystemLibrary"));
        if (!ksl) return true;
        Call v(ksl, STR("IsValid"));
        if (!v.fn) return true;
        v.object(STR("Object"), p);
        v.run();
        FProperty* r = v.param(STR("ReturnValue"));
        return !r || *(v.buffer.data() + r->GetOffset_Internal()) != 0;
    }

    hsvr::Vec3 component_location(UObject* component)
    {
        Call c(component, STR("K2_GetComponentLocation"));
        c.run();
        return c.vec();
    }

    void set_component_transform(UObject* component, const hsvr::Vec3& location, const hsvr::Quat& rotation, bool teleport = true)
    {
        Call c(component, STR("K2_SetWorldLocationAndRotation"));
        hsvr::Rot r = hsvr::quat_to_rot(rotation);
        c.three(STR("NewLocation"), location.x, location.y, location.z);
        c.three(STR("NewRotation"), r.pitch, r.yaw, r.roll);
        c.flag(STR("bSweep"), false);
        c.flag(STR("bTeleport"), teleport);
        c.run();
    }

    double component_scale_z(UObject* component)
    {
        Call c(component, STR("K2_GetComponentScale"));
        c.run();
        double z = c.vec().z;
        return z > 0.01 ? z : 1.0;
    }

    // The end-of-graph Modify Bone node of each bone (the game leaves them at Ignore, component space).
    std::map<std::wstring, ModifyBoneNode> final_chain_nodes(UObject* instance)
    {
        std::map<std::wstring, ModifyBoneNode> chain;
        std::vector<ModifyBoneNode> nodes = find_modify_bone_nodes(instance);
        for (size_t i = 0; i < nodes.size(); ++i)
        {
            ModifyBoneNode& n = nodes[i];
            if (!n.rotation || !n.rotation_mode || !n.rotation_space) continue;
            if (*(n.node + n.rotation_mode->GetOffset_Internal()) != 0 || *(n.node + n.rotation_space->GetOffset_Internal()) != 1) continue;
            std::wstring key = n.bone;
            for (auto& ch : key) ch = (wchar_t)towlower(ch);
            chain[key] = n; // the last one found wins
            HSVR_LOG("Pose: bone %ls -> node %d", n.bone.c_str(), (int)i);
        }
        return chain;
    }

    void node_set_rotation(ModifyBoneNode& n, const hsvr::Quat& component_space)
    {
        hsvr::Rot r = hsvr::quat_to_rot(component_space);
        *(n.node + n.rotation_space->GetOffset_Internal()) = 1; // component space
        write_three(n.node + n.rotation->GetOffset_Internal(), n.rotation, r.pitch, r.yaw, r.roll);
        *(n.node + n.rotation_mode->GetOffset_Internal()) = 1; // replace
    }

    // Adds a turn on top of whatever the game's animation gives the bone (component space), so his
    // own breathing, leaning and crouch bend stay underneath.
    void node_add_rotation(ModifyBoneNode& n, const hsvr::Quat& component_space)
    {
        hsvr::Rot r = hsvr::quat_to_rot(component_space);
        *(n.node + n.rotation_space->GetOffset_Internal()) = 1; // component space
        write_three(n.node + n.rotation->GetOffset_Internal(), n.rotation, r.pitch, r.yaw, r.roll);
        *(n.node + n.rotation_mode->GetOffset_Internal()) = 2; // additive
    }

    void node_release(ModifyBoneNode& n)
    {
        *(n.node + n.rotation_mode->GetOffset_Internal()) = 0;
    }

    // Puts the bone at this spot (component space), replacing the animation's.
    bool node_set_translation(ModifyBoneNode& n, const hsvr::Vec3& component_space)
    {
        if (!n.translation || !n.translation_mode || !n.translation_space) return false;
        *(n.node + n.translation_space->GetOffset_Internal()) = 1; // component space
        if (!write_three(n.node + n.translation->GetOffset_Internal(), n.translation, component_space.x, component_space.y, component_space.z)) return false;
        *(n.node + n.translation_mode->GetOffset_Internal()) = 1; // replace
        return true;
    }

    void node_release_translation(ModifyBoneNode& n)
    {
        if (n.translation_mode) *(n.node + n.translation_mode->GetOffset_Internal()) = 0;
    }

    struct ArmCalibration
    {
        bool valid = false;
        double upper_length = 0, lower_length = 0;
        hsvr::Vec3 upper_dir_local, upper_normal_local; // in the upperarm bone's frame
        hsvr::Vec3 lower_dir_local, lower_normal_local; // in the lowerarm bone's frame
        hsvr::Vec3 fingers_local, thumb_local;           // in the hand bone's frame: toward the fingers, toward the thumb side
        hsvr::Quat clavicle_in_chest;  // clavicle rotation in spine_05's frame, as the animation has it at calibration
        hsvr::Vec3 shoulder_in_clavicle; // the upperarm joint in the clavicle's frame
        bool clavicle_valid = false;
        double twist_deg = 0, bend_deg = 0;              // last frame, for the log
    };

    struct PoseState
    {
        UObject* pawn = nullptr;
        UObject* mesh = nullptr;
        UObject* driver = nullptr;
        UObject* instance = nullptr;
        std::map<std::wstring, ModifyBoneNode> chain;
        bool calibrated = false;
        hsvr::Vec3 mesh_offset_local; // visible mesh relative to the actor, in the actor's heading frame
        hsvr::Quat mesh_rotation_local;
        hsvr::Quat head_offset;       // body frame -> head bone
        bool calib_snap = false;      // calibrated against a facing other than the control yaw: the first placement teleports
        ArmCalibration arm[2];
        double last_check = 0.0;
        hsvr::Vec3 target[2]; // last hand targets (where the hand bone goes, from the controller)
        hsvr::Quat hand_rot[2]; // and the hand bone's world rotation there
        double ctl_frame_yaw[2] = {0.0, 0.0}; // yaw of the frame your controller is tracked in (play space; the actor's heading for test hands)
        hsvr::Vec3 raw_target[2]; // the same before scaling your reach to his (for measuring your arm)
        hsvr::Vec3 reach_target[2]; // scaled to his reach but not yet clamped to it (where you mean his hand to be)
        bool hand_valid[2] = {false, false};
        hsvr::Vec3 swivel_local[2]; // smoothed elbow direction, in the body's frame
        bool swivel_valid[2] = {false, false};
        double twist_deg = 0.0; // how far the spine and neck together turned this frame, for the log
        // Feet (see "Feet that stand and step" below).
        hsvr::Vec3 foot_home_local[2];   // where each foot stands relative to the actor, in the body's frame
        hsvr::Quat foot_rot_local[2];    // body frame -> foot bone, standing
        double ankle_height[2] = {10.0, 10.0}; // foot bone above the floor, standing
        bool ankle_measured[2] = {false, false};
        double calibrated_at = 0.0;
        hsvr::Quat chest_rot_local, pelvis_rot_local; // body frame -> spine_05 / pelvis at calibration, for the twist log
        bool feet_calibrated = false;
        double swivel_time[2] = {0.0, 0.0};
    };
    PoseState g_pose;

    // ---- Torso lean (see pose_lean in config.hpp) -----------------------------------------------
    // The bones it bends, parent first; the last one (head) is only measured, never bent here.
    const char* const kLeanBones[7] = {"spine_02", "spine_03", "spine_04", "spine_05", "neck_01", "neck_02", "head"};
    const double kTwistWeight[6] = {0.10, 0.12, 0.14, 0.16, 0.22, 0.26};
    struct LeanState
    {
        bool calibrated = false;
        hsvr::Vec3 pts[7];       // the bones standing, relative to the actor, in the body's frame (at calibration)
        double fwd = 0.0, side = 0.0;     // degrees bent now (smoothed and held to what the head height allows)
        double want_fwd = 0.0, want_side = 0.0; // from the head alone
        double twist = 0.0;      // torso twist total (degrees), shared with pose_torso_twist
        hsvr::Quat q[6];         // each bone's turn this frame, in the body's frame (twist and bend)
        hsvr::Vec3 head_moved;   // how far the bend and twist carry the head, in the body's frame
        double pitch = 0.0, roll = 0.0; // your head's pitch down and roll right (degrees)
        double t = 0.0;
        double held = 1.0;       // share of the wanted bend allowed by the head height
        double reach_fwd = 0.0;  // forward bend forced by a crouch deeper than his legs go (pose_crouch_bend_for_depth)
        double depth_free = 0.0; // of the forward bend, degrees whose neck counter-bend is dropped (pose_crouch_bend_neck_follow), smoothed
        hsvr::Vec3 offset;       // your neck away from where his hips stand (body frame, cm; pose_lean_step_radius_cm)
        hsvr::Vec3 aim;          // where his head is leaned to: offset, less the chest-back of looking down
        double look_back = 0.0;  // that chest-back now (cm; pose_lean_look_down_back_cm)
        double off_fwd = 0.0, off_side = 0.0; // the bend that offset asks for (degrees)
    };
    LeanState g_lean;
    // Test: hsvr.fake_head_tilt <pitch down> <roll right> <drop cm> nods the TRACKED headset about the
    // base of the neck (12 cm below the head bone) and lowers it, for the pose only (not the view).
    std::atomic<double> g_fake_tilt_pitch{0.0}, g_fake_tilt_roll{0.0}, g_fake_tilt_drop{0.0};
    // Test: hsvr.fake_head_pose 1 = with no tracked headset (dev_fake_headset), a still head at the view's
    // anchor (where your eyes were at recentring), looking straight ahead; the tilt above applies to it.
    std::atomic<bool> g_fake_head_pose{false};
    // Test: hsvr.fake_head_wobble <deg> <hz> nods the head (tracked or fake) up and down by that much,
    // live from the clock, so the pose and the view's late copy see different head poses (as a moving
    // real head does a frame apart).
    std::atomic<double> g_fake_wobble_deg{0.0}, g_fake_wobble_hz{1.0};
    // Test: hsvr.fake_head_shift <forward cm> <right cm> moves the head (tracked or fake) that far, as a lean.
    std::atomic<double> g_fake_shift_fwd{0.0}, g_fake_shift_right{0.0};

    // The bend and twist of the 6 bones, and where they carry the head (body frame). Each bone turns
    // about its own joint and carries everything above it, as the end-of-graph Modify Bone nodes do
    // in component space (Additive).
    hsvr::Vec3 lean_fk(double fwd_deg, double side_deg, double twist_deg, hsvr::Quat out[6], double depth_free = -1.0)
    {
        using namespace hsvr;
        Vec3 p[7];
        for (int i = 0; i < 7; ++i) p[i] = g_lean.pts[i];
        const Vec3 up{0, 0, 1}, right{0, 1, 0}, fwd{1, 0, 0};
        // A bend for depth (reaching down past his legs' crouch) takes the head down with it: that part of
        // the bend has no neck counter-bend (playtest 2026-11-23 17:05 local: bent 85 deg, his neck bent
        // back 64 and kept his head 17 cm above your kneeling view, hands 20-30 cm off the floor).
        if (depth_free < 0.0) depth_free = g_lean.depth_free;
        double neck_fwd = fwd_deg - (std::max)(0.0, (std::min)(fwd_deg, depth_free));
        for (int i = 0; i < 6; ++i)
        {
            // Half Sword's Bend_F: spine_02..05 +20 deg each, neck_01 and neck_02 -30 each (of 80);
            // Bend_L/R: spine 22.5 each, neck -30 each (of 90). Forward is a turn about right; a lean to
            // the right is a turn about forward by minus the angle.
            double f = i < 4 ? fwd_deg / 4.0 : -neck_fwd * 0.375;
            double sd = i < 4 ? side_deg / 4.0 : -side_deg / 3.0;
            Quat bend = (quat_axis_angle(right, f * kDegToRad) * quat_axis_angle(fwd, -sd * kDegToRad)).normalized();
            Quat q = (quat_axis_angle(up, twist_deg * kTwistWeight[i] * kDegToRad) * bend).normalized();
            out[i] = q;
            for (int j = i + 1; j < 7; ++j) p[j] = p[i] + q.rotate(p[j] - p[i]);
        }
        return p[6] - g_lean.pts[6];
    }

    UObject* live_posed_pawn()
    {
        UObject* posed = g_pose.pawn;
        if (!posed) return nullptr;
        UObject* pawn = nullptr;
        find_pawn_mesh(&pawn);
        return pawn == posed ? pawn : nullptr;
    }
    std::atomic<bool> g_hold_capsule{false}; // see "The capsule stays where you are" below
    // Posed and calibrated this frame (crouch and body turning run around his tick).
    std::atomic<bool> g_pose_active{false};
    // Until when (now_seconds) the pose checks physics every tick after a strength gain (muscle_gain_post).
    double g_physics_watch_until = -1.0;
    bool g_body_turning = false;
    // Crouch: how far your headset is below where you stood at recentering (cm, 0 standing).
    std::atomic<int> g_count_steps{0}; // foot steps since hsvr.mark (hsvr.expect steps)
    double g_crouch_drop = 0.0;
    double g_crouch_want_cm = 0.0; // your view's drop below standing (real crouch plus the button), before the leg cap (pose_crouch_anim's head height)
    // Button crouch (B&S: the stick crouches as well as bending down): left stick click toggles it; the
    // view and his body go down together by this much (cm, eased), on top of your own crouch.
    // (g_button_crouch is defined near the top: provide_anchor uses it)
    bool g_button_crouch_on = false;
    std::atomic<double> g_fake_head_drop{-1.0}; // test: hsvr.fake_head_drop <cm> (fake tracking only)
    // test: hsvr.fake_head_speed <cm/s>: how fast the fake head goes to that depth, as a person crouches (0 = at once). Run 8
    // bd711d2: dropped 95 cm in one frame, his legs swept a lantern lying at his feet 1-3 m away.
    std::atomic<double> g_fake_head_speed{150.0};
    bool g_pose_cfg_turn = true, g_pose_cfg_crouch = true, g_pose_fake = false;
    double g_turn_dead_deg = 60.0, g_turn_speed_dps = 150.0, g_turn_max_deg = 85.0;

    const char* side_suffix(int side) { return side == 0 ? "_l" : "_r"; }

    ModifyBoneNode* chain_node(const std::string& bone)
    {
        std::wstring key(bone.begin(), bone.end());
        auto it = g_pose.chain.find(key);
        return it == g_pose.chain.end() ? nullptr : &it->second;
    }

    void feet_reset();
    bool ground_below(UObject* pawn, double x, double y, double from_z, double& ground_z);
    double number_property(UObject* owner, FProperty* p);

    hsvr::Vec3 g_wall_ok;          // where his capsule last stood legally (pose_body_wall_stop)
    bool g_wall_ok_have = false;
    UObject* g_ground_ignore = nullptr; // ground_below also looks through this actor (room_lay: the item being laid)
    UObject* g_wall_pawn = nullptr; // whose (a respawn starts over)
    double g_kept_z = 0.0;          // his capsule's height as capsule_hold last kept it
    bool g_kept_have = false;
    void pose_release()
    {
        for (auto& [bone, n] : g_pose.chain) node_release(n);
        if (g_pose.mesh && g_pose.calibrated)
        {
            set_simulate(g_pose.mesh, true, true);
            HSVR_LOG("Pose: off, physics back on for your character (restart the fight to be sure)");
        }
        g_pose = PoseState{};
        g_pose_anchor_fixed = false;
        g_pose_room_moved_local = {};
        g_wall_ok_have = false;
        g_kept_have = false;
        feet_reset();
    }

    double actor_heading(UObject* pawn)
    {
        if (UObject* controller = find_player_controller())
            if (ue::FRotator* rotation = value_ptr<ue::FRotator>(controller, STR("ControlRotation"))) return rotation->Yaw;
        Call c(pawn, STR("K2_GetActorRotation"));
        c.run();
        return c.vec().y;
    }

    hsvr::Vec3 actor_location(UObject* pawn)
    {
        Call c(pawn, STR("K2_GetActorLocation"));
        c.run();
        return c.vec();
    }

    bool bone_exists(UObject* mesh, const std::string& bone)
    {
        Call c(mesh, STR("GetBoneIndex"));
        c.name(STR("BoneName"), bone_fname(bone));
        return c.run() && c.integer() >= 0;
    }

    void apply_arm_physics(const hsvr::Config&)
    {
        set_simulate(g_pose.mesh, false);
    }

    bool pose_calibrate(const hsvr::Config& cfg)
    {
        using namespace hsvr;
        UObject* d = g_pose.driver;
        double heading = actor_heading(g_pose.pawn);
        // The body needn't face the control yaw yet (restart 2026-11-22 10:04Z: mesh 90, control 77, and every
        // frame stored below was 13 deg off for that life). The mesh component's forward is its +Y; unlike
        // the bones it carries no animation twist, and it equals the control yaw to 0.00 deg in a good spawn.
        auto flat_yaw = [](const Vec3& v) { return std::atan2(v.y, v.x) * kRadToDeg; };
        auto yaw_between = [](double a, double b) {
            double r = std::fmod(a - b, 360.0);
            return r > 180.0 ? r - 360.0 : r < -180.0 ? r + 360.0 : r;
        };
        Vec3 mesh_forward = component_rotation(g_pose.mesh).rotate(Vec3{0, 1, 0});
        bool facing_known = std::hypot(mesh_forward.x, mesh_forward.y) > 0.5; // not lying down
        double facing = facing_known ? flat_yaw(mesh_forward) : heading;
        double yaw_error = yaw_between(facing, heading);
        bool by_facing = cfg.pose_calib_body_facing && facing_known;
        auto line_yaw = [&](const char* left, const char* right) {
            Vec3 across = socket_location(g_pose.mesh, bone_fname(right)) - socket_location(g_pose.mesh, bone_fname(left));
            return yaw_between(flat_yaw(across) - 90.0, facing);
        };
        HSVR_LOG("Calibration: the body faces %.2f, control yaw %.2f: error %.2f deg (%s); against that facing hips %.2f, shoulders %.2f deg", facing, heading, yaw_error,
                 by_facing ? "taken out" : cfg.pose_calib_body_facing ? "kept: the mesh lies flat" : "kept: pose_calib_body_facing=0",
                 line_yaw("thigh_l", "thigh_r"), line_yaw("clavicle_l", "clavicle_r"));
        g_pose.calib_snap = by_facing && std::fabs(yaw_error) > 1.0;
        Quat body = quat_from_yaw_deg(by_facing ? facing : heading);
        Quat body_inv = body.inverse();
        Vec3 actor = actor_location(g_pose.pawn);

        apply_arm_physics(cfg);
        Vec3 mesh_location = component_location(g_pose.mesh);
        g_pose.mesh_offset_local = body_inv.rotate(mesh_location - actor);
        g_pose.mesh_rotation_local = (body_inv * component_rotation(g_pose.mesh)).normalized();

        Vec3 head = socket_location(d, bone_fname("Head"));
        g_pose.head_offset = (body_inv * socket_rotation(d, bone_fname("Head"))).normalized();
        {
            // The head bone's forward is its +Y. Whatever yaw the spawn animation had it at is taken out, so the
            // helmet's front is straight ahead of the eyes. (Over 45 deg: not a neutral head, left as it is.)
            double head_yaw = flat_yaw(g_pose.head_offset.rotate(Vec3{0, 1, 0}));
            bool straighten = by_facing && std::fabs(head_yaw) <= 45.0;
            if (straighten) g_pose.head_offset = (quat_from_yaw_deg(-head_yaw) * g_pose.head_offset).normalized();
            HSVR_LOG("Calibration: head bone %.2f deg from straight ahead (%s)", head_yaw, straighten ? "taken out" : "kept");
        }
        g_pose_anchor_local = body_inv.rotate(head - actor);
        g_pose_anchor_fixed = true;
        g_pose_room_moved_local = {};

        g_pose.chest_rot_local = (body_inv * socket_rotation(g_pose.mesh, bone_fname("spine_05"))).normalized();
        g_lean = LeanState{};
        g_lean.calibrated = true;
        for (int i = 0; i < 7; ++i)
        {
            if (!bone_exists(d, kLeanBones[i])) g_lean.calibrated = false;
            g_lean.pts[i] = body_inv.rotate(socket_location(d, bone_fname(kLeanBones[i])) - actor);
        }
        HSVR_LOG("Lean: %s; spine_02 at %.1f cm, head %.1f cm above the actor, head %.1f cm in front of spine_02",
                 g_lean.calibrated ? "calibrated" : "a bone is MISSING, lean off", g_lean.pts[0].z, g_lean.pts[6].z, g_lean.pts[6].x - g_lean.pts[0].x);
        g_pose.pelvis_rot_local = (body_inv * socket_rotation(g_pose.mesh, bone_fname("pelvis"))).normalized();
        g_pose.feet_calibrated = true;
        for (int side = 0; side < 2; ++side)
        {
            FName foot = bone_fname(side == 0 ? "foot_l" : "foot_r");
            if (!bone_exists(g_pose.mesh, side == 0 ? "foot_l" : "foot_r"))
            {
                g_pose.feet_calibrated = false;
                continue;
            }
            g_pose.foot_home_local[side] = body_inv.rotate(socket_location(g_pose.mesh, foot) - actor);
            g_pose.foot_rot_local[side] = (body_inv * socket_rotation(d, foot)).normalized();
            Vec3 foot_at = socket_location(g_pose.mesh, foot);
            double floor_z = 0.0;
            bool hit = ground_below(g_pose.pawn, foot_at.x, foot_at.y, actor.z, floor_z);
            bool used = hit && foot_at.z - floor_z > 2.0 && foot_at.z - floor_z < 30.0;
            if (used)
            {
                g_pose.ankle_height[side] = foot_at.z - floor_z;
                g_pose.ankle_measured[side] = true;
            }
            g_pose.calibrated_at = now_seconds();
            if (hit)
                HSVR_LOG("Pose: %s ankle %.1f cm above the floor (foot bone at %.1f, floor at %.1f%s)", side == 0 ? "left" : "right",
                         g_pose.ankle_height[side], foot_at.z, floor_z, used ? "" : ", out of range: measured again once he stands");
            else
                HSVR_LOG("Pose: %s ankle: no floor found under the foot (trace from %.0f down), 10 cm used", side == 0 ? "left" : "right", actor.z);
            HSVR_LOG("Pose: %s foot stands at (%.0f, %.0f, %.0f) from the actor", side == 0 ? "left" : "right", g_pose.foot_home_local[side].x,
                     g_pose.foot_home_local[side].y, g_pose.foot_home_local[side].z);
        }

        for (int side = 0; side < 2; ++side)
        {
            ArmCalibration& a = g_pose.arm[side];
            std::string sx = side_suffix(side);
            FName upper = bone_fname("upperarm" + sx), lower = bone_fname("lowerarm" + sx), hand = bone_fname("hand" + sx);
            Vec3 S = socket_location(d, upper), E = socket_location(d, lower), H = socket_location(d, hand);
            {
                FName clav = bone_fname("clavicle" + sx);
                Quat Wch = socket_rotation(d, bone_fname("spine_05")), Wcl = socket_rotation(d, clav);
                a.clavicle_in_chest = (Wch.inverse() * Wcl).normalized();
                a.shoulder_in_clavicle = Wcl.inverse().rotate(S - socket_location(d, clav));
                a.clavicle_valid = length(a.shoulder_in_clavicle) > 1.0;
            }
            a.upper_length = length(E - S);
            a.lower_length = length(H - E);
            Vec3 n = cross(E - S, H - E);
            if (length(n) < 1e-3 * a.upper_length * a.lower_length) n = cross(body.rotate({1, 0, 0}), E - S); // straight arm: elbow bends forward
            Quat Wu = socket_rotation(d, upper), Wl = socket_rotation(d, lower), Wh = socket_rotation(d, hand);
            a.upper_dir_local = Wu.inverse().rotate(normalized(E - S));
            a.upper_normal_local = Wu.inverse().rotate(normalized(n));
            a.lower_dir_local = Wl.inverse().rotate(normalized(H - E));
            a.lower_normal_local = Wl.inverse().rotate(normalized(n));
            // Which way his hand points, in the hand bone's own frame: from the hand to the middle
            // finger's first bone, and from the little finger across to the index finger (the
            // thumb side). Without finger bones, along the forearm, with the elbow's bend as the side.
            Vec3 fingers = H - E, across = n;
            const char* how = "forearm (no finger bones)";
            if (bone_exists(d, "middle_01" + sx) && bone_exists(d, "index_01" + sx) && bone_exists(d, "pinky_01" + sx))
            {
                fingers = socket_location(d, bone_fname("middle_01" + sx)) - H;
                across = socket_location(d, bone_fname("index_01" + sx)) - socket_location(d, bone_fname("pinky_01" + sx));
                how = "finger bones";
            }
            a.fingers_local = normalized(Wh.inverse().rotate(fingers));
            Vec3 t = Wh.inverse().rotate(across);
            a.thumb_local = normalized(t - a.fingers_local * dot(t, a.fingers_local));
            HSVR_LOG("Pose: %s hand frame from %s: fingers (%.2f, %.2f, %.2f), thumb side (%.2f, %.2f, %.2f) in the hand bone", side == 0 ? "left" : "right",
                     how, a.fingers_local.x, a.fingers_local.y, a.fingers_local.z, a.thumb_local.x, a.thumb_local.y, a.thumb_local.z);
            a.valid = a.upper_length > 5.0 && a.lower_length > 5.0 && chain_node("upperarm" + sx) && chain_node("lowerarm" + sx) && chain_node("hand" + sx);
            HSVR_LOG("Pose: %s arm upper %.1f cm, lower %.1f cm%s", side == 0 ? "left" : "right", a.upper_length, a.lower_length, a.valid ? "" : " (not usable)");
        }
        HSVR_LOG("Pose: on. Head %.0f cm above the actor, mesh offset (%.0f, %.0f, %.0f), arms %s", g_pose_anchor_local.z, g_pose.mesh_offset_local.x,
                 g_pose.mesh_offset_local.y, g_pose.mesh_offset_local.z, "exact");
        return true;
    }

    // The bone rotation that points its calibrated direction along `dir` with its calibrated
    // bend-plane normal along `normal`.
    hsvr::Quat aim_bone(const hsvr::Vec3& dir_local, const hsvr::Vec3& normal_local, const hsvr::Vec3& dir, const hsvr::Vec3& normal)
    {
        return (hsvr::quat_from_two(dir, normal) * hsvr::quat_from_two(dir_local, normal_local).inverse()).normalized();
    }

    // ---- Feet that stand and step ---------------------------------------------------------------
    // The game re-measures where each foot stands from the body every tick, so when the body turns
    // or slides the feet go with it, and it lifts a foot only once it is about 25 cm or 60-100
    // degrees off (decompile: Willie_BP @596869-598708). While posed, the mod keeps each foot where
    // it was put down, and steps it (lift and place, one foot at a time) once it is more than
    // pose_step_distance_cm from where it would stand under the hips, or turned more than
    // pose_step_angle_deg from them. The foot positions go into ABP_Willie's two foot IK effectors
    // (in the pelvis's frame) right after the game's animation update writes its own; the leg IK
    // bends the knees. The height is the floor under the foot (a trace straight down) plus his ankle
    // height when standing; the game's own foot height drifts 20-45 cm off in a deep crouch.
    // The floor's height under a point: a straight-down trace on the Visibility channel that ignores
    // your own character (and looks through him too, should a part of him be hit). Weapons (held, belted or loose, scabbards included: a scabbard is a part of
    // its weapon) and creatures are looked through: the trace starts at his hips, and a weapon on the
    // left hip or in a hand over a foot used to count as the floor (the left foot popped up 85 cm,
    // about 40 times a minute). False if nothing else is hit within 2 m below `from_z`.
    bool is_a(UObject* object, const TCHAR* class_name);
    bool ground_below(UObject* pawn, double x, double y, double from_z, double& ground_z)
    {
        static UObject* cdo = UObjectGlobals::StaticFindObject<UObject*>(nullptr, nullptr, STR("/Script/Engine.Default__KismetSystemLibrary"));
        static UObject* gs = UObjectGlobals::StaticFindObject<UObject*>(nullptr, nullptr, STR("/Script/Engine.Default__GameplayStatics"));
        if (!cdo || !pawn) return false;
        const double bottom = from_z - 200.0;
        double start = from_z;
        // 12 looks always: a kick over loose crossbow bolts and a choked Willie lying under him used up 5
        // and found no floor (playtest 2026-11-23, 851.6 s).
        for (int attempt = 0; attempt < 12 && start > bottom; ++attempt)
        {
            Call trace(cdo, STR("LineTraceSingle"));
            if (!trace.fn) return false;
            trace.object(STR("WorldContextObject"), pawn);
            trace.three(STR("Start"), x, y, start);
            trace.three(STR("End"), x, y, bottom);
            trace.flag(STR("bIgnoreSelf"), true);
            if (!trace.run()) return false;
            FProperty* ret = trace.param(STR("ReturnValue"));
            if (!ret || !(*(trace.buffer.data() + ret->GetOffset_Internal()) & 1)) return false;
            FProperty* hit = trace.param(STR("OutHit"));
            FProperty* point = hit ? struct_member(struct_type(hit), STR("ImpactPoint")) : nullptr;
            UScriptStruct* vec_type = struct_type(point);
            FProperty* z = vec_type ? struct_member(vec_type, STR("Z")) : nullptr;
            if (!z) return false;
            const uint8_t* at = trace.buffer.data() + hit->GetOffset_Internal() + point->GetOffset_Internal() + z->GetOffset_Internal();
            double hit_z = z->GetClass().GetName() == STR("DoubleProperty") ? *reinterpret_cast<const double*>(at) : *reinterpret_cast<const float*>(at);
            // What was hit (the game's BreakHitResult gives the actor).
            UObject* actor = nullptr;
            if (gs)
            {
                Call b(gs, STR("BreakHitResult"));
                if (FProperty* hp = b.param(STR("Hit")))
                {
                    std::memcpy(b.buffer.data() + hp->GetOffset_Internal(), trace.buffer.data() + hit->GetOffset_Internal(), (std::min)(hp->GetSize(), hit->GetSize()));
                    b.run();
                    actor = b.object_result(STR("HitActor"));
                }
            }
            bool look_through = actor && (actor == pawn || actor == g_ground_ignore || is_a(actor, STR("ModularWeaponBP_C")) || is_a(actor, STR("Pawn")));
            if (!look_through)
            {
                ground_z = hit_z;
                return true;
            }
            HSVR_LOG_EVERY(2.0, "Feet: ground trace looked through %ls at z %.0f (%.0f cm below the hips)", actor->GetName().c_str(), hit_z, from_z - hit_z);
            start = hit_z - 1.0;
        }
        return false;
    }

    // One sweep on the Visibility channel, simple collision unless `complex`: a sphere (half 0) or an
    // upright capsule. Looks through him, creatures, weapons and anything simulating physics (loose
    // items get pushed, not walked into): those are ignored and the sweep is run again, up to 6 times,
    // so a weapon in front of a wall doesn't hide the wall. Returns 0 when nothing is in the way, 1 on a
    // hit (`stop`: the shape's centre there, `normal`: the surface's), 2 when the shape starts inside
    // something (`normal`: the way out). `hit_name`: what it hit.
    // `walls_only`: a hit or start-inside whose surface faces mostly up or down (the floor, a slope, a
    // table top) doesn't count: that thing is looked through. `depth`: how far in it starts (result 2).
    int world_sweep(const hsvr::Vec3& from, const hsvr::Vec3& to, double radius, double half, bool complex, hsvr::Vec3& stop, hsvr::Vec3* normal = nullptr,
                    std::wstring* hit_name = nullptr, bool walls_only = false, double* depth = nullptr)
    {
        static UObject* cdo = UObjectGlobals::StaticFindObject<UObject*>(nullptr, nullptr, STR("/Script/Engine.Default__KismetSystemLibrary"));
        static UObject* gs = UObjectGlobals::StaticFindObject<UObject*>(nullptr, nullptr, STR("/Script/Engine.Default__GameplayStatics"));
        if (!cdo || !gs || !g_pose.pawn) return 0;
        UObject* ignore[16] = {};
        int ignored = 0;
        for (int attempt = 0; attempt < 16; ++attempt)
        {
            Call trace(cdo, half > 0.0 ? STR("CapsuleTraceSingle") : STR("SphereTraceSingle"));
            if (!trace.fn) return 0;
            trace.object(STR("WorldContextObject"), g_pose.pawn);
            trace.three(STR("Start"), from.x, from.y, from.z);
            trace.three(STR("End"), to.x, to.y, to.z);
            trace.number(STR("Radius"), radius);
            if (half > 0.0) trace.number(STR("HalfHeight"), half);
            trace.flag(STR("bTraceComplex"), complex);
            trace.flag(STR("bIgnoreSelf"), true);
            // ActorsToIgnore (const TArray<AActor*>&): pointed at our own list, read only by the trace.
            if (FProperty* ip = trace.param(STR("ActorsToIgnore")); ip && ignored > 0)
            {
                struct RawArray { UObject** data; int32_t num, max; };
                auto* arr = reinterpret_cast<RawArray*>(trace.buffer.data() + ip->GetOffset_Internal());
                arr->data = ignore, arr->num = ignored, arr->max = ignored;
            }
            bool ran = trace.run();
            if (FProperty* ip = trace.param(STR("ActorsToIgnore")))
                std::memset(trace.buffer.data() + ip->GetOffset_Internal(), 0, ip->GetSize()); // never ours to free
            if (!ran) return 0;
            FProperty* ret = trace.param(STR("ReturnValue"));
            if (!ret || !(*(trace.buffer.data() + ret->GetOffset_Internal()) & 1)) return 0;
            FProperty* hit = trace.param(STR("OutHit"));
            if (!hit) return 0;
            Call b(gs, STR("BreakHitResult"));
            FProperty* hp = b.param(STR("Hit"));
            if (!hp) return 0;
            std::memcpy(b.buffer.data() + hp->GetOffset_Internal(), trace.buffer.data() + hit->GetOffset_Internal(), (std::min)(hp->GetSize(), hit->GetSize()));
            b.run();
            UObject* actor = b.object_result(STR("HitActor"));
            bool look_through = actor && (actor == g_pose.pawn || is_a(actor, STR("ModularWeaponBP_C")) || is_a(actor, STR("Pawn")));
            if (!look_through)
                if (UObject* comp = b.object_result(STR("HitComponent")))
                {
                    Call sim(comp, STR("IsSimulatingPhysics"));
                    if (sim.fn)
                    {
                        static const FName none_name = FName(STR("None"), FNAME_Add);
                        sim.name(STR("BoneName"), none_name);
                        if (sim.run())
                            if (FProperty* r = sim.param(STR("ReturnValue")); r && *(sim.buffer.data() + r->GetOffset_Internal()) != 0) look_through = true;
                    }
                }
            if (look_through)
            {
                if (!actor || ignored >= 16) return 0;
                ignore[ignored++] = actor;
                continue;
            }
            hsvr::Vec3 nrm = b.vec(STR("Normal"));
            FProperty* ov = b.param(STR("bInitialOverlap"));
            bool inside = ov && *(b.buffer.data() + ov->GetOffset_Internal()) != 0;
            if (walls_only && std::sqrt(nrm.x * nrm.x + nrm.y * nrm.y) < 0.3) // floor, slope or table top: not a wall
            {
                if (!actor || ignored >= 16) return 0;
                ignore[ignored++] = actor;
                continue;
            }
            if (hit_name) *hit_name = actor ? actor->GetName() : std::wstring(STR("?"));
            if (normal) *normal = nrm;
            if (inside)
            {
                if (depth)
                {
                    // Not among BreakHitResult's outputs: read from the hit itself (a float in UE 5.4).
                    *depth = 0.0;
                    if (FProperty* pd = struct_member(struct_type(hit), STR("PenetrationDepth")))
                    {
                        const uint8_t* at = trace.buffer.data() + hit->GetOffset_Internal() + pd->GetOffset_Internal();
                        *depth = pd->GetClass().GetName() == STR("DoubleProperty") ? *reinterpret_cast<const double*>(at) : *reinterpret_cast<const float*>(at);
                    }
                }
                stop = from;
                return 2;
            }
            stop = b.vec(STR("Location"));
            return 1;
        }
        return 0;
    }

    // A free hand stops at the world (Matthew 2026-11-22 03:56: "my hand defies the laws of physics…
    // I can just put my hand inside of the post"; nothing stopped it, it went wherever the controller
    // was). A sphere swept from his shoulder to his palm, complex collision (the Yard fence is
    // triangles only).
    bool hand_world_sweep(const hsvr::Vec3& from, const hsvr::Vec3& to, double radius, hsvr::Vec3& stop)
    {
        return world_sweep(from, to, radius, 0.0, true, stop) == 1; // his shoulder already in it: leave the hand be
    }

    // He stops at walls (pose_body_wall_stop). Matthew 2026-11-22 04:00: "I can just walk through the
    // post as if it's not even there. Can I walk through walls?" Yes: Willie's CollisionCylinder ignores
    // WorldStatic (the game's ragdoll body pushed him back off walls; the posed body doesn't). His
    // capsule's move from `from` to `to` (sideways only) is swept as a capsule from a step above his
    // feet to his head, and stops at the first wall, sliding along it. Returns where he may stand.
    hsvr::Vec3 body_wall_sweep(UObject* pawn, const hsvr::Vec3& from, const hsvr::Vec3& to, bool& blocked)
    {
        using namespace hsvr;
        blocked = false;
        const Config cfg = config();
        Vec3 move{to.x - from.x, to.y - from.y, 0.0};
        double len = length(move);
        if (!cfg.pose_body_wall_stop || len < 1e-4 || len > 500.0) return to; // over 5 m in a tick: a teleport (a hitch's catch-up tick moves 1-2 m)
        UObject* cyl = object_property(pawn, STR("CapsuleComponent"));
        if (!cyl) return to;
        double r = 34.0, h = 90.0;
        { Call c(cyl, STR("GetScaledCapsuleRadius")); if (c.run()) r = c.number(); }
        { Call c(cyl, STR("GetScaledCapsuleHalfHeight")); if (c.run()) h = c.number(); }
        r = (std::max)(5.0, r * cfg.pose_body_wall_radius_share);
        double lift = (std::min)(cfg.pose_body_wall_step_cm, h); // the bottom: this far above his feet
        double half = (std::max)(r, h - lift * 0.5);
        double dz = lift * 0.5;
        auto flat = [](Vec3 v) { v.z = 0.0; double l = length(v); return l > 1e-6 ? v * (1.0 / l) : Vec3{}; };
        // Already touching or inside something: only the part of the move out of it is allowed.
        auto out_of = [&](const Vec3& m, const Vec3& n_raw) {
            Vec3 n = flat(n_raw);
            double into = dot(m, n);
            return into < 0.0 ? m - n * into : m;
        };
        Vec3 a{from.x, from.y, to.z + dz}, b{to.x, to.y, to.z + dz};
        Vec3 at, n;
        std::wstring what;
        double depth = 0.0;
        int r1 = world_sweep(a, b, r, half, false, at, &n, &what, true, &depth);
        if (r1 == 2)
        {
            // Touching or in it: pushed out along its (flat) way out, then the move swept from there.
            Vec3 nf = flat(n);
            Vec3 out = a + nf * ((std::min)(5.0, (std::max)(0.0, depth)) + 0.2); // at most 5 cm a tick
            Vec3 m = out_of(b - a, n);
            Vec3 at3, n3;
            int r3 = world_sweep(out, out + m, r, half, false, at3, &n3, nullptr, true);
            Vec3 stop = r3 == 0 ? out + m : r3 == 1 ? at3 + flat(n3) * 0.1 : out;
            blocked = true;
            HSVR_LOG_EVERY(1.0, "Wall: he was %.1f cm into %ls: pushed out and kept out", depth, what.c_str());
            return {stop.x, stop.y, to.z};
        }
        if (r1 == 0) return to;
        blocked = true;
        Vec3 stop;
        {
            Vec3 nf = flat(n);
            if (length(nf) < 0.5) nf = flat(a - b);
            stop = at + nf * 0.1;
            // Slide along it with what is left.
            Vec3 rest = b - stop;
            rest = rest - nf * dot(rest, nf);
            rest.z = 0.0;
            if (length(rest) > 1e-3)
            {
                Vec3 at2, n2, end = stop + rest;
                int r2 = world_sweep(stop, end, r, half, false, at2, &n2, nullptr, true);
                stop = r2 == 0 ? end : r2 == 1 ? at2 + flat(n2) * 0.1 : stop;
            }
        }
        static std::wstring last_what;
        if (what != last_what) { last_what = what; HSVR_LOG("Wall: he walks into %ls", what.c_str()); }
        HSVR_LOG_EVERY(1.0, "Wall: he stopped at %ls %.1f cm short of where he was going (radius %.0f, capsule half height %.0f)", what.c_str(), length(b - stop), r, h);
        return {stop.x, stop.y, to.z};
    }

    struct FootState
    {
        bool valid = false;
        hsvr::Vec3 at;          // where the foot stands (x, y; z unused)
        double yaw = 0.0;
        bool stepping = false;
        double t = 0.0, duration = 0.3;
        hsvr::Vec3 from;
        double yaw_from = 0.0;
        double lift = 0.0;      // this frame's height above the ground (cm)
        double ground_z = 0.0;  // where the foot bone sits when the foot is down: the floor plus the ankle height
        bool have_ground = false;
        double ground_t = -100.0; // when a trace last found the floor under this foot
        int steps = 0;
        bool kicking = false;   // the game's kick has this leg (Kicking L/R): no planting, no flat foot
    };
    FootState g_feet[2];
    double g_kick_fired_at = -100.0; // when right A last fired the game's Kick Event (pose_feet_free_on_kick)
    std::atomic<bool> g_feet_active{false};
    int g_last_foot = -1;
    double g_feet_time = 0.0;
    FProperty* g_effector[2] = {nullptr, nullptr};
    bool g_effector_looked = false;

    double wrap_deg(double a)
    {
        while (a > 180.0) a -= 360.0;
        while (a < -180.0) a += 360.0;
        return a;
    }

    void feet_reset()
    {
        for (FootState& f : g_feet) f = FootState{};
        g_feet_active = false;
        g_last_foot = -1;
    }

    // Called each frame from pose_body, after the body is placed for this frame.
    void pose_feet(const hsvr::Config& cfg, UObject* pawn, const hsvr::Vec3& actor, double heading, const hsvr::Quat& component_inv)
    {
        using namespace hsvr;
        if (!cfg.pose_feet || !g_pose.feet_calibrated)
        {
            if (g_feet_active.load())
            {
                for (const char* b : {"foot_l", "foot_r"})
                    if (ModifyBoneNode* n = chain_node(b)) node_release(*n);
                feet_reset();
            }
            return;
        }
        double now = now_seconds();
        double dt = (std::min)(0.1, (std::max)(0.0, now - g_feet_time));
        g_feet_time = now;
        Quat body = quat_from_yaw_deg(heading);
        // Where your feet would stand under your hips, a little ahead in the direction you move.
        Vec3 velocity{0, 0, 0};
        if (UObject* movement = object_property(pawn, STR("CharacterMovement")))
            if (FProperty* vp = prop_chain(movement, STR("Velocity")))
            {
                double v[3];
                read_three(reinterpret_cast<uint8_t*>(movement) + vp->GetOffset_Internal(), vp, v);
                velocity = {v[0], v[1], 0.0};
            }
        double speed = length(velocity);
        // Crouched, he takes longer, slower steps, as the game does (step size MapRange(Root Height 85..70 ->
        // 0.75..1.5) @579096: twice the standing step 15 cm down). Playtest 2026-11-23 17:23 local: his
        // crouch walk was "way too rapid" (a step every 0.12 s at 150 cm/s with 10 cm steps).
        double crouch_k = 1.0;
        if (cfg.pose_step_crouch_scale > 1.0 && cfg.pose_step_crouch_full_cm > 0.0)
            crouch_k = 1.0 + (cfg.pose_step_crouch_scale - 1.0) * (std::max)(0.0, (std::min)(1.0, g_crouch_drop / cfg.pose_step_crouch_full_cm));
        double step_distance = cfg.pose_step_distance_cm * crouch_k;
        Vec3 want[2];
        double need[2];
        for (int side = 0; side < 2; ++side)
        {
            Vec3 home = g_pose.foot_home_local[side];
            want[side] = actor + body.rotate(Vec3{home.x, home.y, 0.0}) + velocity * (cfg.pose_step_lead_s * crouch_k);
            want[side].z = 0.0;
            FootState& f = g_feet[side];
            if (!f.valid)
            {
                f.valid = true;
                f.at = want[side];
                f.yaw = heading;
            }
            Vec3 off = f.at - want[side];
            off.z = 0.0;
            double d = length(off);
            if (d > 120.0) // teleported or respawned: put both feet down at once
            {
                f.at = want[side];
                f.yaw = heading;
                f.stepping = false;
                d = 0.0;
            }
            need[side] = (std::max)(d / (std::max)(1.0, step_distance), std::fabs(wrap_deg(heading - f.yaw)) / (std::max)(1.0, cfg.pose_step_angle_deg));
        }
        bool any_stepping = g_feet[0].stepping || g_feet[1].stepping;
        if (!any_stepping)
        {
            // The foot that needs it most; after a step the other foot goes next if it needs it at all.
            int pick = need[0] >= need[1] ? 0 : 1;
            if (pick == g_last_foot && need[1 - pick] >= 0.5 && need[pick] < 2.0 * need[1 - pick]) pick = 1 - pick;
            if (need[pick] >= 1.0 && !g_feet[pick].kicking)
            {
                FootState& f = g_feet[pick];
                f.stepping = true;
                f.t = 0.0;
                f.from = f.at;
                f.yaw_from = f.yaw;
                // Quicker steps when moving faster.
                f.duration = cfg.pose_step_time_s * crouch_k / (1.0 + speed / 150.0);
                f.duration = (std::max)(0.12 * crouch_k, f.duration);
                g_last_foot = pick;
                ++f.steps;
                g_count_steps.fetch_add(1);
            }
        }
        for (int side = 0; side < 2; ++side)
        {
            FootState& f = g_feet[side];
            f.lift = 0.0;
            // The game's kick (right A, or its tap-kick) swings this leg: leave the leg to it. Planting
            // the foot at its old spot and holding it flat turned the foot backwards mid-kick
            // (playtest 2026-11-21 11:39). Afterwards the foot stands where the kick put it down.
            // Kicking L/R read 0 right after the Kick Event (playtest log), so the legs are also left to
            // the game for pose_feet_kick_free_s after right A fires it.
            bool flag = bool_property(pawn, side == 0 ? STR("Kicking L") : STR("Kicking R"));
            static bool flag_was[2] = {false, false};
            if (flag != flag_was[side])
                HSVR_LOG("Kick: Kicking %s %d (%.2f s after right A)", side == 0 ? "L" : "R", (int)flag, now - g_kick_fired_at);
            flag_was[side] = flag;
            bool kicking = cfg.pose_feet_free_on_kick && (flag || now - g_kick_fired_at < cfg.pose_feet_kick_free_s);
            if (kicking)
            {
                if (!f.kicking) HSVR_LOG("Kick: %s leg left to the game's kick (no foot planting)", side == 0 ? "left" : "right");
                f.kicking = true;
                f.stepping = false;
                if (ModifyBoneNode* n = chain_node(side == 0 ? "foot_l" : "foot_r")) node_release(*n);
                continue;
            }
            if (f.kicking)
            {
                f.kicking = false;
                Vec3 foot_at = socket_location(g_pose.mesh, bone_fname(side == 0 ? "foot_l" : "foot_r"));
                f.at = {foot_at.x, foot_at.y, 0.0};
                f.yaw = heading;
                HSVR_LOG("Kick: %s kick over; foot planted where it came down (%.0f cm from its home spot)", side == 0 ? "left" : "right",
                         length(Vec3{f.at.x - want[side].x, f.at.y - want[side].y, 0.0}));
            }
            if (f.stepping)
            {
                f.t += dt;
                double u = (std::min)(1.0, f.t / f.duration);
                double s = u * u * (3.0 - 2.0 * u);
                // It aims for where the foot should land now, so it keeps up with a moving body.
                f.at = f.from + (want[side] - f.from) * s;
                f.at.z = 0.0;
                f.yaw = wrap_deg(f.yaw_from + wrap_deg(heading - f.yaw_from) * s);
                f.lift = std::sin(u * 3.14159265358979) * cfg.pose_step_lift_cm;
                if (u >= 1.0) f.stepping = false;
            }
            double floor_z = 0.0;
            if (!g_pose.ankle_measured[side])
            {
                // Posing can start while he is still dropping onto the floor after spawning: measure
                // the ankle once the game's own foot is down (the game keeps the feet until then).
                Vec3 foot_at = socket_location(g_pose.mesh, bone_fname(side == 0 ? "foot_l" : "foot_r"));
                if (ground_below(pawn, foot_at.x, foot_at.y, actor.z, floor_z) && foot_at.z - floor_z > 2.0 && foot_at.z - floor_z < 30.0)
                {
                    g_pose.ankle_height[side] = foot_at.z - floor_z;
                    g_pose.ankle_measured[side] = true;
                    HSVR_LOG("Pose: %s ankle %.1f cm above the floor (measured once he stood)", side == 0 ? "left" : "right", g_pose.ankle_height[side]);
                }
                else if (now - g_pose.calibrated_at > 3.0)
                {
                    g_pose.ankle_measured[side] = true;
                    HSVR_LOG("Pose: %s ankle could not be measured in 3 s; 10 cm used", side == 0 ? "left" : "right");
                }
                if (!g_pose.ankle_measured[side]) continue; // the game's own foot until then
            }
            // From a step (30 cm) above where he stands, not from his middle: from the middle a foot
            // under a 105 cm weapon table found its top and he was stood on it (table test U2).
            double foot_from = g_pose.mesh ? (std::min)(actor.z, actor.z - 90.0 * component_scale_z(g_pose.mesh) + 30.0) : actor.z;
            if (ground_below(pawn, f.at.x, f.at.y, foot_from, floor_z))
            {
                f.ground_z = floor_z + g_pose.ankle_height[side];
                f.have_ground = true;
                f.ground_t = hsvr::now_seconds();
            }
            // The foot points where it was put down, flat (the leg IK takes its turn from the hips otherwise).
            if (ModifyBoneNode* n = chain_node(side == 0 ? "foot_l" : "foot_r"))
                node_set_rotation(*n, component_inv * (quat_from_yaw_deg(f.yaw) * g_pose.foot_rot_local[side]));
        }
        g_feet_active = true;
    }

    // Right after ABP_Willie's animation update (which copies the game's foot targets in): our feet.
    UFunction* g_anim_update = nullptr;
    // ---- Finger shapes, shown to the animation only ---------------------------------------------
    // ABP_Willie copies each hand's finger shape from the pawn's R/L_GripType_Current into its own
    // 'R/L Grip Type' inside BlueprintUpdateAnimation (@152268 / @153084), and the AnimGraph reads only
    // that copy (grip_type_flow.md). Willie's own tick reads the pawn's values for its rules (a non-zero
    // L_GripType_Current drops the right hand's two-handed grip 11 -> 2 every tick, @493002-496128), and
    // Set Up Hand Weapon rewrites them. So the mod never writes the pawn's values: it writes the
    // animation's copy right after that update, for the player only (pose_fingers_anim_only).
    int g_anim_grip[2] = {-1, -1};          // the finger shape the mod wants for that hand (-1 = the game's)
    double g_anim_grip_time[2] = {-1e9, -1e9};
    int g_anim_grip_two = -1;               // the second hand's, while two hands hold (g_two.second)
    int g_anim_grip_two_side = -1;
    void set_anim_grip(int side, int g)
    {
        g_anim_grip[side] = g;
        g_anim_grip_time[side] = hsvr::now_seconds();
    }
    // The body pose written inside his animation update (pose_in_anim_update), right before the arm
    // nodes are evaluated, instead of at the start of the engine tick: on frames where a held item
    // moved, his drawn hand showed the previous frame's solve (96% of the worst ticks, playtest 10:36),
    // which shook the hand on a steady sword. The engine tick still runs it when this has not fired.
    void pose_body(const hsvr::Config& cfg);
    void enter_plain_game(UObject* pawn);
    UObject* g_no_push_for = nullptr; // pose_capsule_no_push was set for this pawn
    std::atomic<double> g_pose_in_anim_at{-1.0};
    double number_property(UObject* owner, FProperty* p);
    bool write_three(uint8_t* field, FProperty* property, double a, double b, double c);
    void read_three(const uint8_t* field, FProperty* property, double out[3]);

    // pose_no_fall_arms: walking fast his feet run 36-47 cm ahead of his head, and ABP_Willie takes
    // that for falling backwards: past 25 cm (its "Shoulders Dislocation", head minus mid-feet, turned
    // into his hips' frame by "Ass Rotation Z", X < -25) each arm blends over 1 s into
    // Anim_Fall_Backward_ArmsSwing, which drops the weapon grip pose (ABP @147915 right, @167150 left;
    // Matthew 2026-11-22 03:50: "my player model's hand started opening up"). After his animation
    // update (the node reads it later in the same update), the player's copy is held at -24.9 cm along
    // that axis. Its other readers (bend AO, the spine_02 aim fade) only change past 25 cm; the pawn's
    // own balance keeps its own value.
    void no_fall_arms(UObject* abp)
    {
        static FProperty* sd = nullptr;
        static FProperty* ass = nullptr;
        static UObject* looked_on = nullptr;
        if (looked_on != abp)
        {
            looked_on = abp;
            sd = prop_chain(abp, STR("Shoulders Dislocation"));
            ass = prop_chain(abp, STR("Ass Rotation Z"));
            HSVR_LOG("Pose: falling-arms guard: Shoulders Dislocation %s, Ass Rotation Z %s", sd ? "found" : "MISSING", ass ? "found" : "MISSING");
        }
        if (!sd || !ass || sd->GetClass().GetName() != STR("StructProperty")) return;
        uint8_t* field = reinterpret_cast<uint8_t*>(abp) + sd->GetOffset_Internal();
        double v[3] = {0, 0, 0};
        read_three(field, sd, v);
        double rot[3] = {0, 0, 0}; // an FRotator: pitch, yaw, roll (degrees; pitch and roll stay 0)
        read_three(reinterpret_cast<uint8_t*>(abp) + ass->GetOffset_Internal(), ass, rot);
        double yaw = rot[1] * 3.14159265358979323846 / 180.0;
        double c = std::cos(yaw), s = std::sin(yaw);
        // UnrotateVector by yaw: into his hips' frame.
        double x = c * v[0] + s * v[1], y = -s * v[0] + c * v[1];
        const double limit = -24.9;
        if (x >= limit) return;
        double was = x;
        x = limit;
        write_three(field, sd, c * x - s * y, s * x + c * y, v[2]);
        HSVR_LOG_EVERY(2.0, "Pose: his feet %.0f cm ahead of his head: kept out of the game's falling-backwards arms", -was);
    }
    void pose_after_anim_update(Hook::TCallbackIterationData<void>&, UObject* context, UFunction* function, void*)
    {
        gc_sync();
        HSVR_PROF(PerfPoseAnim);
        if (!context || !g_pose.instance || context != g_pose.instance || !function) return;
        if (g_anim_update) { if (function != g_anim_update) return; }
        else
        {
            if (function->GetName() != STR("BlueprintUpdateAnimation")) return;
            g_anim_update = function;
        }
        hsvr::Config cfg = hsvr::config();
        if (!cfg.pose_in_anim_update) return;
        static bool said = false;
        if (!said)
        {
            said = true;
            HSVR_LOG("Pose: written inside his animation update (pose_in_anim_update)");
        }
        g_pose_in_anim_at.store(hsvr::now_seconds());
        if (cfg.pose_no_fall_arms && g_pose_active.load()) no_fall_arms(context);
        HSVR_SUB("anim:pose_body");
        pose_body(cfg);
    }

    // The mod's fist is in that hand (set each tick by grab_button), for the fist's finger shape.
    std::atomic<bool> g_fist_side[2] = {false, false};
    std::atomic<bool> g_fist_open[2] = {false, false}; // a slap: the fist is there but the hand is open (fingers as the game's)
    std::atomic<int> g_fist_shape_test{-99}; // test: hsvr.fist_shape <n> (-99 = pose_fist_shape)
    bool set_bool_property(UObject* owner, const TCHAR* name, bool value);
    bool set_variable(UObject* owner, const TCHAR* name, double number, UObject* object, const FName* fname);
    double read_number_variable(UObject* owner, const TCHAR* name);
    bool fingers_tracked_on(int side); // the hand's fingers follow yours (then the fist needs no shape)
    bool wrap_active(int side);        // the hand's fingers wrap what the game's grab holds
    int fist_shape(const hsvr::Config& cfg)
    {
        int t = g_fist_shape_test.load();
        return t != -99 ? t : cfg.pose_fist_shape;
    }

    void fingers_after_anim_update(Hook::TCallbackIterationData<void>&, UObject* context, UFunction* function, void*)
    {
        gc_sync();
        HSVR_PROF(PerfFingersAnim);
        if (!g_pose_active.load() || !context || context != g_pose.instance || !function) return;
        if (g_anim_update) { if (function != g_anim_update) return; }
        else
        {
            if (function->GetName() != STR("BlueprintUpdateAnimation")) return;
            g_anim_update = function;
        }
        // A wrapping hand starts from the open hand (the game's own grab shape would be under the wrap).
        if (hsvr::config().pose_wrap_open_base)
            for (int side = 0; side < 2; ++side)
                if (wrap_active(side)) set_bool_property(context, side == 0 ? STR("Grabbed L") : STR("Grabbed R"), false);
        if (!hsvr::config().pose_fingers_anim_only) return;
        static FProperty* prop[2] = {nullptr, nullptr};
        static bool looked = false;
        if (!looked)
        {
            looked = true;
            prop[0] = prop_chain(context, STR("L Grip Type"));
            prop[1] = prop_chain(context, STR("R Grip Type"));
            HSVR_LOG("Fingers: the animation's grip types L %s, R %s (%ls / %ls)", prop[0] ? "found" : "MISSING", prop[1] ? "found" : "MISSING",
                     prop[0] ? prop[0]->GetClass().GetName().c_str() : STR("-"), prop[1] ? prop[1]->GetClass().GetName().c_str() : STR("-"));
        }
        double now = hsvr::now_seconds();
        static int last[2] = {-2, -2};
        for (int side = 0; side < 2; ++side)
        {
            if (!prop[side]) continue;
            int g = side == g_anim_grip_two_side ? g_anim_grip_two : (now - g_anim_grip_time[side] < 0.1 ? g_anim_grip[side] : -1);
            // A fist: the shape chosen for it (pose_fist_shape). The animation's own fist needs 'Hand
            // Active' (0 in VR), so the hand would stay open (playtest 2026-11-19 21:10).
            if (g_fist_side[side].load() && !g_fist_open[side].load() && !fingers_tracked_on(side))
            {
                int shape = fist_shape(hsvr::config());
                if (shape >= 0 && shape <= 17) g = shape;
                else if (shape == -1) set_bool_property(context, side == 0 ? STR("Grabbed L") : STR("Grabbed R"), true);
                else if (shape == 100 || shape == 101)
                {
                    set_bool_property(context, side == 0 ? STR("L Guarding") : STR("R Guarding"), true);
                    if (shape == 101 && read_number_variable(context, STR("Aim Swing Speed")) < 75.0)
                        set_variable(context, STR("Aim Swing Speed"), 75.0, nullptr, nullptr);
                }
            }
            if (g != last[side])
            {
                HSVR_LOG("Fingers: %s hand shows %d%s", side == 0 ? "left" : "right", g, g < 0 ? " (the game's own)" : "");
                last[side] = g;
            }
            if (g < 0) continue;
            uint8_t* at = reinterpret_cast<uint8_t*>(context) + prop[side]->GetOffset_Internal();
            auto kind = prop[side]->GetClass().GetName();
            if (kind == STR("ByteProperty") || kind == STR("EnumProperty")) *at = (uint8_t)g;
            else if (kind == STR("IntProperty")) *reinterpret_cast<int32_t*>(at) = g;
        }
    }

    // ---- Blade & Sorcery's crouch animation (pose_crouch_anim) -----------------------------------
    // Matthew 2026-11-24: "I just want to copy Blade and Sorcery's animation." B&S's crouch clips are
    // humanoid (muscle) clips; tools/bs-crouch bakes them onto Willie's DriverSkeleton (Willie_Lopoly,
    // a T-pose with every body bone's rotation identity) with Unity 2021.3.38f1's own humanoid
    // retargeting, B&S's engine version, foot IK on as B&S's states have it. Each baked file is one
    // clip at 60 samples a second: every listed bone's position and rotation in his component space
    // (UE axes: x his left, y forward, z up; cm), relative to the clip's moving root on the ground.
    //
    // Played as B&S plays them (B&S ThunderRoad Creature.UpdateLocomotionAnimation + the 'Human'
    // AnimatorController's Dual Wield / Unarmed states):
    // - moving: a freeform-directional 2D blend over the 8 Crouch_Walk clips by your local velocity
    //   (B&S's Strafe/Speed, damped 0.1 s); standing still: a 1D blend Crouch_Turn90L / CrouchLoop /
    //   Crouch_Turn90R by the turn rate (B&S's Turn = deg/s x 0.007, thresholds -1.58 / 0 / 1.58).
    //   A blend tree's clips share one normalized time, as Unity's do.
    // - B&S plays the clips at their own speed; here the time runs at your speed over the blended
    //   clips' speed, so the planted foot stays where it was put down.
    // The pose: the hips turn as the clip's do (pose_crouch_anim_hips); his chest is turned back by as
    // much on spine_02, so it faces as before. Each foot goes where the clip has it from the hips,
    // at the clip's height above the floor found under it; the knee bends toward the clip's knee
    // (two-bone solve with his own leg lengths). Thigh, calf and foot keep the clip's own roll.
    // Written as Replace in component space on the end-of-graph Modify Bone nodes (pelvis, then
    // thigh/calf/foot: parent first), faded in and out by their Alpha.
    struct CrouchClip
    {
        std::string name;
        double length = 0.0;
        hsvr::Vec3 velocity;   // the root's, cm/s, his component frame
        double yaw_rate = 0.0; // the root's turn, deg/s (right +)
        // per sample: pelvis rotation; per leg [0 left, 1 right]: thigh, calf, foot positions relative
        // to the pelvis on the ground plane (z: height above the clip's ground), and their rotations
        std::vector<hsvr::Quat> pelvis;
        std::vector<hsvr::Vec3> pos[2][3];
        std::vector<hsvr::Quat> rot[2][3];
        std::vector<double> planted[2]; // 1 = the foot stands still on the clip's ground (under 30 cm/s)
        hsvr::Vec3 foot_mean[2];        // the foot's mean spot from the pelvis over the cycle (stride centre)
    };
    struct CrouchPose
    {
        hsvr::Quat pelvis;
        hsvr::Vec3 pos[2][3];
        hsvr::Quat rot[2][3];
        double planted[2] = {0.0, 0.0};
        hsvr::Vec3 foot_mean[2];
    };
    struct CrouchAnim
    {
        bool loaded = false, tried = false;
        std::vector<CrouchClip> clips;
        int walk[8] = {-1, -1, -1, -1, -1, -1, -1, -1}; // Fwd Lt45 Lt Lt135 Bwd Rt135 Rt Rt45
        int loop = -1, turn_l = -1, turn_r = -1;
        bool on = false;          // wanted
        double fade = 0.0;        // 0..1 shown
        double moving = 0.0;      // 0 standing tree .. 1 walking tree
        double walk_phase = 0.0, idle_phase = 0.0;
        hsvr::Vec3 last_loc;
        double last_yaw = 0.0, last_t = -1.0;
        hsvr::Vec3 vel;           // damped (B&S animationDampTime 0.1 s), component frame
        double yaw_rate = 0.0;    // damped, deg/s
        hsvr::Quat pelvis_anim;   // the animation's own pelvis rotation (component), measured while off
        double floor_z[2] = {0.0, 0.0};
        bool have_floor[2] = {false, false};
        hsvr::Vec3 target_prev_world[2];
        hsvr::Vec3 target_prev_cs[2]; // where the foot was sent last frame, his component space (unscaled)
        bool target_prev_ok[2] = {false, false};
        // log stats since the last line
        double slip_sum = 0.0, slip_worst = 0.0;
        int slip_n = 0;
        double reach_short_worst = 0.0;
    };
    CrouchAnim g_canim;
    std::atomic<int> g_canim_frames{0}; // frames shown at full weight since hsvr.mark (tests)
    // Since hsvr.mark (test readers canim_*): planted-foot slide, drawn foot vs where it was sent, chest turn.
    struct CrouchAnimStats
    {
        double slip_sum = 0, slip_worst = 0; int slip_n = 0;
        double foot_err_sum = 0, foot_err_worst = 0; int foot_err_n = 0;
        double chest_sum = 0, chest_worst = 0; int chest_n = 0;
        double hips_sum = 0; int hips_n = 0;
        double moving_sum = 0; int moving_n = 0;
        double floor_gap_worst = 0; // planted foot's drawn ankle above (or below: negative kept as abs) the floor plus its clip height
    };
    CrouchAnimStats g_canim_stats;
    void crouch_anim_stats_reset() { g_canim_stats = CrouchAnimStats{}; g_canim_frames.store(0); }

    hsvr::Quat qnlerp(const hsvr::Quat& a, hsvr::Quat b, double t)
    {
        if (a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w < 0.0) b = {-b.x, -b.y, -b.z, -b.w};
        return hsvr::Quat{a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t, a.z + (b.z - a.z) * t, a.w + (b.w - a.w) * t}.normalized();
    }
    // The shortest turn taking direction a onto direction b.
    hsvr::Quat swing_between(const hsvr::Vec3& a_raw, const hsvr::Vec3& b_raw)
    {
        using namespace hsvr;
        Vec3 a = normalized(a_raw), b = normalized(b_raw);
        double d = dot(a, b);
        if (d > 0.999999) return {};
        if (d < -0.999999)
        {
            Vec3 axis = normalized(cross(a, std::fabs(a.x) < 0.9 ? Vec3{1, 0, 0} : Vec3{0, 1, 0}));
            return quat_axis_angle(axis, kPi);
        }
        Vec3 c = cross(a, b);
        return Quat{c.x, c.y, c.z, 1.0 + d}.normalized();
    }

    bool crouch_anim_load()
    {
        using namespace hsvr;
        CrouchAnim& A = g_canim;
        A.tried = true;
        static const char* names[] = {"Crouch_WalkFwd_new", "Crouch_WalkLt45_new", "Crouch_WalkLt_new", "Crouch_WalkLt135_new", "Crouch_WalkBwd_new",
                                      "Crouch_WalkRt135_new", "Crouch_WalkRt_new", "Crouch_WalkRt45_new", "CrouchLoop_new", "Crouch_Turn90L_new", "Crouch_Turn90R_new"};
        std::wstring dir = mod_dir() + L"bs-crouch\\";
        std::string missing;
        for (int ci = 0; ci < 11; ++ci)
        {
            std::string nm = names[ci];
            std::wstring path = dir + std::wstring(nm.begin(), nm.end()) + L".csv";
            FILE* f = _wfopen(path.c_str(), L"rb");
            if (!f) { missing += " " + nm; continue; }
            std::string text;
            char buf[65536];
            size_t got;
            while ((got = std::fread(buf, 1, sizeof(buf), f)) > 0) text.append(buf, got);
            std::fclose(f);
            std::vector<std::string> lines;
            {
                size_t at = 0;
                while (at < text.size())
                {
                    size_t e = text.find('\n', at);
                    if (e == std::string::npos) e = text.size();
                    std::string l = text.substr(at, e - at);
                    if (!l.empty() && l.back() == '\r') l.pop_back();
                    if (!l.empty()) lines.push_back(l);
                    at = e + 1;
                }
            }
            if (lines.size() < 3) { missing += " " + nm + "(empty)"; continue; }
            auto split = [](const std::string& l) {
                std::vector<std::string> out;
                size_t at = 0;
                while (true)
                {
                    size_t c = l.find(',', at);
                    out.push_back(l.substr(at, c == std::string::npos ? std::string::npos : c - at));
                    if (c == std::string::npos) break;
                    at = c + 1;
                }
                return out;
            };
            std::vector<std::string> head = split(lines[0]);
            auto col = [&](const std::string& n) {
                for (size_t i = 0; i < head.size(); ++i) if (head[i] == n) return (int)i;
                return -1;
            };
            static const char* bones[2][3] = {{"thigh_l", "calf_l", "foot_l"}, {"thigh_r", "calf_r", "foot_r"}};
            int c_t = col("t"), c_rx = col("root_x"), c_ry = col("root_y"), c_yaw = col("root_yaw");
            int c_p = col("pelvis_x");
            int c_b[2][3];
            bool ok = c_t >= 0 && c_rx >= 0 && c_ry >= 0 && c_yaw >= 0 && c_p >= 0;
            for (int s = 0; s < 2; ++s)
                for (int k = 0; k < 3; ++k) { c_b[s][k] = col(std::string(bones[s][k]) + "_x"); ok = ok && c_b[s][k] >= 0; }
            if (!ok) { missing += " " + nm + "(columns)"; continue; }
            CrouchClip clip;
            clip.name = nm;
            double t_last = 0.0, rx0 = 0, ry0 = 0, rx1 = 0, ry1 = 0, yaw0 = 0, yaw_total = 0, yaw_prev = 0;
            for (size_t li = 1; li < lines.size(); ++li)
            {
                std::vector<std::string> v = split(lines[li]);
                if (v.size() < head.size()) continue;
                auto D = [&](int i) { return std::strtod(v[i].c_str(), nullptr); };
                auto V = [&](int i) { return Vec3{D(i), D(i + 1), D(i + 2)}; };
                auto Q = [&](int i) { return Quat{D(i + 3), D(i + 4), D(i + 5), D(i + 6)}.normalized(); };
                double yaw = D(c_yaw);
                if (li == 1) { rx0 = D(c_rx), ry0 = D(c_ry), yaw0 = yaw_prev = yaw; }
                yaw_total += wrap_deg(yaw - yaw_prev);
                yaw_prev = yaw;
                rx1 = D(c_rx), ry1 = D(c_ry), t_last = D(c_t);
                Vec3 p = V(c_p);
                clip.pelvis.push_back(Q(c_p));
                for (int s = 0; s < 2; ++s)
                    for (int k = 0; k < 3; ++k)
                    {
                        Vec3 b = V(c_b[s][k]);
                        clip.pos[s][k].push_back(Vec3{b.x - p.x, b.y - p.y, b.z});
                        clip.rot[s][k].push_back(Q(c_b[s][k]));
                    }
            }
            (void)yaw0;
            if (clip.pelvis.size() < 3 || t_last <= 0.0) { missing += " " + nm + "(short)"; continue; }
            clip.length = t_last;
            // Root motion is in the starting root's frame; walking clips don't turn, so this is the velocity.
            clip.velocity = Vec3{(rx1 - rx0) / t_last, (ry1 - ry0) / t_last, 0.0};
            clip.yaw_rate = yaw_total / t_last;
            {
                // A foot is planted where it stands still in the clip's world: its move from the pelvis
                // plus the root's (walking clips don't turn; turning clips are judged in the root's frame).
                size_t n = clip.pelvis.size();
                double sdt = t_last / (double)(n - 1);
                for (int sd = 0; sd < 2; ++sd)
                {
                    clip.planted[sd].assign(n, 0.0);
                    Vec3 sum;
                    for (size_t i = 0; i < n; ++i)
                    {
                        size_t j = i + 1 < n ? i + 1 : 1; // looping
                        Vec3 v = (clip.pos[sd][2][j] - clip.pos[sd][2][i]) * (1.0 / sdt) + clip.velocity;
                        v.z = 0.0;
                        clip.planted[sd][i] = length(v) < 30.0 ? 1.0 : 0.0;
                        sum = sum + clip.pos[sd][2][i];
                    }
                    clip.foot_mean[sd] = sum * (1.0 / (double)n);
                    clip.foot_mean[sd].z = 0.0;
                }
            }
            int index = (int)A.clips.size();
            if (ci < 8) A.walk[ci] = index;
            else if (ci == 8) A.loop = index;
            else if (ci == 9) A.turn_l = index;
            else A.turn_r = index;
            HSVR_LOG("CrouchAnim: %s %.2f s, %zu samples, root %.0f cm/s (%.0f, %.0f), turn %.0f deg/s", nm.c_str(), clip.length, clip.pelvis.size(),
                     length(clip.velocity), clip.velocity.x, clip.velocity.y, clip.yaw_rate);
            A.clips.push_back(std::move(clip));
        }
        bool all_walk = true;
        for (int i : A.walk) all_walk = all_walk && i >= 0;
        A.loaded = all_walk && A.loop >= 0 && A.turn_l >= 0 && A.turn_r >= 0;
        std::string dn(dir.begin(), dir.end());
        HSVR_LOG("CrouchAnim: %s: %zu of 11 B&S crouch clips read from %s%s%s", A.loaded ? "ready" : "NOT USED", A.clips.size(), dn.c_str(),
                 missing.empty() ? "" : "; missing:", missing.c_str());
        return A.loaded;
    }

    // A clip's pose at normalized time u (0..1, looping), samples blended linearly.
    void crouch_sample(const CrouchClip& c, double u, CrouchPose& out)
    {
        size_t n = c.pelvis.size();
        u -= std::floor(u);
        double x = u * (double)(n - 1);
        size_t i = (std::min)(n - 2, (size_t)x);
        double f = x - (double)i;
        out.pelvis = qnlerp(c.pelvis[i], c.pelvis[i + 1], f);
        for (int s = 0; s < 2; ++s)
            for (int k = 0; k < 3; ++k)
            {
                out.pos[s][k] = c.pos[s][k][i] + (c.pos[s][k][i + 1] - c.pos[s][k][i]) * f;
                out.rot[s][k] = qnlerp(c.rot[s][k][i], c.rot[s][k][i + 1], f);
            }
        for (int s = 0; s < 2; ++s)
        {
            out.planted[s] = f < 0.5 ? c.planted[s][i] : c.planted[s][i + 1];
            out.foot_mean[s] = c.foot_mean[s];
        }
    }

    // Weighted mix of poses (weights sum to 1); quaternions summed on one hemisphere and normalized.
    void crouch_mix(const std::vector<std::pair<const CrouchPose*, double>>& in, CrouchPose& out)
    {
        using namespace hsvr;
        auto add = [](Quat& acc, const Quat& ref, const Quat& q, double w) {
            Quat b = q;
            if (ref.x * b.x + ref.y * b.y + ref.z * b.z + ref.w * b.w < 0.0) b = {-b.x, -b.y, -b.z, -b.w};
            acc = {acc.x + b.x * w, acc.y + b.y * w, acc.z + b.z * w, acc.w + b.w * w};
        };
        const CrouchPose& r = *in[0].first;
        Quat pel{0, 0, 0, 0};
        Quat rot[2][3];
        for (int s = 0; s < 2; ++s)
            for (int k = 0; k < 3; ++k) { rot[s][k] = {0, 0, 0, 0}; out.pos[s][k] = {}; }
        for (int s = 0; s < 2; ++s) { out.planted[s] = 0.0; out.foot_mean[s] = {}; }
        for (const auto& [p, w] : in)
        {
            add(pel, r.pelvis, p->pelvis, w);
            for (int s = 0; s < 2; ++s) { out.planted[s] += p->planted[s] * w; out.foot_mean[s] = out.foot_mean[s] + p->foot_mean[s] * w; }
            for (int s = 0; s < 2; ++s)
                for (int k = 0; k < 3; ++k)
                {
                    out.pos[s][k] = out.pos[s][k] + p->pos[s][k] * w;
                    add(rot[s][k], r.rot[s][k], p->rot[s][k], w);
                }
        }
        out.pelvis = pel.normalized();
        for (int s = 0; s < 2; ++s)
            for (int k = 0; k < 3; ++k) out.rot[s][k] = rot[s][k].normalized();
    }

    // Unity's freeform directional 2D blend (gradient band interpolation in polar space,
    // directional influence 2), for children with no centre motion.
    void freeform_directional(const hsvr::Vec3* pts, int n, const hsvr::Vec3& p, double* w)
    {
        double sum = 0.0;
        double mp = std::sqrt(p.x * p.x + p.y * p.y);
        for (int i = 0; i < n; ++i)
        {
            double mi = std::sqrt(pts[i].x * pts[i].x + pts[i].y * pts[i].y);
            double best = 1e9;
            for (int j = 0; j < n; ++j)
            {
                if (j == i) continue;
                double mj = std::sqrt(pts[j].x * pts[j].x + pts[j].y * pts[j].y);
                double avg = 0.5 * (mi + mj);
                double a_ij = std::atan2(pts[i].x * pts[j].y - pts[i].y * pts[j].x, pts[i].x * pts[j].x + pts[i].y * pts[j].y);
                double a_ip = mp > 1e-6 ? std::atan2(pts[i].x * p.y - pts[i].y * p.x, pts[i].x * p.x + pts[i].y * p.y) : 0.0;
                double vij0 = (mj - mi) / avg, vij1 = a_ij * 2.0;
                double vip0 = (mp - mi) / avg, vip1 = a_ip * 2.0;
                double h = 1.0 - (vip0 * vij0 + vip1 * vij1) / (vij0 * vij0 + vij1 * vij1);
                best = (std::min)(best, h);
            }
            w[i] = (std::max)(0.0, best);
            sum += w[i];
        }
        for (int i = 0; i < n; ++i) w[i] = sum > 1e-9 ? w[i] / sum : (i == 0 ? 1.0 : 0.0);
    }

    void crouch_anim_release()
    {
        CrouchAnim& A = g_canim;
        for (const char* b : {"pelvis", "thigh_l", "calf_l", "foot_l", "thigh_r", "calf_r", "foot_r"})
            if (ModifyBoneNode* n = chain_node(b))
            {
                if (n->alpha) *reinterpret_cast<float*>(n->node + n->alpha->GetOffset_Internal()) = 1.0f;
                if (std::string(b) == "pelvis" || std::string(b).rfind("foot", 0) != 0) node_release(*n);
            }
        A.target_prev_ok[0] = A.target_prev_ok[1] = false;
    }

    // Called at the end of feet_after_anim_update (his animation update, after the body pose).
    void crouch_anim_apply(const hsvr::Config& cfg)
    {
        using namespace hsvr;
        CrouchAnim& A = g_canim;
        UObject* driver = g_pose.driver ? g_pose.driver : g_pose.mesh;
        UObject* pawn = g_pose.pawn;
        if (!driver || !pawn) return;
        if (!A.tried && cfg.pose_crouch_anim) crouch_anim_load();
        double now = now_seconds();
        double dt = A.last_t < 0.0 ? 0.0 : (std::min)(0.1, (std::max)(0.0, now - A.last_t));
        A.last_t = now;
        Vec3 loc = component_location(driver);
        Quat crot = component_rotation(driver);
        Quat cinv = crot.inverse();
        double scale = (std::max)(1e-3, component_scale_z(driver));
        double yaw = quat_yaw_deg(crot);
        // Test measures of last frame's drawn pose against what was sent (A.fade full both frames).
        if (A.fade >= 1.0)
        {
            CrouchAnimStats& S = g_canim_stats;
            for (int s2 = 0; s2 < 2; ++s2)
                if (A.target_prev_ok[s2])
                {
                    // In his component space: the body moved on since (v x one frame), the pose didn't.
                    Vec3 drawn = cinv.rotate(socket_location(driver, bone_fname(s2 == 0 ? "foot_l" : "foot_r")) - loc) * (1.0 / scale);
                    double e = length(drawn - A.target_prev_cs[s2]);
                    S.foot_err_sum += e, ++S.foot_err_n;
                    S.foot_err_worst = (std::max)(S.foot_err_worst, e);
                }
        }
        {
            // His chest (spine_05) heading against his body's, on or off (the torso twist turns it toward
            // your look; with the animation on, the hips' turn must not add to that).
            CrouchAnimStats& S = g_canim_stats;
            Vec3 cf = cinv.rotate(socket_rotation(driver, bone_fname("spine_05")).rotate(Vec3{0, 1, 0}));
            double chest = std::fabs(std::atan2(-cf.x, cf.y) * kRadToDeg);
            S.chest_sum += chest, ++S.chest_n;
            S.chest_worst = (std::max)(S.chest_worst, chest);
        }
        // Damped local velocity and turn rate (B&S: animationDampTime 0.1 s), from how his body moved.
        if (dt > 0.0)
        {
            Vec3 d = loc - A.last_loc;
            d.z = 0.0;
            if (length(d) < 100.0)
            {
                Vec3 v = cinv.rotate(d * (1.0 / dt));
                v.z = 0.0;
                double k = 1.0 - std::exp(-dt / 0.1);
                A.vel = A.vel + (v - A.vel) * k;
                A.yaw_rate += (wrap_deg(yaw - A.last_yaw) / dt - A.yaw_rate) * k;
            }
        }
        A.last_loc = loc;
        A.last_yaw = yaw;
        // Head height as B&S measures it: your head over his standing head height.
        double stand = 163.0 * scale;
        double h = 1.0 - g_crouch_want_cm / stand;
        bool kicking = g_feet[0].kicking || g_feet[1].kicking;
        bool want = cfg.pose_crouch_anim && A.loaded && cfg.pose_crouch && g_feet_active.load() && !kicking && g_pose.feet_calibrated;
        bool was = A.on;
        if (!want) A.on = false;
        else if (A.on) A.on = h <= cfg.pose_crouch_anim_off_ratio;
        else A.on = h <= cfg.pose_crouch_anim_on_ratio;
        if (A.on != was)
            HSVR_LOG("CrouchAnim: %s (head at %.2f of standing, %.0f cm down%s)", A.on ? "B&S crouch animation on" : "off: back to stepping",
                     h, g_crouch_want_cm, kicking ? ", a kick has a leg" : "");
        double fade_rate = cfg.pose_crouch_anim_fade_s > 0.0 ? dt / cfg.pose_crouch_anim_fade_s : 1.0;
        if (kicking) fade_rate = 1.0;
        A.fade = (std::max)(0.0, (std::min)(1.0, A.fade + (A.on ? fade_rate : -fade_rate)));
        if (A.fade <= 0.0)
        {
            if (was || A.target_prev_ok[0] || A.target_prev_ok[1])
            {
                crouch_anim_release();
                // The stepping feet start where his feet are now.
                for (int side = 0; side < 2; ++side)
                {
                    FootState& f = g_feet[side];
                    if (!f.valid || f.kicking) continue;
                    Vec3 at = socket_location(driver, bone_fname(side == 0 ? "foot_l" : "foot_r"));
                    f.at = {at.x, at.y, 0.0};
                    f.yaw = yaw + 90.0;
                    f.stepping = false;
                }
            }
            // While off, the animation's own pelvis turn (component), for the chest's counter-turn.
            A.pelvis_anim = (cinv * socket_rotation(driver, bone_fname("pelvis"))).normalized();
            A.moving = 0.0;
            return;
        }
        // ---- the blend trees ----
        double speed = length(A.vel);
        double want_moving = speed > cfg.pose_crouch_anim_still_cms ? 1.0 : 0.0;
        A.moving += (std::max)(-fade_rate, (std::min)(fade_rate, want_moving - A.moving));
        CrouchPose walk_pose, idle_pose, pose;
        double walk_w[8] = {0};
        double walk_rate = 0.0, stride = 1.0;
        if (A.moving > 0.0)
        {
            Vec3 pts[8];
            for (int i = 0; i < 8; ++i) pts[i] = A.clips[A.walk[i]].velocity;
            Vec3 p = speed > 1.0 ? A.vel : pts[0] * 0.01;
            freeform_directional(pts, 8, p, walk_w);
            double dur = 0.0;
            Vec3 cv;
            for (int i = 0; i < 8; ++i) { dur += walk_w[i] * A.clips[A.walk[i]].length; cv = cv + A.clips[A.walk[i]].velocity * walk_w[i]; }
            double cs = length(cv);
            // Faster or slower than the clips: cadence and stride share it (time x sqrt, stride x sqrt), so
            // the planted foot still stands still without the legs spinning at double time.
            double ratio = cs > 1.0 ? speed / cs : 1.0;
            walk_rate = (std::min)(1.6, (std::max)(0.5, std::sqrt(ratio)));
            stride = (std::min)(1.6, (std::max)(0.3, ratio / walk_rate));
            A.walk_phase += dur > 1e-3 ? walk_rate * dt / dur : 0.0;
            A.walk_phase -= std::floor(A.walk_phase);
            static CrouchPose parts[8];
            std::vector<std::pair<const CrouchPose*, double>> mix;
            for (int i = 0; i < 8; ++i)
                if (walk_w[i] > 1e-4) { crouch_sample(A.clips[A.walk[i]], A.walk_phase, parts[i]); mix.push_back({&parts[i], walk_w[i]}); }
            crouch_mix(mix, walk_pose);
        }
        double turn_in = A.yaw_rate * 0.007, idle_w[3] = {0, 1, 0};
        if (A.moving < 1.0)
        {
            const double lo = -1.5757067, hi = 1.5813490;
            if (turn_in <= 0.0) { double t = (std::min)(1.0, turn_in / lo); idle_w[0] = t, idle_w[1] = 1.0 - t; }
            else { double t = (std::min)(1.0, turn_in / hi); idle_w[2] = t, idle_w[1] = 1.0 - t; }
            int ids[3] = {A.turn_l, A.loop, A.turn_r};
            double dur = 0.0;
            for (int i = 0; i < 3; ++i) dur += idle_w[i] * A.clips[ids[i]].length;
            A.idle_phase += dur > 1e-3 ? dt / dur : 0.0;
            A.idle_phase -= std::floor(A.idle_phase);
            static CrouchPose parts[3];
            std::vector<std::pair<const CrouchPose*, double>> mix;
            for (int i = 0; i < 3; ++i)
                if (idle_w[i] > 1e-4) { crouch_sample(A.clips[ids[i]], A.idle_phase, parts[i]); mix.push_back({&parts[i], idle_w[i]}); }
            crouch_mix(mix, idle_pose);
        }
        if (A.moving >= 1.0) pose = walk_pose;
        else if (A.moving <= 0.0) pose = idle_pose;
        else crouch_mix({{&idle_pose, 1.0 - A.moving}, {&walk_pose, A.moving}}, pose);

        // ---- onto his body (component space, cm of his unscaled skeleton) ----
        Vec3 pelvis_cs = cinv.rotate(socket_location(driver, bone_fname("pelvis")) - loc) * (1.0 / scale);
        Quat hips = qnlerp(Quat{}, pose.pelvis, (std::max)(0.0, (std::min)(1.0, cfg.pose_crouch_anim_hips)));
        static const Vec3 hip_off[2] = {{9.969193, 0.25973, -2.35398}, {-9.969189, 0.25973, -2.353971}};
        static const char* bn[2][3] = {{"thigh_l", "calf_l", "foot_l"}, {"thigh_r", "calf_r", "foot_r"}};
        Quat wrote[2][3];
        for (int s = 0; s < 2; ++s)
        {
            // His leg lengths (unscaled), from his current bones.
            Vec3 tw = socket_location(driver, bone_fname(bn[s][0])), cw = socket_location(driver, bone_fname(bn[s][1])), fw = socket_location(driver, bone_fname(bn[s][2]));
            double a = length(cw - tw) / scale, b = length(fw - cw) / scale;
            if (a < 10.0 || b < 10.0) { a = 43.33, b = 42.20; }
            Vec3 H = pelvis_cs + hips.rotate(hip_off[s]);
            Vec3 foot_rel = pose.pos[s][2];
            {
                // Stride: the foot's swing about its mean spot, longer or shorter (walking tree only).
                double k = 1.0 + (stride - 1.0) * A.moving;
                Vec3 m = pose.foot_mean[s];
                foot_rel.x = m.x + (foot_rel.x - m.x) * k;
                foot_rel.y = m.y + (foot_rel.y - m.y) * k;
            }
            Vec3 F{pelvis_cs.x + foot_rel.x, pelvis_cs.y + foot_rel.y, 0.0};
            // The floor under that spot (looking through him, weapons and people), from a step above his last floor.
            Vec3 Fw = loc + crot.rotate(F * scale);
            double from_z = A.have_floor[s] ? A.floor_z[s] + 40.0 * scale : socket_location(driver, bone_fname("pelvis")).z;
            if (g_feet[s].have_ground) from_z = (std::min)(from_z, g_feet[s].ground_z - g_pose.ankle_height[s] + 40.0 * scale);
            double fz = 0.0;
            if (ground_below(pawn, Fw.x, Fw.y, from_z, fz)) { A.floor_z[s] = fz; A.have_floor[s] = true; }
            else if (!A.have_floor[s] && g_feet[s].have_ground) { A.floor_z[s] = g_feet[s].ground_z - g_pose.ankle_height[s]; A.have_floor[s] = true; }
            double floor_cs = A.have_floor[s] ? (A.floor_z[s] - loc.z) / scale : 0.0;
            F.z = floor_cs + foot_rel.z;
            // Two-bone solve, bending toward the clip's knee.
            Vec3 d = F - H;
            double L = length(d), Lw = L;
            L = (std::max)(std::fabs(a - b) + 0.5, (std::min)((a + b) * 0.999, L));
            A.reach_short_worst = (std::max)(A.reach_short_worst, Lw - L);
            Vec3 dn = L > 1e-6 ? normalized(d) : Vec3{0, 0, -1};
            Vec3 kdir = pose.pos[s][1] - pose.pos[s][0];
            Vec3 perp = kdir - dn * dot(kdir, dn);
            if (length(perp) < 1e-3) perp = Vec3{0, 1, 0} - dn * dn.y;
            Vec3 e = normalized(perp);
            double cosA = (std::max)(-1.0, (std::min)(1.0, (a * a + L * L - b * b) / (2.0 * a * L)));
            double sinA = std::sqrt((std::max)(0.0, 1.0 - cosA * cosA));
            Vec3 K = H + dn * (a * cosA) + e * (a * sinA);
            Vec3 Fe = H + dn * L;
            Quat thigh = (swing_between(pose.pos[s][1] - pose.pos[s][0], K - H) * pose.rot[s][0]).normalized();
            Quat calf = (swing_between(pose.pos[s][2] - pose.pos[s][1], Fe - K) * pose.rot[s][1]).normalized();
            wrote[s][0] = thigh, wrote[s][1] = calf, wrote[s][2] = pose.rot[s][2];
            // How far the planted foot's spot moves over the floor (a clip foot under 12 cm is down).
            Vec3 Few = loc + crot.rotate(Fe * scale);
            if (pose.planted[s] > 0.99 && A.target_prev_ok[s] && dt > 0.0 && A.fade >= 1.0)
            {
                Vec3 m = Few - A.target_prev_world[s];
                m.z = 0.0;
                double v = length(m) / dt;
                A.slip_sum += v, ++A.slip_n;
                A.slip_worst = (std::max)(A.slip_worst, v);
                g_canim_stats.slip_sum += v, ++g_canim_stats.slip_n;
                g_canim_stats.slip_worst = (std::max)(g_canim_stats.slip_worst, v);
            }
            A.target_prev_world[s] = Few;
            A.target_prev_cs[s] = Fe;
            A.target_prev_ok[s] = true;
        }
        float alpha = (float)A.fade;
        auto put = [&](const char* bone, const Quat& q) {
            if (ModifyBoneNode* n = chain_node(bone))
            {
                node_set_rotation(*n, q);
                if (n->alpha) *reinterpret_cast<float*>(n->node + n->alpha->GetOffset_Internal()) = alpha;
            }
        };
        put("pelvis", hips);
        for (int s = 0; s < 2; ++s)
            for (int k = 0; k < 3; ++k) put(bn[s][k], wrote[s][k]);
        // The chest turned back by the hips' extra turn (spine_02 is additive in component space:
        // its turn is put before the hips' change, so the bones above keep facing as they were).
        Quat delta = (qnlerp(A.pelvis_anim, hips, A.fade) * A.pelvis_anim.inverse()).normalized();
        if (ModifyBoneNode* n = chain_node("spine_02"))
        {
            // What the torso lean put there this frame (or, if nothing wrote it since, what it put before ours).
            static Quat last_written, last_base;
            static bool have_last = false;
            Quat add{};
            uint8_t mode = *(n->node + n->rotation_mode->GetOffset_Internal());
            if (mode == 2)
            {
                double r[3];
                read_three(n->node + n->rotation->GetOffset_Internal(), n->rotation, r);
                add = rot_to_quat(r[0], r[1], r[2]);
                Quat lw = last_written;
                if (have_last && std::fabs(add.x * lw.x + add.y * lw.y + add.z * lw.z + add.w * lw.w) > 0.999999) add = last_base;
            }
            last_base = add;
            last_written = (add * delta.inverse()).normalized();
            have_last = true;
            node_add_rotation(*n, last_written);
        }
        if (A.fade >= 1.0)
        {
            g_canim_frames.fetch_add(1);
            g_canim_stats.hips_sum += 2.0 * std::acos((std::min)(1.0, std::fabs(hips.w))) * kRadToDeg, ++g_canim_stats.hips_n;
            g_canim_stats.moving_sum += A.moving, ++g_canim_stats.moving_n;
        }
        static double last_log = 0.0;
        if (now - last_log >= 0.5)
        {
            last_log = now;
            static const char* wn[8] = {"Fwd", "Lt45", "Lt", "Lt135", "Bwd", "Rt135", "Rt", "Rt45"};
            std::string top;
            for (int i = 0; i < 8; ++i)
                if (walk_w[i] > 0.05) { char part[32]; std::snprintf(part, sizeof(part), " %s %.2f", wn[i], walk_w[i]); top += part; }
            double hips_deg = 2.0 * std::acos((std::min)(1.0, std::fabs(hips.w))) * kRadToDeg;
            HSVR_LOG("CrouchAnim: shown %.2f, head %.2f of standing (%.0f cm down, legs %.0f), moving %.2f at %.0f cm/s (%.0f, %.0f) walk[%s ] phase %.2f x%.2f stride x%.2f; "
                     "still: L %.2f loop %.2f R %.2f (turn %.0f deg/s); hips turned %.0f deg; planted foot slides %.1f cm/s mean, %.1f worst; leg short of the floor %.1f cm",
                     A.fade, h, g_crouch_want_cm, g_crouch_drop, A.moving, speed, A.vel.x, A.vel.y, top.c_str(), A.walk_phase, walk_rate, stride, idle_w[0], idle_w[1], idle_w[2],
                     A.yaw_rate, hips_deg, A.slip_n ? A.slip_sum / A.slip_n : 0.0, A.slip_worst, A.reach_short_worst);
            A.slip_sum = A.slip_worst = A.reach_short_worst = 0.0;
            A.slip_n = 0;
        }
    }

    void feet_after_anim_update(Hook::TCallbackIterationData<void>&, UObject* context, UFunction* function, void*)
    {
        gc_sync();
        HSVR_PROF(PerfFeetAnim);
        using namespace hsvr;
        if (!g_feet_active.load() || !context || context != g_pose.instance || !function) return;
        if (g_anim_update) { if (function != g_anim_update) return; }
        else
        {
            if (function->GetName() != STR("BlueprintUpdateAnimation")) return;
            g_anim_update = function;
        }
        if (!g_effector_looked)
        {
            g_effector_looked = true;
            g_effector[0] = prop_chain(context, STR("Left Foot Effector Location"));
            g_effector[1] = prop_chain(context, STR("Right Foot Effector Location"));
            std::string seen;
            for (UStruct* level = static_cast<UStruct*>(context->GetClassPrivate()); level; level = level->GetSuperStruct())
                for (FProperty* p : level->ForEachProperty())
                {
                    std::wstring n = p->GetName();
                    if (n.find(STR("Effector")) == std::wstring::npos && n.find(STR("Foot")) == std::wstring::npos) continue;
                    if (!seen.empty()) seen += ", ";
                    for (wchar_t ch : n) seen += (char)(ch < 128 ? ch : '?');
                }
            HSVR_LOG("Feet: animation foot targets %s/%s; foot properties in the animation: %s", g_effector[0] ? "found" : "MISSING",
                     g_effector[1] ? "found" : "MISSING", seen.c_str());
        }
        // His legs stay on the leg IK: the animation's kneel and falling branches (ABP_Willie BLB_131
        // R/L Kneel, BLB_29/TWB_22 Kneel Fall, TWB_80 Free Fall Rate) replace the IK'd legs with canned
        // poses that carry their own lower pelvis (crouch_ik.md). At a deep crouch the game's kneel
        // trigger fired and the whole body sank 50-100 cm (playtest 2026-11-18). Cleared in the
        // animation's copy only, after its update reads the pawn; the pawn's own values are untouched.
        if (hsvr::config().pose_crouch_keep_leg_ik)
        {
            static std::vector<FProperty*> clear_bools, clear_numbers;
            static bool looked = false;
            if (!looked)
            {
                looked = true;
                std::string names;
                for (UStruct* level = static_cast<UStruct*>(context->GetClassPrivate()); level; level = level->GetSuperStruct())
                    for (FProperty* p : level->ForEachProperty())
                    {
                        std::wstring n = p->GetName();
                        auto kind = p->GetClass().GetName();
                        bool kneel_flag = kind == STR("BoolProperty") && n.find(STR("Kneel")) != std::wstring::npos;
                        bool fall_rate = (kind == STR("DoubleProperty") || kind == STR("FloatProperty")) && n == STR("Free Fall Rate");
                        if (!kneel_flag && !fall_rate) continue;
                        (kneel_flag ? clear_bools : clear_numbers).push_back(p);
                        if (!names.empty()) names += ", ";
                        for (wchar_t ch : n) names += (char)(ch < 128 ? ch : '?');
                    }
                HSVR_LOG("Crouch: kept off in the animation every frame (legs stay on the IK): %s", names.empty() ? "NONE FOUND" : names.c_str());
            }
            std::string was;
            for (FProperty* p : clear_bools)
            {
                auto* flag = static_cast<FBoolProperty*>(p);
                uint8_t* byte = reinterpret_cast<uint8_t*>(context) + p->GetOffset_Internal() + flag->GetByteOffset();
                if (*byte & flag->GetFieldMask())
                {
                    std::wstring n = p->GetName();
                    was += " ";
                    for (wchar_t ch : n) was += (char)(ch < 128 ? ch : '?');
                }
                *byte &= (uint8_t)~flag->GetFieldMask();
            }
            for (FProperty* p : clear_numbers)
            {
                double v = number_property(context, p);
                if (v > 0.01)
                {
                    char part[48];
                    std::snprintf(part, sizeof(part), " Free Fall Rate %.2f", v);
                    was += part;
                }
                uint8_t* at = reinterpret_cast<uint8_t*>(context) + p->GetOffset_Internal();
                if (p->GetClass().GetName() == STR("DoubleProperty")) *reinterpret_cast<double*>(at) = 0.0;
                else *reinterpret_cast<float*>(at) = 0.0f;
            }
            if (!was.empty()) HSVR_LOG_EVERY(0.5, "Crouch: the animation wanted canned legs (crouch %.0f cm):%s; kept on the leg IK", g_crouch_drop, was.c_str());
        }
        UObject* mesh = g_pose.mesh;
        UObject* pawn = g_pose.pawn;
        if (!mesh || !pawn) return;
        static const FName pelvis = bone_fname("pelvis");
        for (int side = 0; side < 2; ++side)
        {
            FProperty* p = g_effector[side];
            FootState& f = g_feet[side];
            if (!p || !f.valid || f.kicking) continue;
            uint8_t* field = reinterpret_cast<uint8_t*>(context) + p->GetOffset_Internal();
            if (!f.have_ground) continue; // no floor found yet: the game's own target this frame
            Call to(mesh, STR("TransformToBoneSpace"));
            to.name(STR("BoneName"), pelvis);
            to.three(STR("InPosition"), f.at.x, f.at.y, f.ground_z + f.lift);
            if (!to.run()) continue;
            Vec3 out = to.vec(STR("OutPosition"));
            write_three(field, p, out.x, out.y, out.z);
        }
        crouch_anim_apply(hsvr::config());
    }

    // ---- Torso twist ----------------------------------------------------------------------------
    // Your head turns first, then the neck and chest, and the hips last (they follow with the body
    // turning, outside its dead zone). The spine and neck bones share pose_torso_twist of how far
    // your head is turned from the hips, more toward the top, on top of the game's own animation.
    // The head itself is always exactly the headset; the arms are placed in the world, so they stay
    // on your hands whatever the chest does.
    void pose_torso_twist(const hsvr::Config& cfg, bool have_look, const hsvr::Quat& look_rot, double hips_yaw, const hsvr::Quat& component_inv)
    {
        using namespace hsvr;
        static const struct
        {
            const char* bone;
            double weight;
        } chain[] = {{"spine_02", 0.10}, {"spine_03", 0.12}, {"spine_04", 0.14}, {"spine_05", 0.16}, {"neck_01", 0.22}, {"neck_02", 0.26}};
        double rel = 0.0;
        if (have_look && cfg.pose_torso_twist > 0.0)
        {
            rel = quat_yaw_deg(look_rot) - hips_yaw;
            while (rel > 180.0) rel -= 360.0;
            while (rel < -180.0) rel += 360.0;
            rel = (std::max)(-90.0, (std::min)(90.0, rel));
        }
        Vec3 up = component_inv.rotate({0.0, 0.0, 1.0});
        double total = rel * (std::min)(1.0, cfg.pose_torso_twist);
        if (g_lean.calibrated)
        {
            // With the torso lean: the same twist plus the bend (lean_fk, the bones' turns in the body's
            // frame), turned into his component's frame.
            Quat q[6];
            lean_fk(g_lean.fwd, g_lean.side, total, q);
            Quat body = quat_from_yaw_deg(hips_yaw);
            Quat to_comp = component_inv * body;
            for (int i = 0; i < 6; ++i)
            {
                ModifyBoneNode* n = chain_node(kLeanBones[i]);
                if (!n) continue;
                if (total == 0.0 && g_lean.fwd == 0.0 && g_lean.side == 0.0) node_release(*n);
                else node_add_rotation(*n, (to_comp * q[i] * to_comp.inverse()).normalized());
            }
            g_pose.twist_deg = total;
            return;
        }
        for (const auto& link : chain)
        {
            ModifyBoneNode* n = chain_node(link.bone);
            if (!n) continue;
            if (total == 0.0) node_release(*n);
            else node_add_rotation(*n, quat_axis_angle(up, total * link.weight * 3.14159265358979 / 180.0));
        }
        g_pose.twist_deg = total;
    }

