    // Measuring your arm length: arms straight out to the sides, B and Y held together for 2 s. Your
    // wrist-to-wrist span (from the controllers), less his shoulder width (yours is taken as his),
    // halved, is your arm from shoulder to wrist; it goes into the ini (pose_user_arm_cm) and both
    // controllers buzz. Holding B and Y with the arms not spread (under 100 cm) does nothing.
    void measure_arms(const hsvr::ControllerState& state)
    {
        using namespace hsvr;
        static double held_since = -1.0;
        static double done_at = -100.0;
        static bool measured = false;
        double now = now_seconds();
        if (measured && now - done_at < 0.4)
        {
            controllers_buzz(0, 0.8f);
            controllers_buzz(1, 0.8f);
        }
        bool both = state.hand[0].grip_valid && state.hand[1].grip_valid && state.hand[0].secondary && state.hand[1].secondary &&
                    g_pose.hand_valid[0] && g_pose.hand_valid[1];
        if (!both)
        {
            held_since = -1.0;
            return;
        }
        if (held_since < 0.0) held_since = now;
        if (now - held_since < 2.0 || now - done_at < 3.0) return;
        double span = length(g_pose.raw_target[0] - g_pose.raw_target[1]);
        Vec3 sl = socket_location(g_pose.driver, bone_fname("upperarm_l")), sr = socket_location(g_pose.driver, bone_fname("upperarm_r"));
        double shoulders = length(sl - sr);
        double arm = (span - shoulders) * 0.5;
        double his = (g_pose.arm[0].upper_length + g_pose.arm[0].lower_length + g_pose.arm[1].upper_length + g_pose.arm[1].lower_length) * 0.5;
        done_at = now;
        held_since = -1.0;
        measured = false;
        if (span < 100.0 || arm < 35.0 || arm > 110.0)
        {
            HSVR_LOG("Arms: not measured: wrist-to-wrist %.0f cm (his shoulders %.0f apart) gives an arm of %.0f cm, out of range", span, shoulders, arm);
            return;
        }
        char v[32];
        std::snprintf(v, sizeof(v), "%.1f", arm);
        config_set("pose_user_arm_cm", v);
        HSVR_LOG("Arms: measured: wrist-to-wrist %.0f cm, his shoulders %.0f apart, so your arm is %.1f cm (his %.1f): your reach is scaled by %.2f",
                 span, shoulders, arm, his, his / arm);
        measured = true;
    }

    // The shoulder reaches with you (Matthew's choice 2026-11-18, B&S-style): your real reach is
    // longer than your arm (the shoulder blade slides forward and the shoulder lifts when you reach,
    // ~88 cm controller-to-shoulder against a 56 cm arm in his log), so as the hand target nears the
    // end of his arm, his clavicle turns toward it and carries the shoulder up to pose_shoulder_reach_cm
    // closer. It eases in over the last pose_shoulder_reach_start_cm of his reach. Returns where the
    // shoulder (upperarm joint) will be this frame.
    hsvr::Vec3 shoulder_reach(int side, const hsvr::Config& cfg, const hsvr::Vec3& S, const hsvr::Vec3& target, const hsvr::Quat& component_inv)
    {
        using namespace hsvr;
        std::string sx = side_suffix(side);
        ModifyBoneNode* n = chain_node("clavicle" + sx);
        if (!n)
        {
            static bool told[2] = {false, false};
            if (!told[side])
            {
                told[side] = true;
                HSVR_LOG("Pose: %s clavicle has no bone node in his animation, so the shoulder can't reach forward", side == 0 ? "left" : "right");
            }
            return S;
        }
        const ArmCalibration& a = g_pose.arm[side];
        if (!a.clavicle_valid) return S;
        double reach = a.upper_length + a.lower_length;
        // From the clavicle as the chest carries it, not as posed last frame (its socket already
        // carries last frame's turn, which made the shoulder go only part of the way: run 34).
        Vec3 C = socket_location(g_pose.driver, bone_fname("clavicle" + sx));
        Quat Wc = (socket_rotation(g_pose.driver, bone_fname("spine_05")) * a.clavicle_in_chest).normalized();
        Vec3 arm = Wc.rotate(a.shoulder_in_clavicle);
        Vec3 S0 = C + arm;
        double c = length(arm);
        double D = length(target - S0);
        double from = reach - (std::max)(0.0, cfg.pose_shoulder_reach_start_cm), to = reach + (std::max)(0.0, cfg.pose_shoulder_reach_cm);
        double t = cfg.pose_shoulder_reach_cm > 0.0 && to > from ? (std::min)(1.0, (std::max)(0.0, (D - from) / (to - from))) : 0.0;
        t = t * t * (3.0 - 2.0 * t);
        if (t <= 0.0 || c < 1.0)
        {
            node_release(*n);
            return S;
        }
        // Turn the clavicle about its own root so the shoulder moves toward the target.
        Vec3 want = target - C;
        Vec3 axis = cross(arm, want);
        double al = length(axis);
        if (al < 1e-6)
        {
            node_release(*n);
            return S;
        }
        axis = axis * (1.0 / al);
        double angle = (std::min)(cfg.pose_shoulder_reach_cm * t / c, cfg.pose_shoulder_reach_max_deg * kDegToRad);
        Quat dq = quat_axis_angle(axis, angle);
        node_set_rotation(*n, component_inv * (dq * Wc).normalized());
        Vec3 moved = C + dq.rotate(arm);
        // Check: where we said the shoulder would be last frame against where it is now.
        static Vec3 said[2];
        static double last_log[2] = {0.0, 0.0};
        double now = now_seconds();
        if (now - last_log[side] >= 1.0)
        {
            last_log[side] = now;
            HSVR_LOG("Pose: %s shoulder reaches %.0f%%: %.1f cm forward of where the chest has it; last frame's prediction off by %.1f cm", side == 0 ? "left" : "right",
                     t * 100.0, length(moved - S0), length(said[side] - S));
        }
        said[side] = moved;
        return moved;
    }

    // What the arm solve used and made this frame (deep log): shoulder, elbow, hand (world), and what moved
    // the hand off the controller (1 on the held item, 2 two hands, 4 on a scabbard).
    hsvr::Vec3 g_solved_S[2], g_solved_E[2], g_solved_H[2];
    int g_solved_on[2] = {0, 0};
    // An empty hand's arm, corrected after his body is evaluated (pose_arm_fresh_shoulder): the solve
    // reads the shoulder from last frame's pose (BlueprintUpdateAnimation runs before this frame's spine
    // and clavicles are evaluated), so the drawn hand landed off its target by exactly how far the
    // shoulder moved since: about 8 times a second while walking, his footfall rate, 1.0-1.4 cm peak to
    // peak (session 2026-11-22 03:45-04:04: "they are still bouncing and they're still jittering").
    struct ArmFix
    {
        bool want = false;
        hsvr::Vec3 S_cs;      // the shoulder the solve used, in the driver's component space
        unsigned seq = 0;     // one per solve
    };
    ArmFix g_arm_fix[2];
    std::atomic<bool> g_arm_fix_on{true}, g_arm_fix_held{true};
    bool wrap_active(int side);
    // ---- Your injuries (Matthew 2026-11-21) -----------------------------------------------------
    // The game's own limb values (Willie_BP, extracted 2026-11-19; HalfSwordDecomp\defaults\injuries.md):
    // - Limb health 0..100 per arm and leg. Get Damage only tries to break a bone once that limb's
    //   health is <= 25 (Leg L @63550: LessEqual(Leg_L Health, 25)), and a break sets <Limb> Broken,
    //   the joint profile "Broken" and the health to 0 (UG @237298..238581).
    // - A break also sets that part's Dislocation State to 1 (Break Arm R UG @729062). His tick puts
    //   a broken arm back while it swings fast: R/L Hand Active AND Aim Swing Speed > 60 ->
    //   Restore Bone(2 R / 3 L, MRC(Aim Swing Speed, 60..90 -> 0..50) x dt) (UG @358184..358825, the
    //   same in the pre-update game @391401..392042). Restore Bone lowers the state by heal x 0.05
    //   (heal = amount x MRC(state, 1..0 -> 1..0.1)) and at state <= 0 clears Broken and Dislocated,
    //   sets joint "Motor", Pain +15 and health 25 (Restore_Bone @9087..9557). Hand Active is the
    //   mouse button (0 in VR), so the mod makes that call itself (injury_relocate_tick).
    // - Dislocate Bone (the per-tick pose check) is an empty function now; in the pre-update game its
    //   arm constant 0.025 with the tick's strain decay (FInterpTo 0 at 5/s, old UG @392218) kept an
    //   arm's value under 0.04, never its 0.1 threshold, so arms only "dislocated" by breaking.
    // - The tick holds a limb's health at 0 while it is broken, dislocated or cut off (Dismembered
    //   Parts Map / Hand Torn Off; UG @273479 for Arm R), so health covers all three.
    // - A broken or dislocated leg, or a broken back, drops that leg's tonus to 0 (UG @367031/@367531),
    //   and walk speed has x MapRange(Leg R Tonus + Leg L Tonus, 0..2 -> Crawl Rate + 1..2) (UG @567651).
    // So: a limb is badly hurt at health < injury_limb_health (25), broken, dislocated or cut off.
    struct InjuryState
    {
        UObject* pawn = nullptr; // compared only, never read through
        int arm[2] = {0, 0};     // 0 fine, 1 dislocated (flops after the controller), 2 useless (hangs)
        bool leg_out[2] = {false, false};
        bool back_broken = false, dead = false, down = false, down_now = false;
        double leg_speed = 1.0;  // share of the stick's walk speed
        hsvr::Vec3 p[2], v[2];   // the hanging/flopping wrist point
        bool p_valid[2] = {false, false};
        double t[2] = {0.0, 0.0};
        double last_log = -10.0;
        // Your controller's wrist point (world) each frame, for swinging a broken arm back in.
        hsvr::Vec3 ctrl[2], ctrl_rel[2];
        bool ctrl_valid[2] = {false, false}, rel_valid[2] = {false, false};
        double ctrl_v[2] = {0.0, 0.0}, relocate_t = -1.0, relocate_log[2] = {-10.0, -10.0};
    };
    InjuryState g_inj;
    double g_inj_fake_swing_v[2] = {0.0, 0.0}, g_inj_fake_swing_until[2] = {-1.0, -1.0}; // test (hsvr.injury_fake_swing)

    // A Double property of his, read without the per-call class-name check (per-frame path).
    double pawn_double(UObject* pawn, const TCHAR* name)
    {
        FProperty* p = pawn ? prop_chain(pawn, name) : nullptr;
        if (!p) return -1.0;
        static std::unordered_map<FProperty*, int> kinds;
        auto it = kinds.find(p);
        int kind = 0;
        if (it == kinds.end())
        {
            auto k = p->GetClass().GetName();
            kind = k == STR("DoubleProperty") ? 1 : (k == STR("FloatProperty") ? 2 : 0);
            kinds.emplace(p, kind);
        }
        else
            kind = it->second;
        uint8_t* at = reinterpret_cast<uint8_t*>(pawn) + p->GetOffset_Internal();
        if (kind == 1) return *reinterpret_cast<double*>(at);
        if (kind == 2) return *reinterpret_cast<float*>(at);
        return -1.0;
    }

    void injury_update(const hsvr::Config& cfg, UObject* pawn)
    {
        if (pawn != g_inj.pawn)
        {
            g_inj = InjuryState{};
            g_inj.pawn = pawn;
        }
        if (!pawn) return;
        int arm_was[2] = {g_inj.arm[0], g_inj.arm[1]};
        bool leg_was[2] = {g_inj.leg_out[0], g_inj.leg_out[1]}, back_was = g_inj.back_broken, dead_was = g_inj.dead, down_was = g_inj.down;
        g_inj.dead = cfg.death_ragdoll && bool_property(pawn, STR("DED"));
        double hp[4] = {-1, -1, -1, -1};
        bool brk[4] = {}, dis[4] = {};
        if (!cfg.injury_limbs)
        {
            g_inj.arm[0] = g_inj.arm[1] = 0;
            g_inj.leg_out[0] = g_inj.leg_out[1] = false;
            g_inj.back_broken = false;
        }
        else
        {
            static const TCHAR* health[4] = {STR("Arm_L Health"), STR("Arm_R Health"), STR("Leg_L Health"), STR("Leg_R Health")};
            static const TCHAR* broken[4] = {STR("Arm L Broken"), STR("Arm R Broken"), STR("Leg L Broken"), STR("Leg R Broken")};
            static const TCHAR* disloc[4] = {STR("Arm L Dislocated"), STR("Arm R Dislocated"), STR("Leg L Dislocated"), STR("Leg R Dislocated")};
            double thr = cfg.injury_limb_health;
            for (int i = 0; i < 4; ++i)
            {
                hp[i] = pawn_double(pawn, health[i]);
                brk[i] = bool_property(pawn, broken[i]);
                dis[i] = bool_property(pawn, disloc[i]);
                // Below the threshold (a bone put back is set to exactly 25, and that arm works again).
                bool bad = brk[i] || dis[i] || (hp[i] >= 0.0 && hp[i] < thr);
                if (i < 2) g_inj.arm[i] = !bad ? 0 : (dis[i] && !brk[i] ? 1 : 2);
                else g_inj.leg_out[i - 2] = bad;
            }
            g_inj.back_broken = bool_property(pawn, STR("Back Broken"));
        }
        bool legs_gone = cfg.injury_limbs && ((g_inj.leg_out[0] && g_inj.leg_out[1]) || (cfg.injury_back_broken_falls && g_inj.back_broken));
        g_inj.down = g_inj.dead || (cfg.injury_two_legs_fall && legs_gone);
        g_inj.leg_speed = 1.0;
        double tl = -1.0, tr = -1.0;
        if (legs_gone)
            g_inj.leg_speed = 0.0;
        else if (cfg.injury_limbs && g_inj.leg_out[0] != g_inj.leg_out[1])
        {
            // The game already slows him by the bad leg's tonus; scale the stick so the result is
            // injury_one_leg_speed of what he'd walk with the good leg's tonus on both.
            tl = pawn_double(pawn, STR("Leg L Tonus"));
            tr = pawn_double(pawn, STR("Leg R Tonus"));
            double cr = (std::max)(0.0, pawn_double(pawn, STR("Crawl Rate")));
            auto f = [cr](double sum) { double u = (std::min)(1.0, (std::max)(0.0, sum / 2.0)); return (cr + 1.0) + u * (1.0 - cr); };
            double good = (std::max)(0.0, g_inj.leg_out[0] ? tr : tl);
            double have = f((std::max)(0.0, tl) + (std::max)(0.0, tr)), ref = f(2.0 * good);
            g_inj.leg_speed = have > 1e-3 ? (std::min)(1.0, (std::max)(0.0, cfg.injury_one_leg_speed * ref / have)) : cfg.injury_one_leg_speed;
        }
        bool changed = arm_was[0] != g_inj.arm[0] || arm_was[1] != g_inj.arm[1] || leg_was[0] != g_inj.leg_out[0] || leg_was[1] != g_inj.leg_out[1] ||
                       back_was != g_inj.back_broken || dead_was != g_inj.dead || down_was != g_inj.down;
        double now = hsvr::now_seconds();
        bool any = g_inj.arm[0] || g_inj.arm[1] || g_inj.leg_out[0] || g_inj.leg_out[1] || g_inj.back_broken || g_inj.dead;
        if (changed || (any && now - g_inj.last_log >= 2.0))
        {
            g_inj.last_log = now;
            static const char* arm_text[3] = {"ok", "DISLOCATED (flops)", "USELESS (hangs; a broken one swings back in)"};
            HSVR_LOG("Injury%s: left arm %s (health %.0f, broken %d, dislocated %d, disloc state %.2f), right arm %s (health %.0f, broken %d, dislocated %d, disloc state %.2f); "
                     "left leg %s (health %.0f, broken %d, dislocated %d), right leg %s (health %.0f, broken %d, dislocated %d); back broken %d; walk speed x%.2f; %s",
                     changed ? " changed" : "", arm_text[g_inj.arm[0]], hp[0], (int)brk[0], (int)dis[0], pawn_double(pawn, STR("Arm L Dislocation State")),
                     arm_text[g_inj.arm[1]], hp[1], (int)brk[1], (int)dis[1], pawn_double(pawn, STR("Arm R Dislocation State")),
                     g_inj.leg_out[0] ? "OUT" : "ok", hp[2], (int)brk[2], (int)dis[2], g_inj.leg_out[1] ? "OUT" : "ok", hp[3], (int)brk[3], (int)dis[3],
                     (int)g_inj.back_broken, g_inj.leg_speed, g_inj.dead ? "DEAD (ragdoll)" : (g_inj.down ? "DOWN (both legs: fallen)" : "standing"));
        }
    }

    // Swinging a broken arm back in: his tick's own call (see above), which needs "R/L Hand Active"
    // (0 in VR), made by the mod with that hand's own swing speed: your controller's wrist speed
    // relative to his body, mapped pose_swing_speed_lo..hi m/s -> Aim Swing Speed 0..75 as the swing
    // feed does (the hurt hand holds nothing, so the feed itself leaves it out).
    void injury_relocate_tick(const hsvr::Config& cfg, UObject* pawn)
    {
        using namespace hsvr;
        double now = now_seconds(), dt = g_inj.relocate_t > 0.0 ? now - g_inj.relocate_t : 0.0;
        g_inj.relocate_t = now;
        if (!pawn || g_inj.dead) return;
        Vec3 body = actor_location(pawn);
        double lo = cfg.pose_swing_speed_lo, hi = (std::max)(lo + 0.1, cfg.pose_swing_speed_hi);
        static const TCHAR* state_name[2] = {STR("Arm L Dislocation State"), STR("Arm R Dislocation State")};
        static const TCHAR* broken_name[2] = {STR("Arm L Broken"), STR("Arm R Broken")};
        for (int side = 0; side < 2; ++side)
        {
            Vec3 rel = g_inj.ctrl[side] - body;
            if (g_inj.ctrl_valid[side] && g_inj.rel_valid[side] && dt > 1e-4 && dt < 0.1)
            {
                double v = length(rel - g_inj.ctrl_rel[side]) / dt / 100.0; // m/s
                g_inj.ctrl_v[side] += (v - g_inj.ctrl_v[side]) * (1.0 - std::exp(-dt / 0.03)); // ~30 ms, like the feed
            }
            else
                g_inj.ctrl_v[side] = 0.0;
            g_inj.ctrl_rel[side] = rel;
            g_inj.rel_valid[side] = g_inj.ctrl_valid[side];
            if (!cfg.injury_limbs || !cfg.injury_swing_relocate || dt <= 0.0 || dt >= 0.1) continue;
            // Only an arm the game counts as out of place (broken, or a Dislocation State left from a
            // break; Restore Bone also clears Broken once the state has decayed to 0); a healthy or
            // cut-off arm's swing is left to the game's own rules.
            double state = pawn_double(pawn, state_name[side]);
            bool out_of_place = state > 0.0 || bool_property(pawn, broken_name[side]);
            if (!out_of_place || g_inj.arm[side] == 0) continue;
            double v = g_inj.ctrl_v[side];
            if (now < g_inj_fake_swing_until[side]) v = g_inj_fake_swing_v[side];
            double ass = v <= lo ? 0.0 : (std::min)(75.0, (v - lo) / (hi - lo) * 75.0);
            double rate = ass <= 60.0 ? 0.0 : (std::min)(1.0, (ass - 60.0) / 30.0) * 50.0; // MRC(ASS, 60..90 -> 0..50)
            if (rate <= 0.0) continue;
            Call c(pawn, STR("Restore Bone"));
            if (!c.fn)
            {
                if (now - g_inj.relocate_log[side] > 30.0)
                {
                    g_inj.relocate_log[side] = now;
                    HSVR_LOG("Injury: no Restore Bone on his Willie: a broken arm can't be swung back in");
                }
                continue;
            }
            c.byte(STR("Body Part"), side == 0 ? 3 : 2);
            c.number(STR("Amount"), rate * dt);
            c.flag(STR("Regeneration"), false);
            c.run();
            double after = pawn_double(pawn, state_name[side]);
            bool brk = bool_property(pawn, broken_name[side]);
            if (now - g_inj.relocate_log[side] >= 0.5 || !brk)
            {
                g_inj.relocate_log[side] = now;
                HSVR_LOG("Injury: %s arm swung at %.1f m/s (swing speed %.0f): Restore Bone(%.2f), dislocation state %.3f -> %.3f, broken %d%s", side == 0 ? "left" : "right", v,
                         ass, rate * dt, state, after, (int)brk, brk ? "" : ": PUT BACK");
            }
        }
    }

    void set_simulate(UObject* mesh, bool simulate, bool report);
    // Dead, or fallen with both legs out: the mod stops posing him (the game's body, physics on, as
    // in the flat game) and the view follows his head bone. Back up when a leg recovers (not dead).
    // Returns true while he is down (pose_body does nothing else then).
    bool injury_down_tick(const hsvr::Config& cfg, UObject* pawn, UObject* mesh)
    {
        injury_update(cfg, pawn);
        injury_relocate_tick(cfg, pawn);
        if (g_inj.down)
        {
            if (!g_inj.down_now)
            {
                g_inj.down_now = true;
                for (auto& [bone, n] : g_pose.chain) node_release(n);
                for (int side = 0; side < 2; ++side) ghost_hand(side, cfg, false, hsvr::Vec3{}, hsvr::Quat{});
                set_simulate(mesh, true, true);
                g_pose_anchor_fixed = false; // the view sits on his head bone
                g_turn_valid = false;
                HSVR_LOG("Injury: %s: physics on, the mod stops posing you; the view stays on his head", g_inj.dead ? "you died, he ragdolls" : "both legs out, he falls over");
            }
            g_pose_active.store(false);
            g_hold_capsule.store(false);
            g_wall_ok_have = false; // swept from where he gets up, not from where he fell
            g_kept_have = false;
            return true;
        }
        if (g_inj.down_now)
        {
            g_inj.down_now = false;
            set_simulate(mesh, false, true);
            g_pose_anchor_fixed = true;
            feet_reset();
            HSVR_LOG("Injury: a leg recovered: physics off, posed from the headset again");
        }
        return false;
    }

    // The wrist point of a hurt arm, from his shoulder S (radius R = his arm): mode 2 hangs and swings
    // under gravity; mode 1 (dislocated) flops after the controller's wrist point.
    hsvr::Vec3 injury_arm_point(int side, int mode, const hsvr::Config& cfg, const hsvr::Vec3& S, double R, const hsvr::Vec3& controller_wrist,
                                const hsvr::Quat& body, double out)
    {
        using namespace hsvr;
        double now = now_seconds(), dt = now - g_inj.t[side];
        g_inj.t[side] = now;
        Vec3& p = g_inj.p[side];
        Vec3& v = g_inj.v[side];
        if (!g_inj.p_valid[side] || !(dt > 0.0 && dt < 0.2))
        {
            p = g_pose.target[side];
            if (length(p - S) < 1.0 || length(p - S) > 3.0 * R) p = controller_wrist;
            v = Vec3{};
            g_inj.p_valid[side] = true;
            dt = 0.0;
        }
        int n = (std::max)(1, (int)std::ceil(dt / 0.004));
        double h = dt / n;
        double w = 1.0 / (std::max)(0.02, cfg.injury_dislocated_follow_s);
        Vec3 chest = socket_location(g_pose.driver, bone_fname("spine_05"));
        Quat inv = body.inverse();
        double min_side = inv.rotate(S - chest).y * out - 4.0;
        for (int i = 0; i < n; ++i)
        {
            Vec3 acc;
            if (mode == 1)
            {
                Vec3 want = controller_wrist - Vec3{0.0, 0.0, cfg.injury_dislocated_sag_cm};
                acc = (want - p) * (w * w) - v * (2.0 * 0.5 * w); // under-damped: it flops
            }
            else
                acc = Vec3{0.0, 0.0, -980.0} - v * 2.5;
            v = v + acc * h;
            p = p + v * h;
            Vec3 d = p - S;
            double L = length(d);
            if (L > R && L > 1e-6)
            {
                Vec3 nrm = d * (1.0 / L);
                p = S + nrm * R;
                double vr = dot(v, nrm);
                if (vr > 0.0) v = v - nrm * vr;
            }
            // Not into his side: no nearer his middle than his shoulder (less 4 cm).
            Vec3 lp = inv.rotate(p - chest);
            if (lp.y * out < min_side)
            {
                lp.y = out * min_side;
                p = chest + body.rotate(lp);
                Vec3 lv = inv.rotate(v);
                if (lv.y * out < 0.0) lv.y = 0.0;
                v = body.rotate(lv);
            }
        }
        return p;
    }

    bool xbow_test_grip(int side, hsvr::Vec3& grip, hsvr::Quat& grip_rot);
    // Test aid hsvr.ctl_replay <track file> [blend s] / off: both pretend controllers play back Matthew's own recorded motion,
    // in his body's frame (position from the actor, yaw only), looped. A track is a replay capture cut down by
    // tools/replay/ctl_track.py (t, actor x y z yaw, then each hand's controller x y z qx qy qz qw, world). Made for two-hand
    // jitter (playtest 2026-11-23 19:00Z), which the rig's smooth made-up paths never showed.
    struct CtlTrack
    {
        std::vector<std::array<double, 19>> rows; // t, ax, ay, az, yaw, l(7), r(7)
        bool on = false;
        double start = -1.0, blend = 0.5;
        hsvr::Vec3 from_p[2];
        hsvr::Quat from_q[2];
        bool from_set[2] = {false, false};
    };
    CtlTrack g_ctl_track;
    // Test aid hsvr.hold_rebase <side>: that hand's hold takes the weapon's turn in the hand as it is NOW (as if grabbed so). With
    // his replayed wrists the rig's grab turn was not his: the main wrist aimed the polehammer 135 deg from where his two hands
    // put it and the turn sat at its cap for the whole replay (runs 4750e14 / 6cec1f5). Cleared on a new case or weapon.
    std::atomic<bool> g_hold_rebase_req[2] = {false, false};
    hsvr::Quat g_hold_rebase[2];
    UObject* g_hold_rebase_for[2] = {nullptr, nullptr};
    bool ctl_track_load(const std::string& file, double blend)
    {
        std::wstring path(file.begin(), file.end());
        if (path.find(L':') == std::wstring::npos) path = hsvr::mod_dir() + path;
        FILE* f = _wfopen(path.c_str(), L"rb");
        if (!f) return false;
        CtlTrack t;
        char line[1024];
        while (fgets(line, sizeof line, f))
        {
            if (line[0] == '#' || line[0] == 't') continue;
            std::array<double, 19> r{};
            int n = 0;
            char* p = line;
            while (n < 19 && *p)
            {
                char* e = nullptr;
                r[n] = strtod(p, &e);
                if (e == p) break;
                ++n;
                p = e;
                if (*p == ',') ++p;
            }
            if (n == 19) t.rows.push_back(r);
        }
        fclose(f);
        if (t.rows.size() < 2) return false;
        t.on = true;
        t.start = hsvr::now_seconds();
        t.blend = (std::max)(0.0, blend);
        g_ctl_track = t;
        return true;
    }
    void ctl_track_grip(int side, hsvr::Vec3& grip, hsvr::Quat& grip_rot)
    {
        using namespace hsvr;
        CtlTrack& t = g_ctl_track;
        if (!t.on || !g_pose.pawn) return;
        double now = now_seconds();
        double t0 = t.rows.front()[0], len = t.rows.back()[0] - t0;
        if (len <= 0.0) return;
        double at = t0 + std::fmod(now - t.start, len);
        size_t i = 0;
        while (i + 2 < t.rows.size() && t.rows[i + 1][0] < at) ++i;
        const auto& a = t.rows[i];
        const auto& b = t.rows[i + 1];
        double u = b[0] > a[0] ? (std::min)(1.0, (std::max)(0.0, (at - a[0]) / (b[0] - a[0]))) : 0.0;
        int o = 5 + side * 7;
        auto pose_of = [&](const std::array<double, 19>& r, Vec3& lp, Quat& lq) {
            Quat yaw = quat_from_yaw_deg(r[4]);
            lp = yaw.inverse().rotate(Vec3{r[o], r[o + 1], r[o + 2]} - Vec3{r[1], r[2], r[3]});
            lq = (yaw.inverse() * Quat{r[o + 3], r[o + 4], r[o + 5], r[o + 6]}).normalized();
        };
        Vec3 pa, pb;
        Quat qa, qb;
        pose_of(a, pa, qa);
        pose_of(b, pb, qb);
        if (qa.x * qb.x + qa.y * qb.y + qa.z * qb.z + qa.w * qb.w < 0.0) qb = Quat{-qb.x, -qb.y, -qb.z, -qb.w};
        Vec3 lp = pa + (pb - pa) * u;
        Quat lq = Quat{qa.x + (qb.x - qa.x) * u, qa.y + (qb.y - qa.y) * u, qa.z + (qb.z - qa.z) * u, qa.w + (qb.w - qa.w) * u}.normalized();
        Call rc(g_pose.pawn, STR("K2_GetActorRotation"));
        rc.run();
        Quat yaw_now = quat_from_yaw_deg(rc.vec().y);
        Vec3 p = actor_location(g_pose.pawn) + yaw_now.rotate(lp);
        Quat q = (yaw_now * lq).normalized();
        // Eased in from wherever the rig had the hand over the first blend seconds.
        if (!t.from_set[side]) t.from_p[side] = grip, t.from_q[side] = grip_rot, t.from_set[side] = true;
        double e = t.blend > 0.0 ? (std::min)(1.0, (now - t.start) / t.blend) : 1.0;
        if (e < 1.0)
        {
            e = e * e * (3.0 - 2.0 * e);
            Quat fq = t.from_q[side];
            if (fq.x * q.x + fq.y * q.y + fq.z * q.z + fq.w * q.w < 0.0) fq = Quat{-fq.x, -fq.y, -fq.z, -fq.w};
            p = t.from_p[side] + (p - t.from_p[side]) * e;
            q = Quat{fq.x + (q.x - fq.x) * e, fq.y + (q.y - fq.y) * e, fq.z + (q.z - fq.z) * e, fq.w + (q.w - fq.w) * e}.normalized();
        }
        grip = p;
        grip_rot = q;
    }
    void pose_arm(int side, const hsvr::Config& cfg, const hsvr::ControllerState& state, const hsvr::Quat& body, const hsvr::Quat& component_inv)
    {
        using namespace hsvr;
        ArmCalibration& a = g_pose.arm[side];
        const HandState& hs = state.hand[side];
        if (!a.valid) return;
        std::string sx = side_suffix(side);
        double out = side == 0 ? -1.0 : 1.0;
        Vec3 grip;
        Quat grip_rot;
        bool kbm = g_kbm.load();
        bool tracked = !kbm && !cfg.dev_pose_fake_tracking && hs.grip_valid && stereo_tracking_to_world(hs.grip, grip, grip_rot);
        if (!tracked)
        {
            if (!cfg.dev_pose_fake_tracking || kbm)
            {
                // No controller (playing with mouse and keyboard, or tracking lost): the game's own arms.
                for (const char* b : {"clavicle", "upperarm", "lowerarm", "hand"})
                    if (ModifyBoneNode* n = chain_node(std::string(b) + sx)) node_release(*n);
                g_pose.hand_valid[side] = false;
                ghost_hand(side, cfg, false, Vec3{}, Quat{});
                return;
            }
            // Made-up path for unattended tests (dev_script "hsvr.arm_move <mode>"): 0 each hand circles
            // slowly in front of its shoulder; 1 holds still; 2 slow swing and 3 fast swing (side to
            // side and down, a cut); 4 raised overhead; 5 pushed down through the floor; 6 reaching out
            // 54-70 cm in front of the shoulder (past his 53 cm arm).
            Vec3 shoulder = socket_location(g_pose.driver, bone_fname("upperarm" + sx));
            int mode = g_fake_arm_mode.load();
            double now = now_seconds();
            Vec3 local;
            if (mode == 1) local = Vec3{40.0, out * 15.0, -10.0};
            else if (mode == 2 || mode == 3)
            {
                double t = now * (mode == 2 ? 1.2 : 6.0) + side * 0.3;
                local = Vec3{45.0, out * 10.0 + 35.0 * std::sin(t), 5.0 - 30.0 * std::fabs(std::sin(t))};
            }
            else if (mode == 21)
            {
                // Whoosh test: a wide cut side to side and down, hsvr.arm_move 21 <rad/s> (hand peak
                // speed 55 cm x that; 20 = 11 m/s, a hard real swing).
                double w = (std::max)(1.0, g_fake_two_up.load());
                double t = now * w + side * 0.3;
                local = Vec3{45.0, out * 10.0 + 55.0 * std::sin(t), 5.0 - 30.0 * std::fabs(std::sin(t))};
            }
            else if (mode == 22)
            {
                // Grab-slip test: hsvr.arm_move 22 <up cm> <cm/s>: as mode 1, the right hand rising <up> cm
                // at <cm/s> (default 80) from when the command came.
                static int epoch_seen = -1;
                static double since = 0.0;
                if (epoch_seen != g_fake_arm_epoch.load()) epoch_seen = g_fake_arm_epoch.load(), since = now;
                double speed = g_fake_thrust_pitch.load() > 0.0 ? g_fake_thrust_pitch.load() : 80.0;
                // Optional 4th number: the height it starts from (hsvr.arm_move 22 <to> <cm/s> <from>).
                double from = g_fake_thrust_up.load(), to = g_fake_two_up.load();
                double moved = speed * (now - since);
                double up = side == 1 ? (to >= from ? (std::min)(to, from + moved) : (std::max)(to, from - moved)) : 0.0;
                local = Vec3{40.0, out * 15.0, -10.0 + up};
            }
            else if (mode == 4) local = Vec3{15.0, out * 15.0, 45.0};
            else if (mode == 5) local = Vec3{45.0, out * 15.0, -175.0}; // under the floor: the weapon is stopped by the ground
            else if (mode == 6) local = Vec3{62.0 + 8.0 * std::sin(now * 1.0), out * 10.0, 5.0}; // reaching out past his arm: the shoulder reaches
            else if (mode == 10)
            {
                // Stab test: the left hand still; the right thrusts straight ahead from 20 to 62 cm
                // at hsvr.arm_move 10 <speed> cm/s, holds 0.4 s, draws back over 0.8 s, waits; every 2.5 s.
                local = Vec3{40.0, out * 15.0, -10.0};
                if (side == 1)
                {
                    double v = (std::max)(20.0, g_fake_two_up.load());
                    double t_in = 42.0 / v;
                    double t = std::fmod(now, 2.5);
                    double x = 20.0;
                    if (g_fake_two_up.load() < 1.0) t = 99.0; // speed 0: held back, aiming only
                    if (t < t_in) x = 20.0 + v * t;
                    else if (t < t_in + 0.4) x = 62.0;
                    else if (t < t_in + 1.2) x = 62.0 - 42.0 * (t - t_in - 0.4) / 0.8;
                    local = Vec3{x, out * 5.0, g_fake_thrust_up.load()};
                }
            }
            else if ((mode == 8 || mode == 9) && g_pose.pawn && mouth_point(g_pose.pawn, grip))
            {
                // At his mouth (eating and drinking tests): the hand a little in front of and below it.
                local = body.inverse().rotate(grip - shoulder) + Vec3{6.0, 0.0, -4.0};
            }
            else if (mode == 7 || mode == 23 || mode == 24)
            {
                // (23: as 7, the right wrist rolling +-45 deg about the controller's forward axis at 1 Hz, the
                // hands still: a stick must only roll. 24: as 7, the left hand pushing 15 cm side to side at
                // 0.5 Hz, the right still: a stick must swing about the right hand. War staff tests.)
                // Two hands on one weapon: the right still (as mode 1); the left hsvr.arm_move 7 <cm>
                // from it along the weapon the right hand holds (+ toward the tip, - toward the pommel),
                // or straight up when it holds none.
                shoulder = socket_location(g_pose.driver, bone_fname("upperarm_r"));
                local = Vec3{40.0, 15.0, -10.0};
                if (side == 0)
                {
                    Vec3 along{0, 0, 1};
                    UObject* held = g_pose.pawn ? object_property(g_pose.pawn, STR("Weapon R")) : nullptr;
                    UObject* wb = held ? object_property(held, STR("BaseMesh")) : nullptr;
                    if (wb) along = body.inverse().rotate(component_rotation(wb).rotate(Vec3{0, 0, 1}));
                    // Along where the weapon actually hangs, as a real hand reaches for the handle where it is. (456cfc5 used the right
                    // hold's target axis instead: the left hand then missed drooping long weapons by 12-29 cm and never took them,
                    // run 2 2026-11-23: polehammer, war staff, mace, crossbow.)
                    // Once both hands hold it, the left target stays where it was put (in his body's frame), as
                    // a real hand would: following the weapon's own axis let a drooping weapon pull the hand
                    // down after it (joint-hold test 2026-11-22: the staff fell 87 deg and kept wandering).
                    // (Kept from when the command came: kept from when two hands took hold, it was the axis
                    // of a staff already drooping in one hand, 2026-11-22 r2.)
                    static Vec3 kept_along{0, 0, 1};
                    static Vec3 kept_line{0, 0, 0};
                    static int kept_epoch = -1;
                    static UObject* kept_for = nullptr;
                    if (kept_epoch != g_fake_arm_epoch.load() || kept_for != held)
                    {
                        kept_epoch = g_fake_arm_epoch.load();
                        kept_for = held;
                        kept_along = along;
                        kept_line = Vec3{};
                        // With the "onto the line" flag: from the weapon's own grip point and axis, not from the right controller
                        // (a69b19e+3d47c22 switch_polehammer: after the cut the polehammer hung 11-29 cm off the line through the
                        // right controller, and every retake missed). Taken once per command, kept in his body's frame as above.
                        if (wb && g_fake_two_online.load())
                        {
                            Vec3 r = shoulder + body.rotate(local);
                            Vec3 p0 = component_location(wb);
                            Vec3 a = component_rotation(wb).rotate(Vec3{0, 0, 1});
                            Vec3 on = p0 + a * dot(r - p0, a);
                            kept_line = body.inverse().rotate(on - r);
                        }
                    }
                    along = kept_along;
                    (void)&two_hands_hold;
                    local = local + kept_line + along * g_fake_two_up.load();
                    if (mode == 24) local = local + Vec3{0.0, 15.0 * std::sin(now * 3.14159265358979), 0.0};
                }
            }
            else
            {
                double t = now * 1.5 + side * 1.5;
                local = Vec3{35.0 + 10.0 * std::sin(t), out * 15.0, -15.0 + 20.0 * std::cos(t)};
            }
            grip = shoulder + body.rotate(local);
            if (mode == 15 && side == 1 && g_pose.pawn)
            {
                Vec3 circle = grip; // where the made-up path has the hand this frame: the reach starts from it
                // Pickup test: the right controller this high above the grip point of the nearest loose
                // weapon (one no one holds, not sheathed), as a hand reaching for it on the floor.
                static UObject* item = nullptr;
                static bool item_tracked = track_freed(&item);
                static double found_at = -1.0;
                // Once in his hand it is kept, not looked for again: the controller stays put rather than jumping back
                // to the made-up circle (run 11 floor_kick: "target jumped 81 cm in 14 ms" 0.6 s after the pickup, the
                // crouched arm could not follow and the stretch let-go dropped it).
                bool in_hand = item && (object_property(g_pose.pawn, STR("Weapon R")) == item || object_property(g_pose.pawn, STR("Weapon L")) == item);
                if (!in_hand && (!item || now - found_at > 1.0))
                {
                    found_at = now;
                    item = nullptr;
                    std::vector<UObject*> ws;
                    UObjectGlobals::FindAllOf(STR("ModularWeaponBP_C"), ws);
                    Vec3 ap = actor_location(g_pose.pawn);
                    double best = 1e9;
                    for (UObject* w : ws)
                    {
                        if (!w || w->GetName().rfind(STR("Default__"), 0) == 0 || bool_property(w, STR("Is Sheathed")) || is_fist(w)) continue;
                        if (object_property(g_pose.pawn, STR("Weapon R")) == w || object_property(g_pose.pawn, STR("Weapon L")) == w) continue;
                        // (run 5 c1b013c: without a name it took the light pavise strapped on his back)
                        if (!g_arm_item_name.empty() && w->GetName().find(g_arm_item_name) == std::wstring::npos) continue;
                        UObject* b = object_property(w, STR("BaseMesh"));
                        if (!b) continue;
                        double d = length(component_location(b) - ap);
                        if (d < best) { best = d; item = w; }
                    }
                }
                // In his hand the controller goes to where his hand is at the pickup and stays (following the item would chase
                // itself; staying on the floor left the crouched arm at cap 62 stretched 48-58 cm, and the stretch let-go dropped
                // it 1.3 s later, run 12 floor_pickup_62: a player lifts what he picked up).
                static Vec3 last_grip{};
                static bool was_in_hand = false;
                if (in_hand && !was_in_hand)
                    if (UObject* pm = object_property(g_pose.pawn, STR("Mesh"))) last_grip = socket_location(pm, bone_fname("hand_r"));
                was_in_hand = in_hand;
                if (item && in_hand) grip = last_grip;
                else if (item)
                    if (UObject* b = object_property(item, STR("BaseMesh"))) grip = last_grip = component_location(b) + Vec3{0, 0, g_arm_floor[2]};
                // Moved there at a reach's pace, 120 cm/s: jumping from the made-up circle to the floor in one frame swung
                // his hand at slap speed, and the slap fist knocked the lantern 5 m (run 13 gate floor_pickup 66.51-66.86).
                static Vec3 eased_grip{};
                static double eased_at = -10.0;
                double step = (std::min)(0.1, now - eased_at) * 120.0;
                // First frame of this mode (or after a pause): from the made-up path's spot, not the target (run 15
                // 69408e5: starting at the target still swung the right hand at 8.7 m/s, slap speed 75 every case).
                if (now - eased_at > 0.5) eased_grip = circle;
                else
                {
                    Vec3 to = grip - eased_grip;
                    double dl = length(to);
                    eased_grip = dl <= step ? grip : eased_grip + to * (step / dl);
                }
                eased_at = now;
                grip = eased_grip;
            }
            if (mode == 18 && side == 1)
            {
                // Elbow / forearm test: the right hand swept from out to his right side, raised, across in
                // front of his chest in 0.12 s (a horizontal elbow strike: the forearm and elbow lead),
                // back over 0.6 s, every 2.2 s. Put a foe 35-45 cm in front.
                static double t0 = -1.0;
                static int seen18 = -1;
                if (seen18 != g_fake_arm_epoch.load()) t0 = now;
                seen18 = g_fake_arm_epoch.load();
                // Aimed at the nearest other Willie's head when there is one (the sweep's frame faces him, the
                // hand passing at 60% of his distance, so the forearm and elbow cross his head/neck).
                Quat frame = body;
                double reach = 18.0, height = 12.0;
                {
                    std::vector<UObject*> ws;
                    UObjectGlobals::FindAllOf(STR("Willie_BP_C"), ws);
                    UObject* foe = nullptr;
                    double best = 1e9;
                    for (UObject* w : ws)
                    {
                        if (!w || w == g_pose.pawn || w->GetName().rfind(STR("Default__"), 0) == 0) continue;
                        double d = length(actor_location(w) - shoulder);
                        if (d < best) { best = d; foe = w; }
                    }
                    if (UObject* fm = foe ? object_property(foe, STR("Mesh")) : nullptr)
                    {
                        Vec3 head = socket_location(fm, bone_fname("head"));
                        Vec3 to = head - shoulder;
                        double flat = std::sqrt(to.x * to.x + to.y * to.y);
                        if (flat > 5.0 && flat < 120.0)
                        {
                            frame = quat_from_yaw_deg(std::atan2(to.y, to.x) * 180.0 / 3.14159265358979);
                            reach = flat * 0.6;
                            height = to.z;
                        }
                    }
                }
                Vec3 a{reach, out * 38.0, height}, b{reach, -out * 25.0, height};
                double t = std::fmod(now - t0, 2.2);
                double u = t < 1.4 ? 0.0 : (t < 1.52 ? (t - 1.4) / 0.12 : (t < 1.6 ? 1.0 : (std::max)(0.0, 1.0 - (t - 1.6) / 0.6)));
                grip = shoulder + frame.rotate(a + (b - a) * u);
            }
            if ((mode == 16 || mode == 17) && side == 1 && g_pose.pawn)
            {
                // Fist and grapple tests, on the nearest other Willie. 16: the right hand rests 25 cm in
                // front of his shoulder 1.4 s, punches through the foe's head (10 cm past it) in 0.12 s,
                // stays 0.2 s and comes back over 0.5 s (a punch at ~5-8 m/s), every 2.2 s.
                // 17: the right hand on the foe's neck_02 for 2 s, then pulls back toward him 30 cm
                // over 1 s and holds there (a throat grab and pull).
                static UObject* foe = nullptr;
                static bool foe_tracked = track_freed(&foe);
                static double found_at = -1.0, t0 = -1.0;
                static int seen = -1;
                if (seen != g_fake_arm_epoch.load()) t0 = now;
                seen = g_fake_arm_epoch.load();
                if (!foe || now - found_at > 1.0)
                {
                    found_at = now;
                    foe = nullptr;
                    std::vector<UObject*> ws;
                    UObjectGlobals::FindAllOf(STR("Willie_BP_C"), ws);
                    Vec3 ap = actor_location(g_pose.pawn);
                    double best = 1e9;
                    for (UObject* w : ws)
                    {
                        if (!w || w == g_pose.pawn || w->GetName().rfind(STR("Default__"), 0) == 0) continue;
                        double d = length(actor_location(w) - ap);
                        if (d < best) { best = d; foe = w; }
                    }
                }
                UObject* fm = foe ? object_property(foe, STR("Mesh")) : nullptr;
                if (fm)
                {
                    Vec3 rest = shoulder + body.rotate(Vec3{25.0, out * 10.0, -5.0});
                    if (mode == 16)
                    {
                        Vec3 head = socket_location(fm, bone_fname("head"));
                        Vec3 dir = head - rest;
                        double dl = length(dir);
                        Vec3 hit = dl > 1.0 ? head + dir * (10.0 / dl) : head;
                        double t = std::fmod(now - t0, 2.2);
                        if (t < 1.4) grip = rest;
                        else if (t < 1.52) grip = rest + (hit - rest) * ((t - 1.4) / 0.12);
                        else if (t < 1.72) grip = hit;
                        else grip = hit + (rest - hit) * (std::min)(1.0, (t - 1.72) / 0.5);
                    }
                    else
                    {
                        Vec3 neck = socket_location(fm, bone_fname("neck_02"));
                        Vec3 back = rest - neck;
                        double bl = length(back);
                        Vec3 pulled = bl > 1.0 ? neck + back * (30.0 / bl) : neck;
                        double t = now - t0;
                        static Vec3 hold_at, pull_to;
                        if (t < 2.0)
                        {
                            hold_at = neck;
                            pull_to = pulled;
                            grip = neck;
                        }
                        else grip = hold_at + (pull_to - hold_at) * (std::min)(1.0, (t - 2.0) / 1.0);
                    }
                }
            }
            if (mode == 22 && side == (int)g_slot_test[0] && g_pose.pawn)
            {
                // Hip/back test: this hand on the item on his slot (0 R1, 1 R2, 2 L1, 3 L2, 4 Back), at this far
                // along its own +Z from its BaseMesh, pushed this far out from his pelvis (a hand reaching for
                // it, short of it). It stays there once the item has been taken.
                static Vec3 last{0, 0, 0};
                static bool have = false;
                static const TCHAR* vars[5] = {STR("Weapon Slot R 1"), STR("Weapon Slot R 2"), STR("Weapon Slot L 1"), STR("Weapon Slot L 2"), STR("Weapon Slot Back")};
                int si = (std::max)(0, (std::min)(4, (int)g_slot_test[1]));
                UObject* w = object_property(g_pose.pawn, vars[si]);
                UObject* b = w ? object_property(w, STR("BaseMesh")) : nullptr;
                UObject* m = object_property(g_pose.pawn, STR("Mesh"));
                if (b && m)
                {
                    Vec3 p = component_location(b) + component_rotation(b).rotate(Vec3{0, 0, g_slot_test[2]});
                    Vec3 pel = socket_location(m, bone_fname("pelvis"));
                    Vec3 outw{p.x - pel.x, p.y - pel.y, 0.0};
                    double ol = length(outw);
                    if (ol > 1.0) outw = outw * (1.0 / ol);
                    last = p + outw * g_slot_test[3];
                    have = true;
                }
                else if (have && g_slot_test[4] > 0.0)
                {
                    // Taken: the hand carries it to the front (40 cm ahead of the shoulder) at this speed.
                    static double t_prev = now;
                    double dt = (std::min)(0.1, (std::max)(0.0, now - t_prev));
                    t_prev = now;
                    Vec3 front = shoulder + body.rotate(Vec3{40.0, out * 15.0, -10.0});
                    Vec3 d = front - last;
                    double dl = length(d), step = g_slot_test[4] * dt;
                    last = dl <= step ? front : last + d * (step / dl);
                }
                if (have) grip = last;
            }
            if (mode == 14 && side == 1 && g_pose.pawn)
            {
                // Floor test: the right controller this far ahead of and beside his capsule, this high above
                // the floor under it (the capsule's bottom).
                Vec3 ap = actor_location(g_pose.pawn);
                double floor_z = ap.z - 90.0 * component_scale_z(object_property(g_pose.pawn, STR("Mesh")));
                Vec3 flat = body.rotate(Vec3{g_arm_floor[0], g_arm_floor[1], 0.0});
                Vec3 target{ap.x + flat.x, ap.y + flat.y, floor_z + g_arm_floor[2]};
                // At a reach's pace (120 cm/s) from the made-up path's spot, as arm_to_item: floor_pickup puts the lantern
                // down with this, and a one-frame jump to the floor would swing it at slap speed.
                static Vec3 eased14{};
                static double eased14_at = -10.0;
                if (now - eased14_at > 0.5) eased14 = grip;
                else
                {
                    double step = (std::min)(0.1, now - eased14_at) * 120.0;
                    Vec3 to = target - eased14;
                    double dl = length(to);
                    eased14 = dl <= step ? target : eased14 + to * (step / dl);
                }
                eased14_at = now;
                grip = eased14;
            }
            if (mode == 13 && side == 1 && g_pose.pawn && !g_park_socket.empty())
            {
                // Holster test: the right hand's grip point parked on a named socket of his mesh.
                if (UObject* mesh = object_property(g_pose.pawn, STR("Mesh"))) grip = socket_location(mesh, bone_fname(g_park_socket));
            }
            if (mode == 12 && side == 1 && g_pose.pawn)
            {
                // Sheathe test: the right hand goes from a blade's length out along the right belt
                // scabbard's line in to its mouth over 2.5 s (the weapon in the hand goes in).
                static double t0 = -1.0;
                static int seen12 = -1;
                if (seen12 != 12) t0 = now;
                seen12 = mode;
                UObject* wr = object_property(g_pose.pawn, STR("Weapon R"));
                UObject* mesh = object_property(g_pose.pawn, STR("Mesh"));
                if (mesh)
                {
                    // The slot it is going into, else the first right slot.
                    const char* sock = object_property(g_pose.pawn, STR("Weapon Slot R 1")) && !(wr && object_property(g_pose.pawn, STR("Weapon Slot R 1")) == wr)
                                           ? "Sheath_Slot_R_2" : "Sheath_Slot_R_1";
                    if (const char* now_into = sheathing_socket(1)) sock = now_into; // across too
                    Vec3 m = socket_location(mesh, bone_fname(sock));
                    Vec3 ax = socket_rotation(mesh, bone_fname(sock)).rotate(Vec3{0, 0, 1});
                    double len = wr ? blade_length(wr) : 80.0;
                    double u = (std::min)(1.0, (now - t0) / 2.5);
                    grip = m - ax * ((len + 3.0) * (1.0 - u) - 8.0 * u);
                }
            }
            if (mode == 11 && side == 1 && g_pose.pawn)
            {
                // Draw test: the right hand goes to the first sheathed weapon's grip, holds 1.5 s, then
                // pulls along its blade's -Z (out of the scabbard) to 1.3 x its length over 2 s.
                static double t0 = -1.0, len = 80.0;
                static Vec3 p0, ax;
                static int seen = -1;
                if (seen != 11 || t0 < 0.0)
                {
                    t0 = -1.0;
                    for (const TCHAR* v : {STR("Weapon Slot R 1"), STR("Weapon Slot R 2"), STR("Weapon Slot L 1"), STR("Weapon Slot L 2"), STR("Weapon Slot Back")})
                    {
                        UObject* w = object_property(g_pose.pawn, v);
                        UObject* b = w ? object_property(w, STR("BaseMesh")) : nullptr;
                        if (!b) continue;
                        p0 = component_location(b);
                        ax = component_rotation(b).rotate(Vec3{0, 0, 1});
                        if (FProperty* lp = prop_chain(w, STR("Length to Top R Default"))) len = (std::max)(20.0, number_property(w, lp));
                        t0 = now;
                        break;
                    }
                }
                seen = mode;
                if (t0 >= 0.0)
                {
                    double t = now - t0;
                    double s = t < 1.5 ? 0.0 : (std::min)(1.3 * len, (t - 1.5) / 2.0 * 1.3 * len);
                    grip = p0 - ax * s;
                }
            }
            grip_rot = (body * rot_to_quat(60.0, 0.0, 0.0)).normalized(); // controller handle tilted forward, as held
            // Mode 9: at the mouth, the hand turning over (a full turn about his right in 6 s), so a
            // held bottle tips its neck down at some point (drinking tests).
            if (mode == 10 && side == 1)
            {
                // The test hand turns, a little each tick, until the held weapon's tip points
                // straight ahead (its first "Tip" marker's forward, the direction the game reads a
                // thrust in), pitched down by hsvr.arm_move 10's pitch argument.
                static Quat aim{0, 0, 0, 1};
                Vec3 want = (body * rot_to_quat(-g_fake_thrust_pitch.load(), 0.0, 0.0)).normalized().rotate({1.0, 0.0, 0.0});
                UObject* held = g_pose.pawn ? object_property(g_pose.pawn, STR("Weapon R")) : nullptr;
                RawArray* tips = held ? value_ptr<RawArray>(held, STR("Tips")) : nullptr;
                UObject* held_mesh = held ? object_property(held, STR("BaseMesh")) : nullptr;
                bool have_tip = tips && tips->Data && tips->Num > 0 && tips->Data[0];
                if (have_tip || held_mesh)
                {
                    // The first "Tip" marker's forward; a weapon without Tips (passport-spawned ones
                    // have none) uses its blade axis, the BaseMesh's +Z (pommel to tip).
                    Vec3 have;
                    if (have_tip)
                    {
                        Call f(static_cast<UObject*>(tips->Data[0]), STR("GetForwardVector"));
                        f.run();
                        have = f.vec();
                    }
                    else have = component_rotation(held_mesh).rotate(Vec3{0, 0, 1});
                    HSVR_LOG_EVERY(1.0, "Test aim: %s, tip axis (%.2f, %.2f, %.2f), want (%.2f, %.2f, %.2f)", have_tip ? "Tips[0] forward" : "BaseMesh +Z",
                                   have.x, have.y, have.z, want.x, want.y, want.z);
                    Vec3 axis = cross(have, want);
                    double sn = length(axis), cs = have.x * want.x + have.y * want.y + have.z * want.z;
                    if (sn > 1e-6)
                    {
                        double ang = std::atan2(sn, cs) * 0.15;
                        aim = (quat_axis_angle(axis * (1.0 / sn), ang) * aim).normalized();
                    }
                }
                grip_rot = (aim * body * rot_to_quat(60.0, 0.0, 0.0)).normalized();
            }
            if (mode == 23 && side == 1) grip_rot = (grip_rot * quat_axis_angle(Vec3{1, 0, 0}, 0.785 * std::sin(now * 2.0 * 3.14159265358979))).normalized();
            if (mode == 9) grip_rot = (body * quat_axis_angle(Vec3{0, 1, 0}, std::fmod(now, 6.0) / 6.0 * 2.0 * 3.14159265358979) * rot_to_quat(60.0, 0.0, 0.0)).normalized();
            if (double roll = g_fake_roll_deg[side].load(); roll != 0.0)
                grip_rot = (body * quat_axis_angle(Vec3{1, 0, 0}, roll / 57.29578) * rot_to_quat(60.0, 0.0, 0.0)).normalized();
            if (double yaw = g_fake_yaw_deg[side].load(); yaw != 0.0)
            {
                Vec3 ax{0, 0, 1};
                if (g_fake_yaw_neck[side].load()) held_neck_axis(side, ax);
                grip_rot = (quat_axis_angle(ax, yaw / 57.29578) * grip_rot).normalized();
            }
            xbow_test_grip(side, grip, grip_rot); // test: hsvr.xbow_hand / xbow_wrist / keep, arm_move switches eased
            ctl_track_grip(side, grip, grip_rot);  // test: hsvr.ctl_replay (his own recorded controllers)
        }
        if (cfg.dev_pose_fake_tracking && g_fake_jitter_cm.load() > 0.0)
        {
            // Like a tracked controller: noise of this size at ~10-20 Hz (a fresh offset every 3 frames, eased).
            static Vec3 cur[2], next[2];
            static int n[2] = {0, 0};
            auto gauss = []() {
                double u1 = (std::rand() + 1.0) / (RAND_MAX + 2.0), u2 = (std::rand() + 1.0) / (RAND_MAX + 2.0);
                return std::sqrt(-2.0 * std::log(u1)) * std::cos(6.283185307 * u2);
            };
            double j = g_fake_jitter_cm.load();
            if (++n[side] % 3 == 0) next[side] = Vec3{gauss() * j, gauss() * j, gauss() * j};
            cur[side] = cur[side] + (next[side] - cur[side]) * 0.5;
            grip = grip + cur[side];
        }
        // A badly hurt arm: the controller no longer places it (it hangs, or flops when dislocated).
        bool limp = false;
        g_inj.ctrl[side] = grip + grip_rot.rotate({cfg.pose_wrist_forward_cm, cfg.pose_wrist_right_cm * out, cfg.pose_wrist_up_cm});
        g_inj.ctrl_valid[side] = tracked;
        if (g_inj.arm[side] != 0 && g_inj.pawn == g_pose.pawn)
        {
            Vec3 wrist_off{cfg.pose_wrist_forward_cm, cfg.pose_wrist_right_cm * out, cfg.pose_wrist_up_cm};
            Vec3 Sx = socket_location(g_pose.driver, bone_fname("upperarm" + sx));
            Vec3 p = injury_arm_point(side, g_inj.arm[side], cfg, Sx, (a.upper_length + a.lower_length) * 0.97, grip + grip_rot.rotate(wrist_off), body, out);
            Vec3 dir = p - Sx;
            dir = length(dir) > 1e-3 ? dir * (1.0 / length(dir)) : Vec3{0.0, 0.0, -1.0};
            grip_rot = (quat_from_two(Vec3{0.0, 0.0, -1.0}, dir) * body).normalized(); // fingers down the arm, thumb forward
            grip = p - grip_rot.rotate(wrist_off);
            limp = true;
        }
        else
            g_inj.p_valid[side] = false;
        Vec3 target = grip + grip_rot.rotate({cfg.pose_wrist_forward_cm, cfg.pose_wrist_right_cm * out, cfg.pose_wrist_up_cm});
        g_pose.raw_target[side] = target;
        Vec3 S = socket_location(g_pose.driver, bone_fname("upperarm" + sx));
        const Vec3 S_chest = S; // the shoulder as the chest carries it (before reaching)
        // Your reach scaled to his (once your arm length is measured): from his shoulder, your hand is
        // as far out along his arm as it is along yours.
        if (cfg.pose_user_arm_cm > 1.0 && tracked && !limp) target = S + (target - S) * ((a.upper_length + a.lower_length) / cfg.pose_user_arm_cm);
        g_pose.target[side] = target;
        g_pose.reach_target[side] = target;
        S = shoulder_reach(side, cfg, S, target, component_inv);

        Vec3 to = target - S;
        double D = length(to);
        double L1 = a.upper_length, L2 = a.lower_length;
        double lo = std::fabs(L1 - L2) + 0.5, hi = L1 + L2 - 0.5;
        if (D < 1e-3) return;
        Vec3 dir = to * (1.0 / D);
        D = (std::min)((std::max)(D, lo), hi);
        // A held weapon goes where his hand can be: past his reach, as far as his arm goes (the test
        // switch hsvr.hold_reach 0 leaves the target unclamped, to push a weapon into the floor).
        if (g_hold_reach_clamp.load()) g_pose.target[side] = S + dir * D;
        // The hand in the controller's grip (OpenXR grip pose, here X forward through the fist from
        // the little finger to the thumb, Y right, Z up): the fingers run down the handle, tilted
        // pose_knuckle_deg toward the front; the thumb side is the front. The same for both hands
        // (each palm faces the other hand). Geometry as in Matthew's Chasms VR Framework (MIT).
        Quat offset = rot_to_quat(cfg.pose_hand_pitch, cfg.pose_hand_yaw * out, cfg.pose_hand_roll * out);
        Quat hand_grip = (grip_rot * offset).normalized();
        double k = cfg.pose_knuckle_deg * 3.14159265358979323846 / 180.0;
        Vec3 fingers_world = hand_grip.rotate(Vec3{std::sin(k), 0.0, -std::cos(k)});
        Vec3 thumb_world = hand_grip.rotate(Vec3{std::cos(k), 0.0, std::sin(k)});
        g_thumb_world[side] = thumb_world;
        Quat Wh = (quat_from_two(fingers_world, thumb_world) * quat_from_two(a.fingers_local, a.thumb_local).inverse()).normalized();
        g_pose.hand_rot[side] = Wh;
        g_pose.hand_valid[side] = true;
        {
            // The play space's turn (stick turns), so a hand that does not turn in your room reads as still
            // even when the world turns around you; test hands are made in the actor's heading frame.
            Vec3 an;
            double by = 0.0;
            g_pose.ctl_frame_yaw[side] = (tracked && stereo_view_anchor(an, by)) ? by : quat_yaw_deg(body);
        }
        // Holding a weapon that something has stopped: his hand stays on the weapon (Matthew's framework).
        Vec3 controller_wrist = target;
        Quat controller_rot = Wh;
        bool on_weapon = hand_on_weapon(side, cfg, target, Wh);
        g_solved_on[side] = on_weapon ? 1 : 0;
        if (two_hand_pose(side, target, Wh)) on_weapon = true, g_solved_on[side] |= 2;
        if (!on_weapon && hand_on_scabbard(side, target, Wh)) on_weapon = true, g_solved_on[side] |= 4;
        // A free hand stops at walls and scenery (the palm's middle, pose_hand_world_radius_cm round it).
        bool stopped = false;
        if ((!on_weapon || hand_is_fist(side)) && (g_solved_on[side] & ~1) == 0 && cfg.pose_hand_world_stop && !hand_has_weapon(side) && !g_wrap_on_side(side))
        {
            Vec3 palm_mid = target + fingers_world * cfg.pose_hand_world_reach_cm;
            Vec3 at;
            if (hand_world_sweep(S, palm_mid, cfg.pose_hand_world_radius_cm, at))
            {
                target = target + (at - palm_mid);
                stopped = true;
                HSVR_LOG_EVERY(1.0, "Hand: %s hand stopped by the world %.1f cm short of your controller", side == 0 ? "left" : "right", length(at - palm_mid));
            }
        }
        g_free_palm_unstopped[side] = target + fingers_world * cfg.pose_hand_world_reach_cm;
        g_free_palm_valid[side] = !on_weapon && !hand_has_weapon(side);
        // A free hand rests ON a weapon his other hand holds, not in it (pose_hand_held_weapon_stop): drawn into it, his arm's
        // motors pressed the hand into the haft every step and the weapon wobbled at 450-540 deg/s (park cases 2026-11-24, axe;
        // gone with the free arm not colliding). B&S's free hand is a light body on soft springs (5000 N/m, max 3000 N), which
        // a held item pushes aside; his is the ragdoll's, far stiffer, so its drawn place stops at the weapon's surface instead.
        if (cfg.pose_hand_held_weapon_stop_cm > 0.0 && !on_weapon && (g_solved_on[side] & ~1) == 0 && !hand_has_weapon(side) && hand_has_weapon(1 - side))
        {
            UObject* hw = held_weapon_of(1 - side);
            Vec3 palm_mid = target + fingers_world * cfg.pose_hand_world_reach_cm;
            Vec3 q;
            double d = closest_on_weapon(hw, palm_mid, &q, nullptr);
            double r = cfg.pose_hand_held_weapon_stop_cm;
            if (d >= 0.0 && d < r)
            {
                Vec3 away = palm_mid - q;
                if (d < 0.05)
                {
                    // Inside it: out from the weapon's long axis.
                    UObject* hb = object_property(hw, STR("BaseMesh"));
                    Vec3 ax = hb ? component_rotation(hb).rotate(Vec3{0, 0, 1}) : Vec3{0, 0, 1};
                    Vec3 o = hb ? component_location(hb) : q;
                    Vec3 rel = palm_mid - o;
                    away = rel - ax * dot(rel, ax);
                    double inside = length(away);
                    if (inside < 1e-3) away = cross(ax, Vec3{0, 0, 1});
                }
                if (length(away) > 1e-6)
                {
                    Vec3 push = normalized(away) * (r - d);
                    target = target + push;
                    stopped = true;
                    HSVR_LOG_EVERY(1.0, "Hand: %s free hand rests on %ls (held by the other hand): moved %.1f cm out of it", side == 0 ? "left" : "right",
                                   hw->GetName().c_str(), length(push));
                }
            }
        }
        // A hand that just let go of a weapon the other hand holds passes through it until clear (end_two_hand, B&S).
        if (g_release_linger[side].weapon)
        {
            ReleaseLinger& L = g_release_linger[side];
            UObject* fm = g_pose.pawn ? object_property(g_pose.pawn, STR("Mesh")) : nullptr;
            bool gone = arm_ignore_weapon(side) != L.weapon || !object_alive(L.weapon) || !hand_has_weapon(1 - side) || held_weapon_of(1 - side) != L.weapon;
            if (!gone && is_second_hand(side)) L = ReleaseLinger{}; // took it again: its hold's own ignore stays
            else if (gone)
            {
                bool mine = arm_ignore_weapon(side) == L.weapon && !hand_has_weapon(side);
                L = ReleaseLinger{};
                if (mine) clear_arm_ignore(side);
            }
            else if (fm && now_seconds() - L.t >= cfg.pose_hold_release_ignore_s)
            {
                Vec3 gp = hand_grab_point(fm, side);
                double d = closest_on_weapon(L.weapon, gp, nullptr, nullptr);
                if (d < 0.0 || d >= cfg.pose_hold_release_clear_cm)
                {
                    HSVR_LOG("Two hands: %s hand is %.0f cm clear of %ls %.2f s after letting go: solid against it again", side == 0 ? "left" : "right", d,
                             L.weapon->GetName().c_str(), now_seconds() - L.t);
                    clear_arm_ignore(side);
                }
            }
        }
        // ...and from his REAL hand body (796b650 / e616b9b park runs: the hand's physics body, driven by stiff arm motors, overshot its
        // drawn place and bounced off the held axe every ~0.2 s (blocker log: hand_l only, impulse up to 298) while the drawn place
        // was already 4 cm clear; the axe wobbled 186-504 deg/s in about half the launches). Each frame the hand body is closer than
        // pose_hand_held_weapon_body_gap_cm, its drawn place is moved further off the weapon (at most _body_max_cm); clear, it eases back.
        {
            Vec3& off = g_free_rest_off[side];
            bool active = false;
            if (cfg.pose_hand_held_weapon_body_gap_cm > 0.0 && !on_weapon && (g_solved_on[side] & ~1) == 0 && !hand_has_weapon(side) && hand_has_weapon(1 - side) && g_pose.pawn)
            {
                UObject* hw = held_weapon_of(1 - side);
                UObject* fm = object_property(g_pose.pawn, STR("Mesh"));
                FName hb = bone_fname(side == 0 ? "hand_l" : "hand_r");
                Vec3 hp = fm ? socket_location(fm, hb) : Vec3{};
                Vec3 q;
                double near_cm = hw && fm ? closest_on_weapon(hw, hp, &q, nullptr) : -1.0;
                if (near_cm >= 0.0 && near_cm < 20.0)
                {
                    active = true;
                    double g = item_gap(hw, fm, hb, hp);
                    double g0 = cfg.pose_hand_held_weapon_body_gap_cm;
                    if (g >= 0.0 && g < g0 && hs.squeeze <= 0.3f)
                    {
                        Vec3 away = hp - q;
                        if (length(away) > 1e-3)
                        {
                            off = off + normalized(away) * ((g0 - g) * 0.5);
                            double most = (std::max)(0.0, cfg.pose_hand_held_weapon_body_max_cm);
                            if (length(off) > most) off = normalized(off) * most;
                            HSVR_LOG_EVERY(1.0, "Hand: %s free hand body %.1f cm from %ls (held by the other hand): drawn place moved %.1f cm off it", side == 0 ? "left" : "right", g,
                                           hw->GetName().c_str(), length(off));
                        }
                    }
                }
            }
            // Squeezing to take it (a second hand on the weapon): the hand goes where you put it, at once.
            if (hs.squeeze > 0.3f) active = false, off = Vec3{};
            if (!active) off = off * 0.9;
            else if (length(off) > 0.0) off = off * 0.995;
            if (length(off) < 0.05) off = Vec3{};
            if (length(off) > 0.0) target = target + off, stopped = true;
        }
        if (!on_weapon && hand_on_grab(side, cfg, target, Wh))
        {
            on_weapon = true, g_solved_on[side] |= 8;
            // A hand pinned on scenery: the shoulder reaches for the pinned hand, not for your
            // controller. Reaching for the controller slid the shoulder 7 cm as the controller drifted,
            // and the arm (at full reach) dragged the pinned hand 4 cm up the fence after it
            // (b8b5cb1 test frames: |H - S| 52.8 cm every row, H = drawn hand to 0.1 cm).
            if (hand_on_scenery(side)) S = shoulder_reach(side, cfg, S_chest, target, component_inv);
        }
        // Where your real hand is, while his stays on a stopped weapon.
        ghost_hand(side, cfg, on_weapon && hand_on_weapon_amount(side) > 0.5 && length(controller_wrist - target) > cfg.pose_ghost_from_cm, controller_wrist,
                   controller_rot);
        if (on_weapon || stopped)
        {
            to = target - S;
            double d = length(to);
            if (d < 1e-3) return;
            dir = to * (1.0 / d);
            D = (std::min)((std::max)(d, lo), hi);
        }

        // Where the elbow points around the shoulder-to-wrist line (the swivel): ported from the
        // arm solver in Matthew's Chasms VR Framework (crates/ik/src/arm.rs, MIT, Copyright (c) 2026
        // chasmlol). Start from VRArmIK's tuned version of Parger's position model, follow the
        // hand's twist when the arm is nearly straight, then take the cheapest angle in a short
        // search that keeps the wrist and forearm twist in comfortable ranges, the elbow out of the
        // ribcage and close to last frame. The hand itself is never moved.
        const double PI = 3.14159265358979323846, RAD = PI / 180.0;
        Vec3 up{0, 0, 1}, forward = body.rotate({1, 0, 0}), outward = body.rotate({0, out, 0});
        auto reject = [](const Vec3& v, const Vec3& from) { return v - from * dot(v, from); };
        auto smoothstep = [](double e0, double e1, double x) {
            double t = (std::min)(1.0, (std::max)(0.0, (x - e0) / (e1 - e0)));
            return t * t * (3.0 - 2.0 * t);
        };
        auto wrap = [PI](double x) {
            while (x > PI) x -= 2.0 * PI;
            while (x < -PI) x += 2.0 * PI;
            return x;
        };
        // The rotation taking unit `from` onto unit `to`, applied to `v`.
        auto arc = [](const Vec3& from, const Vec3& to, const Vec3& v) {
            Vec3 c = cross(from, to);
            double d = dot(from, to);
            if (d < -0.999999) return v * -1.0;
            Quat q{c.x, c.y, c.z, 1.0 + d};
            return q.normalized().rotate(v);
        };
        auto signed_angle = [](Vec3 a2, Vec3 b2, Vec3 axis2) {
            axis2 = normalized(axis2);
            a2 = a2 - axis2 * dot(a2, axis2);
            b2 = b2 - axis2 * dot(b2, axis2);
            return std::atan2(dot(cross(a2, b2), axis2), dot(a2, b2));
        };
        // Body frame in the framework's chest space: x right, y up, z forward.
        Vec3 chest = socket_location(g_pose.driver, bone_fname("spine_05"));
        auto local = [&](const Vec3& v) { Vec3 l = body.inverse().rotate(v - chest); return Vec3{l.y, l.z, l.x}; };

        Vec3 axis_sw = dir;
        double lean = -dot(axis_sw, up) * 0.2;
        Vec3 u = reject(up, axis_sw) + reject(forward, axis_sw) * lean;
        if (length(u) < 1e-6) u = reject(forward, axis_sw);
        u = normalized(u);
        Vec3 o = reject(reject(outward, axis_sw) - reject(forward, axis_sw) * 0.3, u);
        if (length(o) < 1e-6)
        {
            o = cross(u, axis_sw);
            if (dot(o, outward) < 0) o = o * -1.0;
        }
        o = normalized(o);
        Vec3 swivel_axis = cross(u, o);
        auto swivel_dir = [&](double al) { return u * std::cos(al) + o * std::sin(al); };
        auto swivel_angle = [&](const Vec3& e) { return std::atan2(dot(e, o), dot(e, u)); };
        double along = (L1 * L1 - L2 * L2 + D * D) / (2.0 * D);
        double h = std::sqrt((std::max)(0.0, L1 * L1 - along * along));
        auto elbow_for = [&](const Vec3& e) { return S + dir * along + normalized(reject(e, dir)) * h; };
        Vec3 H = S + dir * D;

        // 1. The position model, from the wrist relative to the shoulder in arm lengths.
        Vec3 rel = local(target) - local(S);
        // The framework's lengths are metres for a reference body whose arm is 56.5 cm.
        double scale = (L1 + L2) / 56.5;
        Vec3 hn = rel * (1.0 / (L1 + L2));
        double alpha = 135.0 - 60.0 * hn.y;
        alpha += hn.y > 0.0 ? 260.0 * (std::max)(0.0, 0.6 - hn.z) * hn.y : -100.0 * (std::max)(0.0, 0.6 - hn.z) * -hn.y;
        alpha -= 50.0 * (std::max)(0.0, -hn.x * out + 0.1);
        {
            double lo2 = 13.0, hi2 = 175.0, knee = 10.0;
            auto soft = [knee](double over) { return knee * (1.0 - std::exp(-over / knee)); };
            if (alpha > hi2 - knee) alpha = hi2 - knee + soft(alpha - (hi2 - knee));
            else if (alpha < lo2 + knee) alpha = lo2 + knee - soft(lo2 + knee - alpha);
        }
        Vec3 prior_dir = swivel_dir(alpha * RAD);
        // 2. Parger's singularity correction near the shoulder's vertical axis and behind it.
        double radius_m = std::sqrt(rel.x * rel.x + rel.z * rel.z) / 100.0 / scale;
        double blend = (std::max)(1.0 - radius_m / 0.5, (std::min)(1.0, (std::max)(0.0, -rel.z / 100.0 / scale / 0.1)));
        if (blend > 0.0)
        {
            Vec3 fixed_local{0.133 * out, -0.443, -0.886}; // x right, y up, z forward
            Vec3 fixed = body.rotate(Vec3{fixed_local.z, fixed_local.x, fixed_local.y});
            fixed = reject(fixed, swivel_axis);
            if (length(fixed) > 1e-6)
            {
                Vec3 b = prior_dir + (normalized(fixed) - prior_dir) * (std::min)(1.0, blend);
                if (length(b) > 1e-6) prior_dir = normalized(b);
            }
        }
        double prior = swivel_angle(prior_dir);
        // The elbow is chosen for the hand as it is drawn. While his hand rides a weapon that something
        // stopped (a post, a shield, a body), that is the weapon's turn, not your controller's: with the
        // controller's, the elbow sat right for a hand that wasn't there and his wrist bent up to 150 deg
        // (Matthew 2026-11-20 14:43, a war hammer against the wooden post; log: wrist bend median 69,
        // p90 121 deg whenever the weapon was 30+ cm off the controller, 31 deg when it was on it).
        // B&S does the same: the arm's IK target is an anchor on the item's grip, position and rotation
        // (Handle.cs SetHandAnchor(gripInfo.ikAnchor), solved by VRIK with its WristRelaxer).
        if (on_weapon && cfg.pose_arm_solve_drawn_hand)
        {
            fingers_world = normalized(Wh.rotate(a.fingers_local));
            Vec3 th = Wh.rotate(a.thumb_local);
            th = th - fingers_world * dot(th, fingers_world);
            if (length(th) > 1e-6) thumb_world = normalized(th);
        }
        Vec3 hand_y = normalized(fingers_world), hand_z = normalized(thumb_world), hand_x = cross(hand_y, hand_z);
        // A nearly straight arm follows the hand's twist: the inside of the elbow toward the thumb.
        double dd = (std::min)(D, L1 + L2);
        double flexion = std::acos((std::max)(-1.0, (std::min)(1.0, (dd * dd - L1 * L1 - L2 * L2) / (2.0 * L1 * L2))));
        double straight = smoothstep(30.0 * RAD, 8.0 * RAD, flexion);
        {
            Vec3 f = normalized(H - elbow_for(swivel_dir(prior)));
            Vec3 thumb = arc(hand_y, f, hand_z);
            Vec3 r = reject(thumb * -1.0, swivel_axis);
            if (length(r) > 1e-6) prior += wrap(swivel_angle(r) - prior) * straight;
        }
        // 3. The cheapest swivel near the prior.
        Vec3 shoulder_l = local(S);
        auto excess = [RAD](double angle, double limit_deg) { return (std::max)(0.0, angle - limit_deg * RAD); };
        bool have_prev = g_pose.swivel_valid[side];
        double prev = have_prev ? swivel_angle(body.rotate(g_pose.swivel_local[side])) : 0.0;
        auto cost = [&](double al) {
            Vec3 e = swivel_dir(al);
            Vec3 Ee = elbow_for(e);
            Vec3 f = normalized(H - Ee);
            double alg = dot(f, hand_y);
            double flex = std::fabs(std::atan2(dot(f, hand_x), alg));
            double dev = std::atan2(dot(f, hand_z), alg);
            dev = dev > 0.0 ? excess(dev, 30.0) : excess(-dev, 15.0);
            Vec3 thumb = arc(hand_y, f, hand_z);
            double tw = std::fabs(signed_angle(e * -1.0, thumb, f));
            double c = 1.0 - std::cos(al - prior) + 8.0 * (std::pow(excess(flex, 50.0), 2) + dev * dev) + 4.0 * std::pow(excess(tw, 70.0), 2);
            if (have_prev) c += 0.3 * (1.0 - std::cos(al - prev));
            Vec3 el = local(Ee);
            if (std::fabs(el.x) < 14.0 * scale && el.z > -12.0 * scale && el.z < 11.0 * scale && el.y > -55.0 * scale && el.y < shoulder_l.y) c += 20.0;
            double tucked = (std::min)(shoulder_l.x * out, local(H).x * out) - el.x * out;
            c += 2.0 * std::pow((std::max)(0.0, tucked) / (10.0 * scale), 2);
            return c;
        };
        double lo_a = 30.0 * RAD, hi_a = 215.0 * RAD, step = 10.0 * RAD;
        double best = lo_a, best_cost = 1e30;
        for (int i = 0; i <= 18; ++i)
        {
            double al = lo_a + step * i, c = cost(al);
            if (c < best_cost) best = al, best_cost = c;
        }
        {
            double before = cost(best - step), after = cost(best + step), curve = before - 2.0 * best_cost + after;
            if (curve > 1e-6)
            {
                double refined = (std::min)(hi_a, (std::max)(lo_a, best + 0.5 * step * (before - after) / curve));
                if (cost(refined) < best_cost) best = refined;
            }
        }
        // Smooth the swivel (never the hand), in the body's frame.
        Vec3 want_local = body.inverse().rotate(swivel_dir(best));
        double dt = now_seconds() - g_pose.swivel_time[side];
        g_pose.swivel_time[side] = now_seconds();
        if (have_prev && dt > 0.0 && dt < 0.5)
        {
            double k2 = 1.0 - std::exp(-dt / (std::max)(0.001, cfg.pose_swivel_smooth_s));
            Vec3 m = g_pose.swivel_local[side] + (want_local - g_pose.swivel_local[side]) * k2;
            if (length(m) > 1e-6) want_local = normalized(m);
        }
        g_pose.swivel_local[side] = want_local;
        g_pose.swivel_valid[side] = true;
        Vec3 pole = body.rotate(want_local);
        if (length(reject(pole, dir)) < 1e-3) pole = swivel_dir(best);
        Vec3 E = elbow_for(pole);
        // The arm's roll is set from Willie's reference pose (T-pose, palms down, thumbs forward),
        // where upper arm, forearm and hand share their axes (Willie_Lopoly, HalfSwordDecomp
        // defaults/hand_bones.md): along the arm is the bone's own direction, and +Y (the thumb
        // side) is the way the forearm folds when the elbow bends. So the elbow is a pure hinge,
        // and a hand in that same frame (a handshake grip) has no twist. The hand's turn about the
        // forearm away from that is the twist; the forearm bone takes pose_forearm_twist_share of it,
        // since Willie's forearm has no twist bones, and the hand keeps its exact rotation.
        Vec3 fold_axis_local{0.0, 1.0, 0.0};
        Vec3 ud = normalized(E - S), fd = normalized(H - E);
        Vec3 fold = reject(fd, ud);
        if (length(fold) < 1e-3) fold = reject(pole, ud) * -1.0; // straight arm: away from the elbow's side
        fold = normalized(fold);
        Quat Wu = (quat_from_two(ud, fold) * quat_from_two(a.upper_dir_local, fold_axis_local).inverse()).normalized();
        Quat Wl = (quat_from_two(fd, arc(ud, fd, fold)) * quat_from_two(a.lower_dir_local, fold_axis_local).inverse()).normalized();
        Vec3 axis_local = normalized(a.lower_dir_local);
        Quat rel_hand = (Wl.inverse() * Wh).normalized();
        double proj = rel_hand.x * axis_local.x + rel_hand.y * axis_local.y + rel_hand.z * axis_local.z;
        double twist = wrap(2.0 * std::atan2(proj, rel_hand.w));
        Wl = (Wl * quat_axis_angle(axis_local, twist * cfg.pose_forearm_twist_share)).normalized();
        Vec3 axis = fd;
        a.twist_deg = twist * 180.0 / 3.14159265358979323846;
        double c = dot(normalized(Wh.rotate(a.fingers_local)), axis);
        a.bend_deg = std::acos((std::max)(-1.0, (std::min)(1.0, c))) * 180.0 / 3.14159265358979323846;
        g_solved_S[side] = S, g_solved_E[side] = E, g_solved_H[side] = H;
        {
            ArmFix& f = g_arm_fix[side];
            // Empty hands and fists; held weapons, two hands and scabbards with pose_arm_fresh_shoulder_held.
            // Not a grab (the hand is pinned where the game's joint holds it) or a wrap.
            bool held = (g_solved_on[side] & 8) == 0 && !hand_is_fist(side) && (g_solved_on[side] != 0 || hand_has_weapon(side));
            f.want = g_arm_fix_on.load() && (held ? g_arm_fix_held.load() : true) && (g_solved_on[side] & 8) == 0 && !wrap_active(side) && !hand_on_scenery(side);
            double sc = component_scale_z(g_pose.driver);
            if (!(sc > 1e-3)) sc = 1.0;
            f.S_cs = component_inv.rotate(S - component_location(g_pose.driver)) * (1.0 / sc);
            ++f.seq;
        }
        node_set_rotation(*chain_node("upperarm" + sx), component_inv * Wu);
        node_set_rotation(*chain_node("lowerarm" + sx), component_inv * Wl);
        node_set_rotation(*chain_node("hand" + sx), component_inv * Wh);
    }

    // pose_post_physics: his posed skeleton (the driver, where the pose is written in its animation
    // update, and the visible body that copies it) ticks after the physics step, so a drawn hand riding a
    // held item is placed on the item where it is drawn this frame, with no guess ahead. Posed before
    // the physics (as the game ticks it), the hand was placed from where the item was a frame earlier
    // plus a guess, while the hold sets the item a new velocity after that; the guess missed by about
    // the item's own frame-to-frame change and the hand shook on a steady sword (playtest 11:00).
    std::atomic<bool> g_pose_post_physics{false};
    void pose_tick_group(const hsvr::Config& cfg, UObject* driver, UObject* mesh)
    {
        static UObject* set_on[2] = {nullptr, nullptr};
        static bool set_on_tracked = on_freed([] { for (UObject*& o : set_on) if (gone(o)) o = nullptr; });
        static bool set_post[2] = {false, false};
        bool want = cfg.pose_post_physics && cfg.pose_in_anim_update;
        UObject* comps[2] = {driver, mesh};
        for (int i = 0; i < 2; ++i)
        {
            UObject* c = comps[i];
            if (!c) continue;
            if (set_on[i] == c && set_post[i] == want) continue;
            Call tg(c, STR("SetTickGroup"));
            if (!tg.fn) continue;
            // ETickingGroup: TG_PrePhysics 0, TG_PostPhysics 4.
            tg.byte(STR("NewTickGroup"), want ? 4 : 0);
            tg.run();
            set_on[i] = c;
            set_post[i] = want;
            HSVR_LOG("Pose: %s now ticks %s the physics", i == 0 ? "his posed skeleton" : "his visible body", want ? "after" : "before");
        }
        g_pose_post_physics.store(want && set_on[0] == driver && set_post[0]);
        static UObject* prereq_on = nullptr;
        static bool prereq_on_tracked = track_freed(&prereq_on);
        if (cfg.pose_mesh_after_driver && mesh && driver && prereq_on != mesh)
        {
            Call add(mesh, STR("AddTickPrerequisiteComponent"));
            add.object(STR("PrerequisiteComponent"), driver);
            if (add.fn && add.run())
            {
                prereq_on = mesh;
                HSVR_LOG("Pose: his visible body now always ticks after his posed skeleton");
            }
        }
    }

    void set_named_number(UObject* owner, const TCHAR* name, double value);

    // ---- Worn armour: animated every frame, and the helmet measured against your headset ---------
    // Each worn piece is its own skeletal mesh on CharacterMesh0 copying its pose (ABP_CopyPose,
    // PostUpdateWork), with update-rate optimisation on (torso_lean_and_helmet.md). pose_no_uro turns
    // that off on his body, head and armour, and has his body refresh its bones every frame.
    UObject* g_helmet = nullptr;     // the worn piece tagged "Head 2" or "Head 1" (helmet, hood), or null
    UObject* g_helmet_pawn = nullptr;
    std::vector<UObject*> g_head_pieces; // every worn piece on the head, and his head (CharacterMesh_Head)
    struct HeadWear
    {
        UObject* comp;
        int slot; // 2: tagged "Head 2" (helmet), 1: "Head 1" (hood, coif, cap)
    };
    std::vector<HeadWear> g_head_wear; // worn pieces on the head only (helmet_view)
    bool fade_face_covering(UObject* comp, const hsvr::Config& cfg, std::wstring* mesh_name);
    void armour_scan(const hsvr::Config& cfg, UObject* pawn, UObject* mesh)
    {
        static double last = 0.0;
        double now = hsvr::now_seconds();
        if (pawn == g_helmet_pawn && now - last < 1.0) return;
        last = now;
        if (pawn != g_helmet_pawn) g_helmet = nullptr;
        g_helmet_pawn = pawn;
        UObject* helmet = nullptr;
        std::vector<UObject*> parts;
        Call kids(mesh, STR("GetChildrenComponents"));
        kids.flag(STR("bIncludeAllDescendants"), false);
        if (kids.run())
            if (FProperty* cp = kids.param(STR("Children")))
            {
                struct RawArray
                {
                    UObject** data;
                    int32_t num, max;
                };
                RawArray* arr = reinterpret_cast<RawArray*>(kids.buffer.data() + cp->GetOffset_Internal());
                for (int32_t i = 0; arr->data && i < arr->num && i < 512; ++i)
                    if (UObject* c = arr->data[i])
                        if (c->GetClassPrivate()->GetName().find(STR("SkeletalMeshComponent")) != std::wstring::npos) parts.push_back(c);
            }
        int tagged = 0;
        std::vector<UObject*> head_pieces;
        std::vector<HeadWear> head_wear;
        if (UObject* head = object_property(pawn, STR("CharacterMesh_Head"))) head_pieces.push_back(head);
        for (UObject* c : parts)
            for (const TCHAR* tag : {STR("Head 2"), STR("Head 1")})
            {
                Call has(c, STR("ComponentHasTag"));
                has.name(STR("Tag"), FName(tag, FNAME_Add));
                if (!has.run()) continue;
                FProperty* rp = has.param(STR("ReturnValue"));
                if (rp && *(has.buffer.data() + rp->GetOffset_Internal()))
                {
                    if (!helmet || tag[5] == L'2') helmet = c; // the helmet slot (Head 2) over a hood (Head 1)
                    head_pieces.push_back(c);
                    head_wear.push_back(HeadWear{c, tag[5] == L'2' ? 2 : 1});
                    ++tagged;
                    break;
                }
            }
        if (helmet != g_helmet)
        {
            UObject* sk = helmet ? object_property(helmet, STR("SkeletalMesh")) : nullptr;
            if (helmet && !sk) sk = object_property(helmet, STR("SkeletalMeshAsset"));
            HSVR_LOG("Helmet: %ls, mesh %ls (%d skeletal pieces on his body, %d on the head)", helmet ? helmet->GetFullName().c_str() : STR("none worn"),
                     sk ? sk->GetName().c_str() : STR("-"), (int)parts.size(), tagged);
        }
        g_helmet = helmet;
        g_head_pieces = head_pieces;
        g_head_wear = head_wear;
        if (cfg.pose_no_uro)
        {
            static int said = 0;
            parts.push_back(mesh);
            parts.push_back(object_property(pawn, STR("CharacterMesh_Head")));
            parts.push_back(object_property(pawn, STR("DriverSkeleton")));
            int changed = 0;
            for (UObject* c : parts)
            {
                if (!c) continue;
                FProperty* p = prop_chain(c, STR("bEnableUpdateRateOptimizations"));
                if (!p || p->GetClass().GetName() != STR("BoolProperty")) continue;
                auto* flag = static_cast<FBoolProperty*>(p);
                uint8_t* byte = reinterpret_cast<uint8_t*>(c) + p->GetOffset_Internal() + flag->GetByteOffset();
                if (*byte & flag->GetFieldMask())
                {
                    *byte &= (uint8_t)~flag->GetFieldMask();
                    ++changed;
                }
            }
            // EVisibilityBasedAnimTickOption: AlwaysTickPoseAndRefreshBones 0.
            if (FProperty* p = prop_chain(mesh, STR("VisibilityBasedAnimTickOption")))
            {
                uint8_t* at = reinterpret_cast<uint8_t*>(mesh) + p->GetOffset_Internal();
                if (*at != 0)
                {
                    HSVR_LOG("Pose: his body's animation tick option was %d; now refreshes its bones every frame", (int)*at);
                    *at = 0;
                }
            }
            if (changed && said < 20)
            {
                ++said;
                HSVR_LOG("Pose: update-rate optimisation off on %d of his meshes (body, head, armour)", changed);
            }
        }
    }

    // ---- Helmet on this frame's headset pose (pose_helmet_late) ----------------------------------
    // The pose runs on the headset pose read when the previous frame's views were set up; the view then
    // takes a newer one. Right after the view takes it, every head piece is moved rigidly by the change
    // (new headset pose x the one the pose used, inverted), so it sits exactly where the view is. Its
    // place on the body is put back at the start of the next pose.
    bool head_pose_world(const hsvr::Config& cfg, const hsvr::ControllerState& state, hsvr::Vec3& w, hsvr::Quat& r);
    struct HeadUsed
    {
        bool valid = false;
        hsvr::Vec3 at;   // headset (eyes) in the world, as this frame's pose used it
        hsvr::Quat rot;
        UObject* pawn = nullptr;
    } g_head_used;
    struct MovedPiece
    {
        UObject* comp;
        double loc[3], rot[3];
    };
    std::vector<MovedPiece> g_late_moved;
    struct LateStats
    {
        double worst_cm = 0, worst_deg = 0, sum_cm = 0, after_worst = 0, view_worst = 0, view_worst_deg = 0;
        int n = 0;
        double last_log = 0;
    } g_late_stats;

    void late_restore()
    {
        for (auto& m : g_late_moved)
        {
            Call c(m.comp, STR("K2_SetRelativeLocationAndRotation"));
            c.three(STR("NewLocation"), m.loc[0], m.loc[1], m.loc[2]);
            c.three(STR("NewRotation"), m.rot[0], m.rot[1], m.rot[2]);
            c.flag(STR("bSweep"), false);
            c.flag(STR("bTeleport"), true);
            c.run();
        }
        g_late_moved.clear();
    }

    void helmet_on_latch()
    {
        using namespace hsvr;
        hsvr::Config cfg = config();
        if (!cfg.pose_helmet_late || !g_head_used.valid || !g_pose_active.load()) return;
        UObject* pawn = live_posed_pawn();
        if (!pawn || pawn != g_head_used.pawn || pawn != g_helmet_pawn || g_head_pieces.empty()) return;
        Vec3 w;
        Quat r;
        if (!head_pose_world(cfg, controllers_state(), w, r)) return;
        // Where the head bone belongs on the view's headset pose (as the head lock puts it).
        Vec3 want = w - r.rotate(Vec3{cfg.eye_forward_cm, 0.0, cfg.eye_up_cm});
        Quat want_rot = (r * g_pose.head_offset).normalized();
        Quat dr = (r * g_head_used.rot.inverse()).normalized();
        double view_cm = length(w - g_head_used.at), view_deg = 2.0 * std::acos((std::min)(1.0, std::fabs(dr.w))) * kRadToDeg;
        late_restore();
        double off_cm = 0.0, off_deg = 0.0, after = 0.0;
        for (UObject* c : g_head_pieces)
        {
            if (!c) continue;
            FProperty* lp = prop_chain(c, STR("RelativeLocation"));
            FProperty* rp = prop_chain(c, STR("RelativeRotation"));
            if (!lp || !rp) continue;
            // Each piece is moved so ITS head bone lands on the view's head spot: this takes out both the
            // view's newer headset pose and anything his body drew late.
            Vec3 bone = socket_location(c, bone_fname("head"));
            Quat bone_rot = socket_rotation(c, bone_fname("head"));
            Quat d = (want_rot * bone_rot.inverse()).normalized();
            double cm = length(want - bone), deg = 2.0 * std::acos((std::min)(1.0, std::fabs(d.w))) * kRadToDeg;
            off_cm = (std::max)(off_cm, cm);
            off_deg = (std::max)(off_deg, deg);
            if (cm > 20.0 || deg > 45.0) continue; // not a frame's drift: leave it on the body
            MovedPiece m{c, {0, 0, 0}, {0, 0, 0}};
            read_three(reinterpret_cast<uint8_t*>(c) + lp->GetOffset_Internal(), lp, m.loc);
            read_three(reinterpret_cast<uint8_t*>(c) + rp->GetOffset_Internal(), rp, m.rot);
            Vec3 at = component_location(c);
            Quat rot = component_rotation(c);
            set_component_transform(c, want + d.rotate(at - bone), (d * rot).normalized(), true);
            g_late_moved.push_back(m);
            after = (std::max)(after, length(socket_location(c, bone_fname("head")) - want));
        }
        auto& st = g_late_stats;
        st.worst_cm = (std::max)(st.worst_cm, off_cm);
        st.worst_deg = (std::max)(st.worst_deg, off_deg);
        st.after_worst = (std::max)(st.after_worst, after);
        st.sum_cm += off_cm;
        st.view_worst = (std::max)(st.view_worst, view_cm);
        st.view_worst_deg = (std::max)(st.view_worst_deg, view_deg);
        ++st.n;
        double now = now_seconds();
        if (now - st.last_log >= 0.25)
        {
            st.last_log = now;
            HSVR_LOG("Helmet: as drawn before the late move, off the view's head spot by worst %.2f cm / %.2f deg (mean %.2f cm) over %d frames, %d head pieces; "
                     "after the move worst %.3f cm; the view's headset moved %.2f cm / %.2f deg since the pose",
                     st.worst_cm, st.worst_deg, st.n ? st.sum_cm / st.n : 0.0, st.n, (int)g_head_pieces.size(), st.after_worst, st.view_worst, st.view_worst_deg);
            st = LateStats{};
            st.last_log = now;
        }
    }

    // Your headset in the world, as the pose uses it (with the test's made-up nod, hsvr.fake_head_tilt).
    bool head_pose_world(const hsvr::Config& cfg, const hsvr::ControllerState& state, hsvr::Vec3& w, hsvr::Quat& r)
    {
        using namespace hsvr;
        if (state.head_valid)
        {
            if (!stereo_tracking_to_world(state.head, w, r)) return false;
        }
        else
        {
            double base_yaw = 0.0;
            if (!g_fake_head_pose.load() || !stereo_view_anchor(w, base_yaw)) return false;
            r = quat_from_yaw_deg(base_yaw);
        }
        double p = g_fake_tilt_pitch.load(), ro = g_fake_tilt_roll.load(), dr = g_fake_tilt_drop.load();
        if (double wa = g_fake_wobble_deg.load(); wa != 0.0) p += wa * std::sin(now_seconds() * 2.0 * kPi * g_fake_wobble_hz.load());
        if (p != 0.0 || ro != 0.0 || dr != 0.0)
        {
            Vec3 eye_offset{cfg.eye_forward_cm, 0.0, cfg.eye_up_cm};
            Vec3 pivot = w - r.rotate(eye_offset) - Vec3{0.0, 0.0, 12.0};
            Quat y = quat_from_yaw_deg(quat_yaw_deg(r));
            Quat t = (quat_axis_angle(y.rotate({0, 1, 0}), p * kDegToRad) * quat_axis_angle(y.rotate({1, 0, 0}), -ro * kDegToRad)).normalized();
            w = pivot + t.rotate(w - pivot) - Vec3{0.0, 0.0, dr};
            r = (t * r).normalized();
        }
        if (double sf = g_fake_shift_fwd.load(), sr = g_fake_shift_right.load(); sf != 0.0 || sr != 0.0)
            w = w + quat_from_yaw_deg(quat_yaw_deg(r)).rotate(Vec3{sf, sr, 0.0});
        return true;
    }

    // Torso lean for this frame: how far to bend (from your head's pitch and roll, smoothed), held to
    // what the head height allows (his hips can't rise above standing: drop + head_moved.z >= -slack),
    // and the twist share (pose_torso_twist). Fills g_lean.q / head_moved.
    void lean_update(const hsvr::Config& cfg, bool have_head, const hsvr::Quat& head_rot, double heading, double drop, double deficit)
    {
        using namespace hsvr;
        double now = now_seconds(), dt = now - g_lean.t;
        g_lean.t = now;
        double want_f = 0.0, want_s = 0.0, twist = 0.0;
        if (have_head)
        {
            Vec3 f = head_rot.rotate({1, 0, 0}), rt = head_rot.rotate({0, 1, 0});
            g_lean.pitch = std::asin((std::max)(-1.0, (std::min)(1.0, -f.z))) * kRadToDeg;
            g_lean.roll = std::asin((std::max)(-1.0, (std::min)(1.0, -rt.z))) * kRadToDeg;
            if (cfg.pose_lean && g_lean.calibrated && cfg.pose_lean_head_angle)
            {
                want_f = (std::min)(cfg.pose_lean_max_deg, (std::max)(0.0, g_lean.pitch - cfg.pose_lean_pitch_dead_deg) * cfg.pose_lean_pitch_gain);
                double r = std::fabs(g_lean.roll) - cfg.pose_lean_roll_dead_deg;
                want_s = r > 0.0 ? (std::min)(cfg.pose_lean_side_max_deg, r * cfg.pose_lean_roll_gain) * (g_lean.roll < 0.0 ? -1.0 : 1.0) : 0.0;
            }
            if (cfg.pose_torso_twist > 0.0)
            {
                double rel = quat_yaw_deg(head_rot) - heading;
                while (rel > 180.0) rel -= 360.0;
                while (rel < -180.0) rel += 360.0;
                twist = (std::max)(-90.0, (std::min)(90.0, rel)) * (std::min)(1.0, cfg.pose_torso_twist);
            }
        }
        // Looking down, his chest leans back out of the view (the way closed PR #8/#10 did it, which
        // Matthew found right, 2026-11-21): the head is aimed this far behind your neck, up to
        // pose_lean_look_down_back_cm at 60 degrees down, from 5. "Back" is away from where the head
        // faces (its forward and its top both tip that way when it looks down).
        g_lean.aim = g_lean.offset;
        g_lean.look_back = 0.0;
        if (have_head && cfg.pose_lean && g_lean.calibrated && cfg.pose_lean_look_down_back_cm > 0.0)
        {
            Vec3 look = head_rot.rotate({1, 0, 0}), top = head_rot.rotate({0, 0, 1});
            double sgn = look.z < 0.0 ? 1.0 : -1.0;
            Vec3 ahead{look.x + top.x * sgn, look.y + top.y * sgn, 0.0};
            double down = std::asin((std::max)(-1.0, (std::min)(1.0, -look.z))) * kRadToDeg;
            if (down > 5.0 && length(ahead) > 0.05)
            {
                g_lean.look_back = cfg.pose_lean_look_down_back_cm * (std::min)(1.0, (down - 5.0) / 55.0);
                // Not while he bends down for depth: reaching for the floor, his chest goes over his knees,
                // not back out of your view (it pushed his shoulders 16 cm further from your hands).
                if (cfg.pose_crouch_bend_for_depth && cfg.pose_crouch_bend_neck_follow > 0.0)
                    g_lean.look_back *= (std::max)(0.0, 1.0 - deficit / 10.0);
                Vec3 a = quat_from_yaw_deg(heading).inverse().rotate(normalized(ahead));
                g_lean.aim = g_lean.offset - Vec3{a.x, a.y, 0.0} * g_lean.look_back;
            }
        }
        // Lean first, step after: the bend that puts his head over your neck's offset from his hips
        // (about the spine_02 joint, head height h above it).
        g_lean.off_fwd = g_lean.off_side = 0.0;
        if (cfg.pose_lean && g_lean.calibrated && cfg.pose_lean_step_radius_cm > 0.0)
        {
            double h = (std::max)(20.0, g_lean.pts[6].z - g_lean.pts[0].z);
            auto as = [](double v, double lo, double hi) { return std::asin((std::max)(lo, (std::min)(hi, v))) * kRadToDeg; };
            const Vec3& aim = g_lean.aim;
            double of = as(aim.x / h, -0.34, 0.95), os = as(aim.y / h, -0.7, 0.7); // back at most 20 degrees
            // The neck bends back against the spine, so the head goes less far than h sin(bend): scale the
            // bends until the head is carried by your offset, or his hips end off the capsule (test: 11 deg
            // carried the head 7 cm of an 11 cm offset).
            for (int it = 0; it < 3; ++it)
            {
                Quat tq[6];
                Vec3 mm = lean_fk(of, os, 0.0, tq);
                if (std::fabs(mm.x) > 0.5 && std::fabs(aim.x) > 0.5) of *= aim.x / mm.x;
                if (std::fabs(mm.y) > 0.5 && std::fabs(aim.y) > 0.5) os *= aim.y / mm.y;
                of = (std::max)(-20.0, (std::min)(72.0, of));
                os = (std::max)(-44.0, (std::min)(44.0, os));
            }
            g_lean.off_fwd = of;
            g_lean.off_side = os;
            // With the head's own bends: the same way, the larger one; opposite ways, both.
            auto merge = [](double a, double b) { return a * b > 0.0 ? (std::fabs(a) > std::fabs(b) ? a : b) : a + b; };
            want_f = (std::min)(cfg.pose_lean_max_deg, merge(want_f, g_lean.off_fwd));
            want_s = (std::max)(-cfg.pose_lean_side_max_deg - 15.0, (std::min)(cfg.pose_lean_side_max_deg + 15.0, merge(want_s, g_lean.off_side)));
        }
        // Deeper than his legs can crouch (deficit): he bends forward until his head is down there too, so
        // his shoulders and hands come down with your view (playtest 2026-11-21: crouch button plus a real
        // crouch, and his hands still could not reach the ground).
        g_lean.reach_fwd = 0.0;
        double share = (std::max)(0.0, (std::min)(1.0, cfg.pose_crouch_bend_neck_follow));
        if (cfg.pose_lean && g_lean.calibrated && cfg.pose_crouch_bend_for_depth && deficit > 0.5)
        {
            Quat tq[6];
            double lo = 0.0, hi = (std::max)(cfg.pose_lean_max_deg, cfg.pose_crouch_bend_max_deg);
            if (lean_fk(hi, want_s, 0.0, tq, hi * share).z > -deficit) lo = hi; // even the deepest bend is not enough
            else
                for (int it = 0; it < 12; ++it)
                {
                    double mid = 0.5 * (lo + hi);
                    if (lean_fk(mid, want_s, 0.0, tq, mid * share).z > -deficit) lo = mid;
                    else hi = mid;
                }
            g_lean.reach_fwd = lo;
            want_f = (std::max)(want_f, lo);
        }
        g_lean.want_fwd = want_f;
        g_lean.want_side = want_s;
        double a = (cfg.pose_lean_smooth_s > 1e-4 && dt > 0.0 && dt < 0.2) ? 1.0 - std::exp(-dt / cfg.pose_lean_smooth_s) : 1.0;
        double f = g_lean.fwd + (want_f - g_lean.fwd) * a, sd = g_lean.side + (want_s - g_lean.side) * a;
        g_lean.depth_free += (g_lean.reach_fwd * share - g_lean.depth_free) * a;
        g_lean.twist = twist;
        if (!g_lean.calibrated)
        {
            g_lean.fwd = g_lean.side = 0.0;
            for (auto& q : g_lean.q) q = Quat{};
            g_lean.head_moved = {};
            return;
        }
        // Held to the head height: the largest share of (f, sd) whose head drop fits.
        double lo = 0.0, hi = 1.0;
        Quat q[6];
        Vec3 m = lean_fk(f, sd, twist, q);
        if (drop + m.z < -cfg.pose_lean_slack_cm)
        {
            for (int it = 0; it < 10; ++it)
            {
                double mid = 0.5 * (lo + hi);
                if (drop + lean_fk(f * mid, sd * mid, twist, q).z < -cfg.pose_lean_slack_cm) hi = mid;
                else lo = mid;
            }
            f *= lo;
            sd *= lo;
            m = lean_fk(f, sd, twist, q);
            g_lean.held = lo;
        }
        else
            g_lean.held = 1.0;
        g_lean.fwd = f;
        g_lean.side = sd;
        for (int i = 0; i < 6; ++i) g_lean.q[i] = q[i];
        g_lean.head_moved = m;
    }

    void pose_body(const hsvr::Config& cfg)
    {
        using namespace hsvr;
        UObject* pawn = nullptr;
        UObject* mesh = find_pawn_mesh(&pawn);
        // A new map or a new life: everything kept about the old pawn's weapons and holds goes.
        if (g_pose.pawn && pawn != g_pose.pawn) forget_level_objects();
        if (pawn && pawn == g_pose.pawn) late_restore(); // the head pieces back on his body (pose_helmet_late)
        else g_late_moved.clear();
        g_head_used.valid = false;
        bool willie = pawn && pawn->GetFullName().find(STR("Willie_BP")) != std::wstring::npos;
        UObject* driver = willie ? object_property(pawn, STR("DriverSkeleton")) : nullptr;
        UObject* instance = object_property(driver, STR("AnimScriptInstance"));
        bool abp = instance && instance->GetClassPrivate()->GetName().find(STR("ABP_Willie")) != std::wstring::npos;
        // Mouse and keyboard (input_mode): the plain flat game in the headset, as the mod's first build was
        // (Matthew 2026-11-24): no posing, no VR hold, grab, lean, turning, capsule hold or the rest.
        bool want_pose = cfg.pose_body && !g_kbm.load();
        if (!want_pose && g_kbm.load() && g_pose.pawn && g_pose.pawn == pawn) enter_plain_game(pawn);
        g_hold_capsule.store(want_pose && cfg.pose_hold_capsule && abp && mesh && g_pose.calibrated && g_pose.pawn == pawn);
        g_pose_active.store(want_pose && abp && mesh && g_pose.calibrated && g_pose.pawn == pawn);
        g_pose_cfg_turn = cfg.pose_body_turn;
        g_pose_cfg_crouch = cfg.pose_crouch;
        g_pose_fake = cfg.dev_pose_fake_tracking;
        g_turn_dead_deg = cfg.pose_turn_dead_zone_deg;
        g_turn_speed_dps = cfg.pose_turn_speed_dps;
        g_turn_max_deg = (std::max)(g_turn_dead_deg, cfg.pose_turn_max_deg);
        if (!g_pose_active.load()) g_turn_valid = false;
        if (!want_pose || !abp || !mesh)
        {
            if (g_pose.pawn && (pawn == g_pose.pawn)) pose_release();
            else if (g_pose.pawn)
            {
                g_pose = PoseState{}; // character gone: nothing to restore
                feet_reset();
                g_pose_anchor_fixed = false;
                g_pose_room_moved_local = {};
            }
            return;
        }
        if (g_pose.pawn != pawn || g_pose.instance != instance)
        {
            g_pose = PoseState{};
            feet_reset();
            g_effector_looked = false;
            g_anim_update = nullptr;
            g_pose.pawn = pawn;
            g_pose.mesh = mesh;
            g_pose.driver = driver;
            g_pose.instance = instance;
            g_pose.chain = final_chain_nodes(instance);
            g_pose.calibrated = pose_calibrate(cfg);
        }
        // Dead, or both legs out: he falls (physics on) and nothing below poses him.
        if (g_pose.calibrated && injury_down_tick(cfg, pawn, mesh)) return;
        // Keep physics off: the game turns it on again after a spawn and when it rescales the body.
        double now = now_seconds();
        // For a moment after a strength gain the check runs every tick: the game's rescale switches his
        // ragdoll on ~70 ms after Gain Muscle returns (test eb248e7), past the hook.
        if (now < g_physics_watch_until && now - g_pose.last_check < 0.5 && is_simulating(mesh, "pelvis") == 1)
        {
            set_simulate(mesh, false);
            HSVR_LOG("Strength: the game switched his physics on %.0f ms after the gain; switched off this tick",
                     (now - (g_physics_watch_until - 1.5)) * 1000.0);
        }
        if (now - g_pose.last_check >= 0.5)
        {
            g_pose.last_check = now;
            pose_tick_group(cfg, driver, mesh);
            if (is_simulating(mesh, "pelvis") == 1)
            {
                HSVR_LOG_EVERY(5.0, "Pose: the game switched physics on again; switching it off");
                if (g_joint_trace.load()) HSVR_LOG("Joint: physics found on at the pelvis and switched off again (this tick)");
                apply_arm_physics(cfg);
            }
        }

        ControllerState state = controllers_state();
        double heading = actor_heading(pawn);
        Quat body = quat_from_yaw_deg(heading);
        Vec3 actor = actor_location(pawn);

        // Walking in the room moves the game's capsule (with collision), so the game, the camera
        // and the body agree on where you are; the view takes the same amount off its anchor.
        Vec3 room{0, 0, 0};
        Vec3 anchor;
        double base_yaw = 0.0;
        if (cfg.pose_follow_room && (state.head_valid || g_fake_head_pose.load()) && stereo_view_anchor(anchor, base_yaw))
        {
            Vec3 head_world;
            Quat head_rot;
            if (head_pose_world(cfg, state, head_world, head_rot))
            {
                // Walking is measured at your neck, not your eyes: your eyes swing round your neck when
                // you turn or nod, and that is not a step (a 180 degree turn moved the eyes ~18 cm and
                // walked his body out in front of you). The view's anchor is the eye point when you
                // recentred, so the neck then was eye_forward/eye_up behind and below it.
                Quat base = quat_from_yaw_deg(base_yaw);
                Vec3 eye_offset{cfg.eye_forward_cm, 0.0, cfg.eye_up_cm};
                // At the base of the neck (pose_room_neck_base_cm below the head joint, turning with the head):
                // nodding or tilting your head swings the head joint ~10 cm about it, and that is not a lean
                // or a step (test 2026-11-21: a 60 degree look down stepped him 10 cm).
                Vec3 neck_base{0.0, 0.0, (std::max)(0.0, cfg.pose_room_neck_base_cm)};
                Vec3 neck_now = head_world - head_rot.rotate(eye_offset + neck_base);
                Vec3 neck_then = anchor - base.rotate(eye_offset + neck_base);
                Vec3 total = base.inverse().rotate(Vec3{neck_now.x - neck_then.x, neck_now.y - neck_then.y, 0.0});
                total.z = 0.0;
                Vec3 delta = total - g_pose_room_moved_local;
                // Lean first, step after: while your neck stays within pose_lean_step_radius_cm of where his
                // hips stand, the capsule stays put and his torso leans to put his head there (lean_update).
                // Once it goes past the radius he steps: the hips come back under your neck over
                // pose_lean_walk_catchup_s and stay with you (walking) until they are under it again.
                // (64ae2ba also caught up whenever the neck moved faster than 50 cm/s; any quick lean did
                // that, and the hips followed half of a 20 cm lean. Test 2026-11-20 17:06 local.)
                Vec3 follow = delta;
                double radius = cfg.pose_lean && g_lean.calibrated ? (std::min)(40.0, (std::max)(0.0, cfg.pose_lean_step_radius_cm)) : 0.0;
                static bool stepping = false;
                static double last_t = 0.0;
                double tn = now_seconds(), dtn = tn - last_t;
                last_t = tn;
                // How long your neck has been still: a lean you hold still is a new stance, so he steps under
                // you after pose_lean_settle_s (playtest 2026-11-21: after shuffling, he stayed leaned 10-20 cm
                // toward your head for minutes, "never in line with my own spine").
                static Vec3 last_neck;
                static double neck_speed = 0.0, still_s = 0.0;
                if (dtn > 0.0 && dtn < 0.2)
                {
                    double v = length(Vec3{neck_now.x - last_neck.x, neck_now.y - last_neck.y, 0.0}) / dtn;
                    neck_speed += (v - neck_speed) * (1.0 - std::exp(-dtn / 0.15));
                    still_s = neck_speed < cfg.pose_lean_settle_speed_cms ? still_s + dtn : 0.0;
                }
                last_neck = neck_now;
                if (radius > 0.0)
                {
                    // Backwards he doesn't lean (nobody leans back to sit into a crouch): past
                    // pose_lean_back_radius_cm behind his hips, the capsule follows at once (playtest
                    // 2026-11-21: crouching put your neck 25 cm back and he leaned 20 degrees backwards,
                    // shoulders up and away from the floor).
                    Vec3 back_follow{0.0, 0.0, 0.0};
                    {
                        Vec3 dl = body.inverse().rotate(base.rotate(delta));
                        double br = (std::max)(0.0, cfg.pose_lean_back_radius_cm);
                        if (dl.x < -br) back_follow = base.inverse().rotate(body.rotate(Vec3{dl.x + br, 0.0, 0.0}));
                        back_follow.z = 0.0;
                    }
                    Vec3 rest = delta - back_follow;
                    double d = length(rest);
                    bool past = cfg.pose_lean_follow_past_radius; // closed PR #8/#10: beyond the radius the hips follow at once
                    if (d > radius && !past) stepping = true;
                    if (!stepping && cfg.pose_lean_settle_s > 0.0 && still_s > cfg.pose_lean_settle_s && d > 5.0)
                    {
                        stepping = true;
                        HSVR_LOG_EVERY(1.0, "Lean: your neck held %.0f cm from his hips for %.1f s: he steps under you", d, still_s);
                    }
                    double keep = 1.0; // share of the offset kept as lean
                    if (past && !stepping && d > radius)
                    {
                        double over = d - radius;
                        double most = (dtn > 0.0 && dtn < 0.2) ? (std::max)(1.0, cfg.pose_lean_follow_speed_cms) * dtn : over;
                        keep = (d - (std::min)(over, most)) / d;
                    }
                    else if (stepping)
                    {
                        double tau = cfg.pose_lean_walk_catchup_s;
                        keep = (tau > 1e-3 && dtn > 0.0 && dtn < 0.2) ? std::exp(-dtn / tau) : 0.0;
                        if (d * keep > radius) keep = radius / d; // never further out than the radius
                        // At least 0.6 cm a frame, so the step ends under your neck: the last few cm moved
                        // less than the 0.3 cm move threshold a frame, and the step never ended (test
                        // 17:40 local: stuck 3.3 cm out, and the next lean stepped instead of leaning).
                        if (d > 1e-6 && d * (1.0 - keep) < 0.6) keep = (std::max)(0.0, 1.0 - 0.6 / d);
                        if (d < 0.6) stepping = false;
                    }
                    follow = back_follow + rest * (1.0 - keep);
                }
                else
                    stepping = false;
                if (length(delta) > 50.0 + radius)
                {
                    g_pose_room_moved_local = total; // recentred or tracking jumped: take it as the new start
                }
                else if (length(follow) > 0.3)
                {
                    Vec3 want = actor + base.rotate(follow);
                    // Not into a wall (his capsule doesn't block on scenery; the sweep below doesn't stop it).
                    bool walled = false;
                    Vec3 asked = want;
                    want = body_wall_sweep(pawn, actor, want, walled);
                    // What the wall held back is taken as walked: the view stays with him at the wall
                    // instead of going on into it and snapping back at the 50 cm recentre below.
                    if (walled)
                    {
                        Vec3 held = base.inverse().rotate(Vec3{asked.x - want.x, asked.y - want.y, 0.0});
                        held.z = 0.0;
                        g_pose_room_moved_local = g_pose_room_moved_local + held;
                    }
                    Call move(pawn, STR("K2_SetActorLocation"));
                    move.three(STR("NewLocation"), want.x, want.y, want.z);
                    move.flag(STR("bSweep"), true);
                    move.flag(STR("bTeleport"), false);
                    move.run();
                    Vec3 moved = actor_location(pawn) - actor;
                    moved.z = 0.0;
                    g_pose_room_moved_local = g_pose_room_moved_local + base.inverse().rotate(moved);
                    g_pose_room_moved_local.z = 0.0;
                    actor = actor + moved;
                    room = moved;
                    g_wall_ok = actor_location(pawn), g_wall_ok_have = true;
                }
            }
        }
        // Your neck's offset from where his hips stand (what the capsule has not followed), in his body's frame.
        g_lean.offset = {};
        if (cfg.pose_follow_room && (state.head_valid || g_fake_head_pose.load()) && stereo_view_anchor(anchor, base_yaw))
        {
            Vec3 head_world;
            Quat head_rot;
            if (head_pose_world(cfg, state, head_world, head_rot))
            {
                Quat base = quat_from_yaw_deg(base_yaw);
                Vec3 eye_offset{cfg.eye_forward_cm, 0.0, cfg.eye_up_cm};
                Vec3 neck_base{0.0, 0.0, (std::max)(0.0, cfg.pose_room_neck_base_cm)};
                Vec3 total = base.inverse().rotate((head_world - head_rot.rotate(eye_offset + neck_base)) - (anchor - base.rotate(eye_offset + neck_base)));
                Vec3 d{total.x - g_pose_room_moved_local.x, total.y - g_pose_room_moved_local.y, 0.0};
                if (length(d) <= 50.0 + 40.0) g_lean.offset = body.inverse().rotate(base.rotate(d));
                g_lean.offset.z = 0.0;
            }
        }
        // Put the body so its pelvis stands on the capsule. The game pulls the capsule toward the
        // pelvis; a pelvis anywhere else would drag the capsule along and the body with it.
        Vec3 mesh_now = component_location(mesh);
        Vec3 pelvis_off = socket_location(driver, bone_fname("pelvis")) - mesh_now;
        // The capsule's height, smoothed once a frame (see g_actor_z_smooth); the view uses the same value.
        {
            static double last_t = 0.0;
            double tnow = now_seconds(), dt = tnow - last_t;
            last_t = tnow;
            double tau = cfg.pose_actor_z_smooth_s;
            g_actor_z_smooth_on = tau > 1e-4;
            if (!g_actor_z_smooth_on || g_actor_z_smooth < -1e8 || std::fabs(actor.z - g_actor_z_smooth) > 15.0 || !(dt > 0.0 && dt < 0.2))
                g_actor_z_smooth = actor.z;
            else
                g_actor_z_smooth += (actor.z - g_actor_z_smooth) * (1.0 - std::exp(-dt / tau));
        }
        actor.z = g_actor_z_smooth;
        Vec3 place = actor + body.rotate(g_pose.mesh_offset_local);
        place.x = actor.x - pelvis_off.x;
        place.y = actor.y - pelvis_off.y;
        // Crouching: the body goes down by as much as your headset is below where you stood when
        // you recentred. His leg IK keeps the feet planted, so the knees bend. Never raised above
        // standing (the leg IK only stretches 1.1x), and at most pose_crouch_max_cm (times his size) down;
        // deeper than that he bends forward (pose_crouch_bend_for_depth).
        g_crouch_drop = 0.0;
        if (cfg.pose_crouch && cfg.dev_pose_fake_tracking)
        {
            // Made-up path: slowly down to 40 cm and back up; hsvr.fake_head_drop <cm> holds a depth.
            double held = g_fake_head_drop.load();
            static double eased = 0.0, eased_t = -1.0;
            double tn = now_seconds(), gap = eased_t < 0.0 ? 0.0 : (std::min)(0.1, tn - eased_t);
            eased_t = tn;
            double want = held >= 0.0 ? held : 20.0 - 20.0 * std::cos(tn * 0.4);
            double v = g_fake_head_speed.load();
            // Back to the made-up path (-1) eased too: snapping up from 82 cm in one frame flung a lantern let go at his feet
            // 18 m/s (run 11 floor_pickup_62 32.488), a stand no player can do. The made-up path itself moves under 10 cm/s.
            if (v <= 0.0) eased = want;
            else eased += (std::max)(-v * gap, (std::min)(v * gap, want - eased));
            g_crouch_drop = eased;
        }
        else if (cfg.pose_crouch && (state.head_valid || g_fake_head_pose.load()))
        {
            Vec3 view_anchor, head_world;
            Quat head_rot;
            double unused_yaw = 0.0;
            if (stereo_view_anchor(view_anchor, unused_yaw) && head_pose_world(cfg, state, head_world, head_rot))
            {
                double scale = component_scale_z(mesh);
                // Measured at the neck too, so looking down is not crouching: at the base of the neck
                // (pose_room_neck_base_cm below the head joint, as walking measures it), not at the head
                // joint, which drops ~7 cm about the neck base when you look 66 deg down (playtest
                // 2026-11-23 17:22 local: standing and looking at his legs read as a 10 cm crouch, "my
                // Willie is standing weird, as if he's squatted"). pose_crouch_at_neck_base=0: the head joint.
                Vec3 eye_offset{cfg.eye_forward_cm, 0.0, cfg.eye_up_cm};
                if (cfg.pose_crouch_at_neck_base) eye_offset.z += (std::max)(0.0, cfg.pose_room_neck_base_cm);
                double neck_now_z = (head_world - head_rot.rotate(eye_offset)).z;
                double neck_then_z = view_anchor.z - eye_offset.z;
                double drop = (neck_then_z - neck_now_z) - cfg.pose_crouch_dead_zone_cm;
                (void)scale;
                g_crouch_drop = (std::max)(0.0, drop);
            }
        }
        if (cfg.pose_crouch && cfg.pose_crouch_button_cm > 0.0)
        {
            static bool click_was = false;
            bool click = state.hand[0].stick_click || g_fake_stick_click.load();
            if (click && !click_was)
            {
                g_button_crouch_on = !g_button_crouch_on;
                controllers_buzz(0, 0.25f);
                HSVR_LOG("Crouch: left stick click: button crouch %s (%.0f cm)", g_button_crouch_on ? "on" : "off", cfg.pose_crouch_button_cm);
            }
            click_was = click;
            static double last = now_seconds();
            double tnow = now_seconds(), step = (std::min)(0.1, tnow - last) * cfg.pose_crouch_button_cms;
            last = tnow;
            double want = g_button_crouch_on ? cfg.pose_crouch_button_cm : 0.0;
            g_button_crouch += (std::max)(-step, (std::min)(step, want - g_button_crouch));
        }
        else
            g_button_crouch = 0.0;
        // How far your view went down (real crouch plus the button), and how far his legs can take him:
        // the rest he bends forward for (lean_update's deficit).
        double crouch_want = g_crouch_drop + g_button_crouch;
        g_crouch_want_cm = crouch_want;
        double crouch_cap = (std::max)(10.0, cfg.pose_crouch_max_cm) * component_scale_z(mesh);
        g_crouch_drop = (std::min)(crouch_cap, crouch_want);
        // Torso lean: the bend carries his head forward and down; his hips go back by the forward part
        // and stay up by the downward part, so his head still ends at your neck and the chest moves in.
        {
            Vec3 hw;
            Quat hr;
            bool have_head = !cfg.dev_pose_fake_tracking && head_pose_world(cfg, state, hw, hr);
            lean_update(cfg, have_head, hr, heading, crouch_want, (std::max)(0.0, crouch_want - crouch_cap));
            Vec3 m = g_lean.head_moved;
            // His head goes over your neck: hips at the capsule, less the bend's carry, plus your offset.
            place = place - body.rotate(Vec3{m.x - g_lean.aim.x, m.y - g_lean.aim.y, 0.0});
            g_crouch_drop = (std::min)(crouch_cap, (std::max)(0.0, crouch_want + m.z));
        }
        if (g_crouch_drop > 10.0) crouch_push_log(pawn, mesh);
        item_watch_tick(pawn);
        leg_guard_tick(pawn, object_property(pawn, STR("Mesh")), cfg);
        shoulder_slot_tick(pawn, object_property(pawn, STR("Mesh")), cfg);
        lamp_probe_tick(pawn);
        chain_calm_tick(pawn, cfg);
        arm_hanging_tick(pawn);
        {
            // pose_capsule_no_push: the engine's character physics interaction off (touch impulses and repulsion on loose
            // things by the capsule); the game's own push factors are already 0. Set once per pawn, and back when switched off.
            UObject*& set_for = g_no_push_for; // reset by enter_plain_game, which puts the engine's own back
            static bool set_to = true;
            bool want = !cfg.pose_capsule_no_push;
            if (set_for != pawn || set_to != want)
                if (UObject* movement = object_property(pawn, STR("CharacterMovement")))
                {
                    bool was = bool_property(movement, STR("bEnablePhysicsInteraction"));
                    if (set_bool_property(movement, STR("bEnablePhysicsInteraction"), want))
                        HSVR_LOG("Capsule: physics interaction with loose things %s (was %s)", want ? "on" : "off", was ? "on" : "off");
                    else
                        HSVR_LOG("Capsule: no bEnablePhysicsInteraction on %ls", movement->GetName().c_str());
                    set_for = pawn;
                    set_to = want;
                }
        }
        place.z -= g_crouch_drop;
        // Moved, not teleported: a teleport snaps his kinematic physics bodies (the hand holding a
        // weapon) to the new spot with no velocity in the first physics substep, and the held weapon
        // jolts every frame (headset tests 2-3: even the game's locked grip wobbled ~14 deg). A plain
        // move gives the bodies kinematic targets that the substeps interpolate (UE 5.4
        // SkeletalMeshComponentPhysics OnUpdateTransform -> UpdateKinematicBonesToAnim). Large jumps
        // (first placement, recentre) still teleport.
        {
            static Vec3 last_place;
            static bool have_last = false;
            bool jump = !have_last || length(place - last_place) > cfg.pose_teleport_above_cm;
            if (g_pose.calib_snap) jump = true; // turned onto the control yaw: not a swing of the bodies
            g_pose.calib_snap = false;
            set_component_transform(mesh, place, (body * g_pose.mesh_rotation_local).normalized(), jump || !cfg.pose_move_bodies);
            last_place = place;
            have_last = true;
        }

        Quat component_inv = component_rotation(driver).inverse();
        bool have_look = false;
        Quat look_rot;
        if (cfg.pose_head)
        {
            Vec3 head_world;
            Quat head_rot;
            bool have = !cfg.dev_pose_fake_tracking && head_pose_world(cfg, state, head_world, head_rot);
            if (!have && cfg.dev_pose_fake_tracking)
            {
                // Made-up path: looks left and right, and up and down.
                double t = now_seconds();
                head_rot = (body * rot_to_quat(20.0 * std::sin(t * 0.7), 40.0 * std::sin(t * 0.5), 0.0)).normalized();
                if (g_turn_valid && cfg.pose_body_turn) // the same made-up look the body turning follows
                    head_rot = (quat_from_yaw_deg(g_turn_yaw + 80.0 * std::sin(t * 0.25)) * rot_to_quat(20.0 * std::sin(t * 0.7), 0.0, 0.0)).normalized();
                have = true;
            }
            g_head_used.valid = have && !cfg.dev_pose_fake_tracking;
            g_head_used.at = head_world;
            g_head_used.rot = head_rot;
            g_head_used.pawn = pawn;
            // The helmet (and his head) as drawn last frame against where the head was sent last frame:
            // worst and mean over each quarter second (log "Helmet:").
            {
                static Vec3 prev_want;
                static Quat prev_rot;
                static bool prev_ok = false;
                static double worst_cm = 0, worst_deg = 0, sum_cm = 0, mesh_worst = 0, last_log = 0;
                static int count = 0;
                if (prev_ok)
                {
                    auto angle = [](const Quat& a, const Quat& b) {
                        double d = std::fabs(a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w);
                        return 2.0 * std::acos((std::min)(1.0, d)) * kRadToDeg;
                    };
                    double mesh_cm = length(socket_location(mesh, bone_fname("head")) - prev_want);
                    mesh_worst = (std::max)(mesh_worst, mesh_cm);
                    if (g_helmet && g_helmet_pawn == pawn)
                    {
                        double cm = length(socket_location(g_helmet, bone_fname("head")) - prev_want);
                        double deg = angle(socket_rotation(g_helmet, bone_fname("head")), prev_rot);
                        worst_cm = (std::max)(worst_cm, cm);
                        worst_deg = (std::max)(worst_deg, deg);
                        sum_cm += cm;
                        ++count;
                    }
                }
                if (now - last_log >= 0.25)
                {
                    last_log = now;
                    if (prev_ok)
                        HSVR_LOG("Helmet: vs the headset last frame: worst %.2f cm / %.2f deg, mean %.2f cm over %d frames%s; his head bone worst %.2f cm",
                                 worst_cm, worst_deg, count ? sum_cm / count : 0.0, count, g_helmet ? "" : " (no helmet worn)", mesh_worst);
                    worst_cm = worst_deg = sum_cm = mesh_worst = 0.0;
                    count = 0;
                }
                prev_ok = false;
                if (have && cfg.pose_head_lock && g_pose_anchor_fixed && !cfg.dev_pose_fake_tracking)
                {
                    prev_want = head_world - head_rot.rotate(Vec3{cfg.eye_forward_cm, 0.0, cfg.eye_up_cm});
                    prev_rot = (head_rot * g_pose.head_offset).normalized();
                    prev_ok = true;
                }
            }
            if (ModifyBoneNode* n = chain_node("head"))
            {
                if (have) node_set_rotation(*n, component_inv * (head_rot * g_pose.head_offset));
                else node_release(*n);
                // The head where the headset is: the eyes sit eye_forward/eye_up from the head bone (as
                // the view anchor was measured), so the bone is that far back and down from them.
                bool placed = false;
                if (have && cfg.pose_head_lock && g_pose_anchor_fixed && !cfg.dev_pose_fake_tracking)
                {
                    Vec3 eye_offset{cfg.eye_forward_cm, 0.0, cfg.eye_up_cm};
                    Vec3 want = head_world - head_rot.rotate(eye_offset);
                    // Never farther than the animation's neck reaches, plus pose_head_lock_max_cm.
                    Vec3 neck = socket_location(driver, bone_fname("neck_02"));
                    static double neck_len = -1.0;
                    if (neck_len < 0.0 && !*(n->node + n->translation_mode->GetOffset_Internal()))
                        neck_len = length(socket_location(driver, bone_fname("head")) - neck);
                    if (neck_len > 0.0)
                    {
                        Vec3 d = want - neck;
                        double dl = length(d), cap = neck_len + (std::max)(0.0, cfg.pose_head_lock_max_cm);
                        if (dl > cap) want = neck + d * (cap / dl);
                        double scale = (std::max)(1e-3, component_scale_z(driver));
                        placed = node_set_translation(*n, component_inv.rotate(want - component_location(driver)) * (1.0 / scale));
                        HSVR_LOG_EVERY(2.0, "Pose: head bone put at the headset (%.1f cm from the neck, its own neck %.1f cm%s)", dl, neck_len,
                                       dl > cap ? ", held at the limit" : "");
                    }
                }
                if (!placed) node_release_translation(*n);
            }
            have_look = have;
            look_rot = head_rot;
        }
        else if (ModifyBoneNode* n = chain_node("head"))
        {
            node_release(*n);
        }
        pose_torso_twist(cfg, have_look, look_rot, heading, component_inv);
        // The game's own forward bends (crouch Root Height, Lean Forward (Grabbing)) feed
        // Anim_Add_Bend_AO from the animation's copies, written by the update this runs after; with the
        // lean they are set to standing, so only your lean bends him (torso_lean_and_helmet.md).
        if (cfg.pose_lean && cfg.pose_lean_cancel_game_bend && g_lean.calibrated && cfg.pose_in_anim_update && g_pose_in_anim_at.load() >= now - 0.001)
        {
            set_named_number(g_pose.instance, STR("Root Height"), 85.0 * component_scale_z(mesh));
            set_named_number(g_pose.instance, STR("Lean Forward (Grabbing)"), 0.0);
        }
        armour_scan(cfg, pawn, mesh);
        pose_feet(cfg, pawn, actor, heading, component_inv);
        for (int side = 0; side < 2; ++side)
        {
            if (cfg.pose_arms)
            {
                pose_arm(side, cfg, state, body, component_inv);
                if (side == 1) measure_arms(state);
            }
            else
                for (const char* b : {"clavicle", "upperarm", "lowerarm", "hand"})
                    if (ModifyBoneNode* n = chain_node(std::string(b) + side_suffix(side))) node_release(*n);
        }
        static double last_line = 0.0;
        if (now - last_line >= 0.25)
        {
            last_line = now;
            Vec3 pelvis = socket_location(driver, bone_fname("pelvis"));
            Vec3 hl = socket_location(driver, bone_fname("hand_l")), hr = socket_location(driver, bone_fname("hand_r"));
            UObject* movement = object_property(pawn, STR("CharacterMovement"));
            double v[3] = {0, 0, 0};
            int mode = -1;
            if (movement)
            {
                if (FProperty* vp = prop_chain(movement, STR("Velocity")))
                    read_three(reinterpret_cast<uint8_t*>(movement) + vp->GetOffset_Internal(), vp, v);
                if (FProperty* mp = prop_chain(movement, STR("MovementMode")))
                    mode = *(reinterpret_cast<uint8_t*>(movement) + mp->GetOffset_Internal());
            }
            // What his body really does on screen: chest and hips turned from where they were at calibration.
            double chest_yaw = quat_yaw_deg((socket_rotation(mesh, bone_fname("spine_05")) * g_pose.chest_rot_local.inverse()).normalized());
            double hips_yaw = quat_yaw_deg((socket_rotation(mesh, bone_fname("pelvis")) * g_pose.pelvis_rot_local.inverse()).normalized());
            double look_yaw = have_look ? quat_yaw_deg(look_rot) : 0.0;
            {
                // Where his chest is from your eyes (body frame): + forward = under your view when you look down.
                Vec3 hw;
                Quat hr;
                if (!cfg.dev_pose_fake_tracking && head_pose_world(cfg, state, hw, hr))
                {
                    Vec3 c = body.inverse().rotate(socket_location(mesh, bone_fname("spine_05")) - hw);
                    Vec3 cl = body.inverse().rotate(socket_location(mesh, bone_fname("clavicle_l")) - hw);
                    Vec3 cr = body.inverse().rotate(socket_location(mesh, bone_fname("clavicle_r")) - hw);
                    HSVR_LOG("Lean: your head pitch %.0f roll %.0f; wanted forward %.0f side %.0f, bent forward %.0f side %.0f (%.0f%% allowed by head height); "
                             "head carried (%.1f, %.1f, %.1f) cm, crouch %.0f cm; chest (spine_05) %.1f cm in front of your eyes, %.1f below; clavicles %.1f / %.1f in front; "
                             "your neck (%.1f, %.1f) cm from his hips -> lean forward %.0f side %.0f; capsule (%.0f, %.0f); bend for a crouch past his legs %.0f; looking down: chest back %.1f cm",
                             g_lean.pitch, g_lean.roll, g_lean.want_fwd, g_lean.want_side, g_lean.fwd, g_lean.side, g_lean.held * 100.0, g_lean.head_moved.x,
                             g_lean.head_moved.y, g_lean.head_moved.z, g_crouch_drop, c.x, -c.z, cl.x, cr.x, g_lean.offset.x, g_lean.offset.y, g_lean.off_fwd,
                             g_lean.off_side, actor.x, actor.y, g_lean.reach_fwd, g_lean.look_back);
                }
                else if (cfg.dev_pose_fake_tracking)
                    HSVR_LOG_EVERY(1.0, "Lean (test hands): wanted forward %.0f side %.0f, bent forward %.0f side %.0f (%.0f%% allowed by head height); head carried (%.1f, %.1f, %.1f) cm, "
                             "legs crouch %.0f cm (cap %.0f); bend for a crouch past his legs %.0f (max %.0f), neck follows %.0f deg",
                             g_lean.want_fwd, g_lean.want_side, g_lean.fwd, g_lean.side, g_lean.held * 100.0, g_lean.head_moved.x, g_lean.head_moved.y, g_lean.head_moved.z,
                             g_crouch_drop, cfg.pose_crouch_max_cm * component_scale_z(mesh), g_lean.reach_fwd, cfg.pose_crouch_bend_max_deg, g_lean.depth_free);
            }
            HSVR_LOG("Pose: capsule velocity (%.0f, %.0f, %.0f) mode %d, torso twist %.0f deg asked; on screen: head %.0f, chest %.0f, hips %.0f (chest %+.0f from hips)",
                     v[0], v[1], v[2], mode, g_pose.twist_deg, look_yaw, chest_yaw, hips_yaw, wrap_deg(chest_yaw - hips_yaw));
            if (g_feet_active.load())
            {
                Vec3 fl = socket_location(mesh, bone_fname("foot_l")), fr = socket_location(mesh, bone_fname("foot_r"));
                HSVR_LOG("Feet: left at (%.0f, %.0f) foot bone (%.0f, %.0f, %.0f) ground %.0f%s, %d steps; right at (%.0f, %.0f) foot bone (%.0f, %.0f, %.0f) ground %.0f%s, %d steps",
                         g_feet[0].at.x, g_feet[0].at.y, fl.x, fl.y, fl.z, g_feet[0].ground_z, g_feet[0].stepping ? " stepping" : "", g_feet[0].steps,
                         g_feet[1].at.x, g_feet[1].at.y, fr.x, fr.y, fr.z, g_feet[1].ground_z, g_feet[1].stepping ? " stepping" : "", g_feet[1].steps);
            }
            HSVR_LOG("Pose: wrists: left twist %.0f deg, bend %.0f deg; right twist %.0f deg, bend %.0f deg (twist before the forearm's share)",
                     g_pose.arm[0].twist_deg, g_pose.arm[0].bend_deg, g_pose.arm[1].twist_deg, g_pose.arm[1].bend_deg);
            HSVR_LOG("Pose: actor (%.0f, %.0f, %.0f) heading %.0f, pelvis gap %.0f cm, room moved (%.0f, %.0f) this frame (%.1f, %.1f), head %s, hands %s/%s, "
                     "hand_l (%.0f, %.0f, %.0f) target (%.0f, %.0f, %.0f), hand_r (%.0f, %.0f, %.0f) target (%.0f, %.0f, %.0f)",
                     actor.x, actor.y, actor.z, heading, length(Vec3{pelvis.x - actor.x, pelvis.y - actor.y, 0.0}), g_pose_room_moved_local.x,
                     g_pose_room_moved_local.y, room.x, room.y, state.head_valid ? "tracked" : "not tracked",
                     state.hand[0].grip_valid ? "tracked" : (cfg.dev_pose_fake_tracking ? "fake" : "-"),
                     state.hand[1].grip_valid ? "tracked" : (cfg.dev_pose_fake_tracking ? "fake" : "-"), hl.x, hl.y, hl.z, g_pose.target[0].x,
                     g_pose.target[0].y, g_pose.target[0].z, hr.x, hr.y, hr.z, g_pose.target[1].x, g_pose.target[1].y, g_pose.target[1].z);
        }
    }

    // ---- The capsule stays where you are --------------------------------------------------------
    // Willie's tick (ReceiveTick) pulls his capsule toward a point worked out from his pelvis and
    // spine plus the game's stumble, pain, dodge and lean offsets, and sets its height from his
    // steps. With the body posed on the capsule that pull never closes, so a hit (pain stumble)
    // slid him across the arena. While the body is posed, the mod notes where the capsule is just
    // before his tick and puts it back just after, so only your walking moves it. The stumble and
    // dodge offsets are cleared after each tick so they don't build up.
    UFunction* g_receive_tick = nullptr;
    bool g_hold_have = false;
    hsvr::Vec3 g_hold_location;
    // Step Height 2 just before his tick: the leash's height uses this value (walking_floor_loss.md).
    bool g_step_h2_have = false;
    double g_step_h2_pre = 0.0;

    double number_property(UObject* owner, FProperty* p)
    {
        uint8_t* at = reinterpret_cast<uint8_t*>(owner) + p->GetOffset_Internal();
        auto kind = p->GetClass().GetName();
        if (kind == STR("DoubleProperty")) return *reinterpret_cast<double*>(at);
        if (kind == STR("FloatProperty")) return *reinterpret_cast<float*>(at);
        if (kind == STR("BoolProperty"))
        {
            auto* flag = static_cast<FBoolProperty*>(p);
            return (at[flag->GetByteOffset()] & flag->GetFieldMask()) != 0 ? 1.0 : 0.0;
        }
        if (kind == STR("StructProperty"))
        {
            double v[3];
            read_three(at, p, v);
            return hsvr::length(hsvr::Vec3{v[0], v[1], v[2]});
        }
        return -1.0;
    }

    bool is_receive_tick(UObject* context, UFunction* function)
    {
        if (!(g_hold_capsule.load() || g_pose_active.load()) || !context || context != g_pose.pawn || !function) return false;
        if (g_receive_tick) return function == g_receive_tick;
        if (function->GetName() != STR("ReceiveTick")) return false;
        g_receive_tick = function;
        HSVR_LOG("Capsule: found your character's tick (%ls)", function->GetFullName().c_str());
        return true;
    }

    // ---- Your body faces where you face --------------------------------------------------------
    // The game turns Willie's capsule toward the control rotation's yaw (and nothing else turns
    // him); turning that way is not a swing or aim input (the aim reads only the mouse and pitch).
    // So just before his tick the mod sets the control yaw to the body's yaw: your mouse or stick
    // turn plus your real facing, which follows the headset once you look more than
    // pose_turn_dead_zone_deg away, at pose_turn_speed_dps, until it is lined up again. The view's
    // straight ahead keeps only the mouse or stick turn, so turning your head never turns the view
    // twice. Pitch is left as the game has it, so mouse up and down still aims.
    // ---- The left stick walks you ---------------------------------------------------------------
    // The game walks him through Unreal's character movement: its own stick and WASD handlers call
    // AddMovementInput and set "Movement Input Vector", whose length scales his walk speed (decompile:
    // Willie_BP @768801, @768447, @760861, @563757). Just before his tick the mod does the same with
    // the left stick, pointed where you look (pose_move_relative=head) or where your body faces
    // (=body). The capsule hold keeps what the character movement did (it runs before his tick).
    bool g_stick_walking = false;
    double g_stick_walk_until = 0.0;

    void stick_walk_before_tick(UObject* pawn)
    {
        using namespace hsvr;
        Config cfg = config();
        ControllerState state = controllers_state();
        double x = 0.0, y = 0.0;
        if (cfg.pose_stick_walk && state.active && state.focused)
        {
            x = state.hand[0].stick_x;
            y = state.hand[0].stick_y;
        }
        if (cfg.pose_stick_walk && g_fake_stick[0].load() > -5.0)
        {
            x = g_fake_stick[0].load();
            y = g_fake_stick[1].load();
        }
        double m = std::sqrt(x * x + y * y);
        double dz = cfg.pose_stick_dead_zone;
        g_stick_walking = m > dz;
        if (!g_stick_walking) return;
        double scale = (std::min)(1.0, (m - dz) / (1.0 - dz));
        // A bad leg: slower (injury_one_leg_speed); both: no walking at all.
        if (g_inj.pawn == pawn && g_inj.leg_speed < 1.0)
        {
            scale *= g_inj.leg_speed;
            HSVR_LOG_EVERY(2.0, "Walk: injured leg(s): stick x%.2f", g_inj.leg_speed);
            if (scale <= 1e-3)
            {
                g_stick_walking = false;
                return;
            }
        }
        double yaw = g_turn_valid ? wrap_deg(g_turn_yaw + g_body_rel) : actor_heading(pawn);
        if (cfg.pose_move_relative == "head")
        {
            Vec3 head_world;
            Quat head_rot;
            if (state.head_valid && stereo_tracking_to_world(state.head, head_world, head_rot)) yaw = quat_yaw_deg(head_rot);
        }
        // Stick up = forward (+X), right = right (+Y).
        Vec3 dir = quat_from_yaw_deg(yaw).rotate(Vec3{y / m, x / m, 0.0});
        Call add(pawn, STR("AddMovementInput"));
        add.three(STR("WorldDirection"), dir.x, dir.y, 0.0);
        add.number(STR("ScaleValue"), scale);
        add.run();
        if (FProperty* p = prop_chain(pawn, STR("Movement Input Vector")))
            write_three(reinterpret_cast<uint8_t*>(pawn) + p->GetOffset_Internal(), p, dir.x * scale, dir.y * scale, 0.0);
        g_stick_walk_until = now_seconds() + 0.5;
        static double last = 0.0;
        double now = now_seconds();
        if (now - last >= 1.0)
        {
            last = now;
            double v[3] = {0, 0, 0};
            if (UObject* movement = object_property(pawn, STR("CharacterMovement")))
                if (FProperty* vp = prop_chain(movement, STR("Velocity")))
                    read_three(reinterpret_cast<uint8_t*>(movement) + vp->GetOffset_Internal(), vp, v);
            HSVR_LOG("Walk: stick %.2f toward %.0f deg, speed %.0f cm/s", scale, yaw, std::sqrt(v[0] * v[0] + v[1] * v[1]));
        }
    }

    void turn_body_before_tick()
    {
        using namespace hsvr;
        UObject* controller = find_player_controller();
        ue::FRotator* rotation = controller ? value_ptr<ue::FRotator>(controller, STR("ControlRotation")) : nullptr;
        if (!rotation) return;
        auto wrap = [](double a) {
            while (a > 180.0) a -= 360.0;
            while (a < -180.0) a += 360.0;
            return a;
        };
        double now = now_seconds();
        {
            // This runs on the posed pawn's tick, and that can still be the last body's after the controller
            // has moved on to a new one (pose_body hasn't seen the change yet). Playtest 2026-11-22 10:04Z: the
            // control yaw read 90 at the new spawn and 77, the last body's, by its calibration. This is the
            // mod's only write of that yaw; which tick did it wasn't logged.
            UObject* now_pawn = object_property(controller, STR("Pawn"));
            if (now_pawn != g_pose.pawn && hsvr::config().pose_turn_spawn_guard)
            {
                if (g_turn_valid) HSVR_LOG("Turn: a new body: its own facing (%.2f) is left alone (the last body's was %.2f)", (double)rotation->Yaw, g_last_written_yaw);
                g_turn_valid = false;
                return;
            }
        }
        if (!g_pose_cfg_turn)
        {
            if (g_turn_valid) HSVR_LOG("Turn: body turning off; the mouse turns the body again");
            g_turn_valid = false;
            return;
        }
        if (!g_turn_valid)
        {
            g_turn_yaw = rotation->Yaw;
            g_body_rel = 0.0;
            g_last_written_yaw = rotation->Yaw;
            g_turn_time = now;
            g_body_turning = false;
            g_turn_valid = true;
            HSVR_LOG("Turn: your body now faces where you face (start %.0f)", g_turn_yaw);
        }
        ControllerState state = controllers_state();
        // Playing with controllers, the mouse does nothing: no turn, no look up or down (Matthew
        // 2026-11-21: moving the mouse over the window bent him to look down while he stood straight;
        // the game's spine bend reads the control pitch). pose_mouse_off_with_controllers.
        bool controllers_in_use = !g_kbm.load() && state.active && (state.hand[0].grip_valid || state.hand[1].grip_valid);
        g_mouse_off_now.store(config().pose_mouse_off_with_controllers && controllers_in_use);
        bool mouse_off = config().pose_mouse_off_with_controllers && controllers_in_use;
        // Whatever turned the control yaw since we last wrote it (mouse, stick) is your turn.
        if (!mouse_off) g_turn_yaw = wrap(g_turn_yaw + wrap(rotation->Yaw - g_last_written_yaw));
        else
        {
            static bool said = false;
            if (!said && (std::fabs(wrap(rotation->Yaw - g_last_written_yaw)) > 0.5 || std::fabs(rotation->Pitch) > 0.5))
            {
                said = true;
                HSVR_LOG("Turn: mouse turn/look ignored while controllers are in use (yaw %+.1f, pitch %.1f; pose_mouse_off_with_controllers)",
                         wrap(rotation->Yaw - g_last_written_yaw), (double)rotation->Pitch);
            }
            rotation->Pitch = 0.0;
        }
        double dt = (std::min)(0.1, (std::max)(0.0, now - g_turn_time));
        g_turn_time = now;
        // The right stick turns you (view and body together), smoothly or in snaps.
        {
            Config cfg = config();
            double x = state.active && state.focused ? state.hand[1].stick_x : 0.0;
            static bool snap_armed = true;
            if (cfg.pose_stick_turn == "smooth")
            {
                double dz = cfg.pose_stick_dead_zone;
                if (std::fabs(x) > dz)
                {
                    double v = (std::fabs(x) - dz) / (1.0 - dz);
                    g_turn_yaw = wrap(g_turn_yaw + (x > 0 ? v : -v) * cfg.pose_stick_turn_dps * dt);
                }
            }
            else if (cfg.pose_stick_turn == "snap")
            {
                if (snap_armed && std::fabs(x) > 0.6)
                {
                    g_turn_yaw = wrap(g_turn_yaw + (x > 0 ? cfg.pose_snap_turn_deg : -cfg.pose_snap_turn_deg));
                    snap_armed = false;
                }
                else if (std::fabs(x) < 0.3)
                    snap_armed = true;
            }
        }
        Vec3 head_world;
        Quat head_rot;
        bool have_head = !g_pose_fake && state.head_valid && stereo_tracking_to_world(state.head, head_world, head_rot);
        double head_rel = 0.0;
        if (have_head) head_rel = wrap(quat_yaw_deg(head_rot) - g_turn_yaw);
        else if (g_pose_fake)
        {
            // Made-up path: looks up to 80 degrees left and right, slowly (hsvr.fake_look 0: straight ahead).
            head_rel = g_fake_look.load() ? 80.0 * std::sin(now * 0.25) : 0.0;
            have_head = true;
        }
        if (have_head)
        {
            double diff = wrap(head_rel - g_body_rel);
            if (std::fabs(diff) > g_turn_dead_deg) g_body_turning = true;
            if (g_body_turning)
            {
                double step = (std::min)(std::fabs(diff), g_turn_speed_dps * dt);
                g_body_rel = wrap(g_body_rel + (diff > 0 ? step : -step));
                if (std::fabs(diff) - step < 5.0) g_body_turning = false;
            }
            // A neck turns only so far: on a quick spin the hips are dragged round with you at once
            // rather than trailing, so his shoulders stay under your eyes.
            double left = wrap(head_rel - g_body_rel);
            if (std::fabs(left) > g_turn_max_deg) g_body_rel = wrap(head_rel - (left > 0 ? g_turn_max_deg : -g_turn_max_deg));
        }
        double body_yaw = wrap(g_turn_yaw + g_body_rel);
        rotation->Yaw = body_yaw;
        rotation->Roll = 0.0;
        g_last_written_yaw = body_yaw;
        static double last = 0.0;
        if (now - last >= 1.0)
        {
            last = now;
            HSVR_LOG("Turn: view straight ahead %.0f, body %.0f (%+.0f from it)%s, crouch %.0f cm", g_turn_yaw, body_yaw, g_body_rel,
                     g_body_turning ? ", turning" : "", g_crouch_drop);
        }
    }

    // ---- Crouching: the game's own crouch values follow yours ----------------------------------
    // The game rewrites "Crouched Height" and "Root Height" every tick (85 standing, 25 a standing
    // crouch, times his size). After his tick the mod sets them from how far you are down, so his
    // torso bend, stamina, step size and leg logic match. They are kept at 61 or more, because 60
    // or less while standing still starts the game's canned kneel (legs without IK).
    void set_named_number(UObject* owner, const TCHAR* name, double value)
    {
        FProperty* p = owner ? prop_chain(owner, name) : nullptr;
        if (!p) return;
        uint8_t* at = reinterpret_cast<uint8_t*>(owner) + p->GetOffset_Internal();
        auto kind = p->GetClass().GetName();
        if (kind == STR("DoubleProperty")) *reinterpret_cast<double*>(at) = value;
        else if (kind == STR("FloatProperty")) *reinterpret_cast<float*>(at) = (float)value;
    }

    void crouch_after_tick(UObject* pawn)
    {
        if (!g_pose_cfg_crouch || !g_pose.mesh) return;
        double scale = component_scale_z(g_pose.mesh);
        double height = (std::min)(85.0 * scale, (std::max)(61.0, 85.0 * scale - g_crouch_drop));
        set_named_number(pawn, STR("Crouched Height"), height);
        set_named_number(pawn, STR("Root Height"), height);
    }

    void log_joint_before_tick(UObject* pawn);

    void block_offhand_search_before_tick(UObject* pawn);
    void keep_player_off_knees(UObject* pawn, bool after);
    // Test: hsvr.pawn_pin <variable> <value> holds a number variable of his pawn at a value every tick,
    // after his tick and before the hold reads it (e.g. Stamina 10, Arm R Tonus 0.25); "off" clears all.
    std::vector<std::pair<std::wstring, double>> g_pawn_pins;
    bool set_variable(UObject* owner, const TCHAR* name, double number, UObject* object, const FName* fname);

    // ---- Swing speed from the controllers -------------------------------------------------------
    // The game's "Aim Swing Speed" (ASS, 0..75) comes only from the mouse (Willie UG @667580) and is
    // 0 in VR, yet weapon skill growth, combat stance, fists, wrist locks, the AI's threat timing,
    // weapons staying live when fallen, the unsheath length and more read it (aim_swing_speed_flow.md).
    // It is written in his tick before nearly every reader, so the mod sets its only input, "Swing
    // Velocity proxy" (ASS = (proxy - 25) * 1.5), before his tick, divided by how much the tick's own
    // decay takes off (measured after each tick). The value: the faster hand that holds something
    // (a weapon, item or fist; an empty hand waving does not swing), relative to the body, mapped
    // pose_swing_speed_lo..hi m/s -> 0..75, exactly 0 at rest (some game rules need == 0).
    double read_number_variable(UObject* owner, const TCHAR* name);
    double g_hand_world_v[2] = {0.0, 0.0}; // m/s
    // A draw from a scabbard in progress, per hand (see try_draw).
    struct DrawState
    {
        bool active = false;
        int slot_side = 1;           // whose flags the game uses (the slot's side: 0 L, 1 R)
        UObject* weapon = nullptr;
        UObject* scabbard = nullptr;
        double t0 = 0.0;
        double last_log = -1e9;
        bool sheathing = false;      // going in rather than out
        const char* socket = "";     // the slot's socket (where the scabbard belongs)
        int slot = 0;                // and its number on that side (Slot byte)
        double z_in = 1e9;           // sheathing: the furthest in it has been (cm out)
        bool pulling_back = false;   // and being pulled back out of it
        double length = 80.0;        // the blade's length (cm)
        bool block_cleared = false;
        bool past_mouth = false;     // in past the mouth (the game's seat is held off until it is nearly home)
    };
    DrawState g_draw[2];
    const char* sheathing_socket(int side)
    {
        const DrawState& d = g_draw[side];
        return d.active && d.sheathing && d.socket && d.socket[0] ? d.socket : nullptr;
    }
    // A blade just drawn still has its tip at the mouth, lined up: no sheathe until it has been taken
    // well away first (playtest 02:44: every draw went straight back into a sheathe, 1 ms after it freed).
    bool g_sheathe_armed[2] = {true, true};
    // While not armed: the hip the blade came out of (or could not go into), since when, and since when the
    // tip has been clear of that hip.
    int g_sheathe_from[2] = {1, 1};
    double g_sheathe_out_at[2] = {-1e9, -1e9};
    double g_sheathe_clear_since[2] = {-1.0, -1.0};
    void sheathe_disarm(int side, int hip)
    {
        g_sheathe_armed[side] = false;
        g_sheathe_from[side] = hip;
        g_sheathe_out_at[side] = hsvr::now_seconds();
        g_sheathe_clear_since[side] = -1.0;
    }
    // Where each drawn weapon's own scabbard really opens, measured when it was drawn (it sat seated):
    // the blade's start (the guard end of its blade zone) and its line, in the scabbard's frame. The
    // belt socket is only where the scabbard hangs from, and moves with it when the off hand angles it.
    struct SheathFit
    {
        UObject* scab = nullptr;
        int slot_side = 1;
        int slot = 0; // 0 = slot 1, 1 = slot 2 of that side
        const char* socket = "";
        hsvr::Vec3 mouth_local, axis_local;
    };
    std::unordered_map<UObject*, SheathFit> g_sheath_fit;
    bool any_draw() { return g_draw[0].active || g_draw[1].active; }
    bool cfg_scabbard_free() { return hsvr::config().pose_draw_scabbard_free; }
    bool try_draw(int side, UObject* pawn, UObject* mesh, const hsvr::Vec3& at, const hsvr::Vec3& palm, const hsvr::Config& cfg);
    bool in_own_slot(UObject* pawn, UObject* w);
    struct SlotTake
    {
        UObject* weapon = nullptr;
        int slot = 0; // index into k_slots
        double t0 = 0.0;
    };
    SlotTake g_slot_take[2];
    void slot_take_tick(UObject* pawn);
    bool try_scabbard_grab(int side, UObject* pawn, UObject* mesh, const hsvr::Vec3& at, const hsvr::Config& cfg);
    UObject* held_scabbard(int side); // the belt scabbard that hand holds, else null
    void scabbard_let_go(int side, const char* why);
    bool scabbard_held(int side);
    void scabbard_before_tick(UObject* pawn);
    void scabbard_tick(UObject* pawn, const hsvr::Config& cfg);
    double g_swing_want = 0.0, g_swing_written = 0.0, g_swing_keep = 0.89, g_swing_last_t = -1.0;
    hsvr::Vec3 g_swing_rel[2];
    double g_swing_v[2] = {0.0, 0.0};
    FProperty* g_swing_proxy = nullptr;
    bool g_swing_looked = false;
    void swing_speed_before_tick(UObject* pawn)
    {
        using namespace hsvr;
        const Config& cfg = hsvr::config();
        g_swing_written = 0.0;
        {
            // Each hand's speed in the world (for throws), ~30 ms smoothing.
            static hsvr::Vec3 last[2];
            static double last_t = -1.0;
            double t = now_seconds(), d = last_t > 0.0 ? t - last_t : 0.0;
            last_t = t;
            for (int side = 0; side < 2; ++side)
            {
                Vec3 at = g_pose.target[side];
                if (g_pose.hand_valid[side] && d > 1e-4 && d < 0.1)
                {
                    double v = length(at - last[side]) / d / 100.0;
                    g_hand_world_v[side] += (v - g_hand_world_v[side]) * (1.0 - std::exp(-d / 0.03));
                }
                else g_hand_world_v[side] = 0.0;
                last[side] = at;
            }
        }
        if (!cfg.pose_feed_swing_speed) return;
        if (!g_swing_looked)
        {
            g_swing_looked = true;
            g_swing_proxy = prop_chain(pawn, STR("Swing Velocity proxy"));
            HSVR_LOG("Swing: the game's swing speed input %s (%ls)", g_swing_proxy ? "found" : "MISSING", g_swing_proxy ? g_swing_proxy->GetClass().GetName().c_str() : STR("-"));
        }
        if (!g_swing_proxy) return;
        double now = now_seconds(), dt = g_swing_last_t > 0.0 ? now - g_swing_last_t : 0.0;
        g_swing_last_t = now;
        // Relative to his posed chest, not his capsule: in a deep crouch the game pulls the capsule up to 27 cm a tick toward
        // his hips (the mod puts it back), and both hands read slap speed at once (run 14 884eea8 floor_pickup: both fists
        // made while still, then a fist knocked the lantern 5 m). A crouch moves the chest with the hands, too.
        Vec3 body = actor_location(pawn);
        if (cfg.pose_swing_from_chest)
            if (UObject* mesh = object_property(pawn, STR("Mesh"))) body = socket_location(mesh, bone_fname("spine_03"));
        double fastest = 0.0;
        for (int side = 0; side < 2; ++side)
        {
            Vec3 rel = g_pose.target[side] - body;
            if (g_pose.hand_valid[side] && dt > 1e-4 && dt < 0.1)
            {
                double v = length(rel - g_swing_rel[side]) / dt / 100.0; // m/s
                double a = 1.0 - std::exp(-dt / 0.03);                   // ~30 ms smoothing (tracking jitter)
                g_swing_v[side] += (v - g_swing_v[side]) * a;
            }
            else g_swing_v[side] = 0.0;
            g_swing_rel[side] = rel;
            bool holds = object_property(pawn, side == 0 ? STR("Weapon L") : STR("Weapon R")) != nullptr;
            if (holds) fastest = (std::max)(fastest, g_swing_v[side]);
        }
        double lo = cfg.pose_swing_speed_lo, hi = (std::max)(lo + 0.1, cfg.pose_swing_speed_hi);
        double want = fastest <= lo ? 0.0 : (std::min)(75.0, (fastest - lo) / (hi - lo) * 75.0);
        // Rises at once, falls like the game's own (a swing's speed lingers ~0.1-0.2 s).
        if (want >= g_swing_want || dt <= 0.0) g_swing_want = want;
        else g_swing_want += (want - g_swing_want) * (1.0 - std::exp(-dt / (std::max)(0.01, cfg.pose_swing_speed_fall_s)));
        if (g_swing_want < 0.5) g_swing_want = 0.0;
        if (any_draw())
        {
            // A draw breaks free at Length x MRC(Aim Swing Speed 0..75 -> 0.85..0): kept at the
            // game's 85% (Matthew 2026-11-19) by holding the swing speed at 0 while drawing.
            if (number_property(pawn, g_swing_proxy) > 0.0) set_variable(pawn, STR("Swing Velocity proxy"), 0.0, nullptr, nullptr);
            return;
        }
        if (g_swing_want <= 0.0) return; // the game's own (0 at rest, or the mouse's)
        double proxy_now = number_property(pawn, g_swing_proxy);
        double p = (25.0 + g_swing_want / 1.5) / (std::max)(0.1, g_swing_keep);
        if (p <= proxy_now) return; // the mouse already swings harder
        set_variable(pawn, STR("Swing Velocity proxy"), p, nullptr, nullptr);
        g_swing_written = p;
    }
    void swing_speed_after_tick(UObject* pawn)
    {
        if (g_swing_written <= 0.0 || !g_swing_proxy) return;
        double after = number_property(pawn, g_swing_proxy);
        double k = after / g_swing_written;
        if (k > 0.05 && k <= 1.0) g_swing_keep += (k - g_swing_keep) * 0.5; // the tick's decay, measured
        static double last_log = -1e9;
        double now = hsvr::now_seconds();
        if (now - last_log > 1.0)
        {
            last_log = now;
            HSVR_LOG("Swing: hands %.1f / %.1f m/s, swing speed wanted %.0f, game's now %.1f (input kept %.2f per tick)", g_swing_v[0], g_swing_v[1], g_swing_want,
                     read_number_variable(pawn, STR("Aim Swing Speed")), g_swing_keep);
        }
    }

    void fist_flags_before_tick(UObject* pawn);
    void body_grab_before_tick(UObject* pawn);
    void fist_flags_after_tick(UObject* pawn);
    void body_grab_after_tick(UObject* pawn);
    void body_hit_watch(UObject* pawn);
    // ---- Test input: the pawn's own input events, as the mouse and keys call them ------------------
    // hsvr.input <name part> <value> <seconds>: every tick for that long, each of the pawn's
    // InpAxisEvt_/InpActEvt_ functions whose name contains <name part> is called with AxisValue =
    // <value> (seconds 0 = once). hsvr.input_list logs their names. For flat-mode punch measurements.
    struct TestInput { std::wstring part; double value = 0.0; double until = 0.0; bool once = false; };
    std::vector<TestInput> g_test_inputs;
    bool g_input_list_now = false;
    void install_punch_watch();
    void input_before_tick(UObject* pawn)
    {
        if (!pawn) return;
        install_punch_watch(); // flat mode has no posed tick to install it
        if (g_input_list_now)
        {
            g_input_list_now = false;
            std::wstring names;
            for (UStruct* level = static_cast<UStruct*>(pawn->GetClassPrivate()); level; level = level->GetSuperStruct())
                for (UFunction* f : level->ForEachFunction())
                {
                    std::wstring n = f->GetName();
                    if (n.rfind(STR("InpAxisEvt_"), 0) == 0 || n.rfind(STR("InpActEvt_"), 0) == 0) names += n + STR("; ");
                }
            HSVR_LOG("Input: the pawn's input events: %ls", names.c_str());
        }
        if (g_test_inputs.empty()) return;
        double now = hsvr::now_seconds();
        for (auto it = g_test_inputs.begin(); it != g_test_inputs.end();)
        {
            for (UStruct* level = static_cast<UStruct*>(pawn->GetClassPrivate()); level; level = level->GetSuperStruct())
                for (UFunction* f : level->ForEachFunction())
                {
                    std::wstring n = f->GetName();
                    if (n.rfind(STR("InpAxisEvt_"), 0) != 0 && n.rfind(STR("InpActEvt_"), 0) != 0) continue;
                    if (n.find(it->part) == std::wstring::npos) continue;
                    std::vector<uint8_t> buf = param_block(f);
                    for (FProperty* p : f->ForEachProperty())
                        if (p->GetName() == STR("AxisValue"))
                        {
                            auto kind = p->GetClass().GetName();
                            if (kind == STR("FloatProperty")) *reinterpret_cast<float*>(buf.data() + p->GetOffset_Internal()) = (float)it->value;
                            else if (kind == STR("DoubleProperty")) *reinterpret_cast<double*>(buf.data() + p->GetOffset_Internal()) = it->value;
                        }
                    pawn->ProcessEvent(f, buf.data());
                    if (it->once) HSVR_LOG("Input: called %ls (%.2f)", n.c_str(), it->value);
                }
            if (it->once || now >= it->until) it = g_test_inputs.erase(it);
            else ++it;
        }
    }

    // ---- Stamina trace (hsvr.stamina_trace <seconds>, 0 = off) ----------------------------------
    // For matching the VR drain to the flat game: every <seconds>, in flat mode too, logs his
    // number variables whose names contain "stamina", "burn" or "swing", plus Muscle Rate, Fat
    // Rate, Liver Pain, Aim Swing Speed, the frame time and each hand joint's GetConstraintForce
    // (linear and angular, as the game's hand burn reads them, @407166).
    double watch_read(UObject* owner, FProperty* p);
    double g_stamina_trace_s = 0.0;
    double g_stamina_trace_last = -1e9;
    std::vector<FProperty*> g_stamina_trace_props;
    UObject* g_stamina_trace_pawn = nullptr;
    void stamina_trace(UObject* pawn)
    {
        if (g_stamina_trace_s <= 0.0 || !pawn) return;
        double now = hsvr::now_seconds();
        if (now - g_stamina_trace_last < g_stamina_trace_s) return;
        double frame = g_stamina_trace_last > 0.0 ? now - g_stamina_trace_last : 0.0;
        g_stamina_trace_last = now;
        if (pawn != g_stamina_trace_pawn)
        {
            g_stamina_trace_pawn = pawn;
            g_stamina_trace_props.clear();
            for (UStruct* level = static_cast<UStruct*>(pawn->GetClassPrivate()); level; level = level->GetSuperStruct())
                for (FProperty* p : level->ForEachProperty())
                {
                    auto kind = p->GetClass().GetName();
                    if (kind != STR("DoubleProperty") && kind != STR("FloatProperty")) continue;
                    std::wstring lower;
                    for (wchar_t ch : std::wstring(p->GetName())) lower += (wchar_t)towlower(ch);
                    if (lower.find(STR("stamina")) != std::wstring::npos || lower.find(STR("burn")) != std::wstring::npos ||
                        lower.find(STR("swing")) != std::wstring::npos || lower == STR("muscle rate") || lower == STR("fat rate") ||
                        lower == STR("liver pain") || lower.find(STR("fisting rate")) != std::wstring::npos)
                        g_stamina_trace_props.push_back(p);
                }
            HSVR_LOG("StaminaTrace: %d variables", (int)g_stamina_trace_props.size());
        }
        std::string line;
        char buf[160];
        for (FProperty* p : g_stamina_trace_props)
        {
            double v = watch_read(pawn, p);
            std::string n;
            for (wchar_t ch : std::wstring(p->GetName())) n += (char)(ch < 128 ? ch : '?');
            snprintf(buf, sizeof(buf), "%s=%.4g; ", n.c_str(), v);
            line += buf;
        }
        for (int side = 0; side < 2; ++side)
        {
            UObject* joint = object_property(pawn, side == 0 ? STR("PhysicsConstraint L Hand") : STR("PhysicsConstraint R Hand"));
            if (!joint) continue;
            Call f(joint, STR("GetConstraintForce"));
            if (!f.run()) continue;
            snprintf(buf, sizeof(buf), "joint%s lin=%.1f ang=%.1f; ", side == 0 ? "L" : "R", hsvr::length(f.vec(STR("OutLinearForce"))),
                     hsvr::length(f.vec(STR("OutAngularForce"))));
            line += buf;
        }
        UObject* wr = object_property(pawn, STR("Weapon R"));
        HSVR_LOG("StaminaTrace: %.3f (%.2f s) weaponR %ls; %s", now, frame, wr ? wr->GetName().c_str() : STR("none"), line.c_str());
    }

    void capsule_before_tick(Hook::TCallbackIterationData<void>&, UObject* context, UFunction* function, void*)
    {
        gc_sync();
        HSVR_PROF(PerfCapsuleBefore);
        // Test input runs in flat mode too (no posed body): the player's pawn's own tick.
        if ((!g_test_inputs.empty() || g_input_list_now || g_stamina_trace_s > 0.0) && context && function && function->GetName() == STR("ReceiveTick"))
        {
            UObject* pc = find_player_controller();
            if (pc && object_property(pc, STR("Pawn")) == context)
            {
                input_before_tick(context);
                stamina_trace(context);
            }
        }
        if (!is_receive_tick(context, function)) return;
        g_hold_location = actor_location(context);
        // The character movement (your stick) has moved him since the last tick: not into a wall.
        if (context != g_wall_pawn) g_wall_pawn = context, g_wall_ok_have = false, g_kept_have = false;
        if (g_pose_active.load() && g_wall_ok_have)
        {
            bool blocked = false;
            // Swept at the height he was last kept: after a hitch the game has him dropped ~80 cm into the
            // floor for a tick, and swept from there the floor stopped his whole catch-up move.
            hsvr::Vec3 sweep_to = g_hold_location;
            if (g_kept_have && g_hold_location.z < g_kept_z - 30.0) sweep_to.z = g_kept_z;
            hsvr::Vec3 ok = body_wall_sweep(context, g_wall_ok, sweep_to, blocked);
            ok.z = g_hold_location.z;
            if (blocked)
            {
                Call put(context, STR("K2_SetActorLocation"));
                put.three(STR("NewLocation"), ok.x, ok.y, ok.z);
                put.flag(STR("bSweep"), false);
                put.flag(STR("bTeleport"), true);
                put.run();
                // Its speed into the wall goes too, so it doesn't push on next tick.
                if (UObject* movement = object_property(context, STR("CharacterMovement")))
                    if (FProperty* vp = prop_chain(movement, STR("Velocity")))
                    {
                        double v[3] = {0, 0, 0};
                        read_three(reinterpret_cast<uint8_t*>(movement) + vp->GetOffset_Internal(), vp, v);
                        hsvr::Vec3 want{g_hold_location.x - g_wall_ok.x, g_hold_location.y - g_wall_ok.y, 0.0}, got{ok.x - g_wall_ok.x, ok.y - g_wall_ok.y, 0.0};
                        hsvr::Vec3 into = want - got;
                        if (hsvr::length(into) > 1e-3)
                        {
                            hsvr::Vec3 d = hsvr::normalized(into);
                            double k = v[0] * d.x + v[1] * d.y;
                            if (k > 0.0) v[0] -= d.x * k, v[1] -= d.y * k;
                            write_three(reinterpret_cast<uint8_t*>(movement) + vp->GetOffset_Internal(), vp, v[0], v[1], v[2]);
                        }
                    }
                g_hold_location = ok;
            }
        }
        g_hold_have = true;
        {
            FProperty* p = prop_chain(context, STR("Step Height 2"));
            g_step_h2_have = p != nullptr;
            g_step_h2_pre = p ? number_property(context, p) : 0.0;
        }
        if (g_pose_active.load())
        {
            { HSVR_SUB("before:log_joint_before_tick"); log_joint_before_tick(context); }
            { HSVR_SUB("before:block_offhand_search_before_tick"); block_offhand_search_before_tick(context); }
            { HSVR_SUB("before:keep_player_off_knees"); keep_player_off_knees(context, false); }
            { HSVR_SUB("before:turn_body_before_tick"); turn_body_before_tick(); }
            { HSVR_SUB("before:stick_walk_before_tick"); stick_walk_before_tick(context); }
            { HSVR_SUB("before:swing_speed_before_tick"); swing_speed_before_tick(context); }
            { HSVR_SUB("before:fist_flags_before_tick"); fist_flags_before_tick(context); }
            { HSVR_SUB("before:body_grab_before_tick"); body_grab_before_tick(context); }
            for (int side = 0; side < 2; ++side)
                if (g_draw[side].active) set_bool_property(context, side == 0 ? STR("Grab L Target Found") : STR("Grab R Target Found"), false);
            { HSVR_SUB("before:scabbard_before_tick"); scabbard_before_tick(context); }
        }
    }

    // ---- The weapon in your hand: a strength-limited spring --------------------------------------
    // The game holds a weapon with a physics joint between the weapon and the hand bone
    // ("PhysicsConstraint R/L Hand"), locked once the weapon is seated, and re-shapes it in every
    // tick (decompile: Willie_BP @454086-455803). With your hand posed from the controller, a locked
    // joint makes the weapon weightless. Right after his tick the mod turns the seated joint into a
    // spring toward the hand with a force limit (pose_grip_strength_kg), so a heavy weapon lags and
    // sags, and the game's own grip slip and stamina (which read this joint's force) keep working.
    // Its stiffness follows the weapon's mass, so every weapon follows equally well while within
    // your strength. The controller buzzes with the gap.
    // Test overrides from the dev script: -1 = use the ini. g_grip_spring_override 0 leaves the game's
    // own joint alone (still measured); g_grip_k_scale multiplies the spring's stiffness, damping and
    // force cap; g_weapon_gravity 0 turns gravity off on the held weapon.
    std::atomic<int> g_grip_spring_override{-1};
    std::atomic<double> g_grip_k_scale{1.0};
    std::atomic<int> g_weapon_gravity{-1};
    // -1 = leave alone; otherwise the ECollisionEnabled value to give the held weapon's BaseMesh
    // (0 none, 1 query only, 3 query and physics).
    std::atomic<int> g_weapon_collision{-1};
    // Set by hsvr.grip_rejoin: re-create the hand joint once (SetConstrainedComponents) after the
    // spring settings, in case the physics side never took them.
    std::atomic<bool> g_grip_rejoin{false};
    // hsvr.grip_frame_offset x y z: moves the joint's hand-side anchor (Frame2) by this much from
    // where the game put it, in the hand's frame. A working joint must carry the weapon along with
    // it; a dead one leaves the weapon in the fist. Changed values are written once per change.
    std::atomic<double> g_grip_frame_offset[3] = {0.0, 0.0, 0.0};
    std::atomic<int> g_grip_frame_serial{0};
    // Linear drive target for the test (the joint's own frame, cm); zero is the normal spring.
    std::atomic<double> g_grip_target[3] = {0.0, 0.0, 0.0};

    struct GripLog
    {
        double gap = 0.0, mass = 0.0, force = 0.0;
        bool active = false;
        double hand_dist = 0.0; // weapon body to the hand bone, measured directly
        hsvr::Vec3 weapon_at, hand_at;
        UObject* weapon_seen = nullptr;
        hsvr::Vec3 rest; // weapon relative to the hand bone when it was seated (hand frame)
        // The joint's own stretch: its weapon-side anchor (BaseMesh origin + Pos1) minus its hand-side
        // anchor (hand bone + Pos2, in the bone's frame). Zero when the spring holds perfectly.
        hsvr::Vec3 stretch_vec, stretch_hand;
        int broken = -1;
        double mesh_hand_diff = -1.0;
        hsvr::Vec3 hand_com_local, weapon_com_local;
        double turn_err_deg = 0.0;
        hsvr::Vec3 hand_com_world;
        int same_mesh = -1;
        double stretch = 0.0;
        hsvr::Vec3 pos2;
        int visible = -1;
        std::wstring joined;
        int simulating = -1;
        double scale = 0.0;
    };
    GripLog g_grip_log[2];

    // The game's own weapon grip: every direction locked, no drives (as the joint starts out).
    void lock_joint(UObject* joint)
    {
        for (const TCHAR* fn : {STR("SetLinearXLimit"), STR("SetLinearYLimit"), STR("SetLinearZLimit")})
        {
            Call c1(joint, fn);
            c1.byte(STR("ConstraintType"), 2); // locked
            c1.number(STR("LimitSize"), 0.0);
            c1.run();
        }
        for (const TCHAR* fn : {STR("SetAngularSwing1Limit"), STR("SetAngularSwing2Limit"), STR("SetAngularTwistLimit")})
        {
            Call c1(joint, fn);
            c1.byte(STR("MotionType"), 2); // locked
            c1.run();
        }
        Call pos(joint, STR("SetLinearPositionDrive"));
        pos.run(); // all three off
        Call vel(joint, STR("SetLinearVelocityDrive"));
        vel.run();
        Call slerp(joint, STR("SetOrientationDriveSLERP"));
        slerp.first_flag(false);
        slerp.run();
        Call aslerp(joint, STR("SetAngularVelocityDriveSLERP"));
        aslerp.first_flag(false);
        aslerp.run();
    }

    void spring_joint(UObject* joint, double mass, const hsvr::Config& cfg)
    {
        const double pi = 3.14159265358979;
        double w = 2.0 * pi * cfg.pose_grip_hz;
        double scale = g_grip_k_scale.load();
        // Chaos always runs constraint drives in acceleration mode (PhysInterface_Chaos.cpp,
        // UpdateLinearDrive_AssumesLocked: SetLinearDriveForceMode(Acceleration)), so the mass
        // cancels: stiffness is w^2 (1/s^2), damping 2*zeta*w (1/s), and MaxForce is a maximum
        // ACCELERATION (the solver divides it by the effective inverse mass). Strength in kg means:
        // the hand can hold strength_kg against gravity, so the cap is strength_kg*g/mass.
        double k = scale * w * w;
        double c = scale * 2.0 * cfg.pose_grip_damping * w;
        double max_force = scale * cfg.pose_grip_strength_kg * 980.0 / (std::max)(0.05, mass); // cm/s^2
        double wa = w * std::sqrt((std::max)(0.0, cfg.pose_grip_turn_scale));
        double ka = scale * wa * wa, ca = scale * 2.0 * cfg.pose_grip_turn_damping * wa;
        double max_torque = cfg.pose_grip_turn_max_scale * max_force / (std::max)(1.0, cfg.pose_grip_radius_cm); // rad/s^2 for that pull at the radius
        for (const TCHAR* fn : {STR("SetLinearXLimit"), STR("SetLinearYLimit"), STR("SetLinearZLimit")})
        {
            Call c1(joint, fn);
            c1.byte(STR("ConstraintType"), 0); // free
            c1.number(STR("LimitSize"), 0.0);
            c1.run();
        }
        for (const TCHAR* fn : {STR("SetAngularSwing1Limit"), STR("SetAngularSwing2Limit"), STR("SetAngularTwistLimit")})
        {
            Call c1(joint, fn);
            c1.byte(STR("MotionType"), 0); // free
            c1.run();
        }
        Call pos(joint, STR("SetLinearPositionDrive"));
        pos.flag(STR("bEnableDriveX"), true);
        pos.flag(STR("bEnableDriveY"), true);
        pos.flag(STR("bEnableDriveZ"), true);
        pos.run();
        Call vel(joint, STR("SetLinearVelocityDrive"));
        vel.flag(STR("bEnableDriveX"), true);
        vel.flag(STR("bEnableDriveY"), true);
        vel.flag(STR("bEnableDriveZ"), true);
        vel.run();
        Call target(joint, STR("SetLinearPositionTarget"));
        target.three(STR("InPosTarget"), g_grip_target[0].load(), g_grip_target[1].load(), g_grip_target[2].load());
        target.run();
        Call vtarget(joint, STR("SetLinearVelocityTarget"));
        vtarget.three(STR("InVelTarget"), 0.0, 0.0, 0.0);
        vtarget.run();
        Call lin(joint, STR("SetLinearDriveParams"));
        lin.number(STR("PositionStrength"), k);
        lin.number(STR("VelocityStrength"), c);
        lin.number(STR("InForceLimit"), max_force);
        lin.run();
        Call mode(joint, STR("SetAngularDriveMode"));
        mode.byte(STR("DriveMode"), 0); // SLERP
        mode.run();
        Call slerp(joint, STR("SetOrientationDriveSLERP"));
        slerp.first_flag(true);
        slerp.run();
        Call aslerp(joint, STR("SetAngularVelocityDriveSLERP"));
        aslerp.first_flag(true);
        aslerp.run();
        Call atarget(joint, STR("SetAngularOrientationTarget"));
        atarget.three(STR("InPosTarget"), 0.0, 0.0, 0.0);
        atarget.run();
        Call ang(joint, STR("SetAngularDriveParams"));
        ang.number(STR("PositionStrength"), ka);
        ang.number(STR("VelocityStrength"), ca);
        ang.number(STR("InForceLimit"), max_torque);
        ang.run();
    }

    // Reads a number inside nested structs of an object, by member names (e.g. ConstraintInstance >
    // ProfileInstance > LinearDrive > XDrive > Stiffness). NaN when a name is missing.
    double nested_number(UObject* owner, std::initializer_list<const TCHAR*> path)
    {
        if (!owner) return NAN;
        uint8_t* at = reinterpret_cast<uint8_t*>(owner);
        FProperty* p = nullptr;
        UScriptStruct* type = nullptr;
        bool first = true;
        for (const TCHAR* name : path)
        {
            p = first ? prop_chain(owner, name) : struct_member(type, name);
            first = false;
            if (!p) return NAN;
            at += p->GetOffset_Internal();
            type = struct_type(p);
        }
        auto kind = p->GetClass().GetName();
        if (kind == STR("DoubleProperty")) return *reinterpret_cast<double*>(at);
        if (kind == STR("FloatProperty")) return *reinterpret_cast<float*>(at);
        if (kind == STR("ByteProperty") || kind == STR("EnumProperty")) return *at;
        if (kind == STR("BoolProperty"))
        {
            auto* flag = static_cast<FBoolProperty*>(p);
            return (at[flag->GetByteOffset()] & flag->GetFieldMask()) != 0 ? 1.0 : 0.0;
        }
        return NAN;
    }

    // A name inside nested structs (e.g. ConstraintInstance.ConstraintBone2), or "" if missing.
    std::string nested_name(UObject* owner, std::initializer_list<const TCHAR*> path)
    {
        if (!owner) return {};
        uint8_t* at = reinterpret_cast<uint8_t*>(owner);
        FProperty* p = nullptr;
        UScriptStruct* type = nullptr;
        bool first = true;
        for (const TCHAR* name : path)
        {
            p = first ? prop_chain(owner, name) : struct_member(type, name);
            first = false;
            if (!p) return {};
            at += p->GetOffset_Internal();
            type = struct_type(p);
        }
        if (p->GetClass().GetName() != STR("NameProperty")) return {};
        std::wstring w = reinterpret_cast<FName*>(at)->ToString();
        std::string out;
        for (wchar_t ch : w) out += (char)(ch < 128 ? ch : '?');
        return out;
    }

    // Logs every number, flag and enum inside a struct (recursing into nested structs), one line
    // per value, so the joint's whole ConstraintInstance can be read instead of guessed.
    void dump_struct(const std::wstring& prefix, UScriptStruct* type, const uint8_t* at, int depth)
    {
        if (!type || depth > 5) return;
        for (UStruct* level = type; level; level = level->GetSuperStruct())
            for (FProperty* m : level->ForEachProperty())
            {
                const uint8_t* v = at + m->GetOffset_Internal();
                std::wstring name = prefix + STR(".") + m->GetName();
                auto kind = m->GetClass().GetName();
                if (kind == STR("StructProperty")) dump_struct(name, struct_type(m), v, depth + 1);
                else if (kind == STR("DoubleProperty")) HSVR_LOG("Grip:   %ls = %g", name.c_str(), *reinterpret_cast<const double*>(v));
                else if (kind == STR("FloatProperty")) HSVR_LOG("Grip:   %ls = %g", name.c_str(), *reinterpret_cast<const float*>(v));
                else if (kind == STR("IntProperty")) HSVR_LOG("Grip:   %ls = %d", name.c_str(), *reinterpret_cast<const int32_t*>(v));
                else if (kind == STR("ByteProperty") || (kind == STR("EnumProperty") && m->GetSize() == 1)) HSVR_LOG("Grip:   %ls = %d", name.c_str(), (int)*v);
                else if (kind == STR("BoolProperty"))
                {
                    auto* flag = static_cast<FBoolProperty*>(m);
                    HSVR_LOG("Grip:   %ls = %d", name.c_str(), (v[flag->GetByteOffset()] & flag->GetFieldMask()) ? 1 : 0);
                }
                else if (kind == STR("NameProperty")) HSVR_LOG("Grip:   %ls = %ls", name.c_str(), reinterpret_cast<const FName*>(v)->ToString().c_str());
            }
    }

    // Every physics constraint or physics handle an object points at, and what each one joins, to
    // find anything else holding the weapon besides the hand joint.
    void list_holders(UObject* owner)
    {
        if (!owner) return;
        for (UStruct* level = owner->GetClassPrivate(); level; level = level->GetSuperStruct())
            for (FProperty* p : level->ForEachProperty())
            {
                if (p->GetClass().GetName() != STR("ObjectProperty")) continue;
                UObject* o = *reinterpret_cast<UObject**>(reinterpret_cast<uint8_t*>(owner) + p->GetOffset_Internal());
                if (!o) continue;
                std::wstring cls = o->GetClassPrivate()->GetName();
                if (cls.find(STR("PhysicsConstraint")) == std::wstring::npos && cls.find(STR("PhysicsHandle")) == std::wstring::npos) continue;
                std::wstring joined;
                Call who(o, STR("GetConstrainedComponents"));
                if (who.run())
                    for (const TCHAR* pn : {STR("OutComponent1"), STR("OutBoneName1"), STR("OutComponent2"), STR("OutBoneName2")})
                    {
                        FProperty* pp = who.param(pn);
                        if (!pp) continue;
                        uint8_t* at = who.buffer.data() + pp->GetOffset_Internal();
                        if (pp->GetClass().GetName() == STR("NameProperty")) joined += reinterpret_cast<FName*>(at)->ToString() + STR(" ");
                        else
                        {
                            UObject* c = *reinterpret_cast<UObject**>(at);
                            joined += (c ? c->GetFullName() : std::wstring(STR("none"))) + STR(" : ");
                        }
                    }
                UObject* grabbed = object_property(o, STR("GrabbedComponent"));
                if (grabbed) joined += STR("grabs ") + grabbed->GetFullName();
                double xm = nested_number(o, {STR("ConstraintInstance"), STR("ProfileInstance"), STR("LinearLimit"), STR("XMotion")});
                HSVR_LOG("Grip: holder %ls.%ls = %ls (%ls) X motion %.0f: %ls", owner->GetName().c_str(), p->GetName().c_str(), o->GetName().c_str(), cls.c_str(), xm,
                         joined.c_str());
            }
    }

    // ---- keeping the held weapon from colliding with his own hand and forearm ---------------------
    // Contacts are rigid and beat any drive, so a soft grip spring lost to his own fist and forearm
    // bodies pressing on the grip (tests 18-22: ~15 cm off with any stiffness, while the game's
    // locked joint overpowers them). UE turns collision off between two bodies joined by a
    // constraint with bDisableCollision, so the mod adds one free (no-force) constraint between the
    // weapon and each physics body of that arm from the forearm down.
    std::vector<FName> physics_body_bones(UObject* mesh)
    {
        std::vector<FName> out;
        UObject* asset = nullptr;
        for (const TCHAR* n : {STR("SkeletalMeshAsset"), STR("SkinnedAsset"), STR("SkeletalMesh")})
            if (!asset) asset = object_property(mesh, n);
        UObject* physics = object_property(mesh, STR("PhysicsAssetOverride"));
        if (!physics && asset) physics = object_property(asset, STR("PhysicsAsset"));
        if (!physics)
        {
            HSVR_LOG("Grip: no physics asset found on %ls", mesh->GetFullName().c_str());
            return out;
        }
        FProperty* list = prop_chain(physics, STR("SkeletalBodySetups"));
        if (!list) return out;
        const RawArray* arr = reinterpret_cast<const RawArray*>(reinterpret_cast<uint8_t*>(physics) + list->GetOffset_Internal());
        for (int32_t i = 0; i < arr->Num; ++i)
        {
            UObject* body = reinterpret_cast<UObject*>(arr->Data[i]);
            if (!body) continue;
            FProperty* bn = prop_chain(body, STR("BoneName"));
            if (bn) out.push_back(*reinterpret_cast<FName*>(reinterpret_cast<uint8_t*>(body) + bn->GetOffset_Internal()));
        }
        return out;
    }

    FName parent_bone(UObject* mesh, FName bone)
    {
        Call c(mesh, STR("GetParentBone"));
        c.name(STR("BoneName"), bone);
        if (!c.run()) return FName();
        FProperty* rp = c.param(STR("ReturnValue"));
        return rp ? *reinterpret_cast<FName*>(c.buffer.data() + rp->GetOffset_Internal()) : FName();
    }

    // True for the forearm and everything below it on that side (twist bones, hand, fingers).
    bool in_forearm(UObject* mesh, FName bone, int side)
    {
        std::wstring stop = side == 0 ? STR("lowerarm_l") : STR("lowerarm_r");
        FName at = bone;
        for (int i = 0; i < 12; ++i)
        {
            std::wstring n = at.ToString();
            if (n == stop) return true;
            if (n == STR("None") || n.empty()) return false;
            at = parent_bone(mesh, at);
        }
        return false;
    }

    // That side's whole arm (upper arm down to the fingers): B&S's RagdollPart Arm + Hand.
    bool in_arm(UObject* mesh, FName bone, int side)
    {
        std::wstring stop = side == 0 ? STR("upperarm_l") : STR("upperarm_r");
        FName at = bone;
        for (int i = 0; i < 14; ++i)
        {
            std::wstring n = at.ToString();
            if (n == stop) return true;
            if (n == STR("None") || n.empty()) return false;
            at = parent_bone(mesh, at);
        }
        return false;
    }

    struct ArmIgnore
    {
        UObject* weapon = nullptr;
        std::vector<UObject*> joints;
        double dropped_at = -1.0; // let go of by a plain let-go at this time: kept until it is clear of him
        std::vector<UObject*> cm_joints; // that dropped item's no-collide pairs with his CM_* armour proxies
        std::vector<FName> bones;        // his bones the weapon was paired with (its hanging bodies get the same, see arm_hanging_tick)
        std::vector<UObject*> hanging;   // its hanging bodies already paired
        double made_at = -1.0;
    };
    ArmIgnore g_arm_ignore[2];
    UObject* arm_ignore_weapon(int side) { return g_arm_ignore[side].weapon; }
    std::atomic<int> g_grip_ignore_arm{1};
    // hsvr.weapon_channel <channel> <response>: sets the held weapon's response to one collision
    // channel (0 ignore, 1 overlap, 2 block). Changing responses only updates the physics filter,
    // unlike switching collision off, which rebuilt the body and orphaned the hand joint (test 21).
    std::atomic<int> g_weapon_channel_cmd{-1}, g_weapon_channel_resp{2};

    int byte_result(Call& c)
    {
        FProperty* rp = c.param(STR("ReturnValue"));
        return rp ? *(c.buffer.data() + rp->GetOffset_Internal()) : -1;
    }

    // What his own bodies are to the physics (object channel), and how the weapon responds to each.
    void log_collision_types(UObject* pawn, UObject* base)
    {
        std::vector<std::pair<std::wstring, UObject*>> parts;
        parts.push_back({STR("Mesh"), object_property(pawn, STR("Mesh"))});
        parts.push_back({STR("Capsule"), object_property(pawn, STR("CapsuleComponent"))});
        for (const TCHAR* n : {STR("CM_Arm_R"), STR("CM_Arm_L"), STR("CM_Cuirass"), STR("CM_Helmet"), STR("CM_Leg_L"), STR("CM_Leg_R")})
            parts.push_back({n, object_property(pawn, n)});
        for (auto& [name, comp] : parts)
        {
            if (!comp) continue;
            Call t(comp, STR("GetCollisionObjectType"));
            t.run();
            int type = byte_result(t);
            Call e(comp, STR("GetCollisionEnabled"));
            e.run();
            Call r(base, STR("GetCollisionResponseToChannel"));
            r.byte(STR("Channel"), (uint8_t)(type < 0 ? 0 : type));
            r.run();
            HSVR_LOG("Grip: his %ls is channel %d (collision %d); the weapon's response to that channel is %d", name.c_str(), type, byte_result(e), byte_result(r));
        }
        Call t(base, STR("GetCollisionObjectType"));
        t.run();
        HSVR_LOG("Grip: the weapon itself is channel %d", byte_result(t));
    }

    // An item let go of keeps not colliding with his body (and own headgear) until it is clear of him, as a
    // B&S item ignores its last holder until it leaves him. PC run 12925e2: shields let go of were pushed
    // 19-35 cm sideways after the release, the push starting as the no-collide pairs went (~25 ms after).
    // Clear = no part of it within pose_drop_ignore_clear_cm of his bones or his CM_* armour proxies,
    // or pose_drop_ignore_s passed.
    const TCHAR* const k_cm_proxies[] = {STR("CM_Arm_L"), STR("CM_Arm_R"), STR("CM_Cuirass"), STR("CM_Leg_L"), STR("CM_Leg_R"), STR("CM_Helmet")};
    double closest_on_weapon(UObject* weapon, const hsvr::Vec3& point, hsvr::Vec3* out, UObject** out_part);
    void drop_resume_guard(int side, UObject* item);
    // The gap between an item and one body of his (a bone's physics body, or a whole component when bone is
    // None): closest points taken in turn, from the bone's place, three times. 0 = touching or inside. A
    // bone's place alone is not his body: a thigh body reaches 20+ cm from its bone (PC run 55b88f3: a light
    // pavise "17 cm clear" of the bone points was inside him, and was flung 11 m as the pairs went).
    double item_gap(UObject* item, UObject* comp, FName bone, hsvr::Vec3 p)
    {
        double gap = -1.0;
        for (int k = 0; k < 3; ++k)
        {
            hsvr::Vec3 q;
            double dq = closest_on_weapon(item, p, &q, nullptr);
            if (dq < 0.0) return gap;
            if (dq == 0.0) return 0.0;
            Call cp(comp, STR("GetClosestPointOnCollision"));
            cp.three(STR("Point"), q.x, q.y, q.z);
            cp.name(STR("BoneName"), bone);
            cp.run();
            double d = cp.number();
            if (d < 0.0) return gap;
            if (d == 0.0) return 0.0;
            gap = d;
            p = cp.vec(STR("OutPointOnBody"));
        }
        return gap;
    }
    bool drop_ignore_lingers(int side, UObject* pawn)
    {
        using namespace hsvr;
        ArmIgnore& a = g_arm_ignore[side];
        const Config& cfg = hsvr::config();
        if (a.dropped_at < 0.0 || !a.weapon || cfg.pose_drop_ignore_s <= 0.0) return false;
        double age = now_seconds() - a.dropped_at;
        UObject* mesh = pawn ? object_property(pawn, STR("Mesh")) : nullptr;
        if (age > cfg.pose_drop_ignore_s || !mesh || !object_alive(a.weapon))
        {
            if (a.weapon && object_alive(a.weapon))
            {
                HSVR_LOG("Drop: %ls collides with you again (%.2f s after the let-go: time)", a.weapon->GetName().c_str(), age);
                drop_resume_guard(side, a.weapon);
            }
            return false;
        }
        double nearest = 1e9;
        const char* nearest_what = "";
        static UObject* bones_of = nullptr;
        static std::vector<FName> bones;
        if (bones_of != mesh) bones = physics_body_bones(mesh), bones_of = mesh;
        static std::string nearest_bone;
        for (const FName& b : bones)
        {
            double d = item_gap(a.weapon, mesh, b, socket_location(mesh, b));
            if (d >= 0.0 && d < nearest)
            {
                nearest = d;
                std::wstring wn = b.ToString();
                nearest_bone.clear();
                for (wchar_t ch : wn) nearest_bone.push_back((char)ch);
                nearest_what = nearest_bone.c_str();
            }
        }
        if (UObject* cap = object_property(pawn, STR("CapsuleComponent")))
        {
            double d = item_gap(a.weapon, cap, FName(), component_location(cap));
            if (d >= 0.0 && d < nearest) nearest = d, nearest_what = "capsule";
        }
        for (const TCHAR* name : k_cm_proxies)
            if (UObject* cm = object_property(pawn, name))
            {
                Call r(cm, STR("GetScaledSphereRadius"));
                double radius = r.run() ? r.number() : 0.0;
                double d = closest_on_weapon(a.weapon, component_location(cm), nullptr, nullptr);
                if (d >= 0.0 && d - radius < nearest) nearest = d - radius, nearest_what = "armour proxy";
            }
        if (nearest > cfg.pose_drop_ignore_clear_cm)
        {
            HSVR_LOG("Drop: %ls collides with you again (%.2f s after the let-go, %.0f cm clear, nearest %s)", a.weapon->GetName().c_str(), age, nearest, nearest_what);
            drop_resume_guard(side, a.weapon);
            return false;
        }
        HSVR_LOG_EVERY(0.1, "Drop: %ls still %.1f cm from your %s (%.2f s after the let-go)", a.weapon->GetName().c_str(), nearest, nearest_what, age);
        return true;
    }

    void clear_arm_ignore(int side)
    {
        g_release_linger[side] = ReleaseLinger{};
        for (UObject* j : g_arm_ignore[side].joints)
        {
            Call d(j, STR("K2_DestroyComponent"));
            d.object(STR("Object"), j);
            d.run();
        }
        for (UObject* j : g_arm_ignore[side].cm_joints)
            if (j && object_alive(j))
            {
                Call d(j, STR("K2_DestroyComponent"));
                d.object(STR("Object"), j);
                d.run();
            }
        g_arm_ignore[side].joints.clear();
        g_arm_ignore[side].cm_joints.clear();
        g_arm_ignore[side].weapon = nullptr;
        g_arm_ignore[side].dropped_at = -1.0;
        g_arm_ignore[side].bones.clear();
        g_arm_ignore[side].hanging.clear();
        g_arm_ignore[side].made_at = -1.0;
    }

    // His armour proxies (spheres the game keeps on him, channel 20, blocking weapons): a dropped item is
    // not paired off with them while held, so on the let-go any it overlapped shoved it (PC run 0815006: a
    // ~3 m/s kick as the no-collide pairs went with the item 8 cm clear of his bones).
    void attached_meshes(UObject* root, UObject* skip, std::vector<UObject*>& out, int depth);
    std::vector<UObject*> static_parts_of(UObject* owner);
    void first_number(Call& c, double v);
    bool physics_collides(UObject* c);
    void weapons_from_parts(UObject* pawn, std::vector<UObject*>& out);
    UObject* no_collision_pair(UObject* pawn, UClass* cls, UObject* a, UObject* b, FName bone_b = FName());
    void drop_cm_pairs(int side, UObject* pawn, UObject* item)
    {
        UObject* base = object_property(item, STR("BaseMesh"));
        UClass* cls = UObjectGlobals::StaticFindObject<UClass*>(nullptr, nullptr, STR("/Script/Engine.PhysicsConstraintComponent"));
        if (!base || !cls) return;
        std::vector<UObject*> parts;
        attached_meshes(base, object_property(item, STR("Scabbard")), parts, 0);
        int n = 0;
        // And his capsule: a let-go item sliding down it was pushed aside (PC run 55b88f3: light pavise, a
        // steady ~1.6 m/s^2 sideways while its pairs with his bones held).
        for (const TCHAR* name : {STR("CapsuleComponent")})
            if (UObject* cap = object_property(pawn, name))
                for (UObject* p : parts)
                    if (UObject* j = no_collision_pair(pawn, cls, p, cap))
                    {
                        g_arm_ignore[side].cm_joints.push_back(j);
                        ++n;
                    }
        for (const TCHAR* name : k_cm_proxies)
            if (UObject* cm = object_property(pawn, name))
                for (UObject* p : parts)
                    if (UObject* j = no_collision_pair(pawn, cls, p, cm))
                    {
                        g_arm_ignore[side].cm_joints.push_back(j);
                        ++n;
                    }
        HSVR_LOG("Drop: %ls: %d no-collide pair(s) with your capsule and armour proxies until it is clear of you", item->GetName().c_str(), n);
    }

    // A new constraint component of his, at his root, joining nothing yet.
    UObject* new_constraint(UObject* pawn, UClass* cls)
    {
        Call add(pawn, STR("AddComponentByClass"));
        add.object(STR("Class"), cls);
        add.flag(STR("bManualAttachment"), false);
        if (FProperty* t = add.param(STR("RelativeTransform")))
        {
            uint8_t* at = add.buffer.data() + t->GetOffset_Internal();
            UScriptStruct* type = struct_type(t);
            if (FProperty* r = struct_member(type, STR("Rotation")))
                if (FProperty* w = struct_member(struct_type(r), STR("W")))
                {
                    uint8_t* wat = at + r->GetOffset_Internal() + w->GetOffset_Internal();
                    if (w->GetClass().GetName() == STR("DoubleProperty")) *reinterpret_cast<double*>(wat) = 1.0;
                    else *reinterpret_cast<float*>(wat) = 1.0f;
                }
            if (FProperty* sc = struct_member(type, STR("Scale3D"))) write_three(at + sc->GetOffset_Internal(), sc, 1.0, 1.0, 1.0);
        }
        add.flag(STR("bDeferredFinish"), false);
        return add.run() ? add.object_result() : nullptr;
    }

    void ignore_arm_collision(UObject* pawn, UObject* mesh, UObject* weapon, UObject* base, int side)
    {
        if (g_arm_ignore[side].weapon == weapon) return;
        clear_arm_ignore(side);
        g_arm_ignore[side].weapon = weapon;
        UClass* cls = UObjectGlobals::StaticFindObject<UClass*>(nullptr, nullptr, STR("/Script/Engine.PhysicsConstraintComponent"));
        if (!cls || !mesh) return;
        FName hand = bone_fname(side == 0 ? "hand_l" : "hand_r");
        std::wstring names;
        // The weapon's bodies of their own too (a chain lantern's lamp and Link 1-4 hang on constraints outside BaseMesh's weld
        // tree, so a pair with BaseMesh never covered them): run 27 pickup_both, the held lantern's lamp hit his own hand_r 1531,
        // lowerarm_r 4763, upperarm_r 1637 in its first 0.2 s in the hand.
        std::vector<UObject*> hanging;
        {
            std::vector<UObject*> tree, scab;
            attached_meshes(base, nullptr, tree, 0);
            attached_meshes(object_property(weapon, STR("Scabbard")), nullptr, scab, 0);
            for (UObject* c : static_parts_of(weapon))
                if (std::find(tree.begin(), tree.end(), c) == tree.end() && std::find(scab.begin(), scab.end(), c) == scab.end() && physics_collides(c))
                    hanging.push_back(c);
        }
        for (FName bone : physics_body_bones(mesh))
        {
            // The hand too (kick-test3: the hand body, 7.4 cm off the bone, sits in the grip; when the
            // pair collides it shoves the weapon out across the palm about twice a second). B&S never
            // lets a held item touch the hand that holds it.
            // B&S: a held item ignores the whole player body (item.ignoredRagdoll, bs_hold_measured.md §1);
            // the other hand's call (a second hand on it) adds only its own forearm.
            const hsvr::Config& ac = hsvr::config();
            bool whole = ac.pose_hold_ignore_body && g_arm_ignore[1 - side].weapon != weapon;
            if (!ac.pose_hold_ignore_hand && bone.ToString() == hand.ToString()) continue;
            // B&S's Player Self Collision (Item.RefreshCollision, Item.cs:3359-3520; bs_body_physics.md). On
            // (pose_hold_self_collision=1): the weapon ignores only the arm(s) and hand(s) holding it (upper arm to fingers);
            // his torso, head, legs, feet and free arm push it away (playtest 2026-11-23 5:01 PM: a two-handed mace sat inside
            // his torso). Off (0, B&S's default): his whole body but the feet, and the free hand while held in one hand.
            // pose_hold_free_hand_collides=0: the free arm (one hand holding) is ignored too (test switch: park cases 2026-11-24, the
            // free left hand parked beside a held axe set it wobbling at 450-650 deg/s with no contact logged on the axis).
            // A shield or pavise held in one hand also passes through the free arm: strapping it onto that forearm means
            // carrying it into that arm (PC run 2ef27f9: with only the holding arm ignored, the light pavise in the right
            // hand stopped 15-20 cm short of the left forearm, "Hold: right weapon stopped", and never mounted).
            bool one_hand = g_arm_ignore[1 - side].weapon != weapon;
            bool free_ignored = one_hand && (!ac.pose_hold_free_hand_collides || class_name_starts(weapon, STR("Shield")));
            if (ac.pose_hold_ignore_body && ac.pose_hold_self_collision)
            {
                // pose_hold_free_arm_collides=0: of the free arm only the hand stays solid; its forearm and upper arm pass through
                // (796b650 park_axe2h: the axe was pushed 15-20 cm off the hand and held there against his free arm at 446-504 deg/s).
                bool free_hand_bone = bone.ToString() == (side == 0 ? STR("hand_r") : STR("hand_l"));
                bool free_arm_ignored = one_hand && !ac.pose_hold_free_arm_collides && !free_hand_bone;
                if (!in_arm(mesh, bone, side) && !((free_ignored || free_arm_ignored) && in_arm(mesh, bone, 1 - side))) continue;
            }
            else if (whole)
            {
                std::wstring bn = bone.ToString();
                if (bn == STR("foot_l") || bn == STR("foot_r") || (!free_ignored && bn == (side == 0 ? STR("hand_r") : STR("hand_l")))) continue;
            }
            else if (!in_forearm(mesh, bone, side))
                continue;
            UObject* j = new_constraint(pawn, cls);
            if (!j) continue;
            // Free in every direction and no drives: it holds nothing, it only switches off the pair's collision.
            for (const TCHAR* fn : {STR("SetLinearXLimit"), STR("SetLinearYLimit"), STR("SetLinearZLimit")})
            {
                Call c1(j, fn);
                c1.byte(STR("ConstraintType"), 0);
                c1.number(STR("LimitSize"), 0.0);
                c1.run();
            }
            for (const TCHAR* fn : {STR("SetAngularSwing1Limit"), STR("SetAngularSwing2Limit"), STR("SetAngularTwistLimit")})
            {
                Call c1(j, fn);
                c1.byte(STR("MotionType"), 0);
                c1.run();
            }
            Call dc(j, STR("SetDisableCollision"));
            dc.first_flag(true);
            dc.run();
            Call join(j, STR("SetConstrainedComponents"));
            join.object(STR("Component1"), base);
            join.name(STR("BoneName1"), FName());
            join.object(STR("Component2"), mesh);
            join.name(STR("BoneName2"), bone);
            join.run();
            g_arm_ignore[side].joints.push_back(j);
            g_arm_ignore[side].bones.push_back(bone);
            names += bone.ToString() + STR(" ");
            for (UObject* h : hanging)
                if (UObject* hj = no_collision_pair(pawn, cls, h, mesh, bone)) g_arm_ignore[side].joints.push_back(hj);
        }
        if (!hanging.empty()) HSVR_LOG("Grip: %zu hanging bodies of the weapon paired with the same bones", hanging.size());
        g_arm_ignore[side].hanging = hanging;
        g_arm_ignore[side].made_at = hsvr::now_seconds();
        HSVR_LOG("Grip: %s weapon no longer collides with: %ls", side == 0 ? "left" : "right", names.empty() ? STR("(no forearm bodies found)") : names.c_str());
    }

    // His own body against a held weapon: the closest of his physics bodies to the weapon's axis
    // (pommel end to tip, 12 points), if within `within` cm. Vanilla weapons collide with his own
    // body too (self_collision.md), so a weapon stopped by it is not stuck in something else.
    double own_body_contact(UObject* pawn, UObject* weapon, double within, std::wstring* bone_out = nullptr, int holding_side = -1)
    {
        using namespace hsvr;
        UObject* mesh = object_property(pawn, STR("Mesh"));
        UObject* pommel = object_property(weapon, STR("PommelSk"));
        UObject* tip = object_property(weapon, STR("TippyTipScene"));
        if (!mesh || !pommel || !tip) return -1.0;
        Vec3 a = component_location(pommel), b = component_location(tip);
        double best = -1.0;
        for (FName bone : physics_body_bones(mesh))
        {
            // The holding arm from the forearm down never collides with its weapon (ignore_arm_collision),
            // so it is not what stops it (playtest 2: "stopped by his own hand_r").
            if (holding_side >= 0 && in_forearm(mesh, bone, holding_side)) continue;
            for (int i = 0; i <= 11; ++i)
            {
                Vec3 pt = a + (b - a) * (i / 11.0);
                Call c(mesh, STR("GetClosestPointOnCollision"));
                c.three(STR("Point"), pt.x, pt.y, pt.z);
                c.name(STR("BoneName"), bone);
                if (!c.run()) break;
                double d = c.number();
                if (d >= 0.0 && d <= within && (best < 0.0 || d < best))
                {
                    best = d;
                    if (bone_out) *bone_out = bone.ToString();
                }
            }
        }
        return best;
    }

    // ---- what the held weapon is touching (test tool) ----------------------------------------------
    // For each of his physics bodies, the closest distance from the weapon's axis (pommel end to tip,
    // 12 points) to that body's collision. Bodies within 4 cm of the axis are touching or nearly
    // (a grip is ~1.5 cm in radius). Also every other component overlapping the weapon's meshes.
    void log_weapon_contacts(UObject* pawn, UObject* weapon, UObject* base)
    {
        using namespace hsvr;
        UObject* mesh = object_property(pawn, STR("Mesh"));
        UObject* pommel = object_property(weapon, STR("PommelSk"));
        UObject* tip = object_property(weapon, STR("TippyTipScene"));
        if (!mesh || !pommel || !tip) return;
        Vec3 a = component_location(pommel), b = component_location(tip);
        std::wstring near_list;
        for (FName bone : physics_body_bones(mesh))
        {
            double best = 1e9;
            for (int i = 0; i <= 11; ++i)
            {
                Vec3 pt = a + (b - a) * (i / 11.0);
                Call c(mesh, STR("GetClosestPointOnCollision"));
                c.three(STR("Point"), pt.x, pt.y, pt.z);
                c.name(STR("BoneName"), bone);
                if (!c.run()) break;
                double d = c.number();
                if (d >= 0.0 && d < best) best = d;
            }
            if (best < 4.0)
            {
                wchar_t one[96];
                swprintf(one, 96, L"%ls %.1f, ", bone.ToString().c_str(), best);
                near_list += one;
            }
        }
        HSVR_LOG("Grip: contacts: his bodies within 4 cm of the weapon axis: %ls", near_list.empty() ? STR("none") : near_list.c_str());
        static UObject* cdo = UObjectGlobals::StaticFindObject<UObject*>(nullptr, nullptr, STR("/Script/Engine.Default__KismetSystemLibrary"));
        if (!cdo) return;
        static uint8_t types[32];
        for (int i = 0; i < 32; ++i) types[i] = (uint8_t)i;
        std::wstring others;
        for (const TCHAR* part : {STR("Head"), STR("Guard"), STR("Grip"), STR("Pommel"), STR("BaseMesh")})
        {
            UObject* comp = object_property(weapon, part);
            if (!comp) continue;
            Call world(comp, STR("K2_GetComponentToWorld"));
            if (!world.run()) continue;
            FProperty* wr = world.param(STR("ReturnValue"));
            Call ov(cdo, STR("ComponentOverlapComponents"));
            FProperty* ct = ov.param(STR("ComponentTransform"));
            FProperty* ot = ov.param(STR("ObjectTypes"));
            FProperty* out = ov.param(STR("OutComponents"));
            if (!wr || !ct || !ot || !out) continue;
            ov.object(STR("Component"), comp);
            std::memcpy(ov.buffer.data() + ct->GetOffset_Internal(), world.buffer.data() + wr->GetOffset_Internal(), ct->GetSize());
            RawArray* list = reinterpret_cast<RawArray*>(ov.buffer.data() + ot->GetOffset_Internal());
            list->Data = reinterpret_cast<void**>(types);
            list->Num = list->Max = 32;
            if (!ov.run()) continue;
            RawArray* found = reinterpret_cast<RawArray*>(ov.buffer.data() + out->GetOffset_Internal());
            for (int32_t i = 0; i < found->Num && found->Data; ++i)
            {
                UObject* o = reinterpret_cast<UObject*>(found->Data[i]);
                if (!o || o->GetOuterPrivate() == weapon) continue;
                others += std::wstring(part) + STR(" touches ") + o->GetFullName() + STR("; ");
            }
            // The engine allocated that list; leave it (a few bytes per test log line).
            found->Data = nullptr;
            found->Num = found->Max = 0;
            list->Data = nullptr;
            list->Num = list->Max = 0;
        }
        HSVR_LOG("Grip: contacts: overlapping components: %ls", others.empty() ? STR("none") : others.c_str());
    }

    // The physics solver's console variables that shape a joint drive (read through the Kismet
    // library, since the shipping build writes no game log). Logged once per weapon.
    void log_chaos_cvars()
    {
        static UObject* cdo = UObjectGlobals::StaticFindObject<UObject*>(nullptr, nullptr, STR("/Script/Engine.Default__KismetSystemLibrary"));
        if (!cdo) return;
        for (const TCHAR* name :
             {STR("p.Chaos.JointConstraint.LinearDriveStiffnessScale"), STR("p.Chaos.JointConstraint.LinaearDriveDampingScale"),
              STR("p.Chaos.JointConstraint.AngularDriveStiffnessScale"), STR("p.Chaos.JointConstraint.AngularDriveDampingScale"),
              STR("p.Chaos.JointConstraint.SoftLinearForceMode"), STR("p.Chaos.JointConstraint.SoftAngularForceMode"),
              STR("p.Chaos.JointConstraint.JointStiffness"), STR("p.Chaos.Solver.Joint.UsePBDDrives"), STR("p.Chaos.Solver.Joint.UseLinearSolver"),
              STR("p.Chaos.Solver.Joint.MinSolverStiffness"), STR("p.Chaos.Solver.Joint.MaxSolverStiffness"),
              STR("p.Chaos.Solver.Joint.NumIterationsAtMaxSolverStiffness"), STR("p.Chaos.Solver.Joint.SolvePositionLast"),
              STR("p.Chaos.Solver.Joint.TransferCollisions"), STR("p.Chaos.Solver.Joint.MinParentMassRatio"), STR("p.Chaos.Solver.Joint.MaxInertiaRatio"),
              STR("p.Chaos.Solver.Iterations.Position"), STR("p.Chaos.Solver.Iterations.Velocity"), STR("p.Chaos.Solver.Iterations.Projection"),
              STR("p.Chaos.Joint.DisableSoftLimits"), STR("p.Chaos.Joint.VelProjectionAlpha"), STR("p.Chaos.Solver.Collision.MaxPushOutVelocity"),
              STR("p.Chaos.Solver.Collision.DepenetrationVelocity"), STR("p.Chaos.Solver.Joint.ShockPropagation"), STR("p.ChaosSolverEnableJointConstraints")})
        {
            Call f(cdo, STR("GetConsoleVariableFloatValue"));
            FProperty* vp = f.param(STR("VariableName"));
            if (!vp) return;
            FString text(name);
            *reinterpret_cast<FString*>(f.buffer.data() + vp->GetOffset_Internal()) = text;
            f.run();
            double v = f.number();
            *reinterpret_cast<FString*>(f.buffer.data() + vp->GetOffset_Internal()) = FString();
            Call i(cdo, STR("GetConsoleVariableIntValue"));
            FProperty* ip = i.param(STR("VariableName"));
            int iv = 0;
            if (ip)
            {
                *reinterpret_cast<FString*>(i.buffer.data() + ip->GetOffset_Internal()) = FString(name);
                i.run();
                iv = i.integer();
                *reinterpret_cast<FString*>(i.buffer.data() + ip->GetOffset_Internal()) = FString();
            }
            HSVR_LOG("Grip: cvar %ls = %g (int %d)", name, v, iv);
        }
    }

    // Rotation whose X, Y, Z axes are the given (orthonormalised) X and Y axes and their cross product.
    hsvr::Quat quat_from_axes(hsvr::Vec3 x, hsvr::Vec3 y)
    {
        using namespace hsvr;
        x = x * (1.0 / (std::max)(1e-9, length(x)));
        Vec3 z = cross(x, y);
        z = z * (1.0 / (std::max)(1e-9, length(z)));
        y = cross(z, x);
        double m00 = x.x, m10 = x.y, m20 = x.z, m01 = y.x, m11 = y.y, m21 = y.z, m02 = z.x, m12 = z.y, m22 = z.z;
        double tr = m00 + m11 + m22;
        Quat q;
        if (tr > 0)
        {
            double s = std::sqrt(tr + 1.0) * 2;
            q = Quat{(m21 - m12) / s, (m02 - m20) / s, (m10 - m01) / s, 0.25 * s};
        }
        else if (m00 > m11 && m00 > m22)
        {
            double s = std::sqrt(1.0 + m00 - m11 - m22) * 2;
            q = Quat{0.25 * s, (m01 + m10) / s, (m02 + m20) / s, (m21 - m12) / s};
        }
        else if (m11 > m22)
        {
            double s = std::sqrt(1.0 + m11 - m00 - m22) * 2;
            q = Quat{(m01 + m10) / s, 0.25 * s, (m12 + m21) / s, (m02 - m20) / s};
        }
        else
        {
            double s = std::sqrt(1.0 + m22 - m00 - m11) * 2;
            q = Quat{(m02 + m20) / s, (m12 + m21) / s, 0.25 * s, (m10 - m01) / s};
        }
        return q.normalized();
    }

    void dump_joint(UObject* joint)
    {
        FProperty* p = joint ? prop_chain(joint, STR("ConstraintInstance")) : nullptr;
        if (!p) return;
        HSVR_LOG("Grip: full joint settings of %ls:", joint->GetFullName().c_str());
        dump_struct(STR("ConstraintInstance"), struct_type(p), reinterpret_cast<const uint8_t*>(joint) + p->GetOffset_Internal(), 0);
    }

    // What the hand joint really has set, for the log: linear X drive (on, stiffness, damping, max
    // force), slerp drive (on, stiffness, max), linear X motion (0 free, 1 limited, 2 locked).
    std::string joint_settings(UObject* joint)
    {
        auto n = [&](std::initializer_list<const TCHAR*> path) { return nested_number(joint, path); };
        char text[320];
        std::snprintf(text, sizeof(text), "linX pos %.0f k %.0f c %.0f max %.0f, slerp %.0f k %.0f max %.0f, mode %.0f, X motion %.0f, swing1 %.0f",
                      n({STR("ConstraintInstance"), STR("ProfileInstance"), STR("LinearDrive"), STR("XDrive"), STR("bEnablePositionDrive")}),
                      n({STR("ConstraintInstance"), STR("ProfileInstance"), STR("LinearDrive"), STR("XDrive"), STR("Stiffness")}),
                      n({STR("ConstraintInstance"), STR("ProfileInstance"), STR("LinearDrive"), STR("XDrive"), STR("Damping")}),
                      n({STR("ConstraintInstance"), STR("ProfileInstance"), STR("LinearDrive"), STR("XDrive"), STR("MaxForce")}),
                      n({STR("ConstraintInstance"), STR("ProfileInstance"), STR("AngularDrive"), STR("SlerpDrive"), STR("bEnablePositionDrive")}),
                      n({STR("ConstraintInstance"), STR("ProfileInstance"), STR("AngularDrive"), STR("SlerpDrive"), STR("Stiffness")}),
                      n({STR("ConstraintInstance"), STR("ProfileInstance"), STR("AngularDrive"), STR("SlerpDrive"), STR("MaxForce")}),
                      n({STR("ConstraintInstance"), STR("ProfileInstance"), STR("AngularDrive"), STR("AngularDriveMode")}),
                      n({STR("ConstraintInstance"), STR("ProfileInstance"), STR("LinearLimit"), STR("XMotion")}),
                      n({STR("ConstraintInstance"), STR("ProfileInstance"), STR("ConeLimit"), STR("Swing1Motion")}));
        return text;
    }

    // Just before his tick: what the hand joint looks like after everything else ran since our
    // last write (the weapon's own tick, physics), to catch anyone else changing it.
    void log_joint_before_tick(UObject* pawn)
    {
        static double last = 0.0;
        double now = hsvr::now_seconds();
        if (now - last < 1.0) return;
        UObject* joint = object_property(pawn, STR("PhysicsConstraint R Hand"));
        if (!joint || !object_property(pawn, STR("Weapon R"))) return;
        last = now;
        HSVR_LOG("Grip: right joint before his tick: %s", joint_settings(joint).c_str());
    }

    // ---- The weapon in your hand: the hold from Matthew's Chasms VR Framework ---------------------
    // Ported from crates/runtime/src/rig/physics.rs (Physics::joint, Joint::one_hand,
    // body_inertia_tensor_about; MIT, Copyright (c) 2026 chasmlol). No joint pulls the weapon: the
    // game's hand joint is left in place but free (no limits, no drives), so the game still knows the
    // weapon is held. Every tick, before physics, the weapon's own velocity and spin are set so the
    // point held arrives where the controller has the hand at the end of the step: a spring and a
    // damper from the controller to that point, solved implicitly (steady at any frame rate) and no
    // stronger than the hand. The weapon keeps its mass and gravity: its weight turns it about the
    // grip against its inertia about the grip (a heavy head sags and trails a fast grip), and what it
    // hits stops it.
    struct Mat3
    {
        double m[3][3] = {{0, 0, 0}, {0, 0, 0}, {0, 0, 0}};
        static Mat3 diag(double a, double b, double c)
        {
            Mat3 r;
            r.m[0][0] = a, r.m[1][1] = b, r.m[2][2] = c;
            return r;
        }
        static Mat3 from_quat(const hsvr::Quat& q)
        {
            Mat3 r;
            hsvr::Vec3 cols[3] = {q.rotate({1, 0, 0}), q.rotate({0, 1, 0}), q.rotate({0, 0, 1})};
            for (int j = 0; j < 3; ++j) r.m[0][j] = cols[j].x, r.m[1][j] = cols[j].y, r.m[2][j] = cols[j].z;
            return r;
        }
        Mat3 operator*(const Mat3& o) const
        {
            Mat3 r;
            for (int i = 0; i < 3; ++i)
                for (int j = 0; j < 3; ++j)
                    for (int k = 0; k < 3; ++k) r.m[i][j] += m[i][k] * o.m[k][j];
            return r;
        }
        Mat3 operator+(const Mat3& o) const
        {
            Mat3 r;
            for (int i = 0; i < 3; ++i)
                for (int j = 0; j < 3; ++j) r.m[i][j] = m[i][j] + o.m[i][j];
            return r;
        }
        Mat3 operator*(double s) const
        {
            Mat3 r;
            for (int i = 0; i < 3; ++i)
                for (int j = 0; j < 3; ++j) r.m[i][j] = m[i][j] * s;
            return r;
        }
        hsvr::Vec3 operator*(const hsvr::Vec3& v) const
        {
            return {m[0][0] * v.x + m[0][1] * v.y + m[0][2] * v.z, m[1][0] * v.x + m[1][1] * v.y + m[1][2] * v.z,
                    m[2][0] * v.x + m[2][1] * v.y + m[2][2] * v.z};
        }
        Mat3 transpose() const
        {
            Mat3 r;
            for (int i = 0; i < 3; ++i)
                for (int j = 0; j < 3; ++j) r.m[i][j] = m[j][i];
            return r;
        }
        Mat3 inverse() const
        {
            const auto& a = m;
            double c00 = a[1][1] * a[2][2] - a[1][2] * a[2][1], c01 = a[1][2] * a[2][0] - a[1][0] * a[2][2], c02 = a[1][0] * a[2][1] - a[1][1] * a[2][0];
            double det = a[0][0] * c00 + a[0][1] * c01 + a[0][2] * c02;
            Mat3 r;
            if (std::fabs(det) < 1e-18) return r;
            double s = 1.0 / det;
            r.m[0][0] = c00 * s;
            r.m[0][1] = (a[0][2] * a[2][1] - a[0][1] * a[2][2]) * s;
            r.m[0][2] = (a[0][1] * a[1][2] - a[0][2] * a[1][1]) * s;
            r.m[1][0] = c01 * s;
            r.m[1][1] = (a[0][0] * a[2][2] - a[0][2] * a[2][0]) * s;
            r.m[1][2] = (a[0][2] * a[1][0] - a[0][0] * a[1][2]) * s;
            r.m[2][0] = c02 * s;
            r.m[2][1] = (a[0][1] * a[2][0] - a[0][0] * a[2][1]) * s;
            r.m[2][2] = (a[0][0] * a[1][1] - a[0][1] * a[1][0]) * s;
            return r;
        }
    };

    // (The old soft-constraint hold that lived here is gone: the hold is bs_hold_joint, the engine joint with B&S drives.)
    hsvr::Vec3 clamp_length(const hsvr::Vec3& v, double most);
    inline Mat3 skew(const hsvr::Vec3& r)
    {
        Mat3 m;
        m.m[0][1] = -r.z, m.m[0][2] = r.y, m.m[1][0] = r.z, m.m[1][2] = -r.x, m.m[2][0] = -r.y, m.m[2][1] = r.x;
        return m;
    }

    hsvr::Vec3 clamp_length(const hsvr::Vec3& v, double most)
    {
        double l = hsvr::length(v);
        return l > most && l > 1e-12 ? v * (most / l) : v;
    }

    // Rotation vector (axis times angle, radians) of a rotation, the short way round.
    hsvr::Vec3 scaled_axis(hsvr::Quat q)
    {
        q = q.normalized();
        if (q.w < 0) q = hsvr::Quat{-q.x, -q.y, -q.z, -q.w};
        double s = std::sqrt(q.x * q.x + q.y * q.y + q.z * q.z);
        if (s < 1e-12) return {q.x * 2.0, q.y * 2.0, q.z * 2.0};
        double angle = 2.0 * std::atan2(s, q.w);
        return hsvr::Vec3{q.x, q.y, q.z} * (angle / s);
    }

    hsvr::Quat from_scaled_axis(const hsvr::Vec3& v)
    {
        double angle = hsvr::length(v);
        if (angle < 1e-12) return hsvr::Quat{v.x * 0.5, v.y * 0.5, v.z * 0.5, 1.0}.normalized();
        return hsvr::quat_axis_angle(v * (1.0 / angle), angle);
    }

    void free_joint(UObject* joint)
    {
        for (const TCHAR* fn : {STR("SetLinearXLimit"), STR("SetLinearYLimit"), STR("SetLinearZLimit")})
        {
            Call c1(joint, fn);
            c1.byte(STR("ConstraintType"), 0); // free
            c1.number(STR("LimitSize"), 0.0);
            c1.run();
        }
        for (const TCHAR* fn : {STR("SetAngularSwing1Limit"), STR("SetAngularSwing2Limit"), STR("SetAngularTwistLimit")})
        {
            Call c1(joint, fn);
            c1.byte(STR("MotionType"), 0); // free
            c1.run();
        }
        Call pos(joint, STR("SetLinearPositionDrive"));
        pos.run(); // all three off
        Call vel(joint, STR("SetLinearVelocityDrive"));
        vel.run();
        Call slerp(joint, STR("SetOrientationDriveSLERP"));
        slerp.first_flag(false);
        slerp.run();
        Call aslerp(joint, STR("SetAngularVelocityDriveSLERP"));
        aslerp.first_flag(false);
        aslerp.run();
        Call twist(joint, STR("SetOrientationDriveTwistAndSwing"));
        twist.run(); // both off
        Call atwist(joint, STR("SetAngularVelocityDriveTwistAndSwing"));
        atwist.run();
    }

    // -1 = the ini (pose_grip_hold); 0 / 1 from the dev script (hsvr.grip_hold).
    std::atomic<int> g_grip_hold_override{-1};

    // A grip the mod chose instead of the game's (shields: Matthew 2026-11-18, "if i can see more then
    // one grab point then i want to be able to grab it", and the rim anywhere). The weapon is held at
    // `pivot` (BaseMesh frame) by the point `in_anchor` of the anchor (the hand bone, or for a strap
    // the bone `bone`), turned `rel` from the anchor's frame. The game still thinks the hand holds it
    // its own way; only where the hold puts it changes.
    struct FreeGrip
    {
        bool set = false;
        hsvr::Vec3 pivot, in_anchor;
        hsvr::Quat rel;
        bool forearm = false;
        std::string bone;
        std::string what; // for the log: "rim", a strap's name...
        bool place = false; // put the weapon there on the hold's first tick
        bool fingers = false; // curl that hand's fingers (pose_shield_hand_grip_type) while held
        // On a handle (B&S): the segment it may slide along (BaseMesh frame), where on it (0..1), and
        // the finger shape (game grip type, -1 = the game's own).
        bool has_handle = false;
        hsvr::Vec3 ha, hb;
        double t = 0.0;
        std::string handle;
        int grip_type = -1;
        // B&S: on a grab the item stays where it was (kept there while the game sets it up) and the
        // hold then pulls it into the hand over pose_grab_settle_s.
        bool hold_at = false;
        hsvr::Vec3 at_pos;
        hsvr::Quat at_rot;
    };
    FreeGrip g_pending_free[2]; // applied when that hand's next hold starts
    UObject* g_pending_item[2] = {nullptr, nullptr}; // the item it is for (kept in the hand until the hold starts)

    struct HoldState
    {
        UObject* weapon = nullptr;
        FreeGrip free;
        bool handle_slide = false;     // sliding along its handle this tick (axial momentum kept)
        hsvr::Vec3 vel_f, ang_f;       // the hand's velocity and spin at the point held, smoothed
        bool vel_f_set = false;
        hsvr::Vec3 handle_axis;        // that handle's line, world
        double handle_keep = 0.0;      // how much of its own motion along the line it keeps (0..1)
        bool handle_sliding_logged = false;
        double handle_damp = 0.0;      // the slide's damper along the handle (N s/m), from the trigger
        double wrist_tcap_nm = -1.0;   // the old hold's turning limit this tick with its wrist stop (N m; -1 = none)
        double shoulder_cap_n = -1.0;  // the shoulder's limit on each held point's pull this tick (N; -1 = none)
        double settle_until = -1.0;    // pulled from settle_from into the hand until then
        bool flipped = false;          // turned end for end by the grip flip (for the log)
        bool drag_capped = false;      // dragging a body by a stuck weapon with all the hand's strength
        double drag_slip_since = -1.0; // ... since when, with the grip past reach (the grip slipping)
        double settle_s = 0.0;
        hsvr::Vec3 settle_from_pos;
        hsvr::Quat settle_from_rot;
        hsvr::Vec3 last_target_pos;
        hsvr::Quat last_target_rot;
        double last_time = 0.0;
        bool have_last = false;
        bool inertia_logged = false;
        // For the log: the lag of the point held behind the controller (cm), the turn behind it
        // (deg), the hand's force (N) and torque (N m) this tick, and whether either hit its cap.
        double lag = 0.0, turn_deg = 0.0, force_n = 0.0, torque_nm = 0.0, dt = 0.0;
        bool force_capped = false, torque_capped = false;
        // The joint's frames, for placing the hand on the weapon.
        hsvr::Vec3 pivot, in_hand;
        hsvr::Quat f1, f2;
        // His hand on the weapon this frame: how far the weapon is from where the hold sent it (cm),
        // and how much of that the hand took (0 follows the controller, 1 sits on the weapon).
        double blocked_cm = 0.0, on_weapon = 0.0;
        double stuck_since = -1.0;
        double started = -1.0;        // when this hand began holding this weapon
        // Contact, from the physics' answer: where the hold sent the weapon's centre of mass last tick
        // against where it got to. Free, it gets there (within gravity's share of a step); something in
        // the way (the floor, a body, a shield) stops it short. The stuck rule needs this, so a weapon
        // that only lags (a long spear swinging up at the hand's torque limit) is never let go.
        bool have_expected = false;
        hsvr::Vec3 expected_com;
        // Where it really was last tick (measured velocity while it is stopped, pose_hold_measured_v).
        bool have_prev_pose = false;
        hsvr::Vec3 prev_com;
        hsvr::Quat prev_rot;
        double prev_t = 0.0;
        UObject* prev_item = nullptr;
        hsvr::Vec3 last_set_v, last_set_w;
        std::string last_responses;
        double miss_cm = 0.0, last_contact = -100.0;
        double self_checked_at = -1.0; // the stop the own-body check last looked at
        bool self_blocked = false;
        double last_blocked_cm = -1.0; // last tick's blocked_cm (a weapon still coming is not stuck)
        int two_turner = -1;            // two hands (B&S): which hand's joint turns it (for the log)
        const char* two_why = nullptr;
        // The slide: how far the hand has moved along the weapon (cm along its +Z from the game's grip
        // point), and the grip zone it may move in (found once per weapon).
        double slide = 0.0;
        bool zone_known = false;
        double zone_lo = 0.0, zone_hi = 0.0;
        double zone_stop = 0.0, zone_tip = 0.0; // the guard (top stop) and the tip, from the game's grip point
        double body_strength = 1.0; // the game's stats on this hand's hold (strength x injury x stamina)
        bool into_hand_tried = false; // pose_shield_in_hand looked once
        // The game's joint frames and bone, kept from the last tick it had a joint: the hold carries on
        // from these if the game's hand joint goes while the hand still holds the weapon (dismemberment).
        bool joint_frames_known = false;
        std::string kept_bone2;
        hsvr::Vec3 kept_pos1, kept_pos2, kept_pri1, kept_sec1, kept_pri2, kept_sec2;
        bool forearm = false;       // held on the forearm (strap shields: the game's joint is to the lower arm)
        std::string anchor_bone;    // the bone the game's joint holds it to
        bool sliding = false;
        double far_since = -1.0, far_logged = 0.0;
    };
    HoldState g_hold[2];
    bool hand_has_weapon(int side) { return g_hold[side].weapon != nullptr && !is_fist(g_hold[side].weapon); }
    UObject* held_weapon_of(int side) { return g_hold[side].weapon; }
    bool hand_is_fist(int side) { return is_fist(g_hold[side].weapon); }

    // The game's off-hand search: with a two-handed weapon (longswords) in one hand and the other
    // free, about once a second the game drops "Block <other> OffHand Grab", and on the next tick
    // sets "<other> Offhand Searching Grip" and re-seats the weapon (teleports BaseMesh to the hand
    // socket and back, UF @499290-@504348), all inside that one tick. Under the hold that teleport is
    // a one-tick shove across the blade (kick tests 13-14). The mod owns grips, so just before his
    // tick the gate is kept shut for a free other hand while the mod holds a weapon. A hand that holds
    // or grabs something itself is left alone.
    void block_offhand_search_before_tick(UObject* pawn)
    {
        if (!hsvr::config().pose_hold_block_offhand_search) return;
        static const TCHAR* weapon_name[2] = {STR("Weapon L"), STR("Weapon R")};
        static const TCHAR* grabbed_name[2] = {STR("Grabbed L"), STR("Grabbed R")};
        static const TCHAR* block_name[2] = {STR("Block L OffHand Grab"), STR("Block R OffHand Grab")};
        static const TCHAR* search_name[2] = {STR("L Offhand Searching Grip"), STR("R Offhand Searching Grip")};
        static bool reported[2] = {false, false};
        for (int side = 0; side < 2; ++side)
        {
            UObject* weapon = g_hold[side].weapon;
            if (!weapon || object_property(pawn, weapon_name[side]) != weapon) continue;
            int other = 1 - side;
            if (object_property(pawn, weapon_name[other]) || bool_property(pawn, grabbed_name[other])) continue;
            bool block_ok = set_bool_property(pawn, block_name[other], true);
            bool search_ok = set_bool_property(pawn, search_name[other], false);
            if (!reported[other])
            {
                reported[other] = true;
                HSVR_LOG("Hold: the game's %s off-hand search kept off while the %s hand holds a weapon (%ls %s, %ls %s)", other == 0 ? "left" : "right",
                         side == 0 ? "left" : "right", block_name[other], block_ok ? "set" : "NOT FOUND", search_name[other], search_ok ? "cleared" : "NOT FOUND");
            }
        }
    }

    double hand_on_weapon_amount(int side) { return g_hold[side].on_weapon; }

    // ---- No knockdowns for the player ------------------------------------------------------------
    // The game's kneel (Willie_BP UG @616819/@618028 Kneel Falling: a knee within ~6 cm of the floor
    // once Consciousness + All Body Tonus drops under 200 and he leans forward; UG @620739 fires Kneel
    // Event from it, from a crouch under 60 cm, or from a weak pelvis drive) is a fall for an AI body.
    // For a posed player it is a trap: while R/L Kneel is on, Legs Tonus Far Step goes to 0 when the
    // nearer foot is 1 m from Last Step Location (UG @397262), which leg tonus and Root Linear
    // Constraint Power (UG @427425) are multiplied by, and the body sinks with nothing to get it up.
    // So for the player the flags are kept off and Far Step at 1, before and after his tick. The
    // properties are found once per class; the cost is a few byte writes a tick.
    void keep_player_off_knees(UObject* pawn, bool after)
    {
        if (!pawn || !hsvr::config().pose_player_no_kneel) return;
        static UClass* looked_for = nullptr;
        static FProperty* flags[4] = {};
        static FProperty* far_step = nullptr;
        static const TCHAR* flag_names[4] = {STR("R Kneel"), STR("L Kneel"), STR("R Kneel Falling"), STR("L Kneel Falling")};
        UClass* cls = pawn->GetClassPrivate();
        if (cls != looked_for)
        {
            looked_for = cls;
            std::string missing;
            for (int i = 0; i < 4; ++i)
            {
                FProperty* p = prop_chain(pawn, flag_names[i]);
                flags[i] = p && p->GetClass().GetName() == STR("BoolProperty") ? p : nullptr;
                if (!flags[i]) { missing += " "; for (const TCHAR* c = flag_names[i]; *c; ++c) missing += (char)*c; }
            }
            FProperty* p = prop_chain(pawn, STR("Legs Tonus Far Step"));
            far_step = p && p->GetClass().GetName() == STR("DoubleProperty") ? p : nullptr;
            if (!far_step) missing += " Legs Tonus Far Step";
            HSVR_LOG("Knees: your player's kneel and kneel-fall kept off, leg tonus far-step kept at 1 (pose_player_no_kneel)%s%s",
                     missing.empty() ? "" : "; NOT FOUND:", missing.c_str());
        }
        uint8_t* base = reinterpret_cast<uint8_t*>(pawn);
        unsigned was = 0;
        for (int i = 0; i < 4; ++i)
        {
            if (!flags[i]) continue;
            auto* flag = static_cast<FBoolProperty*>(flags[i]);
            uint8_t* byte = base + flags[i]->GetOffset_Internal() + flag->GetByteOffset();
            if (*byte & flag->GetFieldMask()) was |= 1u << i;
            *byte &= (uint8_t)~flag->GetFieldMask();
        }
        double far_now = 1.0; // ("far" is a Windows macro)
        if (far_step)
        {
            double* v = reinterpret_cast<double*>(base + far_step->GetOffset_Internal());
            far_now = *v;
            *v = 1.0;
        }
        if (was || far_now < 0.999)
        {
            static double last_line = -10.0;
            static unsigned seen = 0;
            static double far_low = 1.0;
            seen |= was;
            far_low = (std::min)(far_low, far_now);
            double now = hsvr::now_seconds();
            if (now - last_line >= 1.0)
            {
                std::string names;
                for (int i = 0; i < 4; ++i)
                    if (seen & (1u << i)) { names += " "; for (const TCHAR* c = flag_names[i]; *c; ++c) names += (char)*c; }
                HSVR_LOG("Knees: the game wanted your player down (found %s his tick):%s; far-step low %.2f; kept up (Leg R Tonus %.2f, Root Linear Constraint Power %.2f)",
                         after ? "after" : "before", names.empty() ? " -" : names.c_str(), far_low, read_number_variable(pawn, STR("Leg R Tonus")),
                         read_number_variable(pawn, STR("Root Linear Constraint Power")));
                last_line = now;
                seen = 0;
                far_low = 1.0;
            }
        }
    }

    // ---- The ghost hand ------------------------------------------------------------------------
    // While his hand stays on a stopped weapon, a see-through hand shows where your real hand is
    // (Matthew's framework, rig/mod.rs: "ghosts"). The cooked game has no separate hand mesh, so it
    // is one of the game's static glove meshes with the engine's unlit translucent material
    // (ghost_hand_assets.md). Its offset and turn from the hand bone are in the ini for fitting.
    struct Ghost
    {
        UObject* pawn = nullptr;
        UObject* comp = nullptr;
        bool visible = false;
        bool failed = false;
    };
    Ghost g_ghost[2];
    std::atomic<bool> g_ghost_force{false};

    void ghost_hand(int side, const hsvr::Config& cfg, bool show, const hsvr::Vec3& wrist, const hsvr::Quat& hand_rot)
    {
        using namespace hsvr;
        Ghost& g = g_ghost[side];
        if (g.pawn != g_pose.pawn)
        {
            g = Ghost{};
            g.pawn = g_pose.pawn;
        }
        if (g_ghost_force.load()) show = true; // test: hsvr.ghost_show 1 shows it at your hand all the time
        if (!cfg.pose_ghost_hand) show = false;
        if (!g.comp && show && !g.failed && g.pawn)
        {
            g.failed = true; // tried once per character
            UClass* cls = UObjectGlobals::StaticFindObject<UClass*>(nullptr, nullptr, STR("/Script/Engine.StaticMeshComponent"));
            std::wstring mesh_path(cfg.pose_ghost_mesh.begin(), cfg.pose_ghost_mesh.end());
            std::wstring mat_path(cfg.pose_ghost_material.begin(), cfg.pose_ghost_material.end());
            UObject* mesh = load_asset_object(mesh_path);
            UObject* mat = load_asset_object(mat_path);
            if (!cls || !mesh)
            {
                HSVR_LOG("Ghost: no %ls (mesh %ls), no ghost hand", cls ? STR("mesh") : STR("StaticMeshComponent class"), mesh_path.c_str());
                return;
            }
            Call add(g.pawn, STR("AddComponentByClass"));
            add.object(STR("Class"), cls);
            add.flag(STR("bManualAttachment"), true);
            if (FProperty* t = add.param(STR("RelativeTransform")))
            {
                uint8_t* at = add.buffer.data() + t->GetOffset_Internal();
                UScriptStruct* type = struct_type(t);
                if (FProperty* r = struct_member(type, STR("Rotation")))
                    if (FProperty* w = struct_member(struct_type(r), STR("W")))
                    {
                        uint8_t* wat = at + r->GetOffset_Internal() + w->GetOffset_Internal();
                        if (w->GetClass().GetName() == STR("DoubleProperty")) *reinterpret_cast<double*>(wat) = 1.0;
                        else *reinterpret_cast<float*>(wat) = 1.0f;
                    }
                if (FProperty* sc = struct_member(type, STR("Scale3D"))) write_three(at + sc->GetOffset_Internal(), sc, 1.0, 1.0, 1.0);
            }
            add.flag(STR("bDeferredFinish"), false);
            if (!add.run() || !add.object_result())
            {
                HSVR_LOG("Ghost: could not add the ghost hand component");
                return;
            }
            UObject* c = add.object_result();
            Call sm(c, STR("SetStaticMesh"));
            sm.object(STR("NewMesh"), mesh);
            sm.run();
            Call ce(c, STR("SetCollisionEnabled"));
            ce.byte(STR("NewType"), 0);
            ce.run();
            Call cs(c, STR("SetCastShadow"));
            cs.first_flag(false);
            cs.run();
            int slots = 0;
            if (mat)
            {
                Call n(c, STR("GetNumMaterials"));
                n.run();
                slots = (std::max)(1, n.integer());
                for (int i = 0; i < slots; ++i)
                {
                    Call m(c, STR("SetMaterial"));
                    if (FProperty* ip = m.param(STR("ElementIndex"))) *reinterpret_cast<int32_t*>(m.buffer.data() + ip->GetOffset_Internal()) = i;
                    m.object(STR("Material"), mat);
                    m.run();
                }
            }
            // The left hand is the right glove mirrored.
            Call scale(c, STR("SetWorldScale3D"));
            scale.three(STR("NewScale"), cfg.pose_ghost_scale, cfg.pose_ghost_scale * (side == 0 ? -1.0 : 1.0), cfg.pose_ghost_scale);
            scale.run();
            g.comp = c;
            g.failed = false;
            HSVR_LOG("Ghost: %s ghost hand made from %ls, material %ls on %d slots", side == 0 ? "left" : "right", mesh_path.c_str(),
                     mat ? mat_path.c_str() : STR("(not found, the glove's own)"), slots);
        }
        if (!g.comp) return;
        if (show)
        {
            double out = side == 0 ? -1.0 : 1.0;
            // The glove mesh (bounds from the cooked asset, run 32): its cuff at the origin, fingers
            // along +Z, thumb toward -Y. Turned so its fingers and thumb lie along the hand bone's
            // (measured at calibration); the left glove is the right one mirrored in Y (scale -1), so
            // its thumb is toward +Y. The ini turn (pitch, yaw, roll) is applied on top, in the glove's frame.
            const ArmCalibration& a = g_pose.arm[side];
            Vec3 fingers = hand_rot.rotate(a.fingers_local), thumb = hand_rot.rotate(a.thumb_local);
            Vec3 y = side == 0 ? thumb : thumb * -1.0;
            Vec3 x = cross(y, fingers);
            Quat glove = quat_from_axes(x, y);
            Quat rot = (glove * rot_to_quat(cfg.pose_ghost_pitch, cfg.pose_ghost_yaw * out, cfg.pose_ghost_roll * out)).normalized();
            Vec3 at = wrist + hand_rot.rotate(Vec3{cfg.pose_ghost_x_cm, cfg.pose_ghost_y_cm * out, cfg.pose_ghost_z_cm});
            set_component_transform(g.comp, at, rot, true);
            Call scale_set(g.comp, STR("SetWorldScale3D"));
            scale_set.three(STR("NewScale"), cfg.pose_ghost_scale, cfg.pose_ghost_scale * (side == 0 ? -1.0 : 1.0), cfg.pose_ghost_scale);
            scale_set.run();
            static double last_log[2] = {0.0, 0.0};
            double now = now_seconds();
            if (now - last_log[side] >= 1.0 && g_pose.mesh)
            {
                last_log[side] = now;
                FName hb = bone_fname(side == 0 ? "hand_l" : "hand_r");
                Vec3 hand_at = socket_location(g_pose.mesh, hb);
                Rot hr = quat_to_rot(socket_rotation(g_pose.mesh, hb)), gr = quat_to_rot(rot), cr = quat_to_rot(hand_rot);
                Vec3 tip = at + rot.rotate(Vec3{0.0, 0.0, 20.0 * cfg.pose_ghost_scale});
                Call sc(g.comp, STR("K2_GetComponentScale"));
                sc.run();
                Vec3 scale = sc.vec();
                HSVR_LOG("Ghost: %s at (%.1f, %.1f, %.1f) rot (%.0f, %.0f, %.0f), its fingertips at (%.1f, %.1f, %.1f); your hand at (%.1f, %.1f, %.1f) "
                         "rot (%.0f, %.0f, %.0f); his hand bone at (%.1f, %.1f, %.1f) rot (%.0f, %.0f, %.0f); scale (%.2f, %.2f, %.2f)",
                         side == 0 ? "left" : "right", at.x, at.y, at.z, gr.pitch, gr.yaw, gr.roll, tip.x, tip.y, tip.z, wrist.x, wrist.y, wrist.z, cr.pitch,
                         cr.yaw, cr.roll, hand_at.x, hand_at.y, hand_at.z, hr.pitch, hr.yaw, hr.roll, scale.x, scale.y, scale.z);
            }
        }
        if (show != g.visible)
        {
            g.visible = show;
            Call v(g.comp, STR("SetVisibility"));
            v.flag(STR("bNewVisibility"), show);
            v.flag(STR("bPropagateToChildren"), true);
            v.run();
            Call h(g.comp, STR("SetHiddenInGame"));
            h.flag(STR("NewHidden"), !show);
            h.flag(STR("bPropagateToChildren"), true);
            h.run();
        }
    }

    // Lets go of the weapon in that hand the game's own way: Set Up Right/Left Hand Weapon with no
    // weapon and "Dropped With no Damage" (decompile: what the game's tap on grab does; it breaks the
    // hand joint, detaches the weapon and gives it its dropped damping).
    bool is_fist(UObject* weapon);
    bool holster_snap(int side, UObject* pawn, UObject* mesh, UObject* w, const hsvr::Config& cfg);
    UObject* scabbard_pin(UObject* scab);
    void return_scabbard_pin(UObject* pawn, UObject* scab, bool free);
    void pin_angular_limit(UObject* pin, const TCHAR* fn, uint8_t motion, double degrees);
    void remove_fist(int side, UObject* pawn, const char* why);
    // A throw (B&S: released faster than 2 m/s): the game counts an unheld weapon's hits only while its
    // "Just Thrown" is set and "Last Parent" is the thrower (ModularWeaponBP @67055; hs_throwing.md),
    // which Set Up Hand Weapon sets from "Dropped With no Damage" == false. Its flight is its own (the
    // game adds nothing); B&S doubles the release velocity. The game clears Just Thrown only after a
    // hit, so the mod clears it when the throw lands or misses, and keeps Last Parent while it flies
    // (the game drops it beyond 3 m).
    struct Thrown
    {
        UObject* weapon = nullptr;
        UObject* base = nullptr;
        double t0 = 0.0;
    };
    std::vector<Thrown> g_thrown;

    // The held weapon's centre of mass over the last ticks (time, position), for a throw's speed: the
    // physics' own velocity on the release tick is whatever the hold last set, which can be a large
    // catch-up (playtest 11:25: 40.1 m/s from a 2.2 m/s hand = the B&S solver's 20 m/s clamp x2).
    struct ComSample { double t; hsvr::Vec3 p; UObject* weapon; };
    ComSample g_com_hist[2][8];
    int g_com_head[2] = {0, 0};
    void note_com(int side, UObject* weapon, const hsvr::Vec3& p)
    {
        g_com_hist[side][g_com_head[side]] = ComSample{hsvr::now_seconds(), p, weapon};
        g_com_head[side] = (g_com_head[side] + 1) % 8;
    }
    // Its velocity over about the last 60 ms (false when there is too little history for it).
    bool recent_com_velocity(int side, UObject* weapon, hsvr::Vec3& v)
    {
        int newest = (g_com_head[side] + 7) % 8;
        const ComSample& a = g_com_hist[side][newest];
        if (a.weapon != weapon) return false;
        for (int k = 1; k < 8; ++k)
        {
            const ComSample& b = g_com_hist[side][(newest - k + 8) % 8];
            if (b.weapon != weapon || b.t <= 0.0) return false;
            if (a.t - b.t >= 0.06 || k == 7)
            {
                if (a.t - b.t < 1e-3) return false;
                v = (a.p - b.p) * (1.0 / (a.t - b.t));
                return true;
            }
        }
        return false;
    }

    // The item each hand last let go of, until the hand's fist ball is clear of it (make_fist). Matthew's
    // playtest 2026-11-23 ("anytime I let go of a shield, it just jolts out of my hand"): his fingers stay
    // curled as the grip opens, so the hand became a fist 2 ms after the drop, and the fist's 13 cm physics
    // ball was made inside the shield and shoved it away (log 400.143 -> 400.145, buckler at the hand).
    struct JustDropped
    {
        UObject* item = nullptr;
        double at = -10.0;
    };
    JustDropped g_just_dropped[2];
    bool g_just_dropped_tracked = track_freed(&g_just_dropped[0].item) && track_freed(&g_just_dropped[1].item);

    // For 0.5 s after a hand lets go of an item, where it goes (drop_trace): the most its centre of mass
    // moved sideways (x/y, so falling is left out) off the path its own velocity at the let-go gives it,
    // in the first 0.3 s, for hsvr.expect drop_xy_l / drop_xy_r.
    struct DropTrace
    {
        UObject* item = nullptr;
        UObject* base = nullptr;
        double t0 = -10.0;
        hsvr::Vec3 p0{};   // its centre of mass at the let-go
        hsvr::Vec3 b0{};   // BaseMesh (the grip dummy) at the let-go
        double max_xy = 0.0;      // centre of mass, off the path its own velocity would take it
        double max_base_xy = 0.0; // the grip dummy, plain (it swings with any spin)
        double max_xy_all = 0.0;  // centre of mass off its own path over the whole trace (0.5 s)
        double next_log = 0.0;
        hsvr::Vec3 v0{};   // its own velocity over the last ~60 ms in the hand (recent_com_velocity)
        bool have_v0 = false;
        bool thrown = false;
        int kept = 0;      // ticks its velocity was put back
    };
    DropTrace g_drop_trace[2];
    bool g_drop_trace_tracked = track_freed(&g_drop_trace[0].item) && track_freed(&g_drop_trace[0].base) && track_freed(&g_drop_trace[1].item) &&
                                track_freed(&g_drop_trace[1].base);
    hsvr::Vec3 component_location(UObject* component);

    void drop_trace_start(int side, UObject* item, bool thrown, const hsvr::Vec3& v0, bool have_v0)
    {
        DropTrace& d = g_drop_trace[side];
        d = DropTrace{};
        d.item = item;
        d.base = item ? object_property(item, STR("BaseMesh")) : nullptr;
        if (!d.base) return;
        d.t0 = hsvr::now_seconds();
        d.b0 = component_location(d.base);
        Call cm(d.base, STR("GetCenterOfMass"));
        d.p0 = cm.run() ? cm.vec() : d.b0;
        d.thrown = thrown;
        d.v0 = v0;
        d.have_v0 = have_v0;
        Call av(d.base, STR("GetPhysicsAngularVelocityInRadians"));
        hsvr::Vec3 w = av.run() ? av.vec() : hsvr::Vec3{};
        HSVR_LOG("Drop trace 0.000 s: %ls let go: own velocity %.0f cm/s (%s), spin %.2f rad/s, centre of mass %.1f cm from the grip", item->GetName().c_str(),
                 hsvr::length(v0), have_v0 ? "measured" : "unknown", hsvr::length(w), hsvr::length(d.p0 - d.b0));
    }

    // For 0.3 s after a let-go item collides with him again: a sideways speed jump of more than 2 m/s in a
    // tick is his body pushing out an item it found inside it, not a fall: the sideways speed and the spin
    // are put back as they were (PC run 55b88f3: a light pavise flung 11 m, 63 rad/s, as its pairs went).
    struct ResumeGuard
    {
        UObject* item = nullptr;
        UObject* base = nullptr;
        double t0 = 0.0;
        hsvr::Vec3 v{}, w{};
        int capped = 0;
    };
    ResumeGuard g_resume[2];
    bool g_resume_tracked = on_freed([] {
        for (ResumeGuard& r : g_resume)
            if (gone(r.item) || gone(r.base)) r = ResumeGuard{};
    });
    void drop_resume_guard(int side, UObject* item)
    {
        ResumeGuard& r = g_resume[side];
        r = ResumeGuard{};
        if (!hsvr::config().pose_drop_keep_velocity || !item) return;
        r.base = object_property(item, STR("BaseMesh"));
        if (!r.base) return;
        // Not for an item of several bodies (a chain lantern: lamp and links hang on constraints, outside BaseMesh's tree). Its
        // holder's speed jumps from its own chain's pull, and holding the holder to its old speed tick after tick fought the chain:
        // run 23 floor_pickup_62_b, 8 put-backs of 215-688 cm/s with no touch of his logged, then BaseMesh hit Link 1 at 1149 and
        // the lantern went 5.2 m/s and 3 m away.
        {
            std::vector<UObject*> tree, scab;
            attached_meshes(r.base, nullptr, tree, 0);
            attached_meshes(object_property(item, STR("Scabbard")), nullptr, scab, 0);
            for (UObject* c : static_parts_of(item))
                if (std::find(tree.begin(), tree.end(), c) == tree.end() && std::find(scab.begin(), scab.end(), c) == scab.end())
                {
                    static UObject* said = nullptr;
                    if (said != item) HSVR_LOG("Drop: %ls has bodies of its own (%ls): its speed is not put back", item->GetName().c_str(), c->GetName().c_str());
                    said = item;
                    r = ResumeGuard{};
                    return;
                }
        }
        r.item = item;
        r.t0 = hsvr::now_seconds();
        Call lv(r.base, STR("GetPhysicsLinearVelocity"));
        r.v = lv.run() ? lv.vec() : hsvr::Vec3{};
        Call av(r.base, STR("GetPhysicsAngularVelocityInRadians"));
        r.w = av.run() ? av.vec() : hsvr::Vec3{};
    }
    void resume_guard_tick(UObject* pawn)
    {
        for (int side = 0; side < 2; ++side)
        {
            ResumeGuard& r = g_resume[side];
            if (!r.item) continue;
            double age = hsvr::now_seconds() - r.t0;
            if (age > 0.3 || !object_alive(r.item) || object_property(pawn, STR("Weapon L")) == r.item || object_property(pawn, STR("Weapon R")) == r.item)
            {
                if (r.capped) HSVR_LOG("Drop: %ls: pushed by your body as it collided again; put back %d tick(s)", r.item && object_alive(r.item) ? r.item->GetName().c_str() : STR("item"), r.capped);
                r = ResumeGuard{};
                continue;
            }
            Call lv(r.base, STR("GetPhysicsLinearVelocity"));
            hsvr::Vec3 v = lv.run() ? lv.vec() : r.v;
            Call av(r.base, STR("GetPhysicsAngularVelocityInRadians"));
            hsvr::Vec3 w = av.run() ? av.vec() : r.w;
            double jump = std::sqrt((v.x - r.v.x) * (v.x - r.v.x) + (v.y - r.v.y) * (v.y - r.v.y));
            if (jump > 200.0)
            {
                hsvr::Vec3 keep{r.v.x, r.v.y, v.z};
                Call slv(r.base, STR("SetPhysicsLinearVelocity"));
                slv.three(STR("NewVel"), keep.x, keep.y, keep.z);
                slv.flag(STR("bAddToCurrent"), false);
                slv.run();
                Call sav(r.base, STR("SetPhysicsAngularVelocityInRadians"));
                sav.three(STR("NewAngVel"), r.w.x, r.w.y, r.w.z);
                sav.flag(STR("bAddToCurrent"), false);
                sav.run();
                ++r.capped;
                HSVR_LOG("Drop %.3f s after colliding again: %ls given %.0f cm/s sideways by your body, spin %.1f rad/s: put back", age, r.item->GetName().c_str(), jump,
                         hsvr::length(w));
                v = keep;
                w = r.w;
            }
            r.v = v;
            r.w = w;
        }
    }

    void drop_trace(UObject* pawn)
    {
        resume_guard_tick(pawn);
        for (int side = 0; side < 2; ++side)
        {
            DropTrace& d = g_drop_trace[side];
            if (!d.base) continue;
            double age = hsvr::now_seconds() - d.t0;
            if (age > 0.5 || !object_alive(d.item) || object_property(pawn, STR("Weapon L")) == d.item || object_property(pawn, STR("Weapon R")) == d.item)
            {
                HSVR_LOG("Drop trace: %s hand's %ls: centre of mass at most %.1f cm sideways off its own path in its first 0.3 s, %.1f in 0.5 s (grip dummy %.1f cm plain)",
                         side == 0 ? "left" : "right", d.item && object_alive(d.item) ? d.item->GetName().c_str() : STR("item"), d.max_xy, d.max_xy_all, d.max_base_xy);
                d.base = nullptr;
                continue;
            }
            // A let-go (not a throw) leaves with the item's own velocity from the hand and then falls. PC run
            // f2e499f: a shield let go from a still hand left at ~4 m/s in the release tick (22-56 cm sideways
            // in 0.3 s, with or without the fist), the hold's joint just gone. For 0.15 s, a velocity more than
            // 1 m/s off that is put back (and its spin stopped).
            if (hsvr::config().pose_drop_keep_velocity && !d.thrown && d.have_v0 && age <= 0.15)
            {
                Call lv(d.base, STR("GetPhysicsLinearVelocity"));
                lv.run();
                hsvr::Vec3 v = lv.vec(), want = d.v0 + hsvr::Vec3{0, 0, -980.0 * age};
                if (hsvr::length(v - want) > 100.0)
                {
                    Call slv(d.base, STR("SetPhysicsLinearVelocity"));
                    slv.three(STR("NewVel"), want.x, want.y, want.z);
                    slv.flag(STR("bAddToCurrent"), false);
                    slv.run();
                    Call sav(d.base, STR("SetPhysicsAngularVelocityInRadians"));
                    sav.three(STR("NewAngVel"), 0.0, 0.0, 0.0);
                    sav.flag(STR("bAddToCurrent"), false);
                    sav.run();
                    ++d.kept;
                    HSVR_LOG("Drop trace %.3f s: %s hand's %ls was given %.0f cm/s at the let-go (its own %.0f): put back", age, side == 0 ? "left" : "right",
                             d.item->GetName().c_str(), hsvr::length(v), hsvr::length(d.v0));
                }
            }
            // Judged by the centre of mass against the path its own velocity at the let-go gives it: a tall
            // shield tips as it falls, so its grip dummy (at the strap, off the centre) drifts 3-4 cm with no
            // push at all (PC run 559ae80, light Pavise: smooth 11-18 cm/s, z at free fall, no step).
            Call cm(d.base, STR("GetCenterOfMass"));
            hsvr::Vec3 c = cm.run() ? cm.vec() : component_location(d.base);
            hsvr::Vec3 own = d.have_v0 && !d.thrown ? d.v0 * age : hsvr::Vec3{};
            hsvr::Vec3 m = c - d.p0 - own;
            double xy = std::sqrt(m.x * m.x + m.y * m.y);
            hsvr::Vec3 mb = component_location(d.base) - d.b0;
            double bxy = std::sqrt(mb.x * mb.x + mb.y * mb.y);
            if (age <= 0.3) d.max_xy = (std::max)(d.max_xy, xy), d.max_base_xy = (std::max)(d.max_base_xy, bxy);
            d.max_xy_all = (std::max)(d.max_xy_all, xy);
            if (age >= d.next_log)
            {
                d.next_log = age + 0.05;
                Call av(d.base, STR("GetPhysicsAngularVelocityInRadians"));
                double spin = av.run() ? hsvr::length(av.vec()) : -1.0;
                HSVR_LOG("Drop trace %.3f s: %s hand's %ls centre of mass off its own path (%.1f, %.1f, %.1f) cm, %.1f sideways; grip dummy %.1f sideways; spin %.2f rad/s",
                         age, side == 0 ? "left" : "right", d.item->GetName().c_str(), m.x, m.y, c.z - d.p0.z, xy, bxy, spin);
            }
        }
    }

    void jh_release_for_drop(int side, UObject* w);
    // loose: a plain let-go into the world (grab_button), not a hand-over, hang or mount: only then is the
    // item's own velocity kept (pose_drop_keep_velocity).
    void drop_weapon(int side, UObject* pawn, bool thrown = false, bool loose = false)
    {
        UObject* held = pawn ? object_property(pawn, side == 0 ? STR("Weapon L") : STR("Weapon R")) : nullptr;
        // A fist is not a weapon to drop: it goes.
        if (is_fist(object_property(pawn, side == 0 ? STR("Weapon L") : STR("Weapon R"))))
        {
            remove_fist(side, pawn, "dropped");
            return;
        }
        const TCHAR* name = side == 0 ? STR("Set Up Left Hand Weapon") : STR("Set Up Right Hand Weapon");
        UFunction* fn = pawn ? func_chain(pawn, name) : nullptr;
        if (!fn)
        {
            HSVR_LOG("Hold: no \"%ls\" on the character, the weapon is not dropped", name);
            return;
        }
        // Sized from the function. The fixed 4096-byte static block this replaced was overrun: the
        // hand position written for the fist landed on the grab button's state (fist-eat test 4).
        std::vector<uint8_t> block = param_block(fn);
        uint8_t* parameters = block.data();
        std::wstring names;
        for (FProperty* p : fn->ForEachProperty())
        {
            std::wstring n = p->GetName();
            names += n + STR(", ");
            if (n.find(STR("Dropped")) != std::wstring::npos && p->GetClass().GetName() == STR("BoolProperty") && !thrown)
            {
                auto* flag = static_cast<FBoolProperty*>(p);
                parameters[p->GetOffset_Internal() + flag->GetByteOffset()] |= flag->GetFieldMask();
            }
            // A transform parameter gets a valid (identity) rotation and scale 1, in case it is read.
            if (p->GetClass().GetName() == STR("StructProperty"))
                if (UScriptStruct* type = struct_type(p))
                {
                    uint8_t* at = parameters + p->GetOffset_Internal();
                    if (FProperty* r = struct_member(type, STR("Rotation")))
                        if (FProperty* w = struct_member(struct_type(r), STR("W")))
                        {
                            uint8_t* wat = at + r->GetOffset_Internal() + w->GetOffset_Internal();
                            if (w->GetClass().GetName() == STR("DoubleProperty")) *reinterpret_cast<double*>(wat) = 1.0;
                            else *reinterpret_cast<float*>(wat) = 1.0f;
                        }
                    if (FProperty* sc = struct_member(type, STR("Scale3D"))) write_three(at + sc->GetOffset_Internal(), sc, 1.0, 1.0, 1.0);
                }
        }
        // B&S: a holster stays on the body when its item is dropped. The game's release takes a drawn
        // weapon's scabbard off the belt (Set Up <S> Hand Weapon @11946-@13481: it destroys the scabbard's
        // pelvis pin when the slot's scabbard is the released weapon's), also on the mod's hand-overs. Its
        // Scabbard reference is hidden from that check for the call and put back after.
        UObject* kept_scab = nullptr;
        FProperty* scab_prop = held ? prop_chain(held, STR("Scabbard")) : nullptr;
        if (hsvr::config().pose_keep_scabbard_on_drop && scab_prop && scab_prop->GetClass().GetName() == STR("ObjectProperty"))
        {
            UObject** slot = reinterpret_cast<UObject**>(reinterpret_cast<uint8_t*>(held) + scab_prop->GetOffset_Internal());
            if (*slot && scabbard_pin(*slot))
            {
                kept_scab = *slot;
                *slot = nullptr;
            }
        }
        hsvr::Vec3 v_before{};
        bool have_v = held && recent_com_velocity(side, held, v_before);
        if (held && hsvr::config().pose_drop_joint_first) jh_release_for_drop(side, held);
        if (held && loose && !thrown && g_arm_ignore[side].weapon == held)
        {
            g_arm_ignore[side].dropped_at = hsvr::now_seconds();
            if (hsvr::config().pose_drop_ignore_s > 0.0) drop_cm_pairs(side, pawn, held);
        }
        pawn->ProcessEvent(fn, parameters);
        if (held)
        {
            g_just_dropped[side] = JustDropped{held, hsvr::now_seconds()};
            drop_trace_start(side, held, thrown || !loose, v_before, have_v);
        }
        if (kept_scab)
        {
            *reinterpret_cast<UObject**>(reinterpret_cast<uint8_t*>(held) + scab_prop->GetOffset_Internal()) = kept_scab;
            HSVR_LOG("Hold: %ls's scabbard kept on the belt (%s)", held->GetName().c_str(), scabbard_pin(kept_scab) ? "still pinned" : "its pin is GONE anyway");
        }
        g_hold[side] = HoldState{}; // a new hold (and slide) when anything is next held
        g_grip_log[side] = GripLog{}; // its 0.5 s "Grip:" line stops with the hold
        HSVR_LOG("Hold: dropped with %ls(%ls)%s", name, names.c_str(), thrown ? " as a throw" : "");
        if (thrown && held)
        {
            using namespace hsvr;
            const Config& cfg = hsvr::config();
            UObject* base = object_property(held, STR("BaseMesh"));
            if (!object_property(held, STR("Last Parent"))) set_variable(held, STR("Last Parent"), 0.0, pawn, nullptr);
            Vec3 v{};
            if (base)
            {
                Call lv(base, STR("GetPhysicsLinearVelocity"));
                lv.run();
                v = lv.vec();
                Vec3 mv;
                bool measured = recent_com_velocity(side, held, mv);
                if (measured)
                {
                    HSVR_LOG("Throw: %s hand's weapon moved at %.1f m/s over the last ticks (the physics had %.1f)", side == 0 ? "left" : "right", length(mv) / 100.0,
                             length(v) / 100.0);
                    v = mv;
                }
                if (cfg.pose_throw_multiplier != 1.0 || measured)
                {
                    Vec3 nv = v * cfg.pose_throw_multiplier;
                    Call slv(base, STR("SetPhysicsLinearVelocity"));
                    slv.three(STR("NewVel"), nv.x, nv.y, nv.z);
                    slv.flag(STR("bAddToCurrent"), false);
                    slv.run();
                }
            }
            g_thrown.push_back(Thrown{held, base, now_seconds()});
            HSVR_LOG("Throw: %s hand throws %ls at %.1f m/s (hand %.1f m/s, x%.1f); Just Thrown %d, Last Parent %s", side == 0 ? "left" : "right",
                     held->GetName().c_str(), length(v) * cfg.pose_throw_multiplier / 100.0, g_hand_world_v[side], cfg.pose_throw_multiplier,
                     (int)bool_property(held, STR("Just Thrown")), object_property(held, STR("Last Parent")) == pawn ? "you" : "NOT you");
        }
    }

    void thrown_tick(UObject* pawn)
    {
        using namespace hsvr;
        double now = now_seconds();
        for (size_t i = 0; i < g_thrown.size();)
        {
            Thrown& t = g_thrown[i];
            bool done = !t.weapon || !t.base || now - t.t0 > 4.0;
            bool held = false;
            if (!done)
                for (const TCHAR* slot : {STR("Weapon L"), STR("Weapon R")}) held = held || object_property(pawn, slot) == t.weapon;
            double speed = 0.0;
            if (!done && !held)
            {
                Call lv(t.base, STR("GetPhysicsLinearVelocity"));
                lv.run();
                speed = length(lv.vec());
                if (now - t.t0 > 0.3 && speed < 150.0) done = true; // landed or stopped
                else if (bool_property(t.weapon, STR("Just Thrown")) && object_property(t.weapon, STR("Last Parent")) != pawn)
                    set_variable(t.weapon, STR("Last Parent"), 0.0, pawn, nullptr);
            }
            if (done || held)
            {
                if (t.weapon && !held && bool_property(t.weapon, STR("Just Thrown"))) set_bool_property(t.weapon, STR("Just Thrown"), false);
                if (t.weapon) HSVR_LOG("Throw: %ls %s after %.2f s", t.weapon->GetName().c_str(), held ? "caught" : "landed", now - t.t0);
                g_thrown.erase(g_thrown.begin() + i);
                continue;
            }
            ++i;
        }
    }

    // Puts a weapon lying in the world into that hand the game's own way: Set Up Right/Left Hand
    // Weapon(no class, the weapon, not dropped, don't destroy, empty passport, save) - the call the
    // game's grab makes once its hand reaches a ModularWeaponBP (grab_pickup.md, UF @523466 / @535604).
    // It snaps the weapon's "Grip R Hand Default Pos" onto the hand socket and makes the hand joint.
    bool give_hand_weapon(int side, UObject* pawn, UObject* weapon)
    {
        const TCHAR* name = side == 0 ? STR("Set Up Left Hand Weapon") : STR("Set Up Right Hand Weapon");
        UFunction* fn = pawn ? func_chain(pawn, name) : nullptr;
        if (!fn || !weapon) return false;
        // Sized from the function. The fixed 4096-byte static block this replaced was overrun: the
        // hand position written for the fist landed on the grab button's state (fist-eat test 4).
        std::vector<uint8_t> block = param_block(fn);
        uint8_t* parameters = block.data();
        bool set = false;
        for (FProperty* p : fn->ForEachProperty())
        {
            if (p->GetClass().GetName() == STR("ObjectProperty") && !set)
            {
                *reinterpret_cast<UObject**>(parameters + p->GetOffset_Internal()) = weapon;
                set = true;
            }
            if (p->GetClass().GetName() == STR("StructProperty"))
                if (UScriptStruct* type = struct_type(p))
                {
                    uint8_t* at = parameters + p->GetOffset_Internal();
                    if (FProperty* r = struct_member(type, STR("Rotation")))
                        if (FProperty* w = struct_member(struct_type(r), STR("W")))
                        {
                            uint8_t* wat = at + r->GetOffset_Internal() + w->GetOffset_Internal();
                            if (w->GetClass().GetName() == STR("DoubleProperty")) *reinterpret_cast<double*>(wat) = 1.0;
                            else *reinterpret_cast<float*>(wat) = 1.0f;
                        }
                    if (FProperty* sc = struct_member(type, STR("Scale3D"))) write_three(at + sc->GetOffset_Internal(), sc, 1.0, 1.0, 1.0);
                }
        }
        if (!set) return false;
        pawn->ProcessEvent(fn, parameters);
        g_hold[side] = HoldState{};
        return true;
    }

    // Where a weapon would sit in that hand: the hand socket the game snaps weapons to, else the bone.
    hsvr::Vec3 hand_grab_point(UObject* mesh, int side)
    {
        static const FName sockets[2] = {FName(STR("weapon_lSocket"), FNAME_Add), FName(STR("weapon_rSocket"), FNAME_Add)};
        Call has(mesh, STR("DoesSocketExist"));
        has.name(STR("InSocketName"), sockets[side]);
        has.run();
        FProperty* rp = has.param(STR("ReturnValue"));
        bool exists = rp && *(has.buffer.data() + rp->GetOffset_Internal()) != 0;
        return socket_location(mesh, exists ? sockets[side] : bone_fname(side == 0 ? "hand_l" : "hand_r"));
    }

    // Test (hsvr.weapon_dump): everything about the weapon in a hand that shapes its grip zones, in
    // its BaseMesh's frame (cm; the blade is along +Z): every component of the weapon (class, tags,
    // origin, local bounds), the BaseMesh's sockets, the hand joint's weapon point (Pos1), and every
    // number variable with "Length" in its name. Facts for the slide's zones, not guesses.
    void weapon_dump(int side, UObject* pawn)
    {
        using namespace hsvr;
        UObject* weapon = object_property(pawn, side == 0 ? STR("Weapon L") : STR("Weapon R"));
        UObject* base = object_property(weapon, STR("BaseMesh"));
        if (!base)
        {
            HSVR_LOG("Dump: no weapon in the %s hand", side == 0 ? "left" : "right");
            return;
        }
        Vec3 bp = component_location(base);
        Quat bq = component_rotation(base);
        Quat binv = bq.inverse();
        auto local = [&](const Vec3& w) { return binv.rotate(w - bp); };
        HSVR_LOG("Dump: %ls (class %ls), BaseMesh %ls", weapon->GetFullName().c_str(), weapon->GetClassPrivate()->GetName().c_str(), base->GetFullName().c_str());
        // The weapon in the hand bone's frame (for checking that the left mirrors the right).
        if (UObject* mesh = find_pawn_mesh())
        {
            FName hb = bone_fname(side == 0 ? "hand_l" : "hand_r");
            Vec3 hp = socket_location(mesh, hb);
            Quat hq = socket_rotation(mesh, hb);
            Vec3 at = hq.inverse().rotate(bp - hp);
            Quat q = (hq.inverse() * bq).normalized();
            Vec3 bx = q.rotate(Vec3{1, 0, 0}), bz = q.rotate(Vec3{0, 0, 1});
            HSVR_LOG("Dump: BaseMesh in the %s hand bone's frame: at (%.1f, %.1f, %.1f) cm, its X axis (%.2f, %.2f, %.2f), its Z axis (blade) (%.2f, %.2f, %.2f)",
                     side == 0 ? "left" : "right", at.x, at.y, at.z, bx.x, bx.y, bx.z, bz.x, bz.y, bz.z);
        }
        for (UStruct* level = weapon->GetClassPrivate(); level; level = level->GetSuperStruct())
            for (FProperty* p : level->ForEachProperty())
            {
                std::wstring n = p->GetName();
                auto kind = p->GetClass().GetName();
                if (n.find(STR("Length")) != std::wstring::npos && (kind == STR("DoubleProperty") || kind == STR("FloatProperty")))
                    HSVR_LOG("Dump:   var %ls = %.2f", n.c_str(), number_property(weapon, p));
            }
        std::vector<UObject*> comps;
        UObjectGlobals::FindAllOf(STR("SceneComponent"), comps);
        for (UObject* c : comps)
        {
            if (!c || c->GetOuterPrivate() != weapon) continue;
            Vec3 o = local(component_location(c));
            std::wstring tags;
            if (RawArray* t = value_ptr<RawArray>(c, STR("ComponentTags")))
                for (int32_t i = 0; i < t->Num && t->Data; ++i) tags += reinterpret_cast<const FName*>(t->Data)[i].ToString() + STR(" ");
            double lo = 0, hi = 0;
            bool have_bounds = false;
            Call lb(c, STR("GetLocalBounds"));
            if (lb.fn && lb.run())
            {
                // Local bounds are in the component's own frame; take their Z ends along the BaseMesh axis.
                Vec3 mn = lb.vec(STR("Min")), mx = lb.vec(STR("Max"));
                Quat cq = component_rotation(c);
                Vec3 cp = component_location(c);
                double zs[8];
                for (int k = 0; k < 8; ++k)
                {
                    Vec3 corner{(k & 1) ? mx.x : mn.x, (k & 2) ? mx.y : mn.y, (k & 4) ? mx.z : mn.z};
                    zs[k] = local(cp + cq.rotate(corner)).z;
                }
                lo = *std::min_element(zs, zs + 8);
                hi = *std::max_element(zs, zs + 8);
                have_bounds = true;
            }
            std::wstring span = have_bounds ? STR(", z ") + std::to_wstring(lo) + STR(" .. ") + std::to_wstring(hi) : std::wstring();
            // Physics of a primitive: simulating, its mass (kg, its own body; welded ones are in their root's),
            // and what it is attached to (a dangling chain's links pull on what holds them).
            std::wstring phys;
            if (func_chain(c, STR("GetMass")))
            {
                Call sim(c, STR("IsSimulatingPhysics"));
                sim.name(STR("BoneName"), FName(STR("None"), FNAME_Add));
                sim.run();
                FProperty* sp = sim.param(STR("ReturnValue"));
                bool simulating = sp && *(sim.buffer.data() + sp->GetOffset_Internal());
                Call gm(c, STR("GetMass"));
                gm.run();
                Call ce(c, STR("GetCollisionEnabled"));
                ce.run();
                FProperty* cr = ce.param(STR("ReturnValue"));
                int coll = cr ? *(ce.buffer.data() + cr->GetOffset_Internal()) : -1;
                wchar_t buf[96];
                swprintf(buf, 96, L", sim %d mass %.2f kg collision %d", simulating ? 1 : 0, gm.number(), coll);
                phys = buf;
            }
            if (UObject* parent = object_property(c, STR("AttachParent"))) phys += STR(", on ") + parent->GetName();
            HSVR_LOG("Dump:   comp %ls (%ls) at %.1f %.1f %.1f%ls%ls tags [%ls]", c->GetName().c_str(), c->GetClassPrivate()->GetName().c_str(), o.x, o.y, o.z,
                     span.c_str(), phys.c_str(), tags.c_str());
            // A joint: what it joins (an empty name is the world: a tether), and its limits.
            if (c->GetClassPrivate()->GetName().find(STR("PhysicsConstraint")) != std::wstring::npos)
                HSVR_LOG("Dump:     joint %ls joins '%s' bone '%s' to '%s' bone '%s'; linear motion %.0f/%.0f/%.0f limit %.1f, swing %.0f/%.0f twist %.0f (0 free, 1 limited, 2 locked)", c->GetName().c_str(),
                         nested_name(c, {STR("ComponentName1"), STR("ComponentName")}).c_str(), nested_name(c, {STR("ConstraintInstance"), STR("ConstraintBone1")}).c_str(),
                         nested_name(c, {STR("ComponentName2"), STR("ComponentName")}).c_str(), nested_name(c, {STR("ConstraintInstance"), STR("ConstraintBone2")}).c_str(),
                         nested_number(c, {STR("ConstraintInstance"), STR("ProfileInstance"), STR("LinearLimit"), STR("XMotion")}),
                         nested_number(c, {STR("ConstraintInstance"), STR("ProfileInstance"), STR("LinearLimit"), STR("YMotion")}),
                         nested_number(c, {STR("ConstraintInstance"), STR("ProfileInstance"), STR("LinearLimit"), STR("ZMotion")}),
                         nested_number(c, {STR("ConstraintInstance"), STR("ProfileInstance"), STR("LinearLimit"), STR("Limit")}),
                         nested_number(c, {STR("ConstraintInstance"), STR("ProfileInstance"), STR("ConeLimit"), STR("Swing1Motion")}),
                         nested_number(c, {STR("ConstraintInstance"), STR("ProfileInstance"), STR("ConeLimit"), STR("Swing2Motion")}),
                         nested_number(c, {STR("ConstraintInstance"), STR("ProfileInstance"), STR("TwistLimit"), STR("TwistMotion")}));
        }
        Call sn(base, STR("GetAllSocketNames"));
        if (sn.run())
            if (FProperty* rp = sn.param(STR("ReturnValue")))
            {
                RawArray* names = reinterpret_cast<RawArray*>(sn.buffer.data() + rp->GetOffset_Internal());
                for (int32_t i = 0; i < names->Num && names->Data; ++i)
                {
                    FName n = reinterpret_cast<const FName*>(names->Data)[i];
                    Vec3 at = local(socket_location(base, n));
                    HSVR_LOG("Dump:   socket %ls at %.1f %.1f %.1f", n.ToString().c_str(), at.x, at.y, at.z);
                }
                names->Data = nullptr; // the engine's list; left
                names->Num = names->Max = 0;
            }
        HoldState& h = g_hold[side];
        if (h.weapon == weapon) HSVR_LOG("Dump:   hand joint weapon point (Pos1) %.1f %.1f %.1f", h.pivot.x, h.pivot.y, h.pivot.z);
        Call ext(base, STR("GetLocalBounds"));
        if (ext.run())
        {
            Vec3 mn = ext.vec(STR("Min")), mx = ext.vec(STR("Max"));
            HSVR_LOG("Dump:   BaseMesh local bounds %.1f %.1f %.1f .. %.1f %.1f %.1f", mn.x, mn.y, mn.z, mx.x, mx.y, mx.z);
        }
    }

    // Writes a Blueprint variable of the character by name: a number, yes/no, object or name. False
    // (and the name logged by the caller) if it has no such variable of a fitting kind.
    bool set_variable(UObject* owner, const TCHAR* name, double number, UObject* object = nullptr, const FName* fname = nullptr)
    {
        if (!owner) return false;
        FProperty* p = prop_chain(owner, name);
        if (!p) return false;
        uint8_t* at = reinterpret_cast<uint8_t*>(owner) + p->GetOffset_Internal();
        auto kind = p->GetClass().GetName();
        if (kind == STR("DoubleProperty")) *reinterpret_cast<double*>(at) = number;
        else if (kind == STR("FloatProperty")) *reinterpret_cast<float*>(at) = (float)number;
        else if (kind == STR("IntProperty")) *reinterpret_cast<int32_t*>(at) = (int32_t)number;
        else if (kind == STR("ByteProperty") || kind == STR("EnumProperty")) *at = (uint8_t)number;
        else if (kind == STR("BoolProperty")) return set_bool_property(owner, name, number != 0.0);
        else if (kind == STR("ObjectProperty")) *reinterpret_cast<UObject**>(at) = object;
        else if (kind == STR("NameProperty") && fname) *reinterpret_cast<FName*>(at) = *fname;
        else return false;
        return true;
    }

    // Is the object's class, or one it is built on, named `class_name` (e.g. ModularWeaponBP_C)?


    // Does a list of names (actor Tags / ComponentTags) hold this one?
    bool has_tag(UObject* owner, const TCHAR* list, const TCHAR* tag)
    {
        if (!owner) return false;
        RawArray* tags = value_ptr<RawArray>(owner, list);
        if (!tags || !tags->Data) return false;
        std::wstring want(tag);
        const FName* names = reinterpret_cast<const FName*>(tags->Data);
        for (int32_t i = 0; i < tags->Num; ++i)
            if (names[i].ToString() == want) return true;
        return false;
    }

    // An object or body grab in progress: handed to the game's own latch, checked a few ticks later.
    struct ObjectGrab
    {
        UObject* component = nullptr;
        FName bone;
        hsvr::Vec3 point{0, 0, 0};
        bool character = false;
        double since = -1.0;
        bool fallback_tried = false;
    };
    ObjectGrab g_object_grab[2];
    // Fixed scenery held in a hand (pose_grab_world): no game grab; the mod pins the drawn hand on it.
    struct WorldGrab
    {
        bool on = false;
        UObject* comp = nullptr;
        hsvr::Vec3 point{0, 0, 0};
        double since = -1.0;
    };
    WorldGrab g_world[2];
    bool g_wrap_on_side(int side); // (defined with the wrap)
    // The hand holds an object, a body or scenery, or has just asked the game to (its fist must wait).
    bool mount_gripped(int side);
    bool xbow_string_in_hand(int side); // that hand holds a crossbow's string
    bool hand_holds_thing(int side, UObject* pawn)
    {
        if (g_world[side].on || g_wrap_on_side(side) || mount_gripped(side) || xbow_string_in_hand(side)) return true;
        if (bool_property(pawn, side == 0 ? STR("Grabbed L") : STR("Grabbed R"))) return true;
        const ObjectGrab& g = g_object_grab[side];
        return g.component && !g.fallback_tried && g.since >= 0.0 && hsvr::now_seconds() - g.since < 0.5;
    }
    // Test (hsvr.bring_object): an object kept at the right hand each tick until it is grabbed or 4 s pass.
    UObject* g_bring = nullptr;
    double g_bring_until = -1.0;
    int g_bring_side = 1;
    bool g_bring_weapon = false;   // a shield brought (hsvr.bring_object shield): kept until that hand holds it
    bool g_bring_at_point = false; // kept with g_bring_point (its own frame) at the hand: a rim test
    hsvr::Vec3 g_bring_point;

    void keep_brought_object(UObject* pawn, UObject* mesh)
    {
        if (!g_bring) return;
        const TCHAR* grabbed = g_bring_side == 0 ? STR("Grabbed L") : STR("Grabbed R");
        bool held = bool_property(pawn, grabbed);
        if (g_bring_weapon)
        {
            Call owner_call(g_bring, STR("GetOwner"));
            owner_call.run();
            UObject* owner = owner_call.object_result();
            held = owner && object_property(pawn, g_bring_side == 0 ? STR("Weapon L") : STR("Weapon R")) == owner;
        }
        if (hsvr::now_seconds() > g_bring_until || held)
        {
            HSVR_LOG("Script: hsvr.bring_object: no longer kept at the %s hand (grabbed %d)", g_bring_side == 0 ? "left" : "right", (int)bool_property(pawn, grabbed));
            g_bring = nullptr;
            return;
        }
        hsvr::Vec3 hand = hand_grab_point(mesh, g_bring_side);
        hsvr::Vec3 put = hand + hsvr::Vec3{0, 0, 4.0};
        if (g_bring_at_point) put = hand - component_rotation(g_bring).rotate(g_bring_point);
        Call move(g_bring, STR("K2_SetWorldLocation"));
        move.three(STR("NewLocation"), put.x, put.y, put.z);
        move.flag(STR("bTeleport"), true);
        move.run();
        Call stop(g_bring, STR("SetPhysicsLinearVelocity"));
        stop.run();
        Call spin(g_bring, STR("SetPhysicsAngularVelocityInDegrees"));
        spin.run();
    }

    // Squeezing near something that is not a weapon: a loose physics object (brick, barrel, armour
    // piece, food) or a body (anyone's bone, the dead too). The nearest simulating body within
    // pose_grab_radius_cm of the hand is handed to the game's own grab the way its search does it
    // (grab_pickup.md "Grab button follow-up", UF @523112): Grab Component / Grab Bone set, GrabPoint
    // put on the spot, Stuck Meter 0, then Grab Target Found, and its next tick builds the hand joint
    // with its full handling (unbreakable joints and limb/throat flags on characters, carried armour).
    // If the game has not grabbed it 0.3 s later, a plain object is given to Grab Specific Object
    // (the game's direct grab, which has no special handling); a body is left.
    // Crouched (Matthew 2026-11-19: "it kicks stuff around"): every 0.25 s, the loose things and bodies
    // near his legs that are moving, how fast, and how near his nearest leg bone is. Logging only.
    std::atomic<double> g_kick_speed{0.0}; // m/s: the fastest loose weapon seen moving near his legs while crouched since hsvr.mark
    // Test: hsvr.watch_item <name part>: one loose weapon (not in his hands) watched every frame: how far it moved since
    // hsvr.mark (item_moved, cm) and its fastest speed (item_speed, m/s). Run 9 86af79d: kick_speed counted his own worn
    // gear (pavise on his back, hip sword, dagger swinging on their slots), and never the lantern at his feet.
    std::wstring g_watch_name;
    std::atomic<double> g_watch_moved{0.0}, g_watch_speed{0.0};
    std::atomic<bool> g_watch_reset{false};
    UObject* g_watch_item = nullptr; // the item hsvr.watch_item found (for its Collision Hit log)
    bool is_mounted(UObject* w);
    void own_gear(UObject* pawn, std::vector<UObject*>& out);
    std::vector<UObject*> static_parts_of(UObject* owner);
    struct LegGuard
    {
        std::vector<UObject*> joints;
        double clear_since = -1.0;
        std::vector<UObject*> gear; // his worn gear when the pairs were made: made again when it changes
        // Each part's response to his capsule's object channel before it was set to ignore (restored with the pairs).
        std::vector<std::pair<UObject*, int>> responses;
        int channel = -1;
        UObject* capsule = nullptr; // his capsule, told to ignore this item when it moves (IgnoreActorWhenMoving)
        std::vector<UObject*> parts; // the item's parts the pairs were made for (the Watch hit log names a hit from one not in it)
    };
    std::map<UObject*, LegGuard> g_leg_guard;
    void item_watch_tick(UObject* pawn)
    {
        using namespace hsvr;
        static UObject* item = nullptr;
        static bool tracked = track_freed(&item);
        (void)tracked;
        static Vec3 at_mark{};
        static bool have_mark = false;
        static double found_t = -10.0;
        if (g_watch_name.empty() || !pawn) { item = nullptr; g_watch_item = nullptr; return; }
        double now = now_seconds();
        if (!item && now - found_t > 0.5)
        {
            found_t = now;
            std::vector<UObject*> ws;
            UObjectGlobals::FindAllOf(STR("ModularWeaponBP_C"), ws);
            for (UObject* w : ws)
                if (w && w->GetName().rfind(STR("Default__"), 0) != 0 && w->GetName().find(g_watch_name) != std::wstring::npos) { item = w; break; }
            if (item) HSVR_LOG("Watch: %ls", item->GetName().c_str());
            g_watch_item = item;
            // Every part reports its hits (run 18: only the lamp and the base did; a link or the holder touching him said nothing).
            if (item)
                if (object_property(item, STR("BaseMesh")))
                {
                    std::vector<UObject*> wp;
                    wp = static_parts_of(item);
                    std::wstring was;
                    for (UObject* part : wp)
                    {
                        was += part->GetName() + (bool_property(part, STR("bNotifyRigidBodyCollision")) ? STR(":1 ") : STR(":0 "));
                        Call nc(part, STR("SetNotifyRigidBodyCollision"));
                        nc.first_flag(true);
                        nc.run();
                    }
                    HSVR_LOG("Watch: hit events on for all %zu parts (were %ls)", wp.size(), was.c_str());
                }
            have_mark = false;
        }
        if (!item) return;
        UObject* b = object_property(item, STR("BaseMesh"));
        if (!b) return;
        // Only while loose: in a hand it moves with the hand.
        if (object_property(pawn, STR("Weapon R")) == item || object_property(pawn, STR("Weapon L")) == item) { have_mark = false; return; }
        Vec3 p = component_location(b);
        if (g_watch_reset.exchange(false) || !have_mark)
        {
            at_mark = p;
            have_mark = true;
            g_watch_moved.store(0.0);
            g_watch_speed.store(0.0);
        }
        Call lv(b, STR("GetPhysicsLinearVelocity"));
        double v = lv.run() ? length(lv.vec()) / 100.0 : 0.0;
        double d = length(p - at_mark);
        if (d > g_watch_moved.load()) g_watch_moved.store(d);
        if (v > g_watch_speed.load())
        {
            g_watch_speed.store(v);
            if (v > 0.5)
            {
                // What of his is nearest it as it goes (bones of his posed mesh, and the capsule)
                UObject* mesh = object_property(pawn, STR("Mesh"));
                const char* names[] = {"foot_l", "foot_r", "calf_l", "calf_r", "thigh_l", "thigh_r", "pelvis", "hand_l", "hand_r"};
                double best = 1e9;
                const char* bn = "?";
                for (const char* n : names)
                {
                    double dd = length(socket_location(mesh, bone_fname(n)) - p);
                    if (dd < best) best = dd, bn = n;
                }
                UObject* cap = object_property(pawn, STR("CapsuleComponent"));
                Vec3 cp = cap ? component_location(cap) : Vec3{};
                double cap_d = length(Vec3{cp.x - p.x, cp.y - p.y, 0.0});
                HSVR_LOG_EVERY(0.1, "Watch: %ls at %.1f m/s, %.0f cm from where it lay; nearest his %s %.0f cm, capsule axis %.0f cm away (crouch %.0f)",
                               item->GetName().c_str(), v, d, bn, best, cap_d, g_crouch_drop);
                // Surface gaps (run 11 8653332: with its legs paired it still went off; which of his bodies touched it?):
                // every physics body of his, his capsule, armour proxies and worn gear, nearest three.
                static double surf_t = -1.0;
                if (mesh && now - surf_t > 0.1)
                {
                    surf_t = now;
                    std::vector<std::pair<double, std::wstring>> gaps;
                    for (FName bone : physics_body_bones(mesh))
                    {
                        double g = item_gap(item, mesh, bone, socket_location(mesh, bone));
                        if (g >= 0.0) gaps.push_back({g, bone.ToString()});
                    }
                    if (cap)
                    {
                        double g = item_gap(item, cap, FName(), component_location(cap));
                        if (g >= 0.0) gaps.push_back({g, STR("capsule")});
                    }
                    if (UObject* drv = object_property(pawn, STR("DriverSkeleton")))
                        for (const char* n : {"foot_l", "foot_r", "calf_l", "calf_r", "thigh_l", "thigh_r", "pelvis"})
                        {
                            double g = item_gap(item, drv, bone_fname(n), socket_location(drv, bone_fname(n)));
                            if (g >= 0.0) gaps.push_back({g, std::wstring(STR("driver.")) + std::wstring(n, n + std::strlen(n))});
                        }
                    for (const TCHAR* name : k_cm_proxies)
                        if (UObject* cm = object_property(pawn, name))
                        {
                            Call r(cm, STR("GetScaledSphereRadius"));
                            double radius = r.run() ? r.number() : 0.0;
                            double g = closest_on_weapon(item, component_location(cm), nullptr, nullptr);
                            if (g >= 0.0) gaps.push_back({(std::max)(0.0, g - radius), name});
                        }
                    std::vector<UObject*> gear;
                    own_gear(pawn, gear);
                    for (UObject* gw : gear)
                        if (UObject* gb = object_property(gw, STR("BaseMesh")))
                        {
                            std::vector<UObject*> gp;
                            attached_meshes(gb, nullptr, gp, 0);
                            for (UObject* part : gp)
                            {
                                double g = item_gap(item, part, FName(), component_location(part));
                                if (g >= 0.0) gaps.push_back({g, gw->GetName() + STR(".") + part->GetName()});
                            }
                        }
                    std::sort(gaps.begin(), gaps.end());
                    std::wstring list;
                    for (size_t i = 0; i < gaps.size() && i < 4; ++i)
                    {
                        wchar_t b[200];
                        std::swprintf(b, 200, L"%ls %.1f cm; ", gaps[i].second.c_str(), gaps[i].first);
                        list += b;
                    }
                    HSVR_LOG("Watch: %ls nearest surfaces of his: %ls(leg guard %s)", item->GetName().c_str(), list.c_str(),
                             g_leg_guard.count(item) ? "on" : "off");
                }
            }
        }
    }
    // pose_legs_pass_loose (Matthew 2026-11-24: "I dont want willies feet kicking stuff around"): his legs are kinematic
    // bodies moved to the pose every frame, so they hit what lies at his feet with his legs' speed. PC run 10 d82b641
    // floor_kick: a crouch to 85 cm (eased 150 cm/s) pushed the lantern at his feet 50 cm at 2.5 m/s, his calf_r 12 cm
    // from it. So a loose weapon near his legs gets no-collide pairs with his leg and hip bodies (thigh, calf, foot, ball,
    // pelvis, spine_01, spine_02), his capsule, his leg and cuirass armour proxies and his worn gear, and loses them once it is pose_legs_pass_loose_cm + 15 cm clear for 0.3 s or
    // a hand takes it. A deliberate kick (the game's Kick, right A) makes no new pairs.
    // Where a component of his hangs: up its attach parents to his Mesh ("Mesh:<socket>") or to the last parent (its name).
    std::wstring attach_root(UObject* mesh, UObject* c)
    {
        UObject* p = c;
        for (int i = 0; i < 8 && p; ++i)
        {
            Call ap(p, STR("GetAttachParent"));
            if (!ap.fn || !ap.run()) break;
            UObject* parent = ap.object_result();
            if (!parent) break;
            if (parent == mesh)
            {
                Call sn(p, STR("GetAttachSocketName"));
                std::wstring sock = STR("?");
                if (sn.fn && sn.run())
                    if (FProperty* rp = sn.param(STR("ReturnValue"))) sock = reinterpret_cast<FName*>(sn.buffer.data() + rp->GetOffset_Internal())->ToString();
                return STR("Mesh:") + sock;
            }
            p = parent;
        }
        return p ? p->GetName() : std::wstring(STR("?"));
    }
    bool physics_collides(UObject* c)
    {
        Call ce(c, STR("GetCollisionEnabled"));
        if (!ce.fn || !ce.run()) return false;
        int e = byte_result(ce);
        return e == 2 || e == 3; // PhysicsOnly / QueryAndPhysics
    }
    // A hip or leg bone of his (the guard's bones).
    bool leg_or_hip_name(std::wstring n)
    {
        for (wchar_t& ch : n) ch = (wchar_t)towlower(ch);
        return n.find(L"thigh") != std::wstring::npos || n.find(L"calf") != std::wstring::npos || n.find(L"foot") != std::wstring::npos ||
               n.find(L"ball") != std::wstring::npos || n == L"pelvis" || n == L"spine_01" || n == L"spine_02";
    }

    void leg_guard_drop(UObject* item, LegGuard& g, const char* why)
    {
        for (UObject* j : g.joints)
            if (j && !gone(j) && object_alive(j))
            {
                Call d(j, STR("K2_DestroyComponent"));
                d.object(STR("Object"), j);
                d.run();
            }
        for (auto& [part, was] : g.responses)
            if (part && !gone(part) && object_alive(part) && g.channel >= 0 && was >= 0)
            {
                Call r(part, STR("SetCollisionResponseToChannel"));
                r.byte(STR("Channel"), (uint8_t)g.channel);
                r.byte(STR("NewResponse"), (uint8_t)was);
                r.run();
            }
        g.responses.clear();
        if (g.capsule && item && !gone(g.capsule) && !gone(item) && object_alive(g.capsule))
        {
            Call ig(g.capsule, STR("IgnoreActorWhenMoving"));
            ig.object(STR("Actor"), item);
            ig.flag(STR("bShouldIgnore"), false);
            ig.run();
        }
        g.capsule = nullptr;
        if (item && !gone(item)) HSVR_LOG("Legs: %ls collides with his legs again (%s)", item->GetName().c_str(), why);
        g.joints.clear();
    }
    // A weapon given straight into the hand can have no hanging bodies in the parts list yet when its pairs are made (run 28
    // lantern_hold, 3rd lantern of a launch: none paired, "hanging: none", it trailed 16-17 cm; the other three 0.8-2.4 cm).
    // So for 3 s after, every 0.25 s, any hanging body not yet paired gets the same bones.
    void arm_hanging_tick(UObject* pawn)
    {
        static double last = -1.0;
        double now = hsvr::now_seconds();
        if (now - last < 0.25 || !pawn) return;
        last = now;
        UObject* mesh = object_property(pawn, STR("Mesh"));
        UClass* cls = UObjectGlobals::StaticFindObject<UClass*>(nullptr, nullptr, STR("/Script/Engine.PhysicsConstraintComponent"));
        if (!mesh || !cls) return;
        for (int side = 0; side < 2; ++side)
        {
            ArmIgnore& a = g_arm_ignore[side];
            if (!a.weapon || gone(a.weapon) || a.bones.empty() || a.dropped_at >= 0.0 || now - a.made_at > 3.0) continue;
            UObject* base = object_property(a.weapon, STR("BaseMesh"));
            if (!base) continue;
            std::vector<UObject*> tree, scab;
            attached_meshes(base, nullptr, tree, 0);
            attached_meshes(object_property(a.weapon, STR("Scabbard")), nullptr, scab, 0);
            int added = 0;
            for (UObject* c : static_parts_of(a.weapon))
            {
                if (std::find(tree.begin(), tree.end(), c) != tree.end() || std::find(scab.begin(), scab.end(), c) != scab.end()) continue;
                if (std::find(a.hanging.begin(), a.hanging.end(), c) != a.hanging.end() || !physics_collides(c)) continue;
                for (FName b : a.bones)
                    if (UObject* j = no_collision_pair(pawn, cls, c, mesh, b)) a.joints.push_back(j);
                a.hanging.push_back(c);
                ++added;
            }
            if (added) HSVR_LOG("Grip: %s weapon: %d more hanging bodies found and paired (%.2f s after its pairs)", side == 0 ? "left" : "right", added, now - a.made_at);
        }
    }

    // ---- Chain items (pose_chain_no_self_collision, pose_chain_damping) ---------------------------------
    // A chain lantern's lamp and Link 1-4 hang on PhysicsConstraint1-6, bodies of their own outside BaseMesh's weld tree. Run 26
    // (2741646): spawned on the floor 45 cm from him, nothing of his touching it in 10 of 12 runs, it rolled 0.5-2.6 m and sped up
    // to 5.9 m/s, its only contacts the floor and its own lamp, links and holder (impulses 50-317 between its own parts).
    // Once per item: a no-collide pair between each of its own bodies (per pair, the item's own parts only), and damping on the
    // hanging ones. Kept for the item's life (the joints are components of the item, destroyed with it).
    std::unordered_set<UObject*> g_chain_calmed;
    void chain_calm_tick(UObject* pawn, const hsvr::Config& cfg)
    {
        static bool tracked = on_freed([] {
            for (auto it = g_chain_calmed.begin(); it != g_chain_calmed.end();) it = gone(*it) ? g_chain_calmed.erase(it) : std::next(it);
        });
        (void)tracked;
        if (!cfg.pose_chain_no_self_collision && cfg.pose_chain_damping <= 0.0) return;
        // The pairs are components of his (as the leg guard's: a free joint owned by the weapon would count as one of its chain
        // joints, hanging_mass): a new body of his takes them with the old one, so every item is done again.
        static UObject* calmed_for = nullptr;
        if (pawn != calmed_for) g_chain_calmed.clear(), calmed_for = pawn;
        static double listed = -10.0;
        double now = hsvr::now_seconds();
        if (now - listed < 1.0 || !pawn) return;
        listed = now;
        UClass* cls = UObjectGlobals::StaticFindObject<UClass*>(nullptr, nullptr, STR("/Script/Engine.PhysicsConstraintComponent"));
        if (!cls) return;
        std::vector<UObject*> weapons;
        UObjectGlobals::FindAllOf(STR("ModularWeaponBP_C"), weapons);
        for (UObject* w : weapons)
        {
            if (!w || gone(w) || w->GetName().rfind(STR("Default__"), 0) == 0 || g_chain_calmed.count(w)) continue;
            UObject* base = object_property(w, STR("BaseMesh"));
            if (!base) continue;
            std::vector<UObject*> tree, scab, hanging;
            attached_meshes(base, nullptr, tree, 0);
            attached_meshes(object_property(w, STR("Scabbard")), nullptr, scab, 0);
            for (UObject* c : static_parts_of(w))
                if (std::find(tree.begin(), tree.end(), c) == tree.end() && std::find(scab.begin(), scab.end(), c) == scab.end() && physics_collides(c))
                    hanging.push_back(c);
            g_chain_calmed.insert(w);
            if (hanging.empty()) continue;
            int pairs = 0;
            if (cfg.pose_chain_no_self_collision)
            {
                // The weld tree is one body (its root): one pair per hanging body with it, and one between each two hanging bodies.
                std::vector<UObject*> bodies{base};
                bodies.insert(bodies.end(), hanging.begin(), hanging.end());
                for (size_t i = 0; i < bodies.size(); ++i)
                    for (size_t k = i + 1; k < bodies.size(); ++k)
                        if (no_collision_pair(pawn, cls, bodies[i], bodies[k])) ++pairs;
            }
            if (cfg.pose_chain_damping > 0.0)
                for (UObject* c : hanging)
                {
                    Call ld(c, STR("SetLinearDamping"));
                    first_number(ld, cfg.pose_chain_damping);
                    ld.run();
                    Call ad(c, STR("SetAngularDamping"));
                    first_number(ad, cfg.pose_chain_damping);
                    ad.run();
                }
            HSVR_LOG("Chain: %ls: %zu hanging bodies; %d no-collide pair(s) among its own parts, damping %.2f", w->GetName().c_str(), hanging.size(), pairs,
                     cfg.pose_chain_damping);
        }
    }

    void leg_guard_tick(UObject* pawn, UObject* mesh, const hsvr::Config& cfg)
    {
        using namespace hsvr;
        static bool tracked = on_freed([] {
            for (auto it = g_leg_guard.begin(); it != g_leg_guard.end();)
            {
                if (gone(it->first)) it = g_leg_guard.erase(it);
                else
                {
                    auto& js = it->second.joints;
                    js.erase(std::remove_if(js.begin(), js.end(), [](UObject* o) { return gone(o); }), js.end());
                    // Every other pointer the guard keeps (its parts, their saved responses, his capsule) is read again in
                    // leg_guard_drop, where gone() no longer knows them.
                    auto& rs = it->second.responses;
                    rs.erase(std::remove_if(rs.begin(), rs.end(), [](const std::pair<UObject*, int>& p) { return gone(p.first); }), rs.end());
                    erase_gone(it->second.parts);
                    erase_gone(it->second.gear);
                    if (gone(it->second.capsule)) it->second.capsule = nullptr;
                    ++it;
                }
            }
        });
        (void)tracked;
        static UObject* guard_pawn = nullptr;
        bool on = cfg.pose_legs_pass_loose && pawn && mesh;
        if (!on || pawn != guard_pawn)
        {
            for (auto& [item, g] : g_leg_guard) leg_guard_drop(item, g, on ? "a new body" : "switched off");
            g_leg_guard.clear();
            guard_pawn = on ? pawn : nullptr;
            if (!on) return;
        }
        double now = now_seconds();
        static double last = -1.0;
        if (now - last < 0.1) return;
        last = now;
        // His leg bodies (as their physics asset names them), cached per mesh.
        static UObject* bones_of = nullptr;
        static std::vector<FName> leg_bones;
        if (bones_of != mesh)
        {
            leg_bones.clear();
            for (FName b : physics_body_bones(mesh))
            {
                std::wstring n = b.ToString();
                for (wchar_t& ch : n) ch = (wchar_t)towlower(ch);
                if (n.find(L"thigh") != std::wstring::npos || n.find(L"calf") != std::wstring::npos || n.find(L"foot") != std::wstring::npos ||
                    n.find(L"ball") != std::wstring::npos || n == L"pelvis" || n == L"spine_01" || n == L"spine_02")
                    leg_bones.push_back(b);
            }
            bones_of = mesh;
            std::wstring names;
            for (FName b : leg_bones) names += b.ToString() + STR(" ");
            HSVR_LOG("Legs: his leg bodies: %ls", names.empty() ? STR("(none found)") : names.c_str());
        }
        if (leg_bones.empty()) return;
        // His DriverSkeleton (the hidden animated copy the visible body copies): if it has physics collision of its own,
        // its legs are paired too (run 15 69408e5: the lantern touching his foot_r 0.3 cm with every pair on Mesh still went
        // off at 5 m/s, three times).
        UObject* driver = object_property(pawn, STR("DriverSkeleton"));
        static UObject* driver_of = nullptr;
        static std::vector<FName> driver_bones;
        static bool driver_collides = false;
        if (driver != driver_of)
        {
            driver_of = driver;
            driver_bones.clear();
            driver_collides = false;
            if (driver)
            {
                Call ce(driver, STR("GetCollisionEnabled"));
                ce.run();
                int enabled = byte_result(ce);
                std::vector<FName> all = physics_body_bones(driver);
                for (FName b : all)
                {
                    std::wstring n = b.ToString();
                    for (wchar_t& ch : n) ch = (wchar_t)towlower(ch);
                    if (n.find(L"thigh") != std::wstring::npos || n.find(L"calf") != std::wstring::npos || n.find(L"foot") != std::wstring::npos ||
                        n.find(L"ball") != std::wstring::npos || n == L"pelvis" || n == L"spine_01" || n == L"spine_02")
                        driver_bones.push_back(b);
                }
                driver_collides = (enabled == 2 || enabled == 3) && !driver_bones.empty(); // PhysicsOnly / QueryAndPhysics
                HSVR_LOG("Legs: his DriverSkeleton: collision %d, %zu physics bodies (%zu leg/hip): %s", enabled, all.size(), driver_bones.size(),
                         driver_collides ? "its legs are paired too" : "nothing to pair");
            }
        }
        // Where his legs are: hip, knee, ankle and toe points of both legs.
        std::vector<Vec3> points;
        for (const char* n : {"thigh_l", "calf_l", "foot_l", "ball_l", "thigh_r", "calf_r", "foot_r", "ball_r"})
            points.push_back(socket_location(mesh, bone_fname(n)));
        Vec3 mid{0, 0, 0};
        for (const Vec3& p : points) mid = mid + p * (1.0 / points.size());
        // Loose weapons (not in a hand, sheath, slot or forearm mount), listed again every second.
        static std::vector<UObject*> weapons, willies;
        static bool list_tracked = on_freed([] {
            weapons.erase(std::remove_if(weapons.begin(), weapons.end(), [](UObject* o) { return gone(o); }), weapons.end());
            willies.erase(std::remove_if(willies.begin(), willies.end(), [](UObject* o) { return gone(o); }), willies.end());
        });
        (void)list_tracked;
        static double listed = -10.0;
        weapons_from_parts(pawn, weapons);
        if (now - listed > 1.0)
        {
            listed = now;
            willies.clear();
            UObjectGlobals::FindAllOf(STR("Willie_BP_C"), willies);
        }
        bool kicking = g_feet[0].kicking || g_feet[1].kicking;
        double within = cfg.pose_legs_pass_loose_cm;
        UClass* cls = UObjectGlobals::StaticFindObject<UClass*>(nullptr, nullptr, STR("/Script/Engine.PhysicsConstraintComponent"));
        std::vector<UObject*> gear;
        own_gear(pawn, gear);
        std::unordered_set<UObject*> seen;
        for (UObject* w : weapons)
        {
            if (!w || gone(w) || w->GetName().rfind(STR("Default__"), 0) == 0) continue;
            UObject* base = object_property(w, STR("BaseMesh"));
            if (!base) continue;
            Vec3 bp = component_location(base);
            // Far off (a weapon is at most ~2 m long): not looked at closely.
            if (std::fabs(bp.x - mid.x) > 250.0 || std::fabs(bp.y - mid.y) > 250.0 || std::fabs(bp.z - mid.z) > 250.0) continue;
            bool held = false;
            for (UObject* c : willies)
                if (c && !gone(c) && (object_property(c, STR("Weapon R")) == w || object_property(c, STR("Weapon L")) == w)) held = true;
            bool loose = !held && !bool_property(w, STR("Is Sheathed")) && !is_fist(w) && !in_own_slot(pawn, w) && !is_mounted(w);
            auto it = g_leg_guard.find(w);
            if (!loose)
            {
                if (it != g_leg_guard.end())
                {
                    leg_guard_drop(w, it->second, held ? "taken in a hand" : "sheathed, slotted or mounted");
                    g_leg_guard.erase(it);
                }
                continue;
            }
            double nearest = 1e9;
            for (const Vec3& p : points)
            {
                double d = closest_on_weapon(w, p, nullptr, nullptr);
                if (d >= 0.0 && d < nearest) nearest = d;
            }
            seen.insert(w);
            // Pairs with his leg and hip bodies, capsule, leg armour proxies and his worn gear (run 11 8653332: crouched
            // to 82 cm over a lantern lying under him, his pelvis at z 13 and his slung pavise swinging 1-9 m/s 6-17 cm from
            // his calf, it went off at 5-6 m/s with the legs alone paired).
            auto make_pairs = [&](LegGuard& g, const char* why) {
                // Every physics part of the item, attached or not (run 19 f4cc855: the chain lantern's lamp, its "Weapon", hangs on
                // PhysicsConstraint6 as a body of its own outside BaseMesh's attach tree; every kick hit came from it, never paired).
                // Its own scabbard and what hangs under it are left out (a component of the weapon that stays on a belt).
                std::vector<UObject*> parts, gear_parts, scab_tree;
                attached_meshes(object_property(w, STR("Scabbard")), nullptr, scab_tree, 0);
                std::wstring part_names;
                for (UObject* c : static_parts_of(w))
                    if (std::find(scab_tree.begin(), scab_tree.end(), c) == scab_tree.end() && physics_collides(c))
                    {
                        parts.push_back(c);
                        part_names += (part_names.empty() ? STR("") : STR(", ")) + c->GetName();
                    }
                for (UObject* gw : gear)
                    if (gw != w)
                        for (UObject* c : static_parts_of(gw))
                            if (physics_collides(c)) gear_parts.push_back(c);
                // His own static meshes (armour the game adds to him, NODE_AddStaticMeshComponent-N): run 19 had the lantern hit
                // his NODE_AddStaticMeshComponent-60/-61 at 405-460. Those hanging from a leg or hip bone of his, or from his
                // CM_Leg_L/R or CM_Cuirass proxy, are paired as his legs are; every one is logged with where it hangs.
                std::wstring own_list;
                for (UObject* c : static_parts_of(pawn))
                {
                    if (!physics_collides(c)) continue;
                    std::wstring root = attach_root(mesh, c);
                    bool legs = (root.rfind(STR("Mesh:"), 0) == 0 && leg_or_hip_name(root.substr(5))) || root == STR("CM_Leg_L") ||
                                root == STR("CM_Leg_R") || root == STR("CM_Cuirass");
                    bool proxy = false;
                    for (const TCHAR* n : k_cm_proxies)
                        if (object_property(pawn, n) == c) proxy = true;
                    if (proxy) continue; // CM_* proxies: paired by name below
                    own_list += c->GetName() + STR(" on ") + root + (legs ? STR(" (paired)") : STR("")) + STR("; ");
                    if (legs) gear_parts.push_back(c);
                }
                for (UObject* part : parts)
                {
                    for (FName b : leg_bones)
                        if (UObject* j = no_collision_pair(pawn, cls, part, mesh, b)) g.joints.push_back(j);
                    if (driver_collides)
                        for (FName b : driver_bones)
                            if (UObject* j = no_collision_pair(pawn, cls, part, driver, b)) g.joints.push_back(j);
                    if (UObject* cap = object_property(pawn, STR("CapsuleComponent")))
                        if (UObject* j = no_collision_pair(pawn, cls, part, cap)) g.joints.push_back(j);
                    for (const TCHAR* n : {STR("CM_Leg_L"), STR("CM_Leg_R"), STR("CM_Cuirass")})
                        if (UObject* cm = object_property(pawn, n))
                            if (UObject* j = no_collision_pair(pawn, cls, part, cm)) g.joints.push_back(j);
                    for (UObject* gp : gear_parts)
                        if (UObject* j = no_collision_pair(pawn, cls, part, gp)) g.joints.push_back(j);
                }
                g.gear = gear;
                // And his capsule's own movement: the character movement's sweeps and its repulsion of what overlaps the
                // capsule are queries, which no-collide joints do not reach (run 13 4b7c188: a lantern lying inside his
                // capsule went off at 9.4 m/s as he crouched to 82 cm, his capsule 0-1.7 cm from it, every pair in place).
                // Per pair: his capsule's moves ignore this item (UPrimitiveComponent::IgnoreActorWhenMoving, its
                // MoveIgnoreActors: the sweeps, and so the impact pushes from them, skip it), undone with the pairs.
                if (UObject* cap = object_property(pawn, STR("CapsuleComponent")))
                {
                    Call ig(cap, STR("IgnoreActorWhenMoving"));
                    ig.object(STR("Actor"), w);
                    ig.flag(STR("bShouldIgnore"), true);
                    if (ig.run()) g.capsule = cap;
                    else HSVR_LOG("Legs: no IgnoreActorWhenMoving on %ls", cap->GetName().c_str());
                }
                // Channel-wide (test switch pose_legs_pass_capsule_channel, off: per-pair ignores only, project rule): each part
                // ignores the capsule's object channel while guarded (only the filter changes, no rebuild).
                std::wstring was_list;
                if (UObject* cap = cfg.pose_legs_pass_capsule_channel ? object_property(pawn, STR("CapsuleComponent")) : nullptr)
                {
                    Call t(cap, STR("GetCollisionObjectType"));
                    t.run();
                    g.channel = byte_result(t);
                    // Only while the capsule's channel is its own: never one his body or the item itself is on (ignoring it
                    // would let the item through every body or weapon of that kind, not just his capsule).
                    Call mt(mesh, STR("GetCollisionObjectType"));
                    mt.run();
                    Call it_t(base, STR("GetCollisionObjectType"));
                    it_t.run();
                    int mesh_ch = byte_result(mt), item_ch = byte_result(it_t);
                    if (g.channel == mesh_ch || g.channel == item_ch)
                    {
                        HSVR_LOG("Legs: capsule channel %d is also his body's (%d) or the item's (%d): left as it is", g.channel, mesh_ch, item_ch);
                        g.channel = -1;
                    }
                    if (g.channel >= 0)
                        for (UObject* part : parts)
                        {
                            Call rd(part, STR("GetCollisionResponseToChannel"));
                            rd.byte(STR("Channel"), (uint8_t)g.channel);
                            rd.run();
                            int was = byte_result(rd);
                            g.responses.push_back({part, was});
                            was_list += std::to_wstring(was);
                            if (was <= 0) continue;
                            Call r(part, STR("SetCollisionResponseToChannel"));
                            r.byte(STR("Channel"), (uint8_t)g.channel);
                            r.byte(STR("NewResponse"), (uint8_t)0);
                            r.run();
                        }
                }
                if (cfg.pose_legs_pass_capsule_channel)
                    HSVR_LOG("Legs: capsule channel %d: the parts' responses were [%ls], now ignore", g.channel, was_list.c_str());
                HSVR_LOG("Legs: %ls %.0f cm from his legs: passes through them and his worn gear (%zu no-collide pair(s), %zu part(s) x %zu gear part(s); "
                         "crouch %.0f; %s)",
                         w->GetName().c_str(), nearest, g.joints.size(), parts.size(), gear_parts.size(), g_crouch_drop, why);
                HSVR_LOG("Legs:   its parts: %ls", part_names.c_str());
                HSVR_LOG("Legs:   his own static meshes with physics: %ls", own_list.empty() ? STR("(none)") : own_list.c_str());
                g.parts = parts;
            };
            if (it == g_leg_guard.end())
            {
                if (nearest > within || kicking || !cls) continue;
                LegGuard g;
                make_pairs(g, "new");
                g_leg_guard[w] = std::move(g);
                continue;
            }
            LegGuard& g = it->second;
            // Made again when his worn gear changed. (Two guards' joints on one pair do not undo each other: Chaos counts
            // ignore requests per pair, FIgnoreCollisionManager, UE 5.4.4 CollisionConstraintFlags.cpp:42-92.)
            if (cls && g.gear != gear)
            {
                leg_guard_drop(w, g, "his worn gear changed");
                make_pairs(g, "his worn gear changed");
            }
            if (nearest <= within + 15.0)
            {
                g.clear_since = -1.0;
                continue;
            }
            if (g.clear_since < 0.0) g.clear_since = now;
            if (now - g.clear_since < 0.3) continue;
            char why[64];
            std::snprintf(why, sizeof(why), "%.0f cm clear", nearest);
            leg_guard_drop(w, g, why);
            g_leg_guard.erase(it);
        }
        // Gone from the list (freed, or far off): pairs dropped.
        for (auto it = g_leg_guard.begin(); it != g_leg_guard.end();)
        {
            if (seen.count(it->first)) { ++it; continue; }
            leg_guard_drop(it->first, it->second, "far off");
            it = g_leg_guard.erase(it);
        }
    }
    // pose_shoulder_slot_on_chest: a shield slung on his shoulder (SheathSlot 2, the light pavise and the targe) hangs on the game's
    // Slot Back Constraint from Sheath_Slot_Shoulder_L, whose bone is upperarm_l (Willie skeleton sockets; Sheathe on Spawn
    // @6884 SetConstrainedComponents(BaseMesh, None, Mesh, GetSocketBoneName(socket))). In the flat game that arm is animated and
    // still; in VR it is his tracked left arm, posed every frame with the controller's noise and every move, and the shield,
    // jointed to it with a limited (X motion 1) joint, twitched on his back while he stood still (playtest 11-24 12:02 and his
    // note: "I'm just standing here still, but the pavise is jittering, twitching, and freaking out"). So the joint's second body
    // becomes his chest (spine_05), its frame moved so the shield stays exactly where it hangs now.
    void shoulder_slot_tick(UObject* pawn, UObject* mesh, const hsvr::Config& cfg)
    {
        using namespace hsvr;
        static std::unordered_set<UObject*> done;
        static bool tracked = on_freed([] {
            for (auto it = done.begin(); it != done.end();) it = gone(*it) ? done.erase(it) : std::next(it);
        });
        (void)tracked;
        if (!pawn || !mesh) return;
        // Test measure (slot_back_moved / slot_back_speed): the item on his back slot against his chest, since hsvr.mark.
        {
            static UObject* was_item = nullptr;
            static bool t1 = track_freed(&was_item);
            (void)t1;
            static Vec3 at_mark{}, prev{};
            static double prev_t = -1.0;
            UObject* it = object_property(pawn, STR("Weapon Slot Back"));
            UObject* b = it ? object_property(it, STR("BaseMesh")) : nullptr;
            if (b)
            {
                FName chest = bone_fname("spine_05");
                Vec3 rel = socket_rotation(mesh, chest).inverse().rotate(component_location(b) - socket_location(mesh, chest));
                double tn = now_seconds();
                if (it != was_item || g_slot_reset.exchange(false)) at_mark = rel, prev = rel, prev_t = tn, was_item = it, g_slot_moved = 0.0, g_slot_speed = 0.0;
                g_slot_moved = (std::max)(g_slot_moved, length(rel - at_mark));
                if (tn - prev_t > 1e-4) g_slot_speed = (std::max)(g_slot_speed, length(rel - prev) / (tn - prev_t) / 100.0);
                prev = rel;
                prev_t = tn;
            }
        }
        if (!cfg.pose_shoulder_slot_on_chest) return;
        static double last = -1.0;
        double now = now_seconds();
        if (now - last < 0.25) return;
        last = now;
        UObject* item = object_property(pawn, STR("Weapon Slot Back"));
        UObject* joint = object_property(pawn, STR("Slot Back Constraint"));
        if (!item || !joint || done.count(joint)) return;
        Call who(joint, STR("GetConstrainedComponents"));
        if (!who.run()) return;
        FProperty* c1p = who.param(STR("OutComponent1"));
        FProperty* c2p = who.param(STR("OutComponent2"));
        FProperty* b2p = who.param(STR("OutBoneName2"));
        if (!c1p || !c2p || !b2p) return;
        UObject* c1 = *reinterpret_cast<UObject**>(who.buffer.data() + c1p->GetOffset_Internal());
        UObject* c2 = *reinterpret_cast<UObject**>(who.buffer.data() + c2p->GetOffset_Internal());
        FName b2 = *reinterpret_cast<FName*>(who.buffer.data() + b2p->GetOffset_Internal());
        if (!c1 || c2 != mesh) return;
        std::wstring bone = b2.ToString();
        if (bone != STR("upperarm_l") && bone != STR("upperarm_r") && bone.find(STR("clavicle")) == std::wstring::npos)
        {
            done.insert(joint);
            return;
        }
        // Frame 2 (position and axes) as it is now, in the world, then in spine_05's frame.
        auto n = [&](const TCHAR* a, const TCHAR* b) { return nested_number(joint, {STR("ConstraintInstance"), a, b}); };
        Vec3 pos2{n(STR("Pos2"), STR("X")), n(STR("Pos2"), STR("Y")), n(STR("Pos2"), STR("Z"))};
        Vec3 pri2{n(STR("PriAxis2"), STR("X")), n(STR("PriAxis2"), STR("Y")), n(STR("PriAxis2"), STR("Z"))};
        Vec3 sec2{n(STR("SecAxis2"), STR("X")), n(STR("SecAxis2"), STR("Y")), n(STR("SecAxis2"), STR("Z"))};
        FName chest = bone_fname("spine_05");
        Vec3 bp = socket_location(mesh, b2), cp = socket_location(mesh, chest);
        Quat bq = socket_rotation(mesh, b2), cq = socket_rotation(mesh, chest);
        Vec3 at_w = bp + bq.rotate(pos2), pri_w = bq.rotate(pri2), sec_w = bq.rotate(sec2);
        Vec3 at_c = cq.inverse().rotate(at_w - cp);
        Vec3 pri_c = normalized(cq.inverse().rotate(pri_w)), sec_c = normalized(cq.inverse().rotate(sec_w));
        Call rj(joint, STR("SetConstrainedComponents"));
        rj.object(STR("Component1"), c1);
        rj.name(STR("BoneName1"), FName(STR("None"), FNAME_Add));
        rj.object(STR("Component2"), mesh);
        rj.name(STR("BoneName2"), chest);
        bool ok = rj.run();
        Call rp(joint, STR("SetConstraintReferencePosition"));
        rp.byte_any({STR("Frame"), STR("frame")}, 1);
        rp.three_any({STR("RefPosition"), STR("RefPos")}, at_c.x, at_c.y, at_c.z);
        bool ok2 = rp.run();
        Call ro(joint, STR("SetConstraintReferenceOrientation"));
        ro.byte_any({STR("Frame"), STR("frame")}, 1);
        ro.three_any({STR("PriAxis"), STR("PriAxis1")}, pri_c.x, pri_c.y, pri_c.z);
        ro.three_any({STR("SecAxis"), STR("SecAxis1")}, sec_c.x, sec_c.y, sec_c.z);
        bool ok3 = ro.run();
        done.insert(joint);
        HSVR_LOG("Slot: %ls on his shoulder slot hung from %ls: now from spine_05 (his chest), frame kept in place (%d%d%d; pos (%.1f, %.1f, %.1f))",
                 item->GetName().c_str(), bone.c_str(), (int)ok, (int)ok2, (int)ok3, at_c.x, at_c.y, at_c.z);
    }

    // Lamp probe (Matthew 11-24: the held hanging lantern "feels like it's in zero gravity"): what a held item's hanging body
    // does (the chain lantern's lamp, "Weapon", on PhysicsConstraint1-6 below the handle): where it hangs from the handle,
    // its speed, and what the engine has on it (gravity, damping, mass), every 0.2 s while held. Test readers lamp_*.
    double g_lamp_drop = 0.0, g_lamp_speed_max = 0.0, g_lamp_swing_max = 0.0;
    std::atomic<bool> g_lamp_reset{false};
    void lamp_probe_tick(UObject* pawn)
    {
        using namespace hsvr;
        if (!pawn) return;
        static double last = -1.0, t_prev = -1.0;
        static Vec3 rel_prev{}, rel_mark{};
        static UObject* lamp_prev = nullptr;
        static bool tr = track_freed(&lamp_prev);
        (void)tr;
        UObject* lamp = nullptr;
        UObject* base = nullptr;
        for (int side = 0; side < 2 && !lamp; ++side)
        {
            UObject* w = held_weapon_of(side);
            if (!w || gone(w) || is_fist(w)) continue;
            UObject* b = object_property(w, STR("BaseMesh"));
            if (!b) continue;
            for (UObject* c : static_parts_of(w))
                if (c && c->GetName() == STR("Weapon") && c != b)
                {
                    Call sim(c, STR("IsSimulatingPhysics"));
                    sim.name(STR("BoneName"), FName(STR("None"), FNAME_Add));
                    FProperty* sp = sim.run() ? sim.param(STR("ReturnValue")) : nullptr;
                    if (sp && *(sim.buffer.data() + sp->GetOffset_Internal())) lamp = c, base = b;
                }
        }
        // A held item's hanging bodies (lamp, chain links) swing as hung things do, not in syrup: the chain lantern's lamp
        // carries the asset's own linear damping 1.0 and angular damping 5.0 (Lamp: lines, test cases\lamp), so after a shake
        // it went from 1.7 to 0.1 m/s in 0.6 s with no swing at all: "it feels like it's in zero gravity". B&S items keep
        // Unity's rigidbody defaults (drag 0, angular drag 0.05). While held they get pose_hanging_damping_held; the asset's
        // own values come back when it leaves the hand.
        {
            const hsvr::Config& cfg = hsvr::config();
            static std::map<UObject*, std::pair<double, double>> saved; // hanging body -> its own (linear, angular) damping
            static UObject* saved_for = nullptr;
            static bool t2 = on_freed([] {
                for (auto it = saved.begin(); it != saved.end();) it = gone(it->first) ? saved.erase(it) : std::next(it);
                if (gone(saved_for)) saved_for = nullptr;
            });
            (void)t2;
            UObject* held_item = nullptr;
            if (lamp)
                for (int side = 0; side < 2 && !held_item; ++side)
                    if (UObject* w = held_weapon_of(side))
                        if (object_property(w, STR("BaseMesh")) == base) held_item = w;
            if (saved_for && saved_for != held_item)
            {
                for (auto& [c, d] : saved)
                    if (!gone(c) && object_alive(c))
                    {
                        Call l(c, STR("SetLinearDamping"));
                        first_number(l, d.first);
                        l.run();
                        Call a(c, STR("SetAngularDamping"));
                        first_number(a, d.second);
                        a.run();
                    }
                HSVR_LOG("Lamp: %zu hanging bodies back to their own damping (out of the hand)", saved.size());
                saved.clear();
                saved_for = nullptr;
            }
            if (held_item && !saved_for && cfg.pose_hanging_damping_held >= 0.0)
            {
                std::vector<UObject*> tree;
                attached_meshes(base, nullptr, tree, 0);
                for (UObject* c : static_parts_of(held_item))
                {
                    if (!c || c == base || std::find(tree.begin(), tree.end(), c) != tree.end() || !physics_collides(c)) continue;
                    Call ld(c, STR("GetLinearDamping"));
                    Call ad(c, STR("GetAngularDamping"));
                    double l0 = ld.run() ? ld.number() : 0.0, a0 = ad.run() ? ad.number() : 0.0;
                    saved[c] = {l0, a0};
                    Call l(c, STR("SetLinearDamping"));
                    first_number(l, cfg.pose_hanging_damping_held);
                    l.run();
                    Call a(c, STR("SetAngularDamping"));
                    first_number(a, cfg.pose_hanging_damping_held);
                    a.run();
                }
                saved_for = held_item;
                HSVR_LOG("Lamp: %ls in the hand: %zu hanging bodies' damping %.2f (their own: lamp etc. kept to put back)", held_item->GetName().c_str(), saved.size(),
                         cfg.pose_hanging_damping_held);
            }
        }
        if (!lamp) { lamp_prev = nullptr; return; }
        Vec3 bp = component_location(base);
        Quat bq = component_rotation(base);
        Vec3 lp = component_location(lamp);
        Vec3 rel = lp - bp; // world-axis offset of the lamp from the handle
        double now = now_seconds();
        if (lamp != lamp_prev || g_lamp_reset.exchange(false))
        {
            lamp_prev = lamp;
            rel_mark = rel;
            g_lamp_speed_max = g_lamp_swing_max = 0.0;
            t_prev = -1.0;
        }
        g_lamp_drop = -rel.z;
        if (t_prev > 0.0 && now - t_prev > 1e-4)
            g_lamp_speed_max = (std::max)(g_lamp_speed_max, length(rel - rel_prev) / (now - t_prev) / 100.0); // m/s against the handle
        g_lamp_swing_max = (std::max)(g_lamp_swing_max, length(Vec3{rel.x - rel_mark.x, rel.y - rel_mark.y, 0.0}));
        rel_prev = rel;
        t_prev = now;
        if (now - last < 0.2) return;
        last = now;
        Call g(lamp, STR("IsGravityEnabled"));
        FProperty* gp = g.run() ? g.param(STR("ReturnValue")) : nullptr;
        bool grav = gp && *(g.buffer.data() + gp->GetOffset_Internal());
        Call ld(lamp, STR("GetLinearDamping"));
        double lin = ld.run() ? ld.number() : -1.0;
        Call ad(lamp, STR("GetAngularDamping"));
        double ang = ad.run() ? ad.number() : -1.0;
        Call m(lamp, STR("GetMass"));
        double mass = m.run() ? m.number() : -1.0;
        Call lv(lamp, STR("GetPhysicsLinearVelocity"));
        double v = lv.run() ? length(lv.vec()) / 100.0 : -1.0;
        Call hv(base, STR("GetPhysicsLinearVelocity"));
        double vh = hv.run() ? length(hv.vec()) / 100.0 : -1.0;
        Vec3 local = bq.inverse().rotate(rel);
        HSVR_LOG("Lamp: %.1f cm below the handle, %.1f cm out (world); in the handle's frame (%.1f, %.1f, %.1f); lamp %.2f m/s, handle %.2f m/s; gravity %d, "
                 "damping lin %.2f ang %.2f, mass %.2f kg; swing so far %.1f cm, speed vs handle max %.2f m/s",
                 -rel.z, length(Vec3{rel.x, rel.y, 0.0}), local.x, local.y, local.z, v, vh, (int)grav, lin, ang, mass, g_lamp_swing_max, g_lamp_speed_max);
    }

    void crouch_push_log(UObject* pawn, UObject* mesh)
    {
        using namespace hsvr;
        static double last = 0.0;
        double now = now_seconds();
        if (now - last < 0.25) return;
        last = now;
        static UObject* cdo = UObjectGlobals::StaticFindObject<UObject*>(nullptr, nullptr, STR("/Script/Engine.Default__KismetSystemLibrary"));
        if (!cdo || !pawn || !mesh) return;
        const char* legs[6] = {"thigh_l", "calf_l", "foot_l", "thigh_r", "calf_r", "foot_r"};
        Vec3 leg_at[6];
        Vec3 mid{0, 0, 0};
        for (int i = 0; i < 6; ++i)
        {
            leg_at[i] = socket_location(mesh, bone_fname(legs[i]));
            mid = mid + leg_at[i] * (1.0 / 6.0);
        }
        static uint8_t types[32];
        for (int i = 0; i < 32; ++i) types[i] = (uint8_t)i;
        Call ov(cdo, STR("SphereOverlapComponents"));
        FProperty* ot = ov.param(STR("ObjectTypes"));
        FProperty* out = ov.param(STR("OutComponents"));
        if (!ot || !out) return;
        ov.object(STR("WorldContextObject"), pawn);
        ov.three(STR("SpherePos"), mid.x, mid.y, mid.z);
        ov.number(STR("SphereRadius"), 70.0);
        RawArray* list = reinterpret_cast<RawArray*>(ov.buffer.data() + ot->GetOffset_Internal());
        list->Data = reinterpret_cast<void**>(types);
        list->Num = list->Max = 32;
        ov.run();
        RawArray* found = reinterpret_cast<RawArray*>(ov.buffer.data() + out->GetOffset_Internal());
        std::vector<UObject*> components;
        for (int32_t i = 0; i < found->Num && found->Data; ++i) components.push_back(reinterpret_cast<UObject*>(found->Data[i]));
        found->Data = nullptr;
        found->Num = found->Max = 0;
        list->Data = nullptr;
        list->Num = list->Max = 0;
        std::wstring moving;
        for (UObject* c : components)
        {
            if (!c) continue;
            Call owner_call(c, STR("GetOwner"));
            owner_call.run();
            UObject* owner = owner_call.object_result();
            if (!owner || owner == pawn) continue;
            if (owner == object_property(pawn, STR("Weapon L")) || owner == object_property(pawn, STR("Weapon R"))) continue;
            static const FName none_bone = FName(STR("None"), FNAME_Add);
            FName bone = none_bone;
            if (func_chain(c, STR("FindClosestBone_K2")))
            {
                Call fb(c, STR("FindClosestBone_K2"));
                fb.three(STR("TestLocation"), mid.x, mid.y, mid.z);
                fb.flag(STR("bRequirePhysicsAsset"), true);
                fb.run();
                if (FProperty* rp = fb.param(STR("ReturnValue"))) bone = *reinterpret_cast<FName*>(fb.buffer.data() + rp->GetOffset_Internal());
            }
            Call sim(c, STR("IsSimulatingPhysics"));
            sim.name(STR("BoneName"), bone);
            sim.run();
            FProperty* sp = sim.param(STR("ReturnValue"));
            if (!(sp && *(sim.buffer.data() + sp->GetOffset_Internal()))) continue;
            Call lv(c, STR("GetPhysicsLinearVelocity"));
            lv.name(STR("BoneName"), bone);
            lv.run();
            double speed = length(lv.vec()) / 100.0;
            if (speed < 0.5) continue;
            // A loose weapon (not his, not in a sheath or slot) moving near his legs: the worst since hsvr.mark (expect kick_speed).
            if (is_a(owner, STR("ModularWeaponBP_C")) && !bool_property(owner, STR("Is Sheathed")) && speed > g_kick_speed.load()) g_kick_speed.store(speed);
            int near_i = -1;
            double near_d = 1e9;
            for (int i = 0; i < 6; ++i)
            {
                Call cp(c, STR("GetClosestPointOnCollision"));
                cp.three(STR("Point"), leg_at[i].x, leg_at[i].y, leg_at[i].z);
                cp.name(STR("BoneName"), bone);
                cp.run();
                double d = cp.number();
                if (d >= 0.0 && d < near_d)
                {
                    near_d = d;
                    near_i = i;
                }
            }
            wchar_t buf[256];
            std::swprintf(buf, 256, L"%ls.%ls:%ls %.1f m/s, %.0f cm from his %hs; ", owner->GetName().c_str(), c->GetName().c_str(), bone.ToString().c_str(), speed,
                          near_d, near_i >= 0 ? legs[near_i] : "?");
            moving += buf;
        }
        if (!moving.empty()) HSVR_LOG("Crouch: %.0f cm down, moving near his legs: %ls", g_crouch_drop, moving.c_str());
    }

    // ---- Complex-only collision (scenery) -------------------------------------------------------
    // The Yard's fences and most of its scenery have no simple collision (347 of 597 static actors
    // within 15 m; GetClosestPointOnCollision gives -1 on the fence), only their triangles. Those are
    // measured with line traces against the component's triangles (K2_LineTraceComponent, complex).
    bool trace_component(UObject* c, const hsvr::Vec3& a, const hsvr::Vec3& b, hsvr::Vec3& hit, hsvr::Vec3& normal)
    {
        Call t(c, STR("K2_LineTraceComponent"));
        if (!t.fn) return false;
        t.three(STR("TraceStart"), a.x, a.y, a.z);
        t.three(STR("TraceEnd"), b.x, b.y, b.z);
        t.flag(STR("bTraceComplex"), true);
        t.flag(STR("bShowTrace"), false);
        t.flag(STR("bPersistentShowTrace"), false);
        if (!t.run()) return false;
        FProperty* r = t.param(STR("ReturnValue"));
        if (!r || !(*(t.buffer.data() + r->GetOffset_Internal()) & 1)) return false;
        hit = t.vec(STR("HitLocation"));
        normal = hsvr::normalized(t.vec(STR("HitNormal")));
        return true;
    }
    // n directions spread evenly over the sphere (Fibonacci).
    const std::vector<hsvr::Vec3>& sphere_dirs(int n)
    {
        static std::map<int, std::vector<hsvr::Vec3>> cache;
        std::vector<hsvr::Vec3>& d = cache[n];
        if (d.empty())
            for (int i = 0; i < n; ++i)
            {
                double z = 1.0 - (2.0 * i + 1.0) / n, r = std::sqrt((std::max)(0.0, 1.0 - z * z)), a = i * 2.39996322972865332;
                d.push_back(hsvr::Vec3{r * std::cos(a), r * std::sin(a), z});
            }
        return d;
    }
    // Nearest point of the component's triangles to `at` within `range` (cm), or -1.
    double closest_on_triangles(UObject* c, const hsvr::Vec3& at, double range, hsvr::Vec3* out, hsvr::Vec3* out_n = nullptr)
    {
        using namespace hsvr;
        double best = -1.0;
        Vec3 bp{0, 0, 0}, bn{0, 0, 1};
        for (const Vec3& d : sphere_dirs(42))
        {
            Vec3 h, n;
            if (!trace_component(c, at, at + d * range, h, n)) continue;
            double e = length(h - at);
            if (best < 0.0 || e < best) best = e, bp = h, bn = n;
        }
        if (best < 0.0) return -1.0;
        // The foot of the perpendicular on that face, when it is nearer.
        Vec3 h, n;
        if (trace_component(c, at, at - bn * (best + 1.0), h, n) && length(h - at) < best) best = length(h - at), bp = h, bn = n;
        if (out) *out = bp;
        if (out_n) *out_n = bn;
        return best;
    }
    // The engine's simple-collision distance, or the triangles' when it has none (a static mesh).
    double closest_point_any(UObject* c, FName bone, const hsvr::Vec3& at, double range, hsvr::Vec3* out)
    {
        Call cp(c, STR("GetClosestPointOnCollision"));
        cp.three(STR("Point"), at.x, at.y, at.z);
        cp.name(STR("BoneName"), bone);
        cp.run();
        double d = cp.number();
        if (d >= 0.0)
        {
            if (out) *out = d > 0.0 ? cp.vec(STR("OutPointOnBody")) : at;
            return d;
        }
        if (!is_a(c, STR("StaticMeshComponent"))) return -1.0;
        return closest_on_triangles(c, at, range, out);
    }

    bool grab_object(int side, UObject* pawn, UObject* mesh, const hsvr::Config& cfg, const hsvr::Vec3& at)
    {
        using namespace hsvr;
        const char* hand = side == 0 ? "left" : "right";
        static UObject* cdo = UObjectGlobals::StaticFindObject<UObject*>(nullptr, nullptr, STR("/Script/Engine.Default__KismetSystemLibrary"));
        if (!cdo) return false;
        static uint8_t types[32];
        for (int i = 0; i < 32; ++i) types[i] = (uint8_t)i;
        Call ov(cdo, STR("SphereOverlapComponents"));
        FProperty* ot = ov.param(STR("ObjectTypes"));
        FProperty* out = ov.param(STR("OutComponents"));
        if (!ot || !out)
        {
            HSVR_LOG("Grab: no SphereOverlapComponents, objects can't be grabbed");
            return false;
        }
        ov.object(STR("WorldContextObject"), pawn);
        ov.three(STR("SpherePos"), at.x, at.y, at.z);
        ov.number(STR("SphereRadius"), cfg.pose_grab_radius_cm);
        RawArray* list = reinterpret_cast<RawArray*>(ov.buffer.data() + ot->GetOffset_Internal());
        list->Data = reinterpret_cast<void**>(types);
        list->Num = list->Max = 32;
        ov.run();
        RawArray* found = reinterpret_cast<RawArray*>(ov.buffer.data() + out->GetOffset_Internal());
        std::vector<UObject*> components;
        for (int32_t i = 0; i < found->Num && found->Data; ++i) components.push_back(reinterpret_cast<UObject*>(found->Data[i]));
        found->Data = nullptr; // the engine's list; left (a few bytes per grab)
        found->Num = found->Max = 0;
        list->Data = nullptr;
        list->Num = list->Max = 0;

        static const FName none_bone = FName(STR("None"), FNAME_Add);
        UObject* best = nullptr;
        FName best_bone = none_bone;
        Vec3 best_point{0, 0, 0};
        double best_d = cfg.pose_grab_radius_cm;
        std::wstring seen;
        UObject* still = nullptr; // nearest fixed scenery that blocks (pose_grab_world)
        Vec3 still_point{0, 0, 0};
        double still_d = cfg.pose_grab_radius_cm;
        for (UObject* c : components)
        {
            if (!c) continue;
            Call owner_call(c, STR("GetOwner"));
            owner_call.run();
            UObject* owner = owner_call.object_result();
            if (!owner || owner == pawn) continue;
            if (is_a(owner, STR("ModularWeaponBP_C"))) continue;
            if (has_tag(c, STR("ComponentTags"), STR("NoGrab")) || has_tag(owner, STR("Tags"), STR("Sheathed"))) continue;
            FName bone = none_bone;
            bool skeletal = func_chain(c, STR("FindClosestBone_K2")) != nullptr;
            if (skeletal)
            {
                Call fb(c, STR("FindClosestBone_K2"));
                fb.three(STR("TestLocation"), at.x, at.y, at.z);
                fb.flag(STR("bRequirePhysicsAsset"), true);
                fb.run();
                if (FProperty* rp = fb.param(STR("ReturnValue"))) bone = *reinterpret_cast<FName*>(fb.buffer.data() + rp->GetOffset_Internal());
            }
            Call sim(c, STR("IsSimulatingPhysics"));
            sim.name(STR("BoneName"), bone);
            sim.run();
            FProperty* sp = sim.param(STR("ReturnValue"));
            bool simulating = sp && *(sim.buffer.data() + sp->GetOffset_Internal());
            seen += owner->GetName() + STR(".") + c->GetName() + (skeletal ? STR(":") + bone.ToString() : std::wstring()) + (simulating ? STR(" sim, ") : STR(" still, "));
            if (!simulating)
            {
                // Scenery: a static mesh that physically blocks (not a trigger box), not a person.
                if (!cfg.pose_grab_world || skeletal || is_a(owner, STR("Willie_BP_C")) || !is_a(c, STR("StaticMeshComponent"))) { seen += STR("(not scenery) "); continue; }
                Call ce(c, STR("GetCollisionEnabled"));
                ce.run();
                FProperty* cr = ce.param(STR("ReturnValue"));
                uint8_t enabled = cr ? *(ce.buffer.data() + cr->GetOffset_Internal()) : 0;
                if (enabled < 2) { seen += STR("(collision ") + std::to_wstring(enabled) + STR(") "); continue; } // NoCollision / QueryOnly
                Vec3 sp;
                double d = closest_point_any(c, bone, at, cfg.pose_grab_radius_cm, &sp);
                seen += STR("(") + std::to_wstring((int)std::lround(d)) + STR(" cm) ");
                if (d < 0.0 || d > still_d) continue;
                // Not the ground you stand on: a surface below the hand at his feet's height (playtest
                // 2026-11-23 17:23 local: reaching for a lantern on the floor, the grip took hold of the
                // floor and pinned his hand there). Ledges, walls, rails and table tops still hold.
                if (cfg.pose_grab_world_no_floor && mesh)
                {
                    double feet_z = (std::min)(socket_location(mesh, bone_fname("foot_l")).z, socket_location(mesh, bone_fname("foot_r")).z);
                    Vec3 up = d > 0.5 ? normalized(at - sp) : Vec3{0.0, 0.0, 0.0};
                    double top = feet_z + cfg.pose_grab_world_floor_cm;
                    // Or the spot is the top of a floor-like face: straight down onto it there finds an upward
                    // face that low (test 2026-11-24 a462c97: your controller was in the floor, 30 cm under his
                    // hand, and the floor was taken 8.6 cm from it).
                    bool floor_face = false;
                    if (sp.z < top)
                    {
                        Vec3 h, n;
                        floor_face = trace_component(c, Vec3{sp.x, sp.y, top + 20.0}, Vec3{sp.x, sp.y, sp.z - 5.0}, h, n) && n.z > 0.7 && h.z < top;
                    }
                    // Or at or below the ground he stands on, whichever way it faces: the edge of a neighbouring, lower
                    // floor tile (run 13 floor_no_grab: spots 5 and 11 cm under his feet, facing 17-21% up, were taken).
                    bool under_feet = sp.z <= feet_z + 2.0;
                    if (sp.z < top && (d <= 0.5 || up.z > 0.6 || floor_face || under_feet))
                    {
                        seen += STR("(the floor) ");
                        continue;
                    }
                    seen += STR("(spot z ") + std::to_wstring((int)std::lround(sp.z - feet_z)) + STR(" over his feet, up ") +
                            std::to_wstring((int)std::lround(up.z * 100.0)) + STR("%) ");
                }
                still_d = d;
                still = c;
                still_point = sp;
                continue;
            }
            Call closest(c, STR("GetClosestPointOnCollision"));
            closest.three(STR("Point"), at.x, at.y, at.z);
            closest.name(STR("BoneName"), bone);
            closest.run();
            double d = closest.number();
            if (d < 0.0 || d > best_d) continue;
            best_d = d;
            best = c;
            best_bone = bone;
            best_point = d > 0.0 ? closest.vec(STR("OutPointOnBody")) : at;
        }
        if (!best && still)
        {
            Call oc(still, STR("GetOwner"));
            oc.run();
            UObject* so = oc.object_result();
            WorldGrab& w = g_world[side];
            w.on = true;
            w.comp = still;
            w.point = still_point;
            w.since = now_seconds();
            controllers_buzz(side, 0.4f);
            HSVR_LOG("Grab: %s grip holds %ls.%ls (fixed scenery, %.1f cm from the hand, spot (%.0f %.0f %.0f), looked from (%.0f %.0f %.0f)): the hand stays on it; overlapping: %ls",
                     hand, so ? so->GetName().c_str() : STR("?"), still->GetName().c_str(), still_d, still_point.x, still_point.y, still_point.z, at.x, at.y, at.z,
                     seen.c_str());
            return true;
        }
        if (!best)
        {
            HSVR_LOG("Grab: %s grip squeezed, nothing to grab within %.0f cm (overlapping: %ls)", hand, cfg.pose_grab_radius_cm, seen.empty() ? STR("none") : seen.c_str());
            return false;
        }
        Call owner_call(best, STR("GetOwner"));
        owner_call.run();
        UObject* owner = owner_call.object_result();
        bool character = is_a(owner, STR("Willie_BP_C"));
        if (character && !func_chain(best, STR("FindClosestBone_K2")))
        {
            // Armour welded to him (14:04: a plate, NODE_AddStaticMeshComponent): the grab goes to his
            // body under it, the nearest bone, as the game's own grab would take him.
            UObject* body = object_property(owner, STR("Mesh"));
            if (body && func_chain(body, STR("FindClosestBone_K2")))
            {
                Call fb(body, STR("FindClosestBone_K2"));
                fb.three(STR("TestLocation"), at.x, at.y, at.z);
                fb.flag(STR("bRequirePhysicsAsset"), true);
                fb.run();
                FName nb = best_bone;
                if (FProperty* rp = fb.param(STR("ReturnValue"))) nb = *reinterpret_cast<FName*>(fb.buffer.data() + rp->GetOffset_Internal());
                Vec3 np;
                double nd = closest_point_any(body, nb, at, 30.0, &np);
                HSVR_LOG("Grab: %s grip touched %ls on %ls: takes his bone %ls under it (%.1f cm)", hand, best->GetName().c_str(), owner->GetName().c_str(), nb.ToString().c_str(), nd);
                best = body;
                best_bone = nb;
                if (nd >= 0.0) best_point = np, best_d = nd;
            }
        }
        bool L = side == 0;
        std::wstring missing;
        auto need = [&](bool ok, const TCHAR* n) { if (!ok) missing += std::wstring(n) + STR(", "); };
        bool blocked = bool_property(pawn, L ? STR("Block Grab L") : STR("Block Grab R")) || bool_property(pawn, L ? STR("Hand L Torn Off") : STR("Hand R Torn Off")) ||
                       bool_property(pawn, STR("Swapping weapons"));
        if (blocked) HSVR_LOG("Grab: %s hand: the game blocks grabbing right now (Block Grab / Torn Off / Swapping weapons)", hand);
        need(set_variable(pawn, L ? STR("Grab Component L") : STR("Grab Component R"), 0, best), L ? STR("Grab Component L") : STR("Grab Component R"));
        need(set_variable(pawn, L ? STR("Grab Bone L") : STR("Grab Bone R"), 0, nullptr, &best_bone), L ? STR("Grab Bone L") : STR("Grab Bone R"));
        UObject* grab_point = object_property(pawn, L ? STR("GrabPoint L") : STR("GrabPoint R"));
        need(grab_point != nullptr, L ? STR("GrabPoint L") : STR("GrabPoint R"));
        if (grab_point)
        {
            Call move(grab_point, STR("K2_SetWorldLocation"));
            move.three(STR("NewLocation"), best_point.x, best_point.y, best_point.z);
            move.run();
        }
        need(set_variable(pawn, L ? STR("Stuck Meter L Hand") : STR("Stuck Meter R Hand"), 0.0), L ? STR("Stuck Meter L Hand") : STR("Stuck Meter R Hand"));
        need(set_variable(pawn, L ? STR("Grab L Target Found") : STR("Grab R Target Found"), 1.0), L ? STR("Grab L Target Found") : STR("Grab R Target Found"));
        ObjectGrab& g = g_object_grab[side];
        g.component = best;
        g.bone = best_bone;
        g.point = best_point;
        g.character = character;
        g.since = now_seconds();
        g.fallback_tried = false;
        controllers_buzz(side, 0.4f);
        HSVR_LOG("Grab: %s grip on %ls.%ls bone %ls (%.1f cm from the hand)%ls: handed to the game's latch%ls%ls", hand, owner ? owner->GetName().c_str() : STR("?"),
                 best->GetName().c_str(), best_bone.ToString().c_str(), best_d, character ? STR(", a body") : STR(""), missing.empty() ? STR("") : STR("; missing: "),
                 missing.c_str());
        return true;
    }

    // A few ticks after handing an object to the game's latch: did the game grab it?
    void check_object_grab(int side, UObject* pawn)
    {
        using namespace hsvr;
        ObjectGrab& g = g_object_grab[side];
        if (!g.component || g.since < 0.0 || g.fallback_tried) return;
        double age = now_seconds() - g.since;
        bool L = side == 0;
        bool grabbed = bool_property(pawn, L ? STR("Grabbed L") : STR("Grabbed R"));
        if (grabbed)
        {
            HSVR_LOG("Grab: %s hand: the game grabbed %ls after %.2f s", L ? "left" : "right", g.component->GetName().c_str(), age);
            g.fallback_tried = true;
            return;
        }
        if (age < 0.3) return;
        g.fallback_tried = true;
        set_variable(pawn, L ? STR("Grab L Target Found") : STR("Grab R Target Found"), 0.0);
        if (g.character)
        {
            HSVR_LOG("Grab: %s hand: the game did not take the body in 0.3 s; left", L ? "left" : "right");
            return;
        }
        UFunction* fn = func_chain(pawn, L ? STR("Grab Specific Object L H") : STR("Grab Specific Object R H"));
        if (!fn)
        {
            HSVR_LOG("Grab: %s hand: the game did not take it and there is no Grab Specific Object", L ? "left" : "right");
            return;
        }
        Call c(pawn, L ? STR("Grab Specific Object L H") : STR("Grab Specific Object R H"));
        for (FProperty* p : c.fn->ForEachProperty())
            if (p->GetClass().GetName() == STR("ObjectProperty")) *reinterpret_cast<UObject**>(c.buffer.data() + p->GetOffset_Internal()) = g.component;
            else if (p->GetClass().GetName() == STR("StructProperty")) write_three(c.buffer.data() + p->GetOffset_Internal(), p, g.point.x, g.point.y, g.point.z);
        c.run();
        HSVR_LOG("Grab: %s hand: the game did not take it in 0.3 s; Grab Specific Object -> Grabbed %d", L ? "left" : "right",
                 (int)bool_property(pawn, L ? STR("Grabbed L") : STR("Grabbed R")));
    }

    // Lets go of an object or body the game's grab holds in that hand (Release Grab R/L).
    void disarm_end(int side);
    void release_object(int side, UObject* pawn)
    {
        bool L = side == 0;
        g_object_grab[side] = ObjectGrab{};
        disarm_end(side);
        if (g_world[side].on)
        {
            HSVR_LOG("Grab: %s hand lets go of %ls (held %.1f s)", L ? "left" : "right", object_alive(g_world[side].comp) ? g_world[side].comp->GetName().c_str() : STR("?"),
                     hsvr::now_seconds() - g_world[side].since);
            g_world[side] = WorldGrab{};
        }
        if (!bool_property(pawn, L ? STR("Grabbed L") : STR("Grabbed R"))) return;
        Call c(pawn, L ? STR("Release Grab L") : STR("Release Grab R"));
        bool ok = c.run();
        HSVR_LOG("Grab: %s grip let go: %ls (Grabbed now %d)", L ? "left" : "right", ok ? STR("Release Grab called") : STR("no Release Grab function"),
                 (int)bool_property(pawn, L ? STR("Grabbed L") : STR("Grabbed R")));
    }

    // ---- Handles (the grab rebuild, B&S-style) --------------------------------------------------
    // Every item's handles: segments in its BaseMesh frame a hand can hold and slide along. Weapons:
    // the grip (measured along the axis from the real parts: the haft of a polearm, a sword's grip
    // between guard and pommel) and the blade past the guard (half-swording). Shields: each measured
    // strap and handle. Anywhere else on an item, the hand holds it where it touched, with no slide.
    struct Handle
    {
        hsvr::Vec3 a, b;
        std::string name;
        int grip_r = -1, grip_l = -1; // finger shape for that hand (-1 = the game's own)
        // A fixed grip (a one-handed sword's): touching anywhere on a..b takes it, but the hand always
        // holds it at a + (b - a) * fixed_t and never slides along it.
        bool fixed = false;
        double fixed_t = 0.0;
        // A fixed hand pose (a crossbow's grips, Matthew 2026-11-23: "there's pretty much only one way that
        // you grab a crossbow"): the seat is never the one nearest to how the hand came; it is the one whose
        // forearm points most along seat_forearm (BaseMesh frame, down and back from the grip). Zero = off.
        hsvr::Vec3 seat_forearm{0, 0, 0};
    };
    const std::vector<Handle>& item_handles(UObject* item, UObject* base);
    // Weapons and tools are taken only by a handle; shields and bottles anywhere.
    bool grab_needs_handle(UObject* item)
    {
        if (!item) return false;
        std::wstring cls = item->GetClassPrivate() ? item->GetClassPrivate()->GetName() : std::wstring();
        if (cls.rfind(STR("Shield"), 0) == 0) return false;
        if (cls.find(STR("Consumable")) != std::wstring::npos || cls.find(STR("Bottle")) != std::wstring::npos) return false;
        if (cls.find(STR("Fists")) != std::wstring::npos) return false;
        return true;
    }
    int nearest_handle(const std::vector<Handle>& hs, const hsvr::Vec3& local, double& t, double& dist);
    FreeGrip make_free_grip(int side, UObject* mesh, const hsvr::Vec3& w0_pos, const hsvr::Quat& w0_rot, const hsvr::Vec3& palm, const hsvr::Vec3& point,
                            const hsvr::Vec3* axis, const char* what);
    FreeGrip handle_grip(int side, UObject* mesh, const hsvr::Vec3& w0_pos, const hsvr::Quat& w0_rot, const hsvr::Vec3& palm, const Handle& hd, double t);
    int clamp_grip_type(int side, int g);
    double closest_on_weapon(UObject* weapon, const hsvr::Vec3& point, hsvr::Vec3* out = nullptr, UObject** out_part = nullptr);
    bool class_name_starts(UObject* object, const TCHAR* prefix);
    // A shield touched away from its straps and handles: may the hand take it there (its rim, not a face)?
    bool shield_off_handle_ok(int side, UObject* shield, UObject* base, const hsvr::Vec3& hand, const hsvr::Config& cfg);
    // A pavise that hand wears on its forearm (pose_pavise_forearm): the game's own strap grip for that hand.
    bool pavise_on_forearm(UObject* shield, int side, const hsvr::Config& cfg);

    // The grab button (Phase 4): squeezing a controller's grip with that hand empty picks up the
    // nearest loose weapon whose body is within pose_grab_radius_cm of the hand; letting go of the
    // grip drops what that hand holds (B&S-style hold-to-hold). A weapon he already holds when the
    // grip is not squeezed (one he spawned with) stays until the next squeeze-and-release.
    // Weapons only for now: objects and bodies need the game's latch tick (grab_pickup.md).
    // ---- Two hands on one weapon ---------------------------------------------------------------
    // B&S rules (Matthew's spec 2026-11-18): the free hand squeezes on a weapon the other hand holds,
    // on its grip or directly on the blade anywhere along it (half-swording, as in real life and the
    // B&S MegaPack). The first hand keeps the game's hold; the weapon then lies along the line from
    // the first hand's grip point to the second's, the first hand sets its roll, and the hold is
    // pose_two_hand_strength times as strong. The second hand's arm is posed onto its spot on the
    // weapon. Its trigger slides it along the zone it is on, as the first hand's does.
    struct TwoHand
    {
        bool active = false;
        int main = 1, second = 0;
        UObject* weapon = nullptr;
        hsvr::Quat last_rot;       // last tick's two-hand target turn (diagnostics: how far it jumps per tick)
        bool have_last_rot = false;
        double z = 0.0;            // the second hand's spot along the weapon, cm from the game's grip point
        bool on_blade = false;
        hsvr::Vec3 local{0, 0, 0}; // that spot in BaseMesh's frame (set by the hold each tick)
        hsvr::Vec3 in_hand{0, 0, 0}; // the palm point in the second hand bone's frame (the first's, mirrored)
        bool have_local = false;
        double far_since = -1.0;
        bool sliding = false;
        double grip_type_before = -1.0; // the second hand's grip type before it took hold (its finger pose)
        int anim_grip = -1;              // the second hand's finger shape (handle system)
        // The handle system (pose_grab_handles): the second hand's own grip on the weapon.
        bool use_rel = false;
        hsvr::Quat rel;              // weapon rotation in the second hand's frame
        bool has_handle = false;
        hsvr::Vec3 ha, hb;
        double t = 0.0;
        std::string handle;
        double couple = 0.0; // the second hand's force x the hands' distance on the weapon (kg cm^2/s^2), this tick
        // B&S hold: the second hand's palm point (world), its velocity, and its spot on the weapon (BaseMesh frame).
        hsvr::Vec3 bs_p2, bs_vel, bs_local;
        bool bs_valid = false;
        double slide_c = 300.0; // its slide damper (N s/m) this tick, from its trigger (B&S 300 .. 20)
    };
    TwoHand g_two;
    bool two_hands_hold(UObject* weapon) { return g_two.active && g_two.weapon == weapon; }
    bool is_crossbow(UObject* w);
    // Both hands on this weapon, held as B&S holds two hands (pose_two_hand_bs, on the joint hold): every two-hand weapon but the
    // crossbow, whose two fixed grips keep the one-pose line (Matthew 2026-11-23 13:56Z: it aims "exactly how one would expect").
    bool two_hands_bs(UObject* weapon, const hsvr::Config& cfg)
    {
        return cfg.pose_two_hand_bs && cfg.pose_hold_joint && two_hands_hold(weapon) && !is_crossbow(weapon);
    }

    // The second hand's fingers: the game curls a hand's fingers from its grip type (ABP_Willie copies
    // L/R_GripType_Current, @153084; 1-4 play the sword grip, hand_pose.md), which it sets only for a
    // hand it gave a weapon. While the second hand holds, its grip type is the sword grip (2).
    const TCHAR* grip_type_name(int side) { return side == 0 ? STR("L_GripType_Current") : STR("R_GripType_Current"); }
    double read_number_variable(UObject* owner, const TCHAR* name)
    {
        FProperty* p = owner ? prop_chain(owner, name) : nullptr;
        if (!p) return -1.0;
        uint8_t* at = reinterpret_cast<uint8_t*>(owner) + p->GetOffset_Internal();
        auto kind = p->GetClass().GetName();
        if (kind == STR("IntProperty")) return *reinterpret_cast<int32_t*>(at);
        if (kind == STR("ByteProperty") || kind == STR("EnumProperty")) return *at;
        if (kind == STR("DoubleProperty")) return *reinterpret_cast<double*>(at);
        if (kind == STR("FloatProperty")) return *reinterpret_cast<float*>(at);
        return -1.0;
    }
    double g_pending_slide[2] = {1e9, 1e9}; // a hand-over: where the new hand holds, applied when its hold starts

    bool is_second_hand(int side) { return g_two.active && g_two.second == side; }
    void end_two_hand(const char* why)
    {
        if (!g_two.active) return;
        if (g_two.grip_type_before >= 0.0 && g_pose.pawn)
        {
            double was = read_number_variable(g_pose.pawn, grip_type_name(g_two.second));
            bool ok = set_variable(g_pose.pawn, grip_type_name(g_two.second), g_two.grip_type_before);
            HSVR_LOG("Two hands: %s hand's grip type %.0f -> %.0f restored%s (first hand's now %.0f)", g_two.second == 0 ? "left" : "right", was, g_two.grip_type_before,
                     ok ? "" : ": NOT SET", read_number_variable(g_pose.pawn, grip_type_name(g_two.main)));
        }
        HSVR_LOG("Two hands: %s hand lets go of %ls (%s)", g_two.second == 0 ? "left" : "right", g_two.weapon ? g_two.weapon->GetName().c_str() : STR("?"), why);
        if (g_two.weapon && g_arm_ignore[g_two.second].weapon == g_two.weapon)
        {
            // B&S (RagdollHand.HandOverlapCoroutine, RagdollHand.cs:1502-1548): a hand that lets go keeps ignoring the item until
            // collisionUngrabMinDelay 0.25 s has passed AND a collisionUngrabRadius 0.13 m sphere at its grip is clear. With the free
            // hand solid, letting go inside the haft kicked it (5e085fa switch2_warstaff: 559 deg/s, then dropped).
            if (hsvr::config().pose_hold_release_ignore_s > 0.0 && g_hold[g_two.main].weapon == g_two.weapon)
            {
                g_release_linger[g_two.second] = {g_two.weapon, hsvr::now_seconds()};
                HSVR_LOG("Two hands: %s hand keeps passing through %ls until it is %.0f cm clear (at least %.2f s)", g_two.second == 0 ? "left" : "right",
                         g_two.weapon->GetName().c_str(), hsvr::config().pose_hold_release_clear_cm, hsvr::config().pose_hold_release_ignore_s);
            }
            else
                clear_arm_ignore(g_two.second);
        }
        g_two = TwoHand{};
        g_anim_grip_two_side = -1;
    }

    // The zones the second hand may hold, cm from the game's grip point: the grip (the first hand's
    // slide zone) and, past the guard, the blade up to half a hand short of the tip.
    int two_hand_zones(const HoldState& h, const hsvr::Config& cfg, double lo[2], double hi[2])
    {
        int n = 0;
        if (h.zone_hi > h.zone_lo)
        {
            lo[n] = h.zone_lo;
            hi[n] = h.zone_hi;
            ++n;
        }
        double half = cfg.pose_slide_hand_half_cm;
        double blade_lo = h.zone_stop + half + cfg.pose_two_hand_blade_gap_cm, blade_hi = h.zone_tip - half;
        if (h.zone_stop > 0.0 && blade_hi > blade_lo + 2.0)
        {
            lo[n] = blade_lo;
            hi[n] = blade_hi;
            ++n;
        }
        return n;
    }

    // Clamps z into the zone it is in or nearest (within reach); keeps a hand's width from the first
    // hand at `main_z`. Returns the zone's index, or -1 when z is out of reach of every zone.
    int two_hand_place(double& z, double main_z, const double lo[2], const double hi[2], int n, double reach, double half)
    {
        int best = -1;
        double best_d = reach;
        for (int i = 0; i < n; ++i)
        {
            double d = z < lo[i] ? lo[i] - z : (z > hi[i] ? z - hi[i] : 0.0);
            if (d <= best_d)
            {
                best_d = d;
                best = i;
            }
        }
        if (best < 0) return -1;
        z = (std::min)(hi[best], (std::max)(lo[best], z));
        if (std::fabs(z - main_z) < 2.0 * half)
        {
            z = main_z + (z >= main_z ? 2.0 : -2.0) * half;
            if (z < lo[best] || z > hi[best]) return -1;
        }
        return best;
    }

    void find_grip_zone(HoldState& h, UObject* weapon, UObject* base, const hsvr::Config& cfg);
    bool room_component_box(UObject* c, hsvr::Vec3& origin, hsvr::Vec3& extent);

    // The first hand lets go while both hold (B&S): the weapon stays in the second hand, where it holds
    // it. The game moves it into that hand (Set Up Hand Weapon snaps its grip to the hand socket), so
    // it is put back where it was, and the new hold starts at the second hand's spot.
    bool hand_over(UObject* pawn)
    {
        using namespace hsvr;
        if (!g_two.active) return false;
        int to = g_two.second, from = g_two.main;
        UObject* weapon = g_two.weapon;
        UObject* base = weapon ? object_property(weapon, STR("BaseMesh")) : nullptr;
        if (!base) return false;
        double z = g_two.z;
        Vec3 pos = component_location(base);
        Quat rot = component_rotation(base);
        FreeGrip keep;
        if (g_two.use_rel)
        {
            // The handle system: the second hand keeps its own grip as it was.
            keep.set = true;
            keep.pivot = g_two.local;
            keep.in_anchor = g_two.in_hand;
            keep.rel = g_two.rel;
            keep.what = g_two.handle;
            keep.has_handle = g_two.has_handle;
            keep.ha = g_two.ha;
            keep.hb = g_two.hb;
            keep.t = g_two.t;
            keep.handle = g_two.handle;
            keep.grip_type = hsvr::config().pose_fingers_anim_only ? g_two.anim_grip
                             : g_two.grip_type_before >= 0.0 ? (int)read_number_variable(pawn, grip_type_name(to)) : -1;
            keep.hold_at = true;
            keep.at_pos = pos;
            keep.at_rot = rot;
        }
        g_two = TwoHand{};
        g_anim_grip_two_side = -1;
        drop_weapon(from, pawn);
        bool ok = give_hand_weapon(to, pawn, weapon);
        UObject* now = object_property(pawn, to == 0 ? STR("Weapon L") : STR("Weapon R"));
        if (now == weapon)
        {
            set_component_transform(base, pos, rot, true);
            if (keep.set)
            {
                g_pending_free[to] = keep;
                g_pending_item[to] = weapon;
            }
            else g_pending_slide[to] = z;
        }
        HSVR_LOG("Two hands: %s hand lets go, %ls handed to the %s hand at %.1f cm (%s, %s hand now holds %ls)", from == 0 ? "left" : "right", weapon->GetName().c_str(),
                 to == 0 ? "left" : "right", z, ok ? "set up" : "set-up call missing", to == 0 ? "left" : "right", now ? now->GetName().c_str() : STR("nothing"));
        return now == weapon;
    }

    // A squeeze with an empty hand: onto the weapon the other hand holds, if the hand is on it.
    bool try_two_hand(int side, UObject* pawn, UObject* mesh, const hsvr::Config& cfg)
    {
        using namespace hsvr;
        if (!cfg.pose_two_hand) return false;
        int other = 1 - side;
        UObject* weapon = object_property(pawn, other == 0 ? STR("Weapon L") : STR("Weapon R"));
        HoldState& h = g_hold[other];
        if (!weapon || h.weapon != weapon || !h.have_last || is_fist(weapon) || h.forearm || h.free.set) return false; // the mod's free grip has no grip zones yet
        UObject* base = object_property(weapon, STR("BaseMesh"));
        if (!base) return false;
        double game_z = h.pivot.z - h.slide;
        if (!h.zone_known)
        {
            Vec3 keep = h.pivot;
            h.pivot.z = game_z;
            find_grip_zone(h, weapon, base, cfg);
            h.pivot = keep;
        }
        Vec3 bp = component_location(base);
        Quat bq = component_rotation(base);
        Vec3 at = hand_grab_point(mesh, side);
        Vec3 L = bq.inverse().rotate(at - bp);
        double radial = std::hypot(L.x - h.pivot.x, L.y - h.pivot.y);
        double want = L.z - game_z;
        if (radial > cfg.pose_grab_radius_cm)
        {
            HSVR_LOG("Two hands: %s grip squeezed %.0f cm off the axis of %ls (%.0f cm along it), not on it", side == 0 ? "left" : "right", radial,
                     weapon->GetName().c_str(), want);
            return false;
        }
        double lo[2], hi[2];
        int n = two_hand_zones(h, cfg, lo, hi);
        double z = want;
        int zone = two_hand_place(z, h.slide, lo, hi, n, cfg.pose_two_hand_reach_cm, cfg.pose_slide_hand_half_cm);
        if (zone < 0)
        {
            HSVR_LOG("Two hands: %s grip squeezed on %ls at %.1f cm, outside its zones (%d zones: %.1f..%.1f / %.1f..%.1f; first hand at %.1f)",
                     side == 0 ? "left" : "right", weapon->GetName().c_str(), want, n, n > 0 ? lo[0] : 0.0, n > 0 ? hi[0] : 0.0, n > 1 ? lo[1] : 0.0,
                     n > 1 ? hi[1] : 0.0, h.slide);
            return false;
        }
        // A fist still in this hand (made by an earlier empty squeeze) would sit inside the handle and
        // shove it every tick (playtest 02:44: a fist was in the second hand in 3 of the two-hand holds;
        // the game's whoosh plays on that tick-to-tick shove, "frozen but swooshing").
        if (is_fist(object_property(pawn, side == 0 ? STR("Weapon L") : STR("Weapon R")))) remove_fist(side, pawn, "the hand takes a weapon in two hands");
        g_two = TwoHand{};
        g_two.active = true;
        g_two.main = other;
        g_two.second = side;
        g_two.weapon = weapon;
        g_two.z = z;
        g_two.on_blade = lo[zone] > h.zone_stop && h.zone_stop > 0.0;
        // Willie's hands mirror across the hand bone's X (kick test 15: a weapon in the left hand sits
        // at the right's place with X negated).
        g_two.in_hand = Vec3{-h.in_hand.x, h.in_hand.y, h.in_hand.z};
        if (cfg.pose_fingers_anim_only)
        {
            g_anim_grip_two = clamp_grip_type(side, 2);
            g_anim_grip_two_side = side;
        }
        else if (cfg.pose_two_hand_curl)
        {
            g_two.grip_type_before = read_number_variable(pawn, grip_type_name(side));
            bool ok = set_variable(pawn, grip_type_name(side), 2.0);
            HSVR_LOG("Two hands: %s hand's grip type %.0f -> 2 (sword grip fingers)%s", side == 0 ? "left" : "right", g_two.grip_type_before, ok ? "" : ": NOT SET");
            if (!ok) g_two.grip_type_before = -1.0;
        }
        // The second hand's own forearm must not collide with the weapon either (playtest 10:35: two-handed,
        // the sword stood still while the hands moved up to 28 cm away, then caught up, over and over,
        // "contact miss" = "stopped" at 16-50 N: the left hand body sat on the grip. The game switches
        // that pair's collision off only for grips that list hand_l (self_collision.md).)
        if (UObject* m = object_property(pawn, STR("Mesh"))) ignore_arm_collision(pawn, m, weapon, object_property(weapon, STR("BaseMesh")), side);
        controllers_buzz(side, 0.4f);
        HSVR_LOG("Two hands: %s hand takes %ls on the %s at %.1f cm (squeezed at %.1f, %.1f cm off the axis; first hand at %.1f)", side == 0 ? "left" : "right",
                 weapon->GetName().c_str(), g_two.on_blade ? "blade" : "grip", z, want, radial, h.slide);
        return true;
    }

    // The handle system's second hand (B&S): the free hand squeezes on a weapon the other hand holds,
    // touching it (pose_grab_touch_cm): it holds the nearest handle (grip, blade, a strap) lined up
    // with its grip line, or the spot it touched. The weapon then lies along the line between the two
    // hands' points, the first hand sets its roll, and the hold is pose_two_hand_strength as strong.
    bool held_by_strap(int side, UObject* w);
    bool try_second_hand(int side, UObject* pawn, UObject* mesh, const hsvr::Config& cfg)
    {
        using namespace hsvr;
        if (!cfg.pose_two_hand) return false;
        int other = 1 - side;
        UObject* weapon = object_property(pawn, other == 0 ? STR("Weapon L") : STR("Weapon R"));
        HoldState& h = g_hold[other];
        if (!weapon || h.weapon != weapon || !h.have_last || is_fist(weapon) || h.forearm) return false;
        // Not a blade on its way into or out of a scabbard (playtest 02:44: the off hand reaching for
        // the scabbard took the sheathing sword's blade, and the two holds froze it).
        if (g_draw[other].active && g_draw[other].weapon == weapon) return false;
        // Held by its rear strap a pavise is held in one hand (its strap passes: pavise_pass).
        if (cfg.pose_pavise_strap && held_by_strap(other, weapon)) return false;
        UObject* base = object_property(weapon, STR("BaseMesh"));
        if (!base) return false;
        Vec3 at = hand_grab_point(mesh, side);
        double touch_d = closest_on_weapon(weapon, at);
        // Your own hand's place (before the rest stops hold his drawn hand off the weapon): the solid free hand rests 4 cm off it and its
        // body further (f790b94 runs: retakes squeezed 11-31 cm off). B&S takes by touch of your controller-driven hand.
        if (g_free_palm_valid[side])
        {
            double d2 = closest_on_weapon(weapon, g_free_palm_unstopped[side]);
            if (d2 >= 0.0 && (touch_d < 0.0 || d2 < touch_d))
            {
                HSVR_LOG("Two hands: %s grip squeezed %.1f cm from %ls by your hand (%.1f by his drawn hand, held off it)", side == 0 ? "left" : "right", d2,
                         weapon->GetName().c_str(), touch_d);
                touch_d = d2;
                at = g_free_palm_unstopped[side];
            }
        }
        if (touch_d < 0.0 || touch_d > cfg.pose_grab_touch_cm)
        {
            HSVR_LOG("Two hands: %s grip squeezed %.0f cm from %ls (needs %.0f), not on it", side == 0 ? "left" : "right", touch_d, weapon->GetName().c_str(),
                     cfg.pose_grab_touch_cm);
            return false;
        }
        Vec3 bp = component_location(base);
        Quat bq = component_rotation(base);
        Vec3 local = bq.inverse().rotate(at - bp);
        const std::vector<Handle>& hs = item_handles(weapon, base);
        double t = 0.0, hd = 1e9;
        int hi = nearest_handle(hs, local, t, hd);
        // The first hand's point on the weapon: h.pivot, set every hold tick whether the game's set-up or the mod's
        // free grip placed it. (Checked against h.free.pivot only, a weapon the game had put in the first hand let
        // the second hand take the first hand's own spot: playtest 2026-11-23, the long bastard sword's lower zone
        // and an arming sword's grip, "the offhand sits inside the main hand".)
        const Vec3 first_spot = h.pivot;
        if (hi >= 0 && hs[hi].fixed &&
            length(hs[hi].a + (hs[hi].b - hs[hi].a) * hs[hi].fixed_t - first_spot) < 2.0 * cfg.pose_slide_hand_half_cm)
        {
            // The first hand holds that fixed zone: the nearest other zone (a hand-and-a-half sword's other grip zone).
            std::vector<Handle> others;
            std::vector<int> idx;
            for (int i = 0; i < (int)hs.size(); ++i)
                if (i != hi && !(hs[i].fixed && length(hs[i].a + (hs[i].b - hs[i].a) * hs[i].fixed_t - first_spot) < 2.0 * cfg.pose_slide_hand_half_cm))
                {
                    others.push_back(hs[i]);
                    idx.push_back(i);
                }
            double t2 = 0.0, d2 = 1e9;
            int j = nearest_handle(others, local, t2, d2);
            if (j >= 0 && d2 <= cfg.pose_grab_handle_cm)
            {
                hi = idx[j];
                t = t2;
                hd = d2;
            }
        }
        bool on_handle = hi >= 0 && hd <= cfg.pose_grab_handle_cm;
        if (!on_handle && cfg.pose_grab_weapon_handles_only && grab_needs_handle(weapon))
        {
            HSVR_LOG("Two hands: %s grip squeezed on %ls off its handles (nearest %s %.1f cm away): not taken", side == 0 ? "left" : "right",
                     weapon->GetName().c_str(), hi >= 0 ? hs[hi].name.c_str() : "none", hd);
            return false;
        }
        if (!on_handle && class_name_starts(weapon, STR("Shield")) && !shield_off_handle_ok(side, weapon, base, at, cfg)) return false;
        Vec3 spot = local;
        if (!on_handle)
        {
            Vec3 touch;
            if (closest_on_weapon(weapon, at, &touch) >= 0.0) spot = bq.inverse().rotate(touch - bp);
        }
        // On a sliding handle the hand goes beside the first hand, on the side it touched, never inside it
        // (Matthew 2026-11-23: "between the bottom of the main hand and the top of the pommel ... not on the main hand").
        if (on_handle && !hs[hi].fixed && length(hs[hi].b - hs[hi].a) > 1e-3)
        {
            Vec3 ab = hs[hi].b - hs[hi].a;
            double len = length(ab);
            double tf = dot(first_spot - hs[hi].a, ab) / (len * len);
            double radial_first = length(hs[hi].a + ab * tf - first_spot);
            double gap = 2.0 * cfg.pose_slide_hand_half_cm;
            if (radial_first < gap && std::fabs(t - tf) * len < gap)
            {
                double side_sign = t >= tf ? 1.0 : -1.0;
                double t2 = tf + side_sign * gap / len;
                if (t2 < 0.0 || t2 > 1.0) t2 = tf - side_sign * gap / len; // no room that side: the other side
                if (t2 < -1e-6 || t2 > 1.0 + 1e-6)
                {
                    HSVR_LOG("Two hands: %s grip squeezed on %ls's %s: no room beside the first hand (%.1f cm of %s, a hand needs %.1f)", side == 0 ? "left" : "right",
                             weapon->GetName().c_str(), hs[hi].name.c_str(), len + gap, hs[hi].name.c_str(), 2.0 * gap);
                    return false;
                }
                HSVR_LOG("Two hands: %s hand moved beside the first hand on %ls's %s: %.1f -> %.1f cm along it", side == 0 ? "left" : "right", weapon->GetName().c_str(),
                         hs[hi].name.c_str(), t * len, t2 * len);
                t = (std::min)(1.0, (std::max)(0.0, t2));
                spot = hs[hi].a + ab * t;
            }
        }
        // Not on the first hand's own spot.
        if (length(spot - first_spot) < 2.0 * cfg.pose_slide_hand_half_cm - 0.01)
        {
            HSVR_LOG("Two hands: %s grip squeezed on the first hand's spot of %ls", side == 0 ? "left" : "right", weapon->GetName().c_str());
            return false;
        }
        FreeGrip g = on_handle ? handle_grip(side, mesh, bp, bq, at, hs[hi], t)
                               : make_free_grip(side, mesh, bp, bq, at, bp + bq.rotate(spot), nullptr, "spot where the hand touched it");
        // A fist still in this hand (made by an earlier empty squeeze) would sit inside the handle and
        // shove it every tick (playtest 02:44: a fist was in the second hand in 3 of the two-hand holds;
        // the game's whoosh plays on that tick-to-tick shove, "frozen but swooshing").
        if (is_fist(object_property(pawn, side == 0 ? STR("Weapon L") : STR("Weapon R")))) remove_fist(side, pawn, "the hand takes a weapon in two hands");
        g_two = TwoHand{};
        g_two.active = true;
        g_two.main = other;
        g_two.second = side;
        g_two.weapon = weapon;
        g_two.use_rel = true;
        g_two.rel = g.rel;
        g_two.in_hand = g.in_anchor;
        g_two.local = g.pivot;
        g_two.have_local = true;
        g_two.has_handle = g.has_handle;
        g_two.ha = g.ha;
        g_two.hb = g.hb;
        g_two.t = g.t;
        g_two.handle = on_handle ? hs[hi].name : std::string("spot");
        g_two.on_blade = on_handle && hs[hi].name == "blade";
        int gt = on_handle ? clamp_grip_type(side, side == 1 ? hs[hi].grip_r : hs[hi].grip_l) : 5;
        if (gt < 0) gt = 2;
        g_two.anim_grip = gt;
        if (cfg.pose_fingers_anim_only)
        {
            g_anim_grip_two = gt;
            g_anim_grip_two_side = side;
        }
        else if (cfg.pose_two_hand_curl)
        {
            g_two.grip_type_before = read_number_variable(pawn, grip_type_name(side));
            if (!set_variable(pawn, grip_type_name(side), gt)) g_two.grip_type_before = -1.0;
        }
        // The second hand's own forearm must not collide with the weapon either (playtest 10:35: two-handed,
        // the sword stood still while the hands moved up to 28 cm away, then caught up, over and over,
        // "contact miss" = "stopped" at 16-50 N: the left hand body sat on the grip. The game switches
        // that pair's collision off only for grips that list hand_l (self_collision.md).)
        if (UObject* m = object_property(pawn, STR("Mesh"))) ignore_arm_collision(pawn, m, weapon, object_property(weapon, STR("BaseMesh")), side);
        controllers_buzz(side, 0.4f);
        HSVR_LOG("Two hands: %s hand takes %ls by its %s (%.1f cm from the handle, touched at %.1f cm), at (%.1f, %.1f, %.1f) on it, fingers %d",
                 side == 0 ? "left" : "right", weapon->GetName().c_str(), g_two.handle.c_str(), on_handle ? hd : 0.0, touch_d, spot.x, spot.y, spot.z, gt);
        return true;
    }

    // The second hand's arm: its palm on its spot on the weapon, and the hand locked onto the weapon
    // the way the first hand holds it, mirrored (playtest 2026-11-18: following the controller's turn,
    // it twisted and clipped through the handle). Willie's hands mirror across the hand bone's X and
    // the weapon's Y (kick test 15: a weapon in the left hand has X and Z mirrored in the hand frame,
    // so Y flips), so the second hand's weapon frame is M_hand * R_first * M_weapon.
    // Where an item will be once this frame's physics has moved it (pos/rot in: as it is now).
    // pose_hold_hand_follows_predict 1 (default): from how the item actually moved between the last two
    // frames, at most pose_hold_follow_predict_max_cm / 30 deg ahead. 2: from the velocity the physics
    // reports now (the old way): that is the velocity the hold asked for, so when something blocks
    // the item (or Chaos pushes it out of a contact) it can be metres a second off what the item
    // does, and the drawn hand jumped up to 43 cm for a frame (playtest 2026-11-19 10:04, item still).
    // 0: no prediction (the hand a frame behind the item).
    struct ItemTrack
    {
        hsvr::Vec3 pos, prev_pos;
        hsvr::Quat rot, prev_rot;
        double t = 0.0, prev_t = 0.0;
        bool have = false, have_prev = false;
        hsvr::Vec3 v, w;        // smoothed measured velocity (cm/s) and turn rate (rad/s)
        bool have_v = false;
    };
    std::unordered_map<UObject*, ItemTrack> g_item_track;
    double world_delta_seconds(UObject* context);
    void predicted_item_pose(UObject* base, hsvr::Vec3& pos, hsvr::Quat& rot)
    {
        using namespace hsvr;
        const Config& cfg = hsvr::config();
        int mode = cfg.pose_hold_hand_follows_predict;
        if (mode <= 0 || !base) return;
        if (g_pose_post_physics.load()) return; // the item is already where it is drawn this frame
        double DT = world_delta_seconds(g_pose.pawn);
        if (!(DT > 1e-4 && DT < 0.1)) DT = 1.0 / 90.0;
        if (mode >= 2)
        {
            Call cm(base, STR("GetCenterOfMass"));
            cm.run();
            Call lv(base, STR("GetPhysicsLinearVelocity"));
            lv.run();
            Call av(base, STR("GetPhysicsAngularVelocityInRadians"));
            av.run();
            Vec3 com = cm.vec(), v = lv.vec(), w = av.vec();
            Quat dq = from_scaled_axis(w * DT);
            Vec3 com2 = com + v * DT + Vec3{0.0, 0.0, -980.0 * DT * DT};
            pos = com2 + dq.rotate(pos - com);
            rot = (dq * rot).normalized();
            return;
        }
        // A new frame when the item has moved or 3 ms have passed (several calls a frame read the same pose).
        if (g_item_track.size() > 64) g_item_track.clear();
        ItemTrack& k = g_item_track[base];
        double now = now_seconds();
        bool moved = !k.have || length(pos - k.pos) > 1e-4 || length(scaled_axis((rot * k.rot.inverse()).normalized())) > 1e-6;
        if (!k.have || (moved && now - k.t > 0.003) || now - k.t > 0.1)
        {
            k.prev_pos = k.pos;
            k.prev_rot = k.rot;
            k.prev_t = k.t;
            k.have_prev = k.have;
            k.pos = pos;
            k.rot = rot;
            k.t = now;
            k.have = true;
        }
        double gap = k.t - k.prev_t;
        if (!k.have_prev || !(gap > 0.002 && gap < 0.05)) return;
        // Its velocity from the last two frames, smoothed over pose_hold_follow_predict_smooth_s (once per
        // new frame): straight frame-to-frame extrapolation tripled the item's own frame-to-frame jerk in
        // the hand (playtest 10:36: hand target 2nd difference p50 7.9 cm against the grip's 2.7 on the
        // worst ticks).
        if (k.t != k.prev_t && now == k.t)
        {
            Vec3 v_now = (k.pos - k.prev_pos) * (1.0 / gap);
            Vec3 w_now = scaled_axis((k.rot * k.prev_rot.inverse()).normalized()) * (1.0 / gap);
            double a = cfg.pose_hold_follow_predict_smooth_s > 1e-4 ? 1.0 - std::exp(-gap / cfg.pose_hold_follow_predict_smooth_s) : 1.0;
            if (!k.have_v) k.v = v_now, k.w = w_now, k.have_v = true;
            else k.v = k.v + (v_now - k.v) * a, k.w = k.w + (w_now - k.w) * a;
        }
        if (!k.have_v) return;
        Vec3 step = k.v * DT;
        Vec3 turn = k.w * DT;
        step = clamp_length(step, (std::max)(0.0, cfg.pose_hold_follow_predict_max_cm));
        turn = clamp_length(turn, 30.0 / 57.2958);
        Quat dq = from_scaled_axis(turn);
        // The item's origin moves on by `step` and the item turns about it by `turn`.
        pos = pos + step;
        rot = (dq * rot).normalized();
    }

    bool two_hand_pose(int side, hsvr::Vec3& target, hsvr::Quat& hand_rot)
    {
        using namespace hsvr;
        if (!g_two.active) return false;
        if (side == g_two.main)
        {
            // The first hand too sits on the weapon as it holds it while both hands hold: the weapon
            // follows the line between your hands, not the first controller's turn.
            if (!hsvr::config().pose_two_hand_lock_rotation) return false;
            const HoldState& h = g_hold[side];
            if (h.weapon != g_two.weapon || !h.have_last) return false;
            UObject* b = object_property(g_two.weapon, STR("BaseMesh"));
            if (!b) return false;
            Quat wr = component_rotation(b);
            Vec3 wp = component_location(b);
            if (hsvr::config().pose_hold_hand_follows) predicted_item_pose(b, wp, wr);
            hand_rot = (wr * (h.f2 * h.f1.inverse()).normalized().inverse()).normalized();
            target = wp + wr.rotate(h.pivot) - hand_rot.rotate(h.in_hand);
            return true;
        }
        if (side != g_two.second) return false;
        if (!g_pose.pawn || object_property(g_pose.pawn, g_two.main == 0 ? STR("Weapon L") : STR("Weapon R")) != g_two.weapon)
        {
            end_two_hand("the first hand no longer holds it");
            return false;
        }
        if (!g_two.have_local) return false;
        UObject* base = object_property(g_two.weapon, STR("BaseMesh"));
        if (!base) return false;
        Quat weapon_rot = component_rotation(base);
        Vec3 weapon_pos = component_location(base);
        if (hsvr::config().pose_hold_hand_follows) predicted_item_pose(base, weapon_pos, weapon_rot);
        const HoldState& first = g_hold[g_two.main];
        if (g_two.use_rel)
            hand_rot = (weapon_rot * g_two.rel.inverse()).normalized();
        else if (hsvr::config().pose_two_hand_lock_rotation)
        {
            Quat r = (first.f2 * first.f1.inverse()).normalized(); // the weapon in the first hand's frame
            Vec3 x = r.rotate(Vec3{1, 0, 0}), y = r.rotate(Vec3{0, 1, 0}), z = r.rotate(Vec3{0, 0, 1});
            // The mirror plane on the weapon: the one through its axis whose normal is the palm's
            // (pose_two_hand_mirror: which weapon axis to flip, 0 = X, 1 = Y; Y from kick test 15).
            int flip = hsvr::config().pose_two_hand_mirror;
            double fx = flip == 0 ? -1.0 : 1.0, fy = flip == 1 ? -1.0 : 1.0;
            x = x * fx;
            y = y * fy;
            Vec3 mx{-x.x, x.y, x.z}, my{-y.x, y.y, y.z}, mz{-z.x, z.y, z.z};
            Quat mirrored = quat_from_axes(mx, my, mz).normalized();
            hand_rot = (weapon_rot * mirrored.inverse()).normalized();
        }
        Vec3 spot = weapon_pos + weapon_rot.rotate(g_two.local);
        target = spot - hand_rot.rotate(g_two.in_hand);
        return true;
    }

    // ---- Fists ---------------------------------------------------------------------------------
    // The game punches with an invisible weapon, Weapon_Fists_C (a ModularWeaponBP child: a 13 cm
    // flesh sphere of 0.01 kg, grip type 0), which Willie's tick puts in an empty hand once the
    // mouse's "Aim Swing Speed" reaches 30 and takes away when the hand grabs, falls or he is out
    // (fists_eating.md, UF @556975-@560200). VR never moves that aim speed, so the mod puts it there
    // itself, the game's way (Set Up Hand Weapon(Weapon_Fists_C, none, not dropped, don't destroy,
    // empty passport, don't save) with "Fist R/L Spawned" set, so the game's own removal still
    // works): while you squeeze an empty grip, that hand is a fist. Damage is the game's blunt hit
    // from the fist's speed; the hold moves it with your hand like any weapon.
    UClass* g_fist_class = nullptr;
    bool g_fist_looked = false;

    bool is_fist(UObject* weapon) { return weapon && is_a(weapon, STR("Weapon_Fists_C")); }

    UClass* fist_class(const hsvr::Config& cfg)
    {
        if (g_fist_class) return g_fist_class;
        {
            // An empty ini value (written by an earlier build) means the game's own path.
            std::string chosen = cfg.pose_fist_class.empty() ? std::string("/Game/Assets/Weapons/Blueprints/Built_Weapons/Weapon_Fists.Weapon_Fists_C") : cfg.pose_fist_class;
            std::wstring path(chosen.begin(), chosen.end());
            g_fist_class = UObjectGlobals::StaticFindObject<UClass*>(nullptr, nullptr, path.c_str());
            if (!g_fist_class)
            {
                std::wstring asset = path;
                if (asset.size() > 2 && asset.substr(asset.size() - 2) == STR("_C")) asset.resize(asset.size() - 2);
                load_asset_object(asset);
                g_fist_class = UObjectGlobals::StaticFindObject<UClass*>(nullptr, nullptr, path.c_str());
            }
        }
        if (!g_fist_class)
        {
            // Already loaded by the game: any Blueprint class of that name.
            std::vector<UObject*> classes;
            UObjectGlobals::FindAllOf(STR("BlueprintGeneratedClass"), classes);
            for (UObject* c : classes)
                if (c && c->GetName() == STR("Weapon_Fists_C"))
                {
                    g_fist_class = static_cast<UClass*>(c);
                    break;
                }
        }
        if (!g_fist_looked)
        {
            HSVR_LOG("Fist: class %ls", g_fist_class ? g_fist_class->GetFullName().c_str() : STR("NOT FOUND (set pose_fist_class to its object path)"));
            g_fist_looked = true;
        }
        return g_fist_class;
    }

    // Set Up Right/Left Hand Weapon with a class (or none), and its yes/no switches by name.
    bool set_up_hand(int side, UObject* pawn, UClass* cls, bool dropped, bool destroy_previous, bool dont_save)
    {
        const TCHAR* name = side == 0 ? STR("Set Up Left Hand Weapon") : STR("Set Up Right Hand Weapon");
        UFunction* fn = pawn ? func_chain(pawn, name) : nullptr;
        if (!fn) return false;
        // Sized from the function. The fixed 4096-byte static block this replaced was overrun: the
        // hand position written for the fist landed on the grab button's state (fist-eat test 4).
        std::vector<uint8_t> block = param_block(fn);
        uint8_t* parameters = block.data();
        bool class_set = false;
        static bool sized_logged = false;
        if (!sized_logged)
        {
            sized_logged = true;
            HSVR_LOG("Fist: %ls takes a %zu-byte parameter block", name, block.size() - 64);
        }
        UObject* mesh = object_property(pawn, STR("Mesh"));
        hsvr::Vec3 hand = mesh ? hand_grab_point(mesh, side) : hsvr::Vec3{0, 0, 0};
        for (FProperty* p : fn->ForEachProperty())
        {
            std::wstring n = p->GetName();
            auto kind = p->GetClass().GetName();
            if (kind == STR("ClassProperty") && !class_set)
            {
                *reinterpret_cast<UClass**>(parameters + p->GetOffset_Internal()) = cls;
                class_set = true;
            }
            if (kind == STR("BoolProperty"))
            {
                bool value = n.find(STR("Dropped")) != std::wstring::npos   ? dropped
                             : n.find(STR("Destroy")) != std::wstring::npos ? destroy_previous
                             : n.find(STR("Save")) != std::wstring::npos    ? dont_save
                                                                            : false;
                auto* flag = static_cast<FBoolProperty*>(p);
                if (value) parameters[p->GetOffset_Internal() + flag->GetByteOffset()] |= flag->GetFieldMask();
            }
            if (kind == STR("StructProperty"))
                if (UScriptStruct* type = struct_type(p))
                {
                    uint8_t* at = parameters + p->GetOffset_Internal();
                    if (FProperty* r = struct_member(type, STR("Rotation")))
                        if (FProperty* w = struct_member(struct_type(r), STR("W")))
                        {
                            uint8_t* wat = at + r->GetOffset_Internal() + w->GetOffset_Internal();
                            if (w->GetClass().GetName() == STR("DoubleProperty")) *reinterpret_cast<double*>(wat) = 1.0;
                            else *reinterpret_cast<float*>(wat) = 1.0f;
                        }
                    if (FProperty* t = struct_member(type, STR("Translation"))) write_three(at + t->GetOffset_Internal(), t, hand.x, hand.y, hand.z);
                    if (FProperty* sc = struct_member(type, STR("Scale3D"))) write_three(at + sc->GetOffset_Internal(), sc, 1.0, 1.0, 1.0);
                }
        }
        pawn->ProcessEvent(fn, parameters);
        g_hold[side] = HoldState{};
        return true;
    }

    const TCHAR* fist_spawned_name(int side) { return side == 0 ? STR("Fist L Spawned") : STR("Fist R Spawned"); }
    double g_fist_made_at[2] = {-10.0, -10.0};

    // For half a second after a fist is made, what the game's fist rules read, each tick (the first
    // fist of a run went within one tick, fist test 5).
    void fist_trace(UObject* pawn)
    {
        for (int side = 0; side < 2; ++side)
        {
            double age = hsvr::now_seconds() - g_fist_made_at[side];
            if (age < 0.0 || age > 0.5) continue;
            bool r = side == 1;
            UObject* w = object_property(pawn, r ? STR("Weapon R") : STR("Weapon L"));
            HSVR_LOG("Fist trace %.3f s: %s weapon %ls, Fist Spawned %d, Grabbed %d, Grab Target Found %d, Hand Active %d, GripType_Current %.0f, Free Fall Rate %.2f, Consciousness %.0f",
                     age, r ? "right" : "left", w ? w->GetName().c_str() : STR("none"), (int)bool_property(pawn, fist_spawned_name(side)),
                     (int)bool_property(pawn, r ? STR("Grabbed R") : STR("Grabbed L")), (int)bool_property(pawn, r ? STR("Grab R Target Found") : STR("Grab L Target Found")),
                     (int)bool_property(pawn, r ? STR("R Hand Active") : STR("L Hand Active")), read_number_variable(pawn, r ? STR("R_GripType_Current") : STR("L_GripType_Current")),
                     read_number_variable(pawn, STR("Free Fall Rate")), read_number_variable(pawn, STR("Consciousness")));
        }
    }

    // The fist's collision ball, measured from the first live fist (its "Sphere" component).
    double g_fist_radius_cm = 13.0;
    bool g_fist_radius_measured = false;
    bool g_fist_blocked[2] = {false, false};

    void measure_fist_radius(UObject* fist)
    {
        if (g_fist_radius_measured || !fist) return;
        double most = -1.0;
        for (const TCHAR* n : {STR("Sphere"), STR("SearchBeacon")})
            if (UObject* c = object_property(fist, n))
            {
                Call r(c, STR("GetScaledSphereRadius"));
                r.run();
                double radius = r.number();
                Call q(c, STR("GetCollisionEnabled"));
                q.run();
                FProperty* rp = q.param(STR("ReturnValue"));
                int enabled = rp ? *(q.buffer.data() + rp->GetOffset_Internal()) : -1;
                HSVR_LOG("Fist: its %ls ball has radius %.1f cm, collision %d (0 none, 1 query, 2 physics, 3 both)", n, radius, enabled);
                // Only a ball that takes part in physics pushes anyone.
                if ((enabled == 2 || enabled == 3) && radius > most) most = radius;
            }
        g_fist_radius_measured = true;
        if (most > 0.0) g_fist_radius_cm = most;
        HSVR_LOG("Fist: clearance ball %.1f cm", g_fist_radius_cm);
    }

    // How close the fist's ball centre (where it would be made) is to another Willie's physics bodies:
    // his nearest body to the point, then the distance to that body's collision (0 = inside). Fresh
    // list each call (no Willie pointer kept across frames).
    double fist_clearance(UObject* pawn, const hsvr::Vec3& at, std::wstring& who, std::wstring& bone_out)
    {
        double best = 1e9;
        std::vector<UObject*> all;
        UObjectGlobals::FindAllOf(STR("Willie_BP_C"), all);
        for (UObject* w : all)
        {
            if (!w || w == pawn || w->GetName().rfind(STR("Default__"), 0) == 0 || !object_alive(w)) continue;
            UObject* mesh = object_property(w, STR("Mesh"));
            if (!mesh) continue;
            if (hsvr::length(component_location(mesh) - at) > 250.0) continue;
            Call fb(mesh, STR("FindClosestBone_K2"));
            fb.three(STR("TestLocation"), at.x, at.y, at.z);
            fb.number(STR("IgnoreScale"), 0.0);
            fb.flag(STR("bRequirePhysicsAsset"), true);
            fb.run();
            FProperty* rp = fb.param(STR("ReturnValue"));
            if (!rp) continue;
            FName bone = *reinterpret_cast<FName*>(fb.buffer.data() + rp->GetOffset_Internal());
            Call cp(mesh, STR("GetClosestPointOnCollision"));
            cp.three(STR("Point"), at.x, at.y, at.z);
            cp.name(STR("BoneName"), bone);
            cp.run();
            double d = cp.number();
            if (d < 0.0 || d >= best) continue; // < 0: no collision on that body
            best = d;
            who = w->GetName();
            bone_out = bone.ToString();
        }
        return best;
    }

    bool make_fist(int side, UObject* pawn, const hsvr::Config& cfg)
    {
        g_fist_blocked[side] = false;
        if (!cfg.pose_fists) return false;
        UClass* cls = fist_class(cfg);
        if (!cls) return false;
        if (object_property(pawn, side == 0 ? STR("Weapon L") : STR("Weapon R"))) return false;
        // Knocked out or falling, the fist opens (grab_button, the game's rule UF @556985). Making it again
        // there opened and remade it every tick (playtest 2026-11-20 1296-1306 s: 256 fists in 10 s,
        // "weapons" 113 -> 339).
        {
            double conscious = read_number_variable(pawn, STR("Consciousness"));
            double falling = read_number_variable(pawn, STR("Free Fall Rate"));
            if ((conscious >= 0.0 && conscious <= 0.0) || falling > 0.5)
            {
                g_fist_blocked[side] = true;
                HSVR_LOG_EVERY(1.0, "Fist: %s hand waits: you are %s", side == 0 ? "left" : "right", conscious <= 0.0 ? "knocked out" : "falling");
                return false;
            }
        }
        // Made inside him, the ball is pushed out of his body by the physics while the game pulls it
        // into the hand (its soft attach, which the mod's hold waits out): he is thrown.
        if (cfg.pose_fist_clear)
            if (UObject* mesh = object_property(pawn, STR("Mesh")))
            {
                hsvr::Vec3 at = hand_grab_point(mesh, side);
                std::wstring who, bone;
                double d = fist_clearance(pawn, at, who, bone);
                double need = g_fist_radius_cm + (std::max)(0.0, cfg.pose_fist_clear_margin_cm);
                if (d < need)
                {
                    g_fist_blocked[side] = true;
                    HSVR_LOG_EVERY(0.5, "Fist: %s hand waits: its %.0f cm ball would be inside %ls (%ls %.1f cm from the hand, needs %.0f)",
                                   side == 0 ? "left" : "right", g_fist_radius_cm, who.c_str(), bone.c_str(), d, need);
                    return false;
                }
            }
        // Not inside any loose weapon either (run 12 floor_pickup: reaching down fast at a lantern on the floor made the
        // slap fist with the lantern 0.7 cm from the hand, and the ball threw it 61 cm at 6.2 m/s).
        if (cfg.pose_fist_clear_dropped)
            if (UObject* mesh = object_property(pawn, STR("Mesh")))
            {
                static std::vector<UObject*> loose;
                static double listed = -10.0;
                static bool loose_tracked = on_freed([] { loose.erase(std::remove_if(loose.begin(), loose.end(), [](UObject* o) { return gone(o); }), loose.end()); });
                (void)loose_tracked;
                double tn = hsvr::now_seconds();
                if (tn - listed > 1.0)
                {
                    listed = tn;
                    loose.clear();
                    UObjectGlobals::FindAllOf(STR("ModularWeaponBP_C"), loose);
                }
                hsvr::Vec3 at = hand_grab_point(mesh, side);
                double need = g_fist_radius_cm + (std::max)(0.0, cfg.pose_fist_clear_margin_cm);
                for (UObject* w : loose)
                {
                    if (!w || gone(w) || w->GetName().rfind(STR("Default__"), 0) == 0 || is_fist(w) || bool_property(w, STR("Is Sheathed"))) continue;
                    if (object_property(pawn, STR("Weapon L")) == w || object_property(pawn, STR("Weapon R")) == w || in_own_slot(pawn, w)) continue;
                    UObject* b = object_property(w, STR("BaseMesh"));
                    if (!b || hsvr::length(component_location(b) - at) > 250.0) continue;
                    double d = closest_on_weapon(w, at);
                    if (d >= 0.0 && d < need)
                    {
                        g_fist_blocked[side] = true;
                        HSVR_LOG_EVERY(0.5, "Fist: %s hand waits: its %.0f cm ball would be inside loose %ls (%.1f cm from the hand, needs %.0f)",
                                       side == 0 ? "left" : "right", g_fist_radius_cm, w->GetName().c_str(), d, need);
                        return false;
                    }
                }
            }
        // Not inside what this hand just let go of (g_just_dropped): wait until the ball is clear of it.
        if (cfg.pose_fist_clear_dropped && g_just_dropped[side].item)
        {
            UObject* item = g_just_dropped[side].item;
            UObject* mesh = object_property(pawn, STR("Mesh"));
            double d = -1.0;
            if (mesh && object_alive(item) && object_property(pawn, STR("Weapon L")) != item && object_property(pawn, STR("Weapon R")) != item)
                d = closest_on_weapon(item, hand_grab_point(mesh, side));
            double need = g_fist_radius_cm + (std::max)(0.0, cfg.pose_fist_clear_margin_cm);
            if (d >= 0.0 && d < need)
            {
                g_fist_blocked[side] = true;
                HSVR_LOG_EVERY(0.5, "Fist: %s hand waits: its %.0f cm ball would be inside %ls, which it let go of %.2f s ago (%.1f cm from the hand, needs %.0f)",
                               side == 0 ? "left" : "right", g_fist_radius_cm, item->GetName().c_str(), hsvr::now_seconds() - g_just_dropped[side].at, d, need);
                return false;
            }
            g_just_dropped[side] = JustDropped{};
        }
        set_up_hand(side, pawn, cls, false, false, true);
        UObject* now = object_property(pawn, side == 0 ? STR("Weapon L") : STR("Weapon R"));
        bool ok = is_fist(now);
        if (ok) measure_fist_radius(now);
        if (cfg.pose_fist_mark_spawned) set_bool_property(pawn, fist_spawned_name(side), ok);
        HSVR_LOG("Fist: %s hand %s", side == 0 ? "left" : "right", ok ? "is a fist" : "could not be made a fist");
        if (ok) g_fist_made_at[side] = hsvr::now_seconds();
        return ok;
    }

    void remove_fist(int side, UObject* pawn, const char* why)
    {
        UObject* mine = object_property(pawn, side == 0 ? STR("Weapon L") : STR("Weapon R"));
        if (!is_fist(mine)) return;
        set_up_hand(side, pawn, nullptr, false, true, true);
        // The game destroys a fist on any set-up but leaves "Fist Spawned" set (fists_eating.md).
        set_bool_property(pawn, fist_spawned_name(side), false);
        // Playtest 02:44: after an opened fist the hand still carried a 0.05 kg weapon for minutes (and
        // the second hand of a two-hand hold later sat it inside the handle). Make sure it is gone.
        UObject* after = object_property(pawn, side == 0 ? STR("Weapon L") : STR("Weapon R"));
        bool still = after == mine;
        {
            // Same tick as the set-up, so the actor is still in memory even if it was destroyed
            // (destroying a destroyed actor does nothing).
            Call kill(mine, STR("K2_DestroyActor"));
            kill.run();
        }
        if (still) set_variable(pawn, side == 0 ? STR("Weapon L") : STR("Weapon R"), 0.0, nullptr, nullptr);
        HSVR_LOG("Fist: %s hand opens (%s); hand now holds %ls%s", side == 0 ? "left" : "right", why, after ? after->GetName().c_str() : STR("nothing"),
                 still ? " (the set-up left the fist: destroyed and cleared by the mod)" : "");
    }

    // ---- Eating and drinking -------------------------------------------------------------------
    // Eating (fists_eating.md): the game's "Bite Event" looks for food at his mouth (a 20 cm sphere
    // trace from VoiceScene + Right x10..15 during its 1 s timeline) and bites it; the mod calls it
    // once each time a grabbed food item (BP_Food_Master_C) comes within pose_eat_cm of that point.
    // Drinking: the game's "Drink From Bottle"(bottle), or "Event Gulp" once "Liquid In Mouth" is
    // 0.5 or more, at most once a second, while a held bottle (BP_Weapon_Consumable_Bottle*) is at
    // the mouth with its neck tipped below level.
    bool class_name_starts(UObject* object, const TCHAR* prefix)
    {
        if (!object) return false;
        std::wstring want = prefix;
        for (UStruct* level = object->GetClassPrivate(); level; level = level->GetSuperStruct())
            if (level->GetName().rfind(want, 0) == 0) return true;
        return false;
    }

    // The game's bite trace starts at VoiceScene + Right x10..15 (UF @753233). On his character the
    // component (and its variable) is "Voice Scene", with a space (fist-eat test 2). Read from the
    // variable every call (no cached pointer that could outlive it), and only used if it really is a
    // scene component of his; without it, the head bone of his body 8 cm forward (logged once).
    UObject* find_voice_scene(UObject* pawn)
    {
        UObject* found = nullptr;
        for (const TCHAR* name : {STR("Voice Scene"), STR("VoiceScene")})
        {
            FProperty* p = pawn ? prop_chain(pawn, name) : nullptr;
            if (!p || p->GetClass().GetName() != STR("ObjectProperty")) continue;
            UObject* c = *reinterpret_cast<UObject**>(reinterpret_cast<uint8_t*>(pawn) + p->GetOffset_Internal());
            if (c && is_a(c, STR("SceneComponent")) && c->GetOuterPrivate() == pawn)
            {
                found = c;
                break;
            }
        }
        static UObject* logged_pawn = nullptr;
        static bool logged_pawn_tracked = track_freed(&logged_pawn);
        if (pawn != logged_pawn)
        {
            logged_pawn = pawn;
            HSVR_LOG("Eat: mouth point from %ls", found ? found->GetFullName().c_str() : STR("his head bone (no Voice Scene component found)"));
        }
        return found;
    }

    bool mouth_point(UObject* pawn, hsvr::Vec3& out)
    {
        if (!pawn) return false;
        Call right(pawn, STR("GetActorRightVector"));
        right.run();
        if (UObject* voice = find_voice_scene(pawn))
        {
            out = component_location(voice) + right.vec() * 12.5;
            return true;
        }
        UObject* mesh = object_property(pawn, STR("Mesh"));
        if (!mesh) return false;
        Call fwd(pawn, STR("GetActorForwardVector"));
        fwd.run();
        out = socket_location(mesh, bone_fname("Head")) + fwd.vec() * 8.0;
        return true;
    }

    void eat_and_drink(UObject* pawn, const hsvr::Config& cfg)
    {
        using namespace hsvr;
        if (!cfg.pose_eat || !pawn) return;
        Vec3 mouth;
        if (!mouth_point(pawn, mouth)) return;
        static bool at_mouth[2] = {false, false};
        static double last_drink = -10.0, last_bite = -10.0;
        double now = now_seconds();
        for (int side = 0; side < 2; ++side)
        {
            // Food in a grabbing hand.
            UObject* food = nullptr;
            if (bool_property(pawn, side == 0 ? STR("Grabbed L") : STR("Grabbed R")))
            {
                UObject* comp = object_property(pawn, side == 0 ? STR("Grab Component L") : STR("Grab Component R"));
                if (comp)
                {
                    Call owner_call(comp, STR("GetOwner"));
                    owner_call.run();
                    UObject* owner = owner_call.object_result();
                    if (is_a(owner, STR("BP_Food_Master_C")) || is_a(comp, STR("BP_Food_Master_C"))) food = comp;
                }
            }
            UObject* bottle = object_property(pawn, side == 0 ? STR("Weapon L") : STR("Weapon R"));
            if (!class_name_starts(bottle, STR("BP_Weapon_Consumable_Bottle"))) bottle = nullptr;
            UObject* item = food ? food : (bottle ? object_property(bottle, STR("BaseMesh")) : nullptr);
            if (!item)
            {
                at_mouth[side] = false;
                continue;
            }
            Call closest(item, STR("GetClosestPointOnCollision"));
            closest.three(STR("Point"), mouth.x, mouth.y, mouth.z);
            closest.run();
            double d = closest.number();
            if (d < 0.0) d = length(component_location(item) - mouth);
            bool close = d <= (at_mouth[side] ? cfg.pose_eat_cm + 10.0 : cfg.pose_eat_cm);
            if (food)
            {
                if (close && !at_mouth[side] && now - last_bite > 1.0)
                {
                    Call bite(pawn, STR("Bite Event"));
                    bool ok = bite.run();
                    last_bite = now;
                    HSVR_LOG("Eat: %s hand's food at your mouth (%.0f cm): %s", side == 0 ? "left" : "right", d, ok ? "Bite Event called" : "no Bite Event");
                }
            }
            else if (close && now - last_drink >= cfg.pose_drink_sip_s)
            {
                Quat r = component_rotation(item);
                double tip = dot(r.rotate(Vec3{0, 0, 1}), Vec3{0, 0, 1});
                if (tip < cfg.pose_drink_tip)
                {
                    last_drink = now;
                    double in_mouth = read_number_variable(pawn, STR("Liquid In Mouth"));
                    double bottle_before = read_number_variable(bottle, STR("Liquid Amount In Bottle"));
                    double body_before = read_number_variable(pawn, STR("Body Liquid"));
                    bool ok;
                    const char* what;
                    if (in_mouth >= 0.5)
                    {
                        Call gulp(pawn, STR("Event Gulp"));
                        ok = gulp.run();
                        what = "Event Gulp";
                    }
                    else
                    {
                        Call drink(pawn, STR("Drink From Bottle"));
                        // The bottle goes in the parameter named for it: a function's property list
                        // also holds its locals, so "the first object" was not the parameter (drink
                        // test 2: the call did nothing).
                        static bool listed = false;
                        if (drink.fn)
                        {
                            FProperty* target = nullptr;
                            std::wstring names;
                            for (FProperty* p : drink.fn->ForEachProperty())
                            {
                                names += p->GetName() + STR(" (") + p->GetClass().GetName() + STR("), ");
                                if (!target && p->GetClass().GetName() == STR("ObjectProperty") && p->GetName().find(STR("Bottle")) != std::wstring::npos) target = p;
                            }
                            if (!listed)
                            {
                                listed = true;
                                HSVR_LOG("Drink: Drink From Bottle has %ls; the bottle goes in %ls", names.c_str(), target ? target->GetName().c_str() : STR("NOTHING (no object named Bottle)"));
                            }
                            if (target) *reinterpret_cast<UObject**>(drink.buffer.data() + target->GetOffset_Internal()) = bottle;
                        }
                        ok = drink.run();
                        what = "Drink From Bottle";
                    }
                    HSVR_LOG("Drink: %s hand's %ls at your mouth (%.0f cm, neck %.2f): %s %s (liquid in mouth %.3f -> %.3f, in the bottle %.2f -> %.2f, body liquid %.4f -> %.4f)",
                             side == 0 ? "left" : "right", bottle->GetName().c_str(), d, tip, what, ok ? "called" : "MISSING", in_mouth,
                             read_number_variable(pawn, STR("Liquid In Mouth")), bottle_before, read_number_variable(bottle, STR("Liquid Amount In Bottle")), body_before,
                             read_number_variable(pawn, STR("Body Liquid")));
                }
            }
            // A bottle taken from the mouth with liquid in it: he swallows (the game's own Gulp
            // needs 0.5 in the mouth, which short sips never reach: fist-eat test 4).
            if (bottle && at_mouth[side] && !close)
            {
                double in_mouth = read_number_variable(pawn, STR("Liquid In Mouth"));
                if (in_mouth > 0.01)
                {
                    Call gulp(pawn, STR("Event Gulp"));
                    bool ok = gulp.run();
                    HSVR_LOG("Drink: bottle away from your mouth, swallowing (liquid in mouth %.2f): Event Gulp %s", in_mouth, ok ? "called" : "MISSING");
                }
            }
            at_mouth[side] = close;
        }
    }

    // ---- Armour on and off with your hands (Matthew 2026-11-24) ------------------------------------
    // Grip held and the trigger held armor_hold_s (2 s), one of three things, by what the hand has:
    // 1. A loose armour piece (the game's grab made it "Carried Armor L/R Hand", UG @537050) brought to
    //    its spot on your body (within armor_equip_cm of that slot's bones): the game's own
    //    "Event Equip Armor From L/R Hand" (UG @119017/@124150: it carries the piece onto him, then
    //    Equip Armor with all its layering rules: arming points, blocked slots, the slot's old piece dropped).
    // 2. A hold on another person (the game's grab on his body): the game's own "Event Rob With L/R Hand"
    //    (UG @123673 -> Strip Armor From Bone with the held bone). Its rule, unchanged: a weapon or quiver
    //    within 15 cm of your hand is taken first; otherwise the slot under the held bone comes off only if
    //    he is worn there, it is not in his Block Undress Slots and he is Fallen (on the ground); and his
    //    AI turns hostile (Aggression 1). The piece lands in your hand.
    // 3. An empty hand on one of your own worn pieces (its slot's bones within armor_take_cm, the other
    //    arm's for hands/arms/shoulders, outermost layer first): the game's Remove Armor on that slot
    //    (as its Undress key does, UG @115471), and the piece put in your hand (Grab Specific Object).
    // Mouse and keyboard: the game's own keys (B, and holding Q/E on a held body) do this; off here.
    struct ArmourHold
    {
        int mode = 0;            // 0 nothing, 1 put on, 2 strip him, 3 take off yours
        UObject* target = nullptr; // the piece (1), his body component (2), your worn mesh (3)
        int slot = -1;
        double since = -1.0;     // trigger held on this target since
        double last_buzz = -1.0;
        bool fired = false;      // done: the trigger must come up before the next
        bool down = false;       // trigger past armor_trigger_on (hysteresis)
        int check = 0;           // what was fired, checked once a little later
        double check_at = -1.0;
        UObject* check_obj = nullptr;
        double why_t = -10.0;    // the last "not yet" log
        hsvr::Vec3 last_hand{0, 0, 0}; // hand bone last tick (its speed: taking your own off needs a still hand)
        double last_t = -1.0;
        double speed = 0.0;      // cm/s, smoothed
    };
    ArmourHold g_armour[2];

    const wchar_t* armour_slot_name(int s)
    {
        static const wchar_t* n[17] = {L"Head 2", L"Hands", L"Head 1", L"Neck 3", L"Neck 2", L"Neck 1", L"Arms", L"Shoulders", L"Body 4",
                                       L"Body 3", L"Body 2", L"Legs 2", L"Body 1", L"Waist", L"Legs 3", L"Feet", L"Legs 1"};
        return s >= 0 && s < 17 ? n[s] : L"?";
    }
    // Where the game puts a removed piece (Strip Armor From Bone @18551, its socket per slot).
    const char* armour_slot_socket(int s)
    {
        static const char* n[17] = {"head", "hand_r", "head", "neck_01", "neck_01", "neck_01", "upperarm_r", "clavicle_r", "spine_03",
                                    "spine_03", "spine_03", "thigh_r", "spine_03", "pelvis", "foot_l", "foot_r", "foot_l"};
        return s >= 0 && s < 17 ? n[s] : "spine_03";
    }
    // Outer layers first when two worn pieces sit on the same bones (Head 2 over Head 1, Neck 3 over 1, Body 4 over 1, Legs 3 over 1).
    int armour_layer(int s)
    {
        switch (s)
        {
        case 0: return 2; case 2: return 1;
        case 3: return 3; case 4: return 2; case 5: return 1;
        case 8: return 4; case 9: return 3; case 10: return 2; case 12: return 1;
        case 14: return 3; case 11: return 2; case 16: return 1;
        default: return 0;
        }
    }
    // Nearest distance from a point to a slot's bones on a body. `skip_side` 0/1 leaves out that side's
    // arm (the hand doing it is always on its own arm); -1 leaves out nothing.
    double armour_slot_distance(UObject* mesh, int slot, const hsvr::Vec3& at, int skip_side)
    {
        using namespace hsvr;
        std::vector<const char*> bones;
        switch (slot)
        {
        case 0: case 2: bones = {"head"}; break;
        case 1: bones = {"hand_l", "hand_r"}; break;
        case 3: case 4: case 5: bones = {"neck_01", "neck_02"}; break;
        case 6: bones = {"upperarm_l", "upperarm_r", "lowerarm_l", "lowerarm_r"}; break;
        case 7: bones = {"clavicle_l", "clavicle_r", "upperarm_l", "upperarm_r"}; break;
        case 8: case 9: case 10: case 12: bones = {"spine_02", "spine_03", "spine_01"}; break;
        case 13: bones = {"pelvis", "spine_01"}; break;
        case 11: case 16: bones = {"thigh_l", "thigh_r", "calf_l", "calf_r", "pelvis"}; break;
        case 14: bones = {"calf_l", "calf_r", "thigh_l", "thigh_r"}; break;
        case 15: bones = {"foot_l", "foot_r"}; break;
        default: return 1e9;
        }
        double best = 1e9;
        for (const char* b : bones)
        {
            size_t n = strlen(b);
            if (skip_side >= 0 && n > 2 && b[n - 2] == '_' && b[n - 1] == (skip_side == 0 ? 'l' : 'r') &&
                (strncmp(b, "hand", 4) == 0 || strncmp(b, "lowerarm", 8) == 0 || strncmp(b, "upperarm", 8) == 0 || strncmp(b, "clavicle", 8) == 0))
                continue;
            double d = length(socket_location(mesh, bone_fname(b)) - at);
            if (d < best) best = d;
        }
        return best;
    }
    // Your worn piece nearest the hand: slot, or -1. Worn Armor's components carry the slot's name as a
    // tag (Set Up Armor, armor_equip.md section 1); the game's panties (Sk_Clothing_Underwear_C) and
    // Block Undress Slots are left out, as its Undress key does.
    // A person's worn pieces: slot -> its mesh. Worn Armor's components carry the slot's name as a tag
    // (Set Up Armor, armor_equip.md section 1); hidden ones and the game's panties (Sk_Clothing_Underwear_C)
    // are left out, as its Undress key leaves the panties.
    std::vector<std::pair<int, UObject*>> armour_worn(UObject* willie)
    {
        std::vector<std::pair<int, UObject*>> out;
        RawArray* worn = willie ? value_ptr<RawArray>(willie, STR("Worn Armor")) : nullptr;
        if (!worn || !worn->Data) return out;
        bool seen[17] = {};
        for (int32_t i = 0; i < worn->Num; ++i)
        {
            UObject* c = reinterpret_cast<UObject**>(worn->Data)[i];
            if (!object_alive(c)) continue;
            Call vis(c, STR("IsVisible"));
            if (vis.fn && vis.run())
                if (FProperty* rp = vis.param(STR("ReturnValue")); rp && !*(vis.buffer.data() + rp->GetOffset_Internal())) continue;
            UObject* sk = object_property(c, STR("SkeletalMeshAsset"));
            if (!sk) sk = object_property(c, STR("SkeletalMesh"));
            if (sk && sk->GetName() == STR("Sk_Clothing_Underwear_C")) continue;
            RawArray* tags = value_ptr<RawArray>(c, STR("ComponentTags"));
            if (!tags || !tags->Data) continue;
            int slot = -1;
            for (int32_t t = 0; t < tags->Num && slot < 0; ++t)
            {
                std::wstring tag = reinterpret_cast<const FName*>(tags->Data)[t].ToString();
                for (int s = 0; s < 17; ++s)
                    if (tag == armour_slot_name(s)) { slot = s; break; }
            }
            if (slot < 0 || seen[slot]) continue;
            seen[slot] = true;
            out.push_back({slot, c});
        }
        return out;
    }
    // Your worn piece nearest the hand (its slot's bones within radius): slot, or -1. Block Undress Slots
    // are left out, as the game's Undress key does.
    int armour_own_near(UObject* pawn, UObject* mesh, int side, const hsvr::Vec3& hand, double radius, UObject** comp_out, double* d_out, int keep = -1)
    {
        std::vector<uint8_t> blocked;
        if (RawArray* bl = value_ptr<RawArray>(pawn, STR("Block Undress Slots")); bl && bl->Data)
            for (int32_t i = 0; i < bl->Num; ++i) blocked.push_back(reinterpret_cast<const uint8_t*>(bl->Data)[i]);
        int best = -1, best_layer = -1;
        double best_d = 1e9;
        UObject* best_c = nullptr;
        for (auto& [slot, c] : armour_worn(pawn))
        {
            if (std::find(blocked.begin(), blocked.end(), (uint8_t)slot) != blocked.end()) continue;
            double d = armour_slot_distance(mesh, slot, hand, side);
            if (d > radius) continue;
            if (slot == keep) d = -1000.0; // the piece already counting stays chosen while it is in reach (run bdf917a: head and neck took turns)
            int layer = armour_layer(slot);
            // Same bones (a tie to the cm): the outer layer. Otherwise the nearer.
            if (best < 0 || d < best_d - 1.0 || (std::abs(d - best_d) <= 1.0 && layer > best_layer)) best = slot, best_d = d, best_layer = layer, best_c = c;
        }
        if (comp_out) *comp_out = best_c;
        if (d_out) *d_out = best_d;
        return best;
    }
    // Takes your own worn piece off into that hand: Remove Armor (spawned where the game spawns it), then
    // the hand's grab given the piece, as Strip Armor From Bone does for another's (@19066, @20519).
    // `owner` another Willie (a held foe): his piece, Remove Armor called on him (as Strip does, @19044).
    bool armour_take_own(UObject* pawn, UObject* mesh, int side, int slot, const hsvr::Vec3& hand, UObject* owner = nullptr)
    {
        bool L = side == 0;
        if (!owner) owner = pawn;
        UObject* owner_mesh = owner == pawn ? mesh : object_property(owner, STR("Mesh"));
        if (!owner_mesh) return false;
        const wchar_t* whose = owner == pawn ? L"your" : L"his";
        Call ra(owner, STR("Remove Armor"));
        if (!ra.fn)
        {
            HSVR_LOG("Armour: no Remove Armor function on %ls", pawn->GetName().c_str());
            return false;
        }
        static bool listed = false;
        FProperty *tp = nullptr, *sp = nullptr, *cp = nullptr, *outp = nullptr;
        std::wstring names;
        for (FProperty* p : ra.fn->ForEachProperty())
        {
            std::wstring n = p->GetName(), k = p->GetClass().GetName();
            names += n + STR(" (") + k + STR("), ");
            if (n == STR("SpawnTransform")) tp = p;
            else if (n == STR("Slot")) sp = p;
            else if (n == STR("Disable Collision With")) cp = p;
            else if (n == STR("Spawned Armor1")) outp = p;
        }
        if (!listed)
        {
            listed = true;
            HSVR_LOG("Armour: Remove Armor has %ls", names.c_str());
        }
        if (!tp || !sp || !outp)
        {
            HSVR_LOG("Armour: Remove Armor's parameters not found (transform %d, slot %d, out %d)", tp != nullptr, sp != nullptr, outp != nullptr);
            return false;
        }
        Call st(owner_mesh, STR("GetSocketTransform"));
        st.name(STR("InSocketName"), bone_fname(armour_slot_socket(slot)));
        FProperty* rp = st.param(STR("ReturnValue"));
        if (!st.run() || !rp || rp->GetSize() != tp->GetSize())
        {
            HSVR_LOG("Armour: no socket transform for %s", armour_slot_socket(slot));
            return false;
        }
        memcpy(ra.buffer.data() + tp->GetOffset_Internal(), st.buffer.data() + rp->GetOffset_Internal(), tp->GetSize());
        *(ra.buffer.data() + sp->GetOffset_Internal()) = (uint8_t)slot;
        if (cp) *reinterpret_cast<UObject**>(ra.buffer.data() + cp->GetOffset_Internal()) = mesh;
        ra.run();
        UObject* spawned = *reinterpret_cast<UObject**>(ra.buffer.data() + outp->GetOffset_Internal());
        if (!object_alive(spawned))
        {
            HSVR_LOG("Armour: Remove Armor on %ls %ls gave nothing", whose, armour_slot_name(slot));
            return false;
        }
        if (bool_property(pawn, L ? STR("Grabbed L") : STR("Grabbed R"))) Call(pawn, L ? STR("Release Grab L") : STR("Release Grab R")).run();
        // A closed hand (grip + trigger + thumb) is the game's fist weapon: gone before the hand takes the piece.
        if (is_fist(object_property(pawn, L ? STR("Weapon L") : STR("Weapon R")))) remove_fist(side, pawn, "taking armour off");
        set_variable(pawn, L ? STR("Carried Armor L Hand") : STR("Carried Armor R Hand"), 0.0, spawned);
        UObject* comp = object_property(spawned, bool_property(spawned, STR("World Mesh Static")) ? STR("Armor Mesh Static") : STR("Armor Mesh Skeletal"));
        if (!comp) comp = object_property(spawned, STR("Armor Mesh Skeletal"));
        // Handed to the game's own grab latch, as the grip does with a loose piece (grab_object): its tick
        // builds the hand joint and its armour handling; 0.3 s later check_object_grab falls back to Grab
        // Specific Object. (Test af81c12: Grab Specific Object straight away held for one tick, then the
        // fist came back and the piece fell.)
        set_variable(pawn, L ? STR("Grab Component L") : STR("Grab Component R"), 0, comp);
        static const FName none_bone = FName(STR("None"), FNAME_Add);
        set_variable(pawn, L ? STR("Grab Bone L") : STR("Grab Bone R"), 0, nullptr, &none_bone);
        if (UObject* gp = object_property(pawn, L ? STR("GrabPoint L") : STR("GrabPoint R")))
        {
            Call move(gp, STR("K2_SetWorldLocation"));
            move.three(STR("NewLocation"), hand.x, hand.y, hand.z);
            move.run();
        }
        set_variable(pawn, L ? STR("Stuck Meter L Hand") : STR("Stuck Meter R Hand"), 0.0);
        set_variable(pawn, L ? STR("Grab L Target Found") : STR("Grab R Target Found"), 1.0);
        ObjectGrab& og = g_object_grab[side];
        og = ObjectGrab{};
        og.component = comp;
        og.point = hand;
        og.since = hsvr::now_seconds();
        HSVR_LOG("Armour: %s hand took off %ls %ls (%ls): %ls (%ls), Grabbed %d", L ? "left" : "right", whose, armour_slot_name(slot), owner->GetName().c_str(), spawned->GetName().c_str(),
                 comp ? comp->GetName().c_str() : STR("no mesh"), (int)bool_property(pawn, L ? STR("Grabbed L") : STR("Grabbed R")));
        return true;
    }

    void armour_tick(UObject* pawn, UObject* mesh, const hsvr::ControllerState& state, const hsvr::Config& cfg)
    {
        using namespace hsvr;
        if (!cfg.armor_hands || !pawn || !mesh || g_kbm.load()) return;
        double now = now_seconds();
        for (int side = 0; side < 2; ++side)
        {
            bool L = side == 0;
            const char* hand_name = L ? "left" : "right";
            ArmourHold& a = g_armour[side];
            // A result to read back, a moment after the game's event ran.
            if (a.check && now >= a.check_at)
            {
                UObject* carried = object_property(pawn, L ? STR("Carried Armor L Hand") : STR("Carried Armor R Hand"));
                if (a.check == 1)
                    HSVR_LOG("Armour: %s hand put on: %ls (the piece is %ls)", hand_name,
                             object_alive(a.check_obj) && carried == a.check_obj ? STR("NOT taken (still in the hand: its slot is blocked or needs the layer under it)") : STR("done"),
                             object_alive(a.check_obj) ? STR("still in the world") : STR("gone into his armour"));
                else if (a.check == 2)
                {
                    UObject* comp = object_property(pawn, L ? STR("Grab Component L") : STR("Grab Component R"));
                    if (object_alive(carried))
                    {
                        HSVR_LOG("Armour: %s hand stripped %ls off %ls (in your hand)", hand_name, carried->GetName().c_str(),
                                 object_alive(a.check_obj) ? a.check_obj->GetName().c_str() : STR("him"));
                        ObjectGrab& og = g_object_grab[side];
                        og = ObjectGrab{};
                        og.component = comp;
                        og.since = now;
                        og.fallback_tried = true;
                    }
                    else
                        HSVR_LOG("Armour: %s hand: nothing came off %ls (Fallen %d; the game strips only someone on the ground, and only a worn slot under the held bone; a weapon near your hand is taken instead)",
                                 hand_name, object_alive(a.check_obj) ? a.check_obj->GetName().c_str() : STR("him"), object_alive(a.check_obj) ? (int)bool_property(a.check_obj, STR("Fallen")) : -1);
                }
                a.check = 0;
            }
            float trig = g_fake_trigger[side].load() >= 0.0f ? g_fake_trigger[side].load() : state.hand[side].trigger;
            float sq = g_fake_squeeze[side].load() >= 0.0f ? g_fake_squeeze[side].load() : state.hand[side].squeeze;
            {
                Vec3 hp = socket_location(mesh, bone_fname(L ? "hand_l" : "hand_r"));
                double dt = a.last_t < 0.0 ? 0.0 : now - a.last_t;
                if (dt > 0.0 && dt < 0.5)
                {
                    double v = length(hp - a.last_hand) / dt;
                    double k = (std::min)(1.0, dt / 0.15);
                    a.speed += (v - a.speed) * k;
                }
                a.last_hand = hp, a.last_t = now;
            }
            a.down = a.down ? trig >= cfg.armor_trigger_off : trig >= cfg.armor_trigger_on;
            if (!a.down || sq < 0.6f)
            {
                if (a.mode && a.since >= 0.0 && !a.fired) HSVR_LOG("Armour: %s hand let go of the trigger after %.1f s (needs %.1f)", hand_name, now - a.since, cfg.armor_hold_s);
                a.mode = 0, a.target = nullptr, a.since = -1.0, a.fired = false;
                continue;
            }
            if (a.fired) continue;
            // What this hand can do now.
            int mode = 0, slot = -1;
            UObject* target = nullptr;
            Vec3 hb = socket_location(mesh, bone_fname(L ? "hand_l" : "hand_r"));
            bool grabbed = bool_property(pawn, L ? STR("Grabbed L") : STR("Grabbed R"));
            UObject* carried = object_property(pawn, L ? STR("Carried Armor L Hand") : STR("Carried Armor R Hand"));
            std::string why;
            char buf[200];
            if (grabbed && object_alive(carried))
            {
                uint8_t* sp = value_ptr<uint8_t>(carried, STR("Armor Slot"));
                slot = sp ? *sp : -1;
                double d = armour_slot_distance(mesh, slot, hb, side);
                if (d <= cfg.armor_equip_cm) mode = 1, target = carried;
                else
                {
                    snprintf(buf, sizeof buf, "the %ls piece is %.0f cm from its spot (bring it within %.0f)", armour_slot_name(slot), d, cfg.armor_equip_cm);
                    why = buf;
                }
            }
            else if (grabbed)
            {
                UObject* comp = object_property(pawn, L ? STR("Grab Component L") : STR("Grab Component R"));
                UObject* owner = nullptr;
                if (comp)
                {
                    Call oc(comp, STR("GetOwner"));
                    oc.run();
                    owner = oc.object_result();
                }
                if (owner && owner != pawn && is_a(owner, STR("Willie_BP_C"))) mode = 2, target = owner;
            }
            else
            {
                UObject* own = object_property(pawn, L ? STR("Weapon L") : STR("Weapon R"));
                bool empty = !(own && !is_fist(own)) && !g_world[side].on && !scabbard_held(side);
                if (empty)
                {
                    UObject* c = nullptr;
                    double d = 0.0;
                    slot = armour_own_near(pawn, mesh, side, hb, cfg.armor_take_cm, &c, &d, a.mode == 3 ? a.slot : -1);
                    if (slot >= 0) mode = 3, target = c;
                    else why = "no worn piece of yours near the hand";
                }
            }
            if (mode != a.mode || target != a.target)
            {
                a.mode = mode, a.target = target, a.slot = slot, a.since = mode ? now : -1.0, a.last_buzz = -1.0;
                if (mode)
                    HSVR_LOG("Armour: %s hand, grip and trigger held: %s %ls (%ls); hold %.1f s", hand_name,
                             mode == 1 ? "put on" : mode == 2 ? "strip" : "take off your", mode == 2 ? target->GetName().c_str() : armour_slot_name(slot),
                             mode == 2 ? (bool_property(target, STR("Fallen")) ? STR("he is down") : STR("he is STANDING: the game will refuse")) : STR("in reach"), cfg.armor_hold_s);
            }
            if (!mode)
            {
                if (!why.empty() && now - a.why_t > 2.0)
                {
                    a.why_t = now;
                    HSVR_LOG("Armour: %s hand, grip and trigger held: nothing to do (%s)", hand_name, why.c_str());
                }
                continue;
            }
            // Your own piece: the hand must stay still on it (a fist held up in a guard is grip + trigger too).
            if (mode == 3 && a.speed > cfg.armor_take_still_cms)
            {
                if (now - a.since > 0.5) HSVR_LOG("Armour: %s hand moved (%.0f cm/s) while taking off your %ls: the count starts again", hand_name, a.speed, armour_slot_name(a.slot));
                a.since = now;
            }
            double held = now - a.since;
            if (held < cfg.armor_hold_s)
            {
                // A rising buzz while it counts down.
                if (a.last_buzz < 0.0 || now - a.last_buzz >= 0.25)
                {
                    a.last_buzz = now;
                    controllers_buzz(side, (float)(0.08 + 0.3 * held / cfg.armor_hold_s));
                }
                continue;
            }
            a.fired = true;
            controllers_buzz(side, 0.8f);
            if (mode == 1)
            {
                bool ok = Call(pawn, L ? STR("Event Equip Armor From L Hand") : STR("Event Equip Armor From R Hand")).run();
                HSVR_LOG("Armour: %s hand puts on %ls (%ls): Event Equip Armor From %s Hand %s", hand_name, target->GetName().c_str(), armour_slot_name(a.slot),
                         L ? "L" : "R", ok ? "called" : "MISSING");
                a.check = 1, a.check_at = now + 1.2, a.check_obj = target;
            }
            else if (mode == 2)
            {
                // The game's Strip rule (Strip Armor From Bone @3801): Fallen, and the slot not in his Block
                // Undress Slots; his AI turns hostile (@1651). The piece is the worn one nearest your hand (the
                // game's bone-to-slot map took the neck under a held helmet: test 9dc5dc2), not the weapon rob.
                UObject* fmesh = object_property(target, STR("Mesh"));
                bool fallen = bool_property(target, STR("Fallen"));
                UObject* c = nullptr;
                double d = 0.0;
                int fs = fmesh ? armour_own_near(target, fmesh, -1, hb, cfg.armor_strip_cm, &c, &d) : -1;
                Call gc(target, STR("GetController"));
                gc.run();
                UObject* ctl = gc.object_result();
                if (ctl && is_a(ctl, STR("AI_BP_C"))) set_variable(ctl, STR("Aggression"), 1.0);
                if (!fallen)
                    HSVR_LOG("Armour: %s hand: %ls is standing: the game only strips someone who is down (Fallen)", hand_name, target->GetName().c_str());
                else if (fs < 0)
                    HSVR_LOG("Armour: %s hand: no worn piece of %ls within %.0f cm of your hand", hand_name, target->GetName().c_str(), cfg.armor_strip_cm);
                else if (!armour_take_own(pawn, mesh, side, fs, hb, target))
                    HSVR_LOG("Armour: %s hand: %ls's %ls did not come off", hand_name, target->GetName().c_str(), armour_slot_name(fs));
                if (!fallen || fs < 0) controllers_buzz(side, 0.15f);
            }
            else
                armour_take_own(pawn, mesh, side, a.slot, hb);
        }
    }

    // A weapon's real shape. Its BaseMesh is a 2 cm grip dummy (SM_Grip_Dummy); the blade, grip, guard,
    // pommel or shield plate are child static meshes welded into its body, and a closest-point query
    // on the root skips welded shapes (PhysInterface_Chaos GetSquaredDistanceToBody, IsShapeBoundToBody)
    // while one on a welded child answers with that child's own shapes (collision dump, 2026-11-18).
    // So every static mesh part of the weapon is asked, and the nearest answer wins. The parts list
    // (by outer) is rebuilt at most every 0.25 s.
    std::unordered_map<UObject*, std::vector<UObject*>> g_weapon_parts;
    double g_weapon_parts_time = -10.0;

    void refresh_weapon_parts(UObject* weapon)
    {
        double now = hsvr::now_seconds();
        // A weapon spawned straight into the hand (free play) is not in a list made before it existed:
        // rebuild at once for it (at most every 0.05 s), not only every 0.25 s (playtest 12:19: a fresh
        // two-handed axe measured a zero-length handle and kept it).
        bool unknown = g_weapon_parts.find(weapon) == g_weapon_parts.end();
        if (now - g_weapon_parts_time > 0.25 || (unknown && now - g_weapon_parts_time > 0.05))
        {
            g_weapon_parts_time = now;
            g_weapon_parts.clear();
            std::vector<UObject*> comps;
            UObjectGlobals::FindAllOf(STR("StaticMeshComponent"), comps);
            for (UObject* c : comps)
                if (c && c->GetOuterPrivate()) g_weapon_parts[c->GetOuterPrivate()].push_back(c);
        }
    }

    // Weapons (ModularWeaponBP_C) among the owners of the static mesh parts list, rebuilt with it every 0.25 s (one FindAllOf for
    // both): the leg guard sees a weapon that just came near his legs within 0.25 s, not the 1 s its own FindAllOf took (run 27
    // settle_self_b fresh: a lantern spawned 2 cm from his legs was kicked at 6623 for 0.5 s before the guard found it).
    void weapons_from_parts(UObject* pawn, std::vector<UObject*>& out)
    {
        out.clear();
        refresh_weapon_parts(pawn);
        // Made again after every garbage collection too: gone() is only true inside gc_sync, so a weapon freed since the
        // list was made stayed in it until the next 0.25 s rebuild, and the leg guard read the freed actor (6 crashes in
        // Matthew's 11-24 playtest, all leg_guard_tick -> object_property / component_location right after a "GC:" line).
        static double built = -10.0;
        static uint64_t built_epoch = 0;
        static std::vector<UObject*> cache;
        if (built != g_weapon_parts_time || built_epoch != g_gc_epoch)
        {
            built = g_weapon_parts_time;
            built_epoch = g_gc_epoch;
            cache.clear();
            for (auto& [owner, parts] : g_weapon_parts)
                if (owner && !gone(owner) && is_a(owner, STR("ModularWeaponBP_C"))) cache.push_back(owner);
        }
        for (UObject* w : cache)
            if (!gone(w)) out.push_back(w);
    }

    // Every static mesh component an actor owns (by outer), attached or not: a chain lantern's lamp ("Weapon") and
    // Link 1-4 hang off physics constraints as bodies of their own, outside BaseMesh's attach tree (run 19 f4cc855).
    std::vector<UObject*> static_parts_of(UObject* owner)
    {
        if (!owner) return {};
        refresh_weapon_parts(owner);
        auto it = g_weapon_parts.find(owner);
        if (it == g_weapon_parts.end()) return {};
        std::vector<UObject*> out;
        for (UObject* c : it->second)
            if (c && !gone(c)) out.push_back(c);
        return out;
    }

    double closest_on_weapon(UObject* weapon, const hsvr::Vec3& point, hsvr::Vec3* out, UObject** out_part)
    {
        if (!weapon) return -1.0;
        refresh_weapon_parts(weapon);
        double best = -1.0;
        auto it = g_weapon_parts.find(weapon);
        if (it == g_weapon_parts.end()) return -1.0;
        // The weapon's scabbard is one of its own components too (NODE_AddStaticMeshComponent-N, its
        // "Scabbard"), and stays on the belt after a draw: it is not the weapon (playtest 09:38: the
        // off hand on the belt scabbard took the drawn sword "by its spot" 55-92 cm away from it).
        UObject* scab = object_property(weapon, STR("Scabbard"));
        auto under_scabbard = [&](UObject* c) {
            if (!scab) return false;
            UObject* p = c;
            for (int i = 0; i < 6 && p; ++i)
            {
                if (p == scab) return true;
                Call ap(p, STR("GetAttachParent"));
                if (!ap.fn || !ap.run()) return false;
                p = ap.object_result();
            }
            return false;
        };
        for (UObject* c : it->second)
        {
            if (under_scabbard(c)) continue;
            Call q(c, STR("GetClosestPointOnCollision"));
            if (!q.fn) continue;
            q.three(STR("Point"), point.x, point.y, point.z);
            q.run();
            double d = q.number();
            if (d < 0.0 || (best >= 0.0 && d >= best)) continue;
            best = d;
            if (out) *out = q.vec(STR("OutPointOnBody"));
            if (out_part) *out_part = c;
        }
        return best;
    }

    // Every strap and handle you can see on a shield is a grab point (Matthew 2026-11-18: "if i can
    // see more then one grab point then i want to be able to grab it"). Measured from the shields'
    // own meshes (HalfSwordDecomp defaults/shield_grab_points_measured.csv: the cooked StaticMesh
    // LOD0, each fitting a separate piece of the mesh): its centre line in the BaseMesh frame (cm),
    // and which hands the game itself puts on it (its own grip: "Grip R/L Hand Default" and the arm
    // pose it snaps to). Flush fittings with no room for a hand are left out.
    struct ShieldFitting
    {
        const wchar_t* shield; // class name without _C
        const char* name;
        double cx, cy, cz, ax, ay, az, length;
        bool game_r, game_l; // part of the game's own grip for that hand
    };
    const ShieldFitting k_shield_fittings[] = {
        {L"Shield_Buckler", "handle", 0.00, 0.00, -0.04, -0.000, -0.006, -1.000, 33.4, true, true},
        {L"Shield_Buckler_2", "handle", 0.01, 0.01, 0.05, 0.000, -0.002, -1.000, 23.6, true, true},
        {L"Shield_Buckler_3", "handle", -0.01, 0.00, 0.07, -0.000, -0.000, -1.000, 26.6, true, true},
        {L"Shield_Tagre", "big strap", 6.91, -6.56, -7.52, 0.643, 0.000, 0.766, 19.3, true, true},
        {L"Shield_Tagre", "narrow strap", -6.00, -4.54, 0.54, 0.735, 0.000, 0.678, 19.6, true, false},
        {L"Shield_Tagre", "upright strap", -6.12, -4.06, 0.61, 0.164, 0.000, 0.987, 19.4, true, true},
        {L"Shield_Pavise_Light", "upright handle", 0.18, 1.43, -0.16, -0.014, 0.000, 1.000, 21.1, false, false},
        {L"Shield_Pavise_Light", "top handle", 0.12, -3.03, 15.94, -1.000, 0.000, 0.022, 27.5, true, false},
        {L"Shield_Pavise_Light", "lower strap", 0.38, -7.42, -8.74, 1.000, 0.000, 0.004, 26.0, false, false},
        {L"Shield_Pavise_Heavy", "centre handle", -0.09, 0.60, -3.33, 0.008, 0.000, 1.000, 18.9, true, false},
        {L"Shield_Pavise_Heavy", "centre handle's right arm", 5.47, 1.52, 9.55, 0.922, 0.000, 0.386, 14.0, false, false},
        {L"Shield_Pavise_Heavy", "centre handle's left arm", -5.53, 1.53, 9.57, -0.929, 0.000, 0.370, 13.9, false, false},
        {L"Shield_Pavise_Heavy", "side bar", -16.42, -2.18, 14.36, 0.018, 0.000, 1.000, 25.9, false, true},
        {L"Shield_Pavise_Heavy", "long strap", 13.80, -6.77, 12.38, -0.007, 0.000, 1.000, 39.6, false, true},
        {L"Shield_Pavise_Tower", "crossed strap's middle", -0.21, -0.60, -0.31, 0.008, 0.000, 1.000, 20.9, true, true},
        {L"Shield_Pavise_Tower", "crossed strap, upper right", 5.66, 1.34, 12.63, 0.808, 0.000, 0.589, 15.2, false, false},
        {L"Shield_Pavise_Tower", "crossed strap, upper left", -5.54, 1.64, 12.43, -0.797, 0.000, 0.604, 13.1, false, false},
        {L"Shield_Pavise_Tower", "crossed strap, lower right", 5.82, 1.26, -11.79, -0.833, 0.000, 0.553, 14.6, false, false},
        {L"Shield_Pavise_Tower", "crossed strap, lower left", -5.71, 1.47, -11.77, 0.880, 0.000, 0.474, 14.2, false, false},
        {L"Shield_Pavise_Tower", "top rod", 0.31, 2.67, 51.44, 1.000, 0.000, 0.000, 13.2, false, false},
        {L"Shield_Pavise_Tower", "bottom bar", 0.18, 0.69, -48.85, 1.000, 0.000, -0.000, 25.5, false, false},
        {L"Shield_BossGrip", "handle", -0.00, -0.39, 0.70, -0.001, 0.000, 1.000, 50.1, true, true},
    };

    // The hand's grip line in the hand bone's frame (right: the game's sword grip, measured; left mirrored across X).
    hsvr::Vec3 hand_grip_axis(int side) { return hsvr::normalized(hsvr::Vec3{side == 0 ? 0.50 : -0.50, 0.86, 0.11}); }

    // The mod's free grip: held in the hand (the hand bone) by `point` (world, on the weapon), turned
    // as it was in pose (w0), or, given `axis` (world, a strap's or handle's line), turned the least
    // that lays that line along the hand's grip line.
    FreeGrip make_free_grip(int side, UObject* mesh, const hsvr::Vec3& w0_pos, const hsvr::Quat& w0_rot, const hsvr::Vec3& palm, const hsvr::Vec3& point,
                            const hsvr::Vec3* axis, const char* what)
    {
        using namespace hsvr;
        Vec3 a_pos = socket_location(mesh, bone_fname(side == 0 ? "hand_l" : "hand_r"));
        Quat a_rot = socket_rotation(mesh, bone_fname(side == 0 ? "hand_l" : "hand_r"));
        FreeGrip g;
        g.set = true;
        g.place = true;
        g.pivot = w0_rot.inverse().rotate(point - w0_pos);
        g.in_anchor = a_rot.inverse().rotate(palm - a_pos);
        g.rel = (a_rot.inverse() * w0_rot).normalized();
        if (axis)
        {
            Vec3 f = normalized(a_rot.inverse().rotate(*axis)), want = hand_grip_axis(side);
            if (dot(f, want) < 0.0) want = want * -1.0;
            Vec3 n = cross(f, want);
            double sn = length(n), c = dot(f, want);
            if (sn > 1e-6)
            {
                Quat turn = quat_axis_angle(n * (1.0 / sn), std::atan2(sn, c));
                g.rel = (turn * g.rel).normalized();
                HSVR_LOG("Grab: %s hand turns the %s %.0f deg to lie along the hand's grip line", side == 0 ? "left" : "right", what, std::atan2(sn, c) * 180.0 / 3.14159265358979);
            }
        }
        g.what = what;
        return g;
    }

    // The same, for a weapon just set up in that hand: applied when its hold starts.
    void hold_where_touched(int side, UObject* mesh, UObject* weapon, UObject* base, const hsvr::Vec3& w0_pos, const hsvr::Quat& w0_rot, const hsvr::Vec3& palm,
                            const hsvr::Vec3& point, const char* what, const hsvr::Vec3* axis = nullptr, bool fingers = false)
    {
        using namespace hsvr;
        g_pending_free[side] = make_free_grip(side, mesh, w0_pos, w0_rot, palm, point, axis, what);
        g_pending_item[side] = weapon;
        g_pending_free[side].hold_at = hsvr::config().pose_grab_settle_s > 0.0;
        g_pending_free[side].at_pos = w0_pos;
        g_pending_free[side].at_rot = w0_rot;
        g_pending_free[side].place = !g_pending_free[side].hold_at;
        g_pending_free[side].fingers = fingers;
        set_component_transform(base, w0_pos, w0_rot, true);
        HSVR_LOG("Grab: %s hand took %ls by the %s (%.1f cm from the hand), held in the hand there", side == 0 ? "left" : "right", weapon->GetName().c_str(), what,
                 length(point - palm));
    }

    // The fitting of a shield nearest a point (shield BaseMesh frame): its name, the point on it and
    // its line. `within` limits the distance (cm); game_only takes only the game's own for that hand.
    const ShieldFitting* nearest_fitting(const std::wstring& cls, const hsvr::Vec3& local, double within, int side, bool game_only, hsvr::Vec3& on, double& dist,
                                         int* known = nullptr);

    const ShieldFitting* nearest_fitting(const std::wstring& cls, const hsvr::Vec3& local, double within, int side, bool game_only, hsvr::Vec3& on, double& dist,
                                         int* known)
    {
        using namespace hsvr;
        const ShieldFitting* best = nullptr;
        dist = within;
        if (known) *known = 0;
        for (const ShieldFitting& f : k_shield_fittings)
        {
            if (cls != f.shield) continue;
            if (known) ++*known;
            if (game_only && !(side == 1 ? f.game_r : f.game_l)) continue;
            Vec3 c{f.cx, f.cy, f.cz}, a = normalized(Vec3{f.ax, f.ay, f.az});
            double t = (std::max)(-f.length * 0.5, (std::min)(f.length * 0.5, dot(local - c, a)));
            Vec3 p = c + a * t;
            double d = length(local - p);
            if (d <= dist)
            {
                dist = d;
                best = &f;
                on = p;
            }
        }
        return best;
    }

    std::wstring shield_class(UObject* shield)
    {
        std::wstring cls = shield && shield->GetClassPrivate() ? shield->GetClassPrivate()->GetName() : std::wstring();
        if (cls.size() > 2 && cls.substr(cls.size() - 2) == STR("_C")) cls.resize(cls.size() - 2);
        return cls;
    }

    // A shield's plate normal in its BaseMesh frame: the local axis with the least collision across it
    // (asked from 200 cm out each way, as hsvr.bring_object's rim test), found once per class.
    hsvr::Vec3 shield_plate_normal(UObject* shield, UObject* base)
    {
        using namespace hsvr;
        static std::unordered_map<std::wstring, Vec3> known;
        std::wstring cls = shield_class(shield);
        auto f = known.find(cls);
        if (f != known.end()) return f->second;
        Vec3 centre = component_location(base);
        Quat rot = component_rotation(base);
        const Vec3 axes[3] = {{1, 0, 0}, {0, 1, 0}, {0, 0, 1}};
        double across[3];
        bool ok = true;
        for (int a = 0; a < 3; ++a)
        {
            across[a] = 0.0;
            for (double sgn : {1.0, -1.0})
            {
                Vec3 dir = rot.rotate(axes[a] * sgn), p;
                if (closest_on_weapon(shield, centre + dir * 200.0, &p) < 0.0)
                {
                    ok = false;
                    p = centre;
                }
                across[a] += dot(p - centre, dir);
            }
        }
        int thin = 0;
        for (int a = 1; a < 3; ++a)
            if (across[a] < across[thin]) thin = a;
        HSVR_LOG("Shield: %ls across its local X %.1f, Y %.1f, Z %.1f cm: plate faces along %c", cls.c_str(), across[0], across[1], across[2], "XYZ"[thin]);
        if (ok) known[cls] = axes[thin];
        return axes[thin];
    }

    // A pavise's rear strap (pose_pavise_strap), and where that pavise sits on each forearm: the point of
    // its BaseMesh that lands on the game's shield_<s>_socket and the turn there, as Set Up <S> Hand Weapon
    // places "Grip <S> Hand Default Pos" on it (@3701-4222). The heavy's left and the light's both are the
    // game's own scenes. The game has none for the heavy on the right: that is the left's mirror image,
    // still top up, the long strap round the arm by the wrist. Nor for the tower, which has no forearm
    // strap: the middle of its crossed strap is used, placed as the heavy is.
    struct PaviseSpec
    {
        const wchar_t* shield;
        const char* strap;
        struct
        {
            double x, y, z, pitch, yaw, roll;
        } at[2]; // left, right
    };
    const PaviseSpec k_pavises[] = {
        {L"Shield_Pavise_Heavy", "long strap", {{-7, 0, 16, 0, -5, -20}, {17, 0, 16, 0, 5, -20}}},
        {L"Shield_Pavise_Light", "lower strap", {{0, 0, 6, -90, 0, 0}, {0, 0, 6, 90, 0, 0}}},
        {L"Shield_Pavise_Tower", "crossed strap's middle", {{-7, 0, 0, 0, -5, -20}, {7, 0, 0, 0, 5, -20}}},
        // Matthew 2026-11-23: his "pavise" was the small shoulder shield, so the targe (the other SheathSlot 2
        // shield) gets the same rules. Held by its big strap: the loop that stands off the back, the one the
        // game's own right-hand pose closes the fist on (shield_grab_points.md, screenshot 112). On the
        // forearm: the game's own scenes, L (0.18, 0, -4.67) and R (-3.05, 0, -1.54), both P-45 (shield_grips.md).
        {L"Shield_Tagre", "big strap", {{0.18, 0, -4.67, -45, 0, 0}, {-3.05, 0, -1.54, -45, 0, 0}}},
    };
    const PaviseSpec* pavise_spec(UObject* item)
    {
        if (!item || !class_name_starts(item, STR("Shield_"))) return nullptr;
        std::wstring cls = shield_class(item);
        for (const PaviseSpec& p : k_pavises)
            if (cls == p.shield) return &p;
        return nullptr;
    }

    // Pavises start locked to the forearm, like a real pavise (Matthew 2026-11-20). The game already
    // straps a shield to the forearm for grip types 6 (Shield) and 7 (Shield_Heavy): its joint is to
    // lowerarm_x at shield_x_socket (shield_grips.md). Pavise_Light is 6 for both hands (forearm through
    // its lower strap, fist on its top handle); Pavise_Heavy is 7 for the left hand only (forearm
    // through its long strap, fist on its side bar) and 8 (a handle in the hand) for the right; the
    // Tower pavise is 8 for both and has no forearm strap on its mesh. So: the game's own forearm
    // grip, kept (not moved into the hand), wherever the game has one for that hand.
    // A shield mounted on a forearm that this arm's own hand closed on: held with the game's own forearm grip
    // (fist on its forward grip) until that hand opens, then mounted again (mount_grip / mount_fist_release).
    UObject* g_mount_fist[2] = {nullptr, nullptr};
    bool g_mount_fist_tracked = track_freed(&g_mount_fist[0]) && track_freed(&g_mount_fist[1]);
    bool g_mount_fist_game[2] = {false, false}; // held with the game's forearm grip (pose_mount_fist_grip 2), not by a handle
    // How far it moved from its mounted place as the hand took the forward grip, measured 0.3 s after (cm).
    double g_mount_fist_moved[2] = {-1.0, -1.0};
    struct MountFistCheck
    {
        double at = -1.0;
        hsvr::Vec3 from{};
        hsvr::Quat from_q{0, 0, 0, 1};
    };
    MountFistCheck g_mount_fist_check[2];
    bool pavise_on_forearm(UObject* shield, int side, const hsvr::Config& cfg)
    {
        if (shield && shield == g_mount_fist[side] && g_mount_fist_game[side]) return true;
        if (cfg.pose_pavise_strap && pavise_spec(shield)) return false; // held by the strap, mounted by the player
        if (!cfg.pose_pavise_forearm || !shield || !(class_name_starts(shield, STR("Shield_Pavise")) || class_name_starts(shield, STR("Shield_Tagre")))) return false;
        double g = read_number_variable(shield, side == 0 ? STR("Grip L Hand Default") : STR("Grip R Hand Default"));
        return g == 6.0 || g == 7.0;
    }

    // ---- Pavises by the rear strap (pose_pavise_strap, Matthew 2026-11-22) ---------------------------
    // Off the back only the hand across the body from the strap takes one, and holds it in the hand by
    // the strap. The other hand taking the strap gets it. Let go by the back of the other forearm, it is
    // mounted there by a joint of the mod's, and that hand stays free: Weapon L/R is NOT the shield. The
    // game needs it there for nothing a block or a hit reads (ModularWeaponBP tells its user by Last
    // Parent @62285 / @67069, Sheathed @62363 and Is Held @42700 / @62991 / @65103); Set Weapon Damping
    // Pick Up gives it Is Held (which also keeps the game's pickups off it, UG @217087 / @224880), its
    // held mass and the boxes the AI reads a held shield by (My Box Collisions @1132-1544, AI_BP @30683).
    const Handle* pavise_strap(UObject* w, UObject* base)
    {
        const PaviseSpec* spec = base ? pavise_spec(w) : nullptr;
        if (!spec) return nullptr;
        for (const Handle& hd : item_handles(w, base))
            if (hd.name == spec->strap) return &hd;
        return nullptr;
    }

    hsvr::Vec3 handle_middle(const Handle& hd) { return (hd.a + hd.b) * 0.5; }

    double to_segment(const hsvr::Vec3& p, const hsvr::Vec3& a, const hsvr::Vec3& b, hsvr::Vec3* on = nullptr)
    {
        using namespace hsvr;
        Vec3 ab = b - a;
        double len2 = dot(ab, ab);
        double u = len2 > 1e-6 ? (std::min)(1.0, (std::max)(0.0, dot(p - a, ab) / len2)) : 0.0;
        Vec3 q = a + ab * u;
        if (on) *on = q;
        return length(p - q);
    }

    // The hand across the body from a strap at this point: spine_05's X is his left. -1: either (a strap
    // on the spine, as the tower's).
    int opposite_hand(UObject* mesh, const hsvr::Vec3& strap)
    {
        using namespace hsvr;
        static const FName spine = bone_fname("spine_05");
        double x = socket_rotation(mesh, spine).inverse().rotate(strap - socket_location(mesh, spine)).x;
        if (std::fabs(x) < 4.0) return -1;
        return x > 0.0 ? 1 : 0;
    }

    // The hand that may take or hang a pavise on his back (Matthew 2026-11-22: only the opposite-side
    // hand). SheathSlot 2 hangs it on Sheath_Slot_Shoulder_L, on upperarm_l (back_slot_physics.md), so
    // the right hand, whatever the strap's X: the light pavise's strap sits within 4 cm of the spine
    // there and either hand got it (test slot 2026-11-22, 2 of 9). SheathSlot 3 (Sheath_Slot_Back, mid
    // back): across from its strap; -1 = either (a strap on the spine, as the tower's).
    int back_pavise_hand(UObject* mesh, UObject* w, const hsvr::Vec3& strap)
    {
        if (read_number_variable(w, STR("SheathSlot")) == 2.0) return 1;
        return opposite_hand(mesh, strap);
    }

    const char* pavise_back_socket(UObject* w) { return read_number_variable(w, STR("SheathSlot")) == 2.0 ? "Sheath_Slot_Shoulder_L" : "Sheath_Slot_Back"; }

    // Where a pavise sat when it hung, in its slot socket's frame (kept at each take off the back).
    struct HungPose
    {
        hsvr::Vec3 pos;
        hsvr::Quat rot;
    };
    std::unordered_map<UObject*, HungPose> g_hung;

    void remember_hung(UObject* mesh, UObject* w, const hsvr::Vec3& p, const hsvr::Quat& q)
    {
        using namespace hsvr;
        static bool tracked = on_freed([] { erase_gone_keys(g_hung); });
        (void)tracked;
        FName sock = bone_fname(pavise_back_socket(w));
        Quat iq = socket_rotation(mesh, sock).inverse();
        g_hung[w] = HungPose{iq.rotate(p - socket_location(mesh, sock)), (iq * q).normalized()};
    }

    // Where its strap would be, hung again. Never seen hung: the socket's pose, 7 cm down it on the back
    // (where the heavy rests there, pavise_strap_and_scabbard_hold.md (a)).
    void hung_strap(UObject* mesh, UObject* w, const Handle& strap, hsvr::Vec3& a, hsvr::Vec3& b)
    {
        using namespace hsvr;
        FName sock = bone_fname(pavise_back_socket(w));
        HungPose hp{Vec3{0, 0, read_number_variable(w, STR("SheathSlot")) == 3.0 ? -7.0 : 0.0}, Quat{}};
        auto known = g_hung.find(w);
        if (known != g_hung.end()) hp = known->second;
        Vec3 sp = socket_location(mesh, sock);
        Quat sq = socket_rotation(mesh, sock);
        a = sp + sq.rotate(hp.pos + hp.rot.rotate(strap.a));
        b = sp + sq.rotate(hp.pos + hp.rot.rotate(strap.b));
    }

    bool held_by_strap(int side, UObject* w)
    {
        const FreeGrip* g = nullptr;
        if (g_pending_item[side] == w && g_pending_free[side].set) g = &g_pending_free[side];
        else if (g_hold[side].weapon == w && g_hold[side].free.set) g = &g_hold[side].free;
        if (!g) return false;
        const PaviseSpec* spec = pavise_spec(w);
        return spec && g->handle == spec->strap;
    }

    // Into that hand by its strap, from where it is.
    bool take_by_strap(int side, UObject* pawn, UObject* mesh, UObject* w, UObject* base, const Handle& strap, const hsvr::Vec3& palm)
    {
        using namespace hsvr;
        Vec3 p = component_location(base);
        Quat q = component_rotation(base);
        if (!give_hand_weapon(side, pawn, w) || object_property(pawn, side == 0 ? STR("Weapon L") : STR("Weapon R")) != w) return false;
        FreeGrip g = handle_grip(side, mesh, p, q, palm, strap, 0.5);
        g.hold_at = hsvr::config().pose_grab_settle_s > 0.0;
        g.at_pos = p;
        g.at_rot = q;
        g.place = !g.hold_at;
        g_pending_free[side] = g;
        g_pending_item[side] = w;
        set_component_transform(base, p, q, true); // back from where the game's set-up snapped it
        return true;
    }

    // The other hand on the rear strap of a pavise in a hand: it passes to that hand.
    bool pavise_pass(int side, UObject* pawn, UObject* mesh, const hsvr::Config& cfg)
    {
        using namespace hsvr;
        if (!cfg.pose_pavise_strap || g_two.active) return false;
        int from = 1 - side;
        UObject* w = object_property(pawn, from == 0 ? STR("Weapon L") : STR("Weapon R"));
        if (!w || g_hold[from].weapon != w || in_own_slot(pawn, w)) return false;
        UObject* base = object_property(w, STR("BaseMesh"));
        const Handle* strap = pavise_strap(w, base);
        if (!strap) return false;
        Vec3 palm = hand_grab_point(mesh, side);
        double d = to_segment(component_rotation(base).inverse().rotate(palm - component_location(base)), strap->a, strap->b);
        if (d > cfg.pose_grab_handle_cm) return false;
        Vec3 p = component_location(base);
        Quat q = component_rotation(base);
        drop_weapon(from, pawn, false);
        clear_arm_ignore(from); // else the new hand's hold would switch off only its forearm against it
        g_pending_free[from] = FreeGrip{};
        g_pending_item[from] = nullptr;
        set_component_transform(base, p, q, true);
        bool ok = take_by_strap(side, pawn, mesh, w, base, *strap, palm);
        if (ok) controllers_buzz(side, 0.4f);
        HSVR_LOG("Pavise: %s hand %s %ls by its %s from the %s hand (%.1f cm from it)", side == 0 ? "left" : "right", ok ? "takes" : "could NOT take",
                 w->GetName().c_str(), strap->name.c_str(), from == 0 ? "left" : "right", d);
        return true;
    }

    // One pavise on each forearm, by that arm's side.
    struct Mount
    {
        UObject* weapon = nullptr;
        UObject* base = nullptr;
        UObject* mesh = nullptr;
        UObject* pawn = nullptr;
        UObject* anchor = nullptr; // a kinematic sphere of the mod's, moved with the forearm's shield socket
        UObject* joint = nullptr;  // anchor <-> shield, locked
        std::vector<UObject*> no_collide; // against his own bodies
        UObject* beside = nullptr;        // what that arm's hand holds, not colliding with it either
        UObject* beside_joint = nullptr;
        const PaviseSpec* spec = nullptr;
        bool gripped = false; // that arm's own hand is on its strap (or on its handle: handle not empty)
        std::string handle;   // the handle that hand closed on, the shield still strapped on (pose_mount_fist_grip 1)
        hsvr::Vec3 shift{0.0, 0.0, 0.0}; // shield-frame move off the strap's place while that hand holds its forward grip (handle into the palm)
        bool unstuck = false; // its "Static Mesh Collision Disabled (Unstuck)" as last seen
        double last_log = -1e9;
    };
    Mount g_mount[2];
    bool g_mount_tracked = on_freed([] {
        for (Mount& m : g_mount)
        {
            erase_gone(m.no_collide);
            for (UObject** p : {&m.anchor, &m.joint, &m.beside, &m.beside_joint})
                if (gone(*p)) *p = nullptr;
            if (gone(m.weapon) || gone(m.base) || gone(m.mesh) || gone(m.pawn)) m = Mount{};
        }
    });

    bool mount_gripped(int side) { return g_mount[side].gripped; }
    bool mount_on_handle(int side) { return g_mount[side].weapon && g_mount[side].gripped && !g_mount[side].handle.empty(); }
    void mount_pose(int arm, const Mount& m, hsvr::Vec3& p, hsvr::Quat& q);
    double mount_off_cm(int side)
    {
        const Mount& m = g_mount[side];
        if (!m.weapon || !m.base || !object_alive(m.weapon)) return -1.0;
        hsvr::Vec3 p;
        hsvr::Quat q;
        mount_pose(side, m, p, q);
        return hsvr::length(component_location(m.base) - p);
    }
    bool is_mounted(UObject* w) { return w && (w == g_mount[0].weapon || w == g_mount[1].weapon); }

    // His "Ignore Pick Up Array" (TArray<AActor*>): the actors his own traces look through. The game puts
    // each weapon in a hand there (Set Up Right Hand Weapon @3568, Left @3672) and each sheathed one (Create
    // Sheath Constraint L @3627, Sheathe on Spawn @5541), and takes it out when the hand lets go (Set Up
    // <S> Hand Weapon @9504/@11175, Right @10094/@11268). A pavise on a forearm is in neither, so it was out:
    // his head-room trace (UG @49612: a line from 100 to 180 cm over the middle of his feet, ignoring this
    // list) then hit his own shield and set Head Hitting Ceiling (@51331: blocking hit and distance > 1),
    // which crouches him (ABP Is Crouched?? @229009) for the 1 s until it is traced again: 5 of 8 light pavise
    // mounts in test 00daa6e (Matthew 2026-11-23: "a vomit-like animation" each time it goes on or off).
    // In place only: an entry is added only into the room already there (no allocation of ours in the
    // game's array); none is logged.
    bool own_ignore(UObject* pawn, UObject* actor, bool want)
    {
        if (!pawn || !actor) return false;
        FProperty* p = prop_chain(pawn, STR("Ignore Pick Up Array"));
        if (!p) return false;
        struct Arr { UObject** data; int32_t num, max; };
        auto* a = reinterpret_cast<Arr*>(reinterpret_cast<uint8_t*>(pawn) + p->GetOffset_Internal());
        if (a->num < 0 || a->num > a->max || (a->num > 0 && !a->data)) return false;
        int at = -1;
        for (int32_t i = 0; i < a->num; ++i)
            if (a->data[i] == actor)
            {
                at = i;
                break;
            }
        if (want)
        {
            if (at >= 0) return true;
            if (!a->data || a->num >= a->max)
            {
                HSVR_LOG_EVERY(5.0, "Pavise: no room in his Ignore Pick Up Array (%d of %d) for %ls: not added", a->num, a->max, actor->GetName().c_str());
                return false;
            }
            a->data[a->num++] = actor;
            HSVR_LOG("Pavise: %ls added to his Ignore Pick Up Array (%d of %d): his own traces look through it", actor->GetName().c_str(), a->num, a->max);
            return true;
        }
        if (at < 0) return false;
        for (int32_t i = at; i + 1 < a->num; ++i) a->data[i] = a->data[i + 1];
        a->data[--a->num] = nullptr;
        HSVR_LOG("Pavise: %ls out of his Ignore Pick Up Array (%d left)", actor->GetName().c_str(), a->num);
        return true;
    }

    // Each change of his Head Hitting Ceiling, logged with what the game's own trace for it hits now (the same
    // line, channel and ignore list, UG @48880-49743), so a test shows what crouched him.
    void ceiling_watch(UObject* pawn)
    {
        using namespace hsvr;
        static UObject* last_pawn = nullptr;
        static bool was = false;
        if (!pawn) return;
        const bool now_on = bool_property(pawn, STR("Head Hitting Ceiling"));
        if (pawn != last_pawn) last_pawn = pawn, was = now_on;
        if (now_on == was) return;
        was = now_on;
        if (!now_on)
        {
            HSVR_LOG("Ceiling: Head Hitting Ceiling off");
            return;
        }
        static UObject* cdo = UObjectGlobals::StaticFindObject<UObject*>(nullptr, nullptr, STR("/Script/Engine.Default__KismetSystemLibrary"));
        static UObject* gs = UObjectGlobals::StaticFindObject<UObject*>(nullptr, nullptr, STR("/Script/Engine.Default__GameplayStatics"));
        const double* r = value_ptr<double>(pawn, STR("R Foot On Ground Loc"));
        const double* l = value_ptr<double>(pawn, STR("L Foot On Ground Loc"));
        const double* scale = value_ptr<double>(pawn, STR("Character Scale (Set in BP)"));
        FProperty* ip = prop_chain(pawn, STR("Ignore Pick Up Array"));
        if (!cdo || !gs || !r || !l || !ip)
        {
            HSVR_LOG("Ceiling: Head Hitting Ceiling on (its trace could not be repeated)");
            return;
        }
        const double s = scale ? scale[0] : 1.0;
        Vec3 from{(r[0] + l[0]) * 0.5, (r[1] + l[1]) * 0.5, (r[2] + l[2]) * 0.5 + 100.0 * s};
        Vec3 to{from.x, from.y, from.z + 80.0 * s};
        Call trace(cdo, STR("LineTraceSingle"));
        if (!trace.fn) return;
        trace.object(STR("WorldContextObject"), pawn);
        trace.three(STR("Start"), from.x, from.y, from.z);
        trace.three(STR("End"), to.x, to.y, to.z);
        trace.byte(STR("TraceChannel"), 5);
        trace.flag(STR("bTraceComplex"), false);
        trace.flag(STR("bIgnoreSelf"), true);
        FProperty* tp = trace.param(STR("ActorsToIgnore"));
        if (tp) std::memcpy(trace.buffer.data() + tp->GetOffset_Internal(), reinterpret_cast<uint8_t*>(pawn) + ip->GetOffset_Internal(), 16); // his list, read only
        bool ran = trace.run();
        if (tp) std::memset(trace.buffer.data() + tp->GetOffset_Internal(), 0, tp->GetSize()); // never ours to free
        FProperty* ret = trace.param(STR("ReturnValue"));
        FProperty* hit = trace.param(STR("OutHit"));
        if (!ran || !ret || !hit || !(*(trace.buffer.data() + ret->GetOffset_Internal()) & 1))
        {
            HSVR_LOG("Ceiling: Head Hitting Ceiling on; its trace repeated now (%.0f %.0f %.0f up %.0f cm) hits nothing", from.x, from.y, from.z, 80.0 * s);
            return;
        }
        Call b(gs, STR("BreakHitResult"));
        FProperty* hp = b.param(STR("Hit"));
        if (!hp) return;
        std::memcpy(b.buffer.data() + hp->GetOffset_Internal(), trace.buffer.data() + hit->GetOffset_Internal(), (std::min)(hp->GetSize(), hit->GetSize()));
        b.run();
        UObject* actor = b.object_result(STR("HitActor"));
        UObject* comp = b.object_result(STR("HitComponent"));
        HSVR_LOG("Ceiling: Head Hitting Ceiling on; its trace repeated now hits %ls / %ls %.1f cm up from %.0f cm over his feet%s", actor ? actor->GetName().c_str() : STR("?"),
                 comp ? comp->GetName().c_str() : STR("?"), b.number(STR("Distance")), 100.0 * s,
                 is_mounted(actor) ? " (his own mounted pavise)" : actor && (actor == object_property(pawn, STR("Weapon L")) || actor == object_property(pawn, STR("Weapon R"))) ? " (in his hand)" : "");
    }

    void destroy_joint(UObject*& j)
    {
        if (!j) return;
        Call d(j, STR("K2_DestroyComponent"));
        d.object(STR("Object"), j);
        d.run();
        j = nullptr;
    }

    // motion 0 free (it only switches the pair's collision off), 2 locked.
    UObject* pair_joint(UObject* pawn, UObject* a, UObject* b, FName bone, uint8_t motion, UObject* attach_to = nullptr, const FName* socket = nullptr)
    {
        static UClass* cls = UObjectGlobals::StaticFindObject<UClass*>(nullptr, nullptr, STR("/Script/Engine.PhysicsConstraintComponent"));
        if (!cls) return nullptr;
        UObject* j = new_constraint(pawn, cls);
        if (!j) return nullptr;
        if (attach_to && socket)
        {
            // The game's hand joint sits on the socket too (Set Up Left Hand Weapon @6276).
            Call at(j, STR("K2_AttachToComponent"));
            at.object(STR("Parent"), attach_to);
            at.name(STR("SocketName"), *socket);
            at.byte(STR("LocationRule"), 2); // SnapToTarget
            at.byte(STR("RotationRule"), 2);
            at.byte(STR("ScaleRule"), 2);
            at.flag(STR("bWeldSimulatedBodies"), false);
            at.run();
        }
        for (const TCHAR* fn : {STR("SetLinearXLimit"), STR("SetLinearYLimit"), STR("SetLinearZLimit")})
        {
            Call c(j, fn);
            c.byte(STR("ConstraintType"), motion);
            c.number(STR("LimitSize"), 0.0);
            c.run();
        }
        // By type, not by name: the engine calls the twist's motion "ConstraintType" and the swings' "MotionType",
        // and a missed name leaves the byte 0 = free (test 2026-11-22 06:27Z: ang 2 2 0, a mounted pavise
        // swung up to 151 deg about the forearm).
        for (const TCHAR* fn : {STR("SetAngularSwing1Limit"), STR("SetAngularSwing2Limit"), STR("SetAngularTwistLimit")})
            pin_angular_limit(j, fn, motion, 0.0);
        Call dc(j, STR("SetDisableCollision"));
        dc.first_flag(true);
        dc.run();
        Call join(j, STR("SetConstrainedComponents"));
        join.object(STR("Component1"), a);
        join.name(STR("BoneName1"), FName());
        join.object(STR("Component2"), b);
        join.name(STR("BoneName2"), bone);
        join.run();
        return j;
    }

    UObject* jh_add(UObject* pawn, const TCHAR* cls);

    // The anchor: as the joint hold's sphere (jh_make), it touches nothing. Its collision is switched to
    // PhysicsOnly once, before anything is jointed to it: a body exists only so.
    UObject* mount_anchor(UObject* pawn, const hsvr::Vec3& at, const hsvr::Quat& rot)
    {
        UObject* s = jh_add(pawn, STR("/Script/Engine.SphereComponent"));
        if (!s) return nullptr;
        Call ab(s, STR("SetAbsolute"));
        ab.flag(STR("bNewAbsoluteLocation"), true);
        ab.flag(STR("bNewAbsoluteRotation"), true);
        ab.flag(STR("bNewAbsoluteScale"), true);
        ab.run();
        Call r(s, STR("SetSphereRadius"));
        r.number(STR("InSphereRadius"), 1.0);
        r.flag(STR("bUpdateOverlaps"), false);
        r.run();
        Call hid(s, STR("SetHiddenInGame"));
        hid.first_flag(true);
        hid.run();
        Call ov(s, STR("SetGenerateOverlapEvents"));
        ov.first_flag(false);
        ov.run();
        Call all(s, STR("SetCollisionResponseToAllChannels"));
        all.byte(STR("NewResponse"), 0); // ignore everything
        all.run();
        Call sim(s, STR("SetSimulatePhysics"));
        sim.first_flag(false);
        sim.run();
        if (FProperty* step = prop_chain(s, STR("CanCharacterStepUpOn"))) *(reinterpret_cast<uint8_t*>(s) + step->GetOffset_Internal()) = 0;
        set_component_transform(s, at, rot, true); // a new component: placed once
        Call ce(s, STR("SetCollisionEnabled"));
        ce.byte(STR("NewType"), 2); // PhysicsOnly
        ce.run();
        return s;
    }

    void unjoin_mount(Mount& m)
    {
        destroy_joint(m.joint);
        destroy_joint(m.anchor);
        destroy_joint(m.beside_joint);
        m.beside = nullptr;
        for (UObject* j : m.no_collide) destroy_joint(j);
        m.no_collide.clear();
    }

    // Where a mount belongs now.
    void mount_pose(int arm, const Mount& m, hsvr::Vec3& p, hsvr::Quat& q)
    {
        using namespace hsvr;
        static const FName sockets[2] = {bone_fname("shield_l_socket"), bone_fname("shield_r_socket")};
        const auto& at = m.spec->at[arm];
        q = (socket_rotation(m.mesh, sockets[arm]) * rot_to_quat(-at.pitch, -at.yaw, -at.roll)).normalized();
        p = socket_location(m.mesh, sockets[arm]) - q.rotate(Vec3{at.x, at.y, at.z}) + q.rotate(m.shift);
    }

    // Placed on the forearm (one teleport) and jointed to it: at the mount, and again only when the
    // game's unstick has rebuilt its collision.
    bool join_mount(int arm, Mount& m)
    {
        using namespace hsvr;
        static const FName sockets[2] = {bone_fname("shield_l_socket"), bone_fname("shield_r_socket")};
        Vec3 p;
        Quat q;
        mount_pose(arm, m, p, q);
        set_component_transform(m.base, p, q, true);
        // Not to Mesh:lowerarm, as the game's hand joint is (Set Up Left Hand Weapon @14301): his kinematic
        // forearm body is not where the arm is drawn. It is moved to the drawn place afresh every step
        // (120-360 cm/s standing still), and a shield on it hung 2.5-7 cm off (tests 2026-11-22 06:38Z).
        m.anchor = mount_anchor(m.pawn, socket_location(m.mesh, sockets[arm]), socket_rotation(m.mesh, sockets[arm]));
        if (!m.anchor) return false;
        m.joint = pair_joint(m.pawn, m.base, m.anchor, FName(), 2, m.mesh, &sockets[arm]);
        if (!m.joint)
        {
            destroy_joint(m.anchor);
            return false;
        }
        // As held: it touches none of his own bodies (the game's NewFunction_0 @537, UG @97167). What Set Up
        // <S> Hand Weapon switched off as it was taken (his armour's bodies @16370, his sheathed items
        // @17145-20157) stays off: only the next taker, or 3 m from Last Parent (ModularWeaponBP @144-302),
        // switches it back on.
        for (FName bone : physics_body_bones(m.mesh))
            if (UObject* j = pair_joint(m.pawn, m.base, m.mesh, bone, 0)) m.no_collide.push_back(j);
        return true;
    }

    // Off the arm, and loose as a dropped weapon is.
    void unmount_loose(int arm, const char* why)
    {
        Mount m = g_mount[arm];
        g_mount[arm] = Mount{};
        unjoin_mount(m);
        own_ignore(m.pawn, m.weapon, false); // loose: his pickups find it again
        Call(m.weapon, STR("Set Weapon Damping Drop")).run();
        HSVR_LOG("Pavise: %ls comes off the %s forearm (%s)", m.weapon->GetName().c_str(), arm == 0 ? "left" : "right", why);
    }

    bool mount_on(int arm, int side, UObject* pawn, UObject* mesh, UObject* w, UObject* base, const PaviseSpec* spec);
    // Let go of the strap by the back of the other forearm: mounted on it.
    bool pavise_mount(int side, UObject* pawn, UObject* mesh, UObject* w, const hsvr::Config& cfg)
    {
        using namespace hsvr;
        if (!cfg.pose_pavise_strap || g_two.active || !held_by_strap(side, w)) return false;
        const int arm = 1 - side;
        const char* hand = side == 0 ? "left" : "right";
        UObject* base = object_property(w, STR("BaseMesh"));
        const PaviseSpec* spec = pavise_spec(w);
        if (!base || !spec) return false;
        static const FName sockets[2] = {bone_fname("shield_l_socket"), bone_fname("shield_r_socket")};
        static const FName lower[2] = {bone_fname("lowerarm_l"), bone_fname("lowerarm_r")};
        static const FName wrist[2] = {bone_fname("hand_l"), bone_fname("hand_r")};
        Vec3 palm = hand_grab_point(mesh, side), on;
        double d = to_segment(palm, socket_location(mesh, lower[arm]), socket_location(mesh, wrist[arm]), &on);
        // The socket's +Y is out of the back of the forearm (a shield's face there). Logged only: requiring
        // the palm on that side (>= -3 cm) failed every one of Matthew's mounts (playtest 2026-11-23 00:3xZ,
        // 6 of 6, his palm 3.4-8.1 cm on the palm side at 3.5-8.9 cm from the forearm). Distance alone.
        double behind = dot(palm - on, socket_rotation(mesh, sockets[arm]).rotate(Vec3{0, 1, 0}));
        if (d > cfg.pose_pavise_mount_cm)
        {
            if (d < 40.0)
                HSVR_LOG("Pavise: %s hand let go of the strap %.1f cm from the other forearm, %.1f cm to its back (needs %.0f cm): not mounted", hand, d, behind,
                         cfg.pose_pavise_mount_cm);
            return false;
        }
        // The shoulder's hung strap is a few cm from where the left forearm is held at the chest: with the
        // palm on that strap it was mounted on the arm whenever the palm was just on the arm's back side
        // (test b6_light_right 2026-11-22 19:24Z: strap 0.2 cm, arm 3.2 cm). The nearer wins.
        const double kind = read_number_variable(w, STR("SheathSlot"));
        const Handle* strap = pavise_strap(w, base);
        if (cfg.pose_holster_snap && strap && (kind == 2.0 || kind == 3.0) && !object_property(pawn, STR("Weapon Slot Back")))
        {
            Vec3 a, b;
            hung_strap(mesh, w, *strap, a, b);
            const int only = back_pavise_hand(mesh, w, (a + b) * 0.5);
            const double hang = to_segment(palm, a, b);
            if ((only < 0 || only == side) && hang <= cfg.pose_holster_zone_cm && hang < d)
            {
                HSVR_LOG("Pavise: %s hand let go of the strap %.1f cm from where it hangs, nearer than the other forearm (%.1f cm): hung, not mounted", hand, hang, d);
                return false;
            }
        }
        const char* no = nullptr;
        if (g_mount[arm].weapon) no = "that forearm has one";
        else if (bool_property(pawn, arm == 0 ? STR("Hand L Torn Off") : STR("Hand R Torn Off"))) no = "that arm is cut off";
        else if (in_own_slot(pawn, w)) no = "still leaving its slot";
        else if (g_hand_world_v[side] > cfg.pose_holster_max_speed) no = "hand too fast: a throw";
        if (no)
        {
            HSVR_LOG("Pavise: %s hand let go of the strap by the other forearm: not mounted (%s)", hand, no);
            return false;
        }
        if (!mount_on(arm, side, pawn, mesh, w, base, spec)) return true;
        controllers_buzz(side, 0.4f);
        controllers_buzz(arm, 0.3f);
        HSVR_LOG("Pavise: %s hand let go of the %s %.1f cm from the %s forearm: %ls mounted there, that hand free", hand, spec->strap, d,
                 arm == 0 ? "left" : "right", w->GetName().c_str());
        return true;
    }

    // Out of hand <side> (Set Up <S> Hand Weapon(None): that hand's joint goes) and mounted on forearm <arm>.
    // False when no joint could be made (then it is loose).
    bool mount_on(int arm, int side, UObject* pawn, UObject* mesh, UObject* w, UObject* base, const PaviseSpec* spec)
    {
        drop_weapon(side, pawn, false);
        clear_arm_ignore(side);
        g_pending_free[side] = FreeGrip{};
        g_pending_item[side] = nullptr;
        // What Set Up Left Hand Weapon gives a shield it straps on, bar Weapon L and the hand's grip
        // (@4418 owner, @4537 Last Parent, @19081 pick-up damping). Its SearchBeacon stays on: the game's
        // pickups pass over it on Is Held.
        Call own(w, STR("SetOwner"));
        own.object(STR("NewOwner"), pawn);
        own.run();
        set_variable(w, STR("Last Parent"), 0.0, pawn, nullptr);
        Call(w, STR("Set Weapon Damping Pick Up")).run();
        Mount& m = g_mount[arm];
        m = Mount{};
        m.weapon = w;
        m.base = base;
        m.mesh = mesh;
        m.pawn = pawn;
        m.spec = spec;
        m.unstuck = bool_property(w, STR("Static Mesh Collision Disabled (Unstuck)"));
        if (!join_mount(arm, m))
        {
            unmount_loose(arm, "no joint could be made");
            return false;
        }
        return true;
    }

    // The free hand on the strap of the pavise on the other forearm: off the arm, into that hand.
    bool pavise_unmount(int side, UObject* pawn, UObject* mesh, const hsvr::Vec3& palm, const hsvr::Config& cfg)
    {
        using namespace hsvr;
        const int arm = 1 - side;
        Mount& m = g_mount[arm];
        if (!m.weapon || m.pawn != pawn || !object_alive(m.weapon)) return false;
        const Handle* strap = pavise_strap(m.weapon, m.base);
        if (!strap) return false;
        double d = to_segment(component_rotation(m.base).inverse().rotate(palm - component_location(m.base)), strap->a, strap->b);
        if (d > cfg.pose_grab_handle_cm) return false;
        UObject* w = m.weapon;
        UObject* base = m.base;
        if (m.gripped) set_anim_grip(arm, -1); // that arm's fist was on its strap or handle: it opens
        unjoin_mount(m);
        m = Mount{};
        bool ok = take_by_strap(side, pawn, mesh, w, base, *strap, palm);
        if (ok) controllers_buzz(side, 0.4f); // in that hand: the game's set-up keeps it in his ignore list
        else own_ignore(pawn, w, false), Call(w, STR("Set Weapon Damping Drop")).run();
        HSVR_LOG("Pavise: %s hand %s %ls off the %s forearm by its %s (%.1f cm from it)", side == 0 ? "left" : "right", ok ? "takes" : "could NOT take",
                 w->GetName().c_str(), arm == 0 ? "left" : "right", strap->name.c_str(), d);
        return true;
    }

    // The mounted arm's own hand, with nothing else in reach: its fist on the shield's forward grip, as the
    // game holds a strap shield (grip 6: forearm through the strap, fist on the handle; Matthew 2026-11-23:
    // "I can't close my fist and grab the shield's grip, the forward grip, while the shield is on my
    // forearm"). The mount's joint goes and the game's own forearm grip holds it in that hand; the game's
    // scene for it is the one the mount uses (k_pavises), so it does not move. Opening the hand mounts it again.
    bool mount_grip(int side, UObject* pawn)
    {
        Mount& m = g_mount[side];
        if (!m.weapon || m.pawn != pawn) return false;
        const hsvr::Config& cfg = hsvr::config();
        const char* hand = side == 0 ? "left" : "right";
        UObject* w = m.weapon;
        const bool hand_free = object_alive(w) && !object_property(pawn, side == 0 ? STR("Weapon L") : STR("Weapon R"));
        // 1: the handle by the hand, held in that hand as any handle is (the mod's grip: the fingers close on
        // it and the shield follows the hand), the strap still round the forearm when the hand opens (Matthew
        // 2026-11-23 19:00Z: "When the light [Pavise] is strapped to my forearm, I still want the ability to
        // grab main handle, the one that's right by my hand"). His playtest on mode 2 (the game's forearm
        // grip): no handle in the hand, the hold pulling a forearm-jointed shield 26 cm and 95 deg off.
        // 1 (Matthew 2026-11-23 17:06, on the big pavise: "the arm strap is strapping it to my forearm, but when I
        // go to grab the grip, it then unstraps the forearm. I don't want that to happen. I want it to stay
        // strapped. The only way it comes unstrapped is if I go to grab that back strap with my other hand"):
        // the fist closes on the handle by the palm and the shield stays on the forearm's joint, as it was;
        // the hand opening leaves it so. Only the other hand on its back strap takes it off (pavise_unmount).
        // 3: the earlier 1, the handle taken into that hand and the strap's joint gone until the hand opens.
        if ((cfg.pose_mount_fist_grip == 1 || cfg.pose_mount_fist_grip == 3) && hand_free)
        {
            using namespace hsvr;
            Vec3 bp = component_location(m.base);
            Quat bq = component_rotation(m.base);
            Vec3 palm = hand_grab_point(m.mesh, side);
            const std::vector<Handle>& hs = item_handles(w, m.base);
            double t = 0.0, d = 1e9;
            Vec3 local_palm = bq.inverse().rotate(palm - bp);
            int hi = nearest_handle(hs, local_palm, t, d);
            // The forward grip first (the light pavise's upright handle, the heavy's centre handle): Matthew 11-24, 5-6
            // times: "I still can't grab the forward grip when it's strapped to my forearm". On the light pavise the
            // strap's place puts the palm 9.7-9.9 cm from that handle and 1-3 cm from the top handle, so the nearest
            // (the top) always won and the forward grip was past the 8 cm reach. Within pose_mount_forward_cm it is taken,
            // and the shield slides along the forearm so that handle sits in the palm, still strapped on.
            int fwd = -1;
            double fwd_t = 0.0, fwd_d = 1e9;
            for (int i = 0; i < (int)hs.size(); ++i)
                if (hs[i].name == "upright handle" || hs[i].name == "centre handle")
                {
                    std::vector<Handle> one{hs[i]};
                    double tt = 0.0, dd = 1e9;
                    nearest_handle(one, local_palm, tt, dd);
                    if (dd < fwd_d) fwd = i, fwd_t = tt, fwd_d = dd;
                }
            bool forward = fwd >= 0 && fwd_d <= cfg.pose_mount_forward_cm && cfg.pose_mount_fist_grip == 1;
            if (forward) hi = fwd, t = fwd_t, d = fwd_d;
            if (forward)
            {
                Vec3 ab = hs[hi].b - hs[hi].a;
                Vec3 on_local = hs[hi].a + ab * t;
                // Moved so that point lands on the palm (in the shield's frame, on top of any earlier move).
                m.shift = m.shift + (local_palm - on_local);
                unjoin_mount(m);
                if (!join_mount(side, m))
                {
                    m.shift = Vec3{0.0, 0.0, 0.0};
                    if (!join_mount(side, m)) unmount_loose(side, "no joint could be made after the forward grip");
                    HSVR_LOG("Pavise: %s hand: the forward grip move could not be jointed; back on the strap", hand);
                    return true;
                }
                m.gripped = true;
                m.handle = hs[hi].name;
                controllers_buzz(side, 0.3f);
                HSVR_LOG("Pavise: %s hand closes on the forward grip (%s) of %ls on its own forearm: was %.1f cm from the palm, the shield moved %.1f cm "
                         "along the arm to put it in the hand; it stays strapped on",
                         hand, m.handle.c_str(), w->GetName().c_str(), d, length(local_palm - on_local));
                return true;
            }
            if (hi < 0 || d > cfg.pose_mount_handle_cm)
            {
                HSVR_LOG("Pavise: %s hand closes by %ls on its forearm: no handle within %.0f cm of the palm (nearest %s %.1f cm): it closes on the strap", hand,
                         w->GetName().c_str(), cfg.pose_mount_handle_cm, hi >= 0 ? hs[hi].name.c_str() : "none", d);
            }
            else if (cfg.pose_mount_fist_grip == 1)
            {
                m.gripped = true;
                m.handle = hs[hi].name;
                controllers_buzz(side, 0.3f);
                HSVR_LOG("Pavise: %s hand closes on the %s of %ls on its own forearm (%.1f cm from the palm): it stays strapped on that forearm", hand,
                         m.handle.c_str(), w->GetName().c_str(), d);
                return true;
            }
            else
            {
                Handle hd = hs[hi];
                MountFistCheck check{now_seconds(), bp, bq};
                Mount keep = m;
                unjoin_mount(m);
                m = Mount{};
                // Held as it is on the forearm: the handle's point nearest the palm, the shield NOT turned to lie
                // along the hand's grip line (as take_by_strap turns it). Turned so, the light pavise swung 14 cm
                // and the heavy 18 cm off the forearm as the hand took it (PC run 229b88c), its strap off the arm.
                bool ok = give_hand_weapon(side, pawn, w) && object_property(pawn, side == 0 ? STR("Weapon L") : STR("Weapon R")) == w;
                if (ok)
                {
                    Vec3 ab = hd.b - hd.a;
                    double len2 = dot(ab, ab);
                    Vec3 local = bq.inverse().rotate(palm - bp);
                    double u = len2 > 1e-6 ? (std::min)(1.0, (std::max)(0.0, dot(local - hd.a, ab) / len2)) : 0.0;
                    Vec3 on = bp + bq.rotate(hd.a + ab * u);
                    FreeGrip g = make_free_grip(side, keep.mesh, bp, bq, palm, on, nullptr, hd.name.c_str());
                    g.grip_type = clamp_grip_type(side, side == 1 ? hd.grip_r : hd.grip_l);
                    g.handle = hd.name;
                    g.ha = hd.a;
                    g.hb = hd.b;
                    g.t = u;
                    g.hold_at = cfg.pose_grab_settle_s > 0.0;
                    g.at_pos = bp;
                    g.at_rot = bq;
                    g.place = !g.hold_at;
                    g_pending_free[side] = g;
                    g_pending_item[side] = w;
                    set_component_transform(keep.base, bp, bq, true); // back from where the game's set-up snapped it
                }
                if (ok)
                {
                    g_mount_fist[side] = w;
                    g_mount_fist_game[side] = false;
                    g_mount_fist_check[side] = check;
                    g_mount_fist_moved[side] = -1.0;
                    controllers_buzz(side, 0.3f);
                    HSVR_LOG("Pavise: %s hand closes on the %s of %ls on its own forearm (%.1f cm from the palm): held in that hand by it; opening the hand mounts it again",
                             hand, hd.name.c_str(), w->GetName().c_str(), d);
                    return true;
                }
                Call(w, STR("Set Weapon Damping Pick Up")).run();
                m = keep;
                m.joint = m.anchor = m.beside_joint = nullptr;
                m.beside = nullptr;
                m.no_collide.clear();
                if (!join_mount(side, m)) unmount_loose(side, "the hand could not take it and no joint could be made");
                HSVR_LOG("Pavise: %s hand could NOT take the %s of %ls; it stays mounted", hand, hd.name.c_str(), w->GetName().c_str());
                return true;
            }
        }
        // 2: the game's own forearm grip, only where the game has one for that hand (6 or 7), whose scene the
        // mount uses: the heavy pavise's right is 8 (a handle in the hand) and the tower has none.
        const double game_grip = object_alive(w) ? read_number_variable(w, side == 0 ? STR("Grip L Hand Default") : STR("Grip R Hand Default")) : 0.0;
        const bool forearm_grip = game_grip == 6.0 || game_grip == 7.0;
        if (cfg.pose_mount_fist_grip == 2 && !forearm_grip)
            HSVR_LOG_EVERY(2.0, "Pavise: %s hand: the game has no forearm grip for %ls in that hand (grip %.0f): it closes on the strap only", hand, w->GetName().c_str(),
                           game_grip);
        if (cfg.pose_mount_fist_grip == 2 && forearm_grip && hand_free)
        {
            Mount keep = m;
            g_mount_fist_check[side] = MountFistCheck{hsvr::now_seconds(), component_location(m.base), component_rotation(m.base)};
            g_mount_fist_moved[side] = -1.0;
            unjoin_mount(m);
            m = Mount{};
            g_mount_fist[side] = w;
            g_mount_fist_game[side] = true;
            bool ok = give_hand_weapon(side, pawn, w) && object_property(pawn, side == 0 ? STR("Weapon L") : STR("Weapon R")) == w;
            if (ok)
            {
                g_pending_free[side] = FreeGrip{};
                g_pending_item[side] = nullptr;
                hsvr::controllers_buzz(side, 0.3f);
                HSVR_LOG("Pavise: %s hand closes on the forward grip of %ls on its own forearm: in that hand, the game's own forearm grip %.0f", hand,
                         w->GetName().c_str(), read_number_variable(pawn, side == 0 ? STR("L_GripType_Current") : STR("R_GripType_Current")));
                return true;
            }
            g_mount_fist[side] = nullptr;
            g_mount_fist_game[side] = false;
            m = keep;
            m.joint = m.anchor = m.beside_joint = nullptr;
            m.beside = nullptr;
            m.no_collide.clear();
            if (!join_mount(side, m)) unmount_loose(side, "the hand could not take it and no joint could be made");
            HSVR_LOG("Pavise: %s hand could NOT take the forward grip of %ls; it stays mounted", hand, w->GetName().c_str());
            return true;
        }
        m.gripped = true;
        hsvr::controllers_buzz(side, 0.3f);
        HSVR_LOG("Pavise: %s hand grips the strap of the pavise on its own forearm (nothing else in reach)", hand);
        return true;
    }

    bool mount_let_go(int side)
    {
        if (!g_mount[side].gripped) return false;
        g_mount[side].gripped = false;
        // Off the forward grip: back to the strap's own place on the forearm.
        if (hsvr::length(g_mount[side].shift) > 0.01)
        {
            Mount& m = g_mount[side];
            m.shift = hsvr::Vec3{0.0, 0.0, 0.0};
            unjoin_mount(m);
            if (!join_mount(side, m)) unmount_loose(side, "no joint could be made back on the strap");
        }
        std::string was = g_mount[side].handle.empty() ? std::string("strap") : g_mount[side].handle;
        g_mount[side].handle.clear();
        set_anim_grip(side, -1);
        HSVR_LOG("Pavise: %s hand lets go of the %s; it stays mounted", side == 0 ? "left" : "right", was.c_str());
        return true;
    }

    // That hand opening on the forward grip (or let go by a hurt arm): the shield stays on the forearm, mounted.
    bool mount_fist_release(int side, UObject* pawn, UObject* mesh, UObject* w, const char* why)
    {
        if (!w || w != g_mount_fist[side]) return false;
        g_mount_fist[side] = nullptr;
        g_mount_fist_game[side] = false;
        UObject* base = object_property(w, STR("BaseMesh"));
        const PaviseSpec* spec = pavise_spec(w);
        if (!base || !spec || g_mount[side].weapon) return false;
        bool ok = mount_on(side, side, pawn, mesh, w, base, spec);
        HSVR_LOG("Pavise: %s hand opens on the forward grip of %ls (%s): %s", side == 0 ? "left" : "right", w->GetName().c_str(), why,
                 ok ? "it stays mounted on that forearm" : "no joint could be made, it is loose");
        return true;
    }

    // What that arm's hand holds or is taking never collides with the pavise on its forearm. The pair is
    // made as soon as the hand starts taking it (its pending grip, before Weapon <S> is set and while the
    // grab's settle pulls it in past the shield), not after his tick once Weapon <S> is set: a mace taken
    // by the mounted arm's hand knocked the pavise 1.1-5.7 cm / 5-11 deg off its place for under a second
    // (test 886981a, 3 of 3; Matthew 2026-11-22 chose to fix it before install).
    void mount_beside(int arm, UObject* pawn, UObject* held)
    {
        Mount& m = g_mount[arm];
        if (!m.weapon || m.pawn != pawn) return;
        UObject* want = held ? held : g_pending_item[arm] ? g_pending_item[arm] : g_hold[arm].weapon;
        // That arm's hand as the second hand on a weapon the other hand holds: Weapon <S> of this side stays
        // empty, so it was never paired (playtest 2026-11-23 17:09: a war hammer two-handed with the light
        // pavise on the second hand's forearm hit the pavise over and over, 4.8-6.1 m/s, the hammer spinning
        // at 1000-4500 deg/s and the pavise knocked up to 18 cm / 65 deg off: "freaking out like crazy").
        if ((!want || is_fist(want)) && g_two.active && g_two.second == arm && g_two.weapon) want = g_two.weapon;
        if (want == m.weapon) want = nullptr;
        if (want == m.beside) return;
        destroy_joint(m.beside_joint);
        m.beside = want;
        if (UObject* other = want ? object_property(want, STR("BaseMesh")) : nullptr)
        {
            m.beside_joint = pair_joint(pawn, m.base, other, FName(), 0);
            HSVR_LOG("Pavise: the %s forearm's pavise and %ls in that hand no longer collide", arm == 0 ? "left" : "right", want->GetName().c_str());
        }
    }

    // After his tick.
    void mount_tick(UObject* pawn)
    {
        if (!g_mount[0].weapon && !g_mount[1].weapon) return;
        UObject* in_hand[2] = {object_property(pawn, STR("Weapon L")), object_property(pawn, STR("Weapon R"))};
        for (int arm = 0; arm < 2; ++arm)
        {
            Mount& m = g_mount[arm];
            if (!m.weapon) continue;
            if (m.pawn != pawn)
            {
                m = Mount{}; // an old pawn's: its joints end with it
                continue;
            }
            if (!object_alive(m.weapon))
            {
                unjoin_mount(m);
                m = Mount{};
                continue;
            }
            // Someone's set-up took it (Last Parent is whoever took it last, @4537), or the game has given
            // up on him as its user: 3 m away from him (ModularWeaponBP @144-1155, checked each 0.2 s).
            UObject* user = object_property(m.weapon, STR("Last Parent"));
            if (!user)
            {
                unmount_loose(arm, "it was 3 m from him");
                continue;
            }
            if (m.weapon == in_hand[0] || m.weapon == in_hand[1] || user != pawn)
            {
                unjoin_mount(m);
                if (user != pawn) own_ignore(pawn, m.weapon, false);
                HSVR_LOG("Pavise: the pavise on the %s forearm was taken; its joints removed", arm == 0 ? "left" : "right");
                m = Mount{};
                continue;
            }
            if (bool_property(pawn, arm == 0 ? STR("Hand L Torn Off") : STR("Hand R Torn Off")))
            {
                unmount_loose(arm, "the arm was cut off");
                continue;
            }
            // The game's unstick (ModularWeaponBP @77374-79251) switches its parts' collision off and on,
            // which makes their shapes again: the joints and the no-collide pairs are made again after it.
            bool unstuck = bool_property(m.weapon, STR("Static Mesh Collision Disabled (Unstuck)"));
            if (unstuck != m.unstuck)
            {
                m.unstuck = unstuck;
                unjoin_mount(m);
                if (!join_mount(arm, m))
                {
                    unmount_loose(arm, "its joint could not be made again");
                    continue;
                }
                HSVR_LOG("Pavise: joints on the %s forearm made again after the game's unstick", arm == 0 ? "left" : "right");
            }
            {
                // Each tick, moved and not teleported: the substeps carry the shield along with the arm.
                static const FName sockets[2] = {bone_fname("shield_l_socket"), bone_fname("shield_r_socket")};
                if (m.anchor) set_component_transform(m.anchor, socket_location(m.mesh, sockets[arm]), socket_rotation(m.mesh, sockets[arm]), false);
            }
            mount_beside(arm, pawn, in_hand[arm]);
            // Each tick: the game's own grab search takes what it hit out of the list again (UG @216701).
            if (hsvr::config().pose_mount_head_ignore) own_ignore(pawn, m.weapon, true);
            if (m.gripped) set_anim_grip(arm, (int)(std::max)(0.0, hsvr::config().pose_shield_hand_grip_type));
            const double now = hsvr::now_seconds();
            if (now - m.last_log >= 1.0)
            {
                // Once a second: how far the joint lets it off the forearm.
                m.last_log = now;
                hsvr::Vec3 p;
                hsvr::Quat q;
                mount_pose(arm, m, p, q);
                HSVR_LOG("Pavise: on the %s forearm: %.1f cm, %.1f deg off its place%s", arm == 0 ? "left" : "right", hsvr::length(component_location(m.base) - p),
                         hsvr::length(scaled_axis((component_rotation(m.base) * q.inverse()).normalized())) * 57.2958, m.gripped ? " (gripped)" : "");
            }
        }
    }

    // Away from its straps and handles a shield is taken only by its rim: the point the hand touched
    // is within pose_shield_rim_cm of an outer edge (a probe that far out from it, along the plate,
    // finds the shield's nearest point off to the side, past the edge). A flat face is never taken.
    bool shield_off_handle_ok(int side, UObject* shield, UObject* base, const hsvr::Vec3& hand, const hsvr::Config& cfg)
    {
        using namespace hsvr;
        if (cfg.pose_shield_grab_face) return true;
        const char* hname = side == 0 ? "left" : "right";
        if (!cfg.pose_shield_grab_rim)
        {
            HSVR_LOG("Grab: %s hand touched %ls off its straps and handles: not taken (pose_shield_grab_rim 0)", hname, shield->GetName().c_str());
            return false;
        }
        Vec3 touch;
        if (closest_on_weapon(shield, hand, &touch) < 0.0) return false;
        Quat rot = component_rotation(base);
        Vec3 n = normalized(rot.rotate(shield_plate_normal(shield, base)));
        // Two directions along the plate, and eight probes round the touch point.
        Vec3 u = cross(n, Vec3{0, 0, 1});
        if (length(u) < 0.2) u = cross(n, Vec3{1, 0, 0});
        u = normalized(u);
        Vec3 v = cross(n, u);
        double r = cfg.pose_shield_rim_cm, most = 0.0;
        for (int i = 0; i < 8; ++i)
        {
            double ang = i * 3.14159265358979 / 4.0;
            Vec3 probe = touch + (u * std::cos(ang) + v * std::sin(ang)) * r, p;
            if (closest_on_weapon(shield, probe, &p) < 0.0) continue;
            Vec3 off = p - probe;
            off = off - n * dot(off, n); // along the plate only (a curved face sits a little behind)
            most = (std::max)(most, length(off));
        }
        bool rim = most > 1.0;
        HSVR_LOG("Grab: %s hand touched %ls off its straps and handles: %s (an edge %s %.0f cm; probes reached %.1f cm past it)", hname, shield->GetName().c_str(),
                 rim ? "by the rim, taken" : "on a flat face, not taken", rim ? "within" : "not within", r, most);
        return rim;
    }

    // A shield taken with the grip button. The hand point, in the shield's frame from before the
    // game's set-up moves it, is matched against its fittings: the nearest within
    // pose_shield_point_cm wins. One of the game's own for that hand keeps the game's grip (bucklers
    // and the heater's boss grip are held in the hand by it; a strap shield the game puts on the
    // forearm is moved into the hand when its hold starts, pose_shield_in_hand). Any other fitting is
    // held in the hand, its line along the hand's grip line, and anywhere else on the shield (the
    // rim, an edge, the face) the hand holds it where it touched, turned as it was. The hold places
    // it there on its first tick (the game's set-up snaps it to its own grip a tick later).
    void shield_grip(int side, UObject* mesh, UObject* shield, UObject* base, const hsvr::Vec3& w0_pos, const hsvr::Quat& w0_rot, const hsvr::Vec3& palm,
                     const hsvr::Vec3& touch, const hsvr::Config& cfg)
    {
        using namespace hsvr;
        const char* hand = side == 0 ? "left" : "right";
        if (pavise_on_forearm(shield, side, cfg))
        {
            HSVR_LOG("Shield: %s hand took %ls: strapped on the forearm (the game's own strap grip, pose_pavise_forearm)", hand, shield->GetName().c_str());
            return;
        }
        std::wstring cls = shield_class(shield);
        Vec3 local = w0_rot.inverse().rotate(palm - w0_pos);
        Vec3 best_on;
        double best_d = 0.0;
        int known = 0;
        const ShieldFitting* best = nearest_fitting(cls, local, cfg.pose_shield_point_cm, side, false, best_on, best_d, &known);
        if (best && (side == 1 ? best->game_r : best->game_l))
        {
            HSVR_LOG("Shield: %s hand took %ls by its %s (%.1f cm), the game's own grip", hand, shield->GetName().c_str(), best->name, best_d);
            return;
        }
        if (!known && length(touch - palm) <= cfg.pose_shield_point_cm)
        {
            HSVR_LOG("Shield: %s hand took %ls, a shield with no measured grab points: the game's own grip", hand, cls.c_str());
            return;
        }
        if (best)
        {
            Vec3 axis = w0_rot.rotate(normalized(Vec3{best->ax, best->ay, best->az}));
            hold_where_touched(side, mesh, shield, base, w0_pos, w0_rot, palm, w0_pos + w0_rot.rotate(best_on), best->name, &axis, true);
        }
        else
            hold_where_touched(side, mesh, shield, base, w0_pos, w0_rot, palm, touch, "edge where the hand touched it", nullptr, true);
    }

    // A strap shield the game holds on the forearm, moved into the hand (pose_shield_in_hand): by the
    // fitting nearest the hand, the game's own for that hand first (within 15 cm), else any.
    bool shield_into_hand(int side, UObject* pawn, UObject* shield, UObject* base, FreeGrip& out)
    {
        using namespace hsvr;
        UObject* mesh = object_property(pawn, STR("Mesh"));
        if (!mesh || !base) return false;
        std::wstring cls = shield_class(shield);
        Vec3 palm = hand_grab_point(mesh, side);
        Vec3 w0_pos = component_location(base);
        Quat w0_rot = component_rotation(base);
        Vec3 local = w0_rot.inverse().rotate(palm - w0_pos), on;
        double d = 0.0;
        const ShieldFitting* f = nullptr;
        if (hsvr::config().pose_pavise_strap)
            if (const PaviseSpec* spec = pavise_spec(shield))
                for (const ShieldFitting& sf : k_shield_fittings)
                    if (cls == sf.shield && std::string(sf.name) == spec->strap)
                    {
                        f = &sf;
                        on = Vec3{sf.cx, sf.cy, sf.cz};
                        d = length(local - on);
                    }
        if (!f) f = nearest_fitting(cls, local, 15.0, side, true, on, d);
        if (!f) f = nearest_fitting(cls, local, 1e9, side, false, on, d);
        if (!f)
        {
            HSVR_LOG("Shield: %ls has no measured fittings: left on the forearm", cls.c_str());
            return false;
        }
        Vec3 axis = w0_rot.rotate(normalized(Vec3{f->ax, f->ay, f->az}));
        out = make_free_grip(side, mesh, w0_pos, w0_rot, palm, w0_pos + w0_rot.rotate(on), &axis, f->name);
        out.fingers = true;
        out.handle = f->name;
        HSVR_LOG("Shield: %s hand holds %ls in the hand by its %s (was on the forearm; the hand was %.1f cm from it)", side == 0 ? "left" : "right",
                 shield->GetName().c_str(), f->name, d);
        return true;
    }

    // ---- Body grabs (a Willie's throat, arm, ...) ---------------------------------------------------
    // The game's latch joins hand_r to the victim's bone with 'PhysicsConstraint R Hand' (linear
    // limited, reeled in over 0.2 s; grab_pickup.md). Its grip-slip (UG @360300) lets go when the
    // joint's force beats his grip strength; with his hand posed from your controller (kinematic),
    // the pull has no limit. log_body_grab writes what the game sees every 0.1 s, to measure it.
    // pose_grab_body_hold 1: after 0.25 s the joint's linear part becomes a capped spring (as Matthew's
    // framework, protocol/grab.rs: the body's weight holds the hand back), and the hand pulled
    // pose_grab_body_let_go_cm past where it took hold for 0.3 s lets go (B&S).
    struct BodyGrab
    {
        bool on = false;
        double since = -1.0, rest = 0.0, far_since = -1.0, last_log = -10.0;
        UObject* comp = nullptr;
        UObject* victim = nullptr;
        FName bone;
        bool softened = false;
        double force = 0.0, torque = 0.0, release_rate = 0.0, stretch = 0.0, strangle = 0.0, choke = 0.0, conscious = 0.0;
        double grip_t = 121.0; // his grip strength T as the game's slip rule computes it
        // Your controller's hand turn when you took hold (g_pose.hand_rot, before the hand rides the
        // body): joint_break_tick counts a twist of his neck/arm only as far as your own wrist turned it.
        hsvr::Quat ctl0;
        double ctl0_yaw = 0.0; // g_pose.ctl_frame_yaw then
        bool ctl0_ok = false;
    };
    BodyGrab g_body_grab[2];
    bool bone_parent_axis(UObject* mesh, const char* bone_text, hsvr::Vec3& axis);
    bool held_neck_axis(int side, hsvr::Vec3& axis)
    {
        const BodyGrab& b = g_body_grab[side];
        return b.on && b.comp && bone_parent_axis(b.comp, "neck_01", axis);
    }
    std::atomic<int> g_body_hold_test{-99}; // test: hsvr.body_hold <n> (-99 = pose_grab_body_hold)

    // The spring's cap: pose_grab_body_cap_per_t x his grip strength T, so the joint's force stays under
    // T (the game's slip threshold) and his strength, injuries, pain and consciousness set how hard he
    // can pull a body (test 4, 2026-11-19: the force levels off at about cap/500). 0 = pose_grab_body_max.
    double body_spring_cap(const hsvr::Config& cfg, double grip_t)
    {
        return cfg.pose_grab_body_cap_per_t > 0.0 ? cfg.pose_grab_body_cap_per_t * (std::max)(1.0, grip_t) : cfg.pose_grab_body_max;
    }
    void body_spring_joint(UObject* joint, const hsvr::Config& cfg, double cap)
    {
        for (const TCHAR* fn : {STR("SetLinearXLimit"), STR("SetLinearYLimit"), STR("SetLinearZLimit")})
        {
            Call c1(joint, fn);
            c1.byte(STR("ConstraintType"), 0); // free: the spring holds it
            c1.number(STR("LimitSize"), 0.0);
            c1.run();
        }
        Call pos(joint, STR("SetLinearPositionDrive"));
        pos.flag(STR("bEnableDriveX"), true);
        pos.flag(STR("bEnableDriveY"), true);
        pos.flag(STR("bEnableDriveZ"), true);
        pos.run();
        Call vel(joint, STR("SetLinearVelocityDrive"));
        vel.flag(STR("bEnableDriveX"), true);
        vel.flag(STR("bEnableDriveY"), true);
        vel.flag(STR("bEnableDriveZ"), true);
        vel.run();
        Call target(joint, STR("SetLinearPositionTarget"));
        target.three(STR("InPosTarget"), 0.0, 0.0, 0.0);
        target.run();
        Call vtarget(joint, STR("SetLinearVelocityTarget"));
        vtarget.three(STR("InVelTarget"), 0.0, 0.0, 0.0);
        vtarget.run();
        Call lin(joint, STR("SetLinearDriveParams"));
        lin.number(STR("PositionStrength"), cfg.pose_grab_body_spring);
        lin.number(STR("VelocityStrength"), cfg.pose_grab_body_damper);
        lin.number(STR("InForceLimit"), cap);
        lin.run();
    }

    // What the game's Dislocate Bone (run in every Willie's tick over neck_01, upperarm_r/l, spine_03,
    // calf_r/l) reads: the bone's forward (X) in its parent bone's space, dotted with X. Only a bend
    // moves it; a twist about the bone's own X does not. Logged for the Willies you hold, with the
    // twist about X (swing-twist split) and his Strain / Dislocation State / part health.
    // Test (dev_script "hsvr.joint_torque <bone> <x|y|z> <N m> <seconds>"): that torque, about the
    // bone's own axis, on that bone of the first passive foe, every tick for that long. The foe is
    // looked up again each tick (no Willie pointer kept across frames) and logged with the Joints lines.
    struct JointTorqueTest
    {
        bool on = false;
        std::string bone;
        int axis = 0;
        double nm = 0.0, until = 0.0;
    };
    JointTorqueTest g_joint_torque;

    UObject* joint_torque_foe(UObject* pawn)
    {
        std::vector<UObject*> foes;
        UObjectGlobals::FindAllOf(STR("Willie_BP_C"), foes);
        for (UObject* foe : foes)
            if (foe && foe != pawn && foe->GetName().rfind(STR("Default__"), 0) != 0 && object_alive(foe) && !bool_property(foe, STR("Neck Snapped")) &&
                read_number_variable(foe, STR("Health")) > 0.0)
                return foe;
        return nullptr;
    }

    void joint_torque_tick(UObject* pawn)
    {
        using namespace hsvr;
        if (!g_joint_torque.on) return;
        if (now_seconds() > g_joint_torque.until)
        {
            g_joint_torque.on = false;
            HSVR_LOG("Script: hsvr.joint_torque: done");
            return;
        }
        UObject* foe = joint_torque_foe(pawn);
        UObject* mesh = foe ? object_property(foe, STR("Mesh")) : nullptr;
        if (!mesh) return;
        FName bone = bone_fname(g_joint_torque.bone.c_str());
        Quat q = socket_rotation(mesh, bone);
        Vec3 a{g_joint_torque.axis == 0 ? 1.0 : 0.0, g_joint_torque.axis == 1 ? 1.0 : 0.0, g_joint_torque.axis == 2 ? 1.0 : 0.0};
        Vec3 t = q.rotate(a) * (g_joint_torque.nm * 10000.0); // N m -> kg cm^2 / s^2
        Call c(mesh, STR("AddTorqueInRadians"));
        c.three(STR("Torque"), t.x, t.y, t.z);
        c.name(STR("BoneName"), bone);
        c.flag(STR("bAccelChange"), false);
        c.run();
    }

    void joint_strain_log(UObject* pawn)
    {
        using namespace hsvr;
        if (!config().log_joint_strain) return;
        static double last = -10.0;
        double now = now_seconds();
        if (now - last < 0.2) return;
        last = now;
        UObject* done = nullptr;
        for (int side = 0; side < 3; ++side)
        {
            UObject* w = side < 2 ? (g_body_grab[side].on ? g_body_grab[side].victim : nullptr) : (g_joint_torque.on ? joint_torque_foe(pawn) : nullptr);
            if (!w || w == done || !object_alive(w)) continue;
            done = w;
            UObject* mesh = object_property(w, STR("Mesh"));
            if (!mesh) continue;
            struct Part { const char* bone; const TCHAR* strain; const TCHAR* state; const TCHAR* health; };
            static const Part parts[] = {
                {"neck_01", STR("Neck Strain"), STR("Neck Dislocation State"), STR("Neck Health")},
                {"neck_02", nullptr, nullptr, nullptr},
                {"Head", nullptr, nullptr, nullptr},
                {"upperarm_r", STR("Arm R Strain"), STR("Arm R Dislocation State"), STR("Arm_R Health")},
                {"upperarm_l", STR("Arm L Strain"), STR("Arm L Dislocation State"), STR("Arm_L Health")},
                {"spine_03", STR("Back Strain"), STR("Back Dislocation State"), STR("Back Health")},
            };
            std::string line;
            for (const Part& p : parts)
            {
                FName bone = bone_fname(p.bone);
                Call pb(mesh, STR("GetParentBone"));
                pb.name(STR("BoneName"), bone);
                pb.run();
                FProperty* rp = pb.param(STR("ReturnValue"));
                if (!rp) continue;
                FName parent = *reinterpret_cast<FName*>(pb.buffer.data() + rp->GetOffset_Internal());
                Quat qb = socket_rotation(mesh, bone), qp = socket_rotation(mesh, parent);
                Quat rel = (qp.inverse() * qb).normalized();
                Vec3 f = rel.rotate({1.0, 0.0, 0.0});
                // Twist about X: the X part of the relative rotation.
                double tw = 2.0 * std::atan2(rel.x, rel.w) * 57.2958;
                if (tw > 180.0) tw -= 360.0;
                if (tw < -180.0) tw += 360.0;
                char buf[256];
                std::snprintf(buf, sizeof(buf), " %s(of %ls): bend %.0f deg (dot %.2f) twist %.0f", p.bone, parent.ToString().c_str(),
                              std::acos((std::max)(-1.0, (std::min)(1.0, f.x))) * 57.2958, f.x, tw);
                line += buf;
                if (p.strain)
                {
                    std::snprintf(buf, sizeof(buf), " [strain %.2f state %.2f health %.0f]", read_number_variable(w, p.strain), read_number_variable(w, p.state),
                                  read_number_variable(w, p.health));
                    line += buf;
                }
            }
            HSVR_LOG("Joints: %ls (neck dislocated %d, snapped %d, arm R/L dislocated %d/%d, invulnerable %d, dislocation blocked %d):%s", w->GetName().c_str(),
                     (int)bool_property(w, STR("Neck Dislocated")), (int)bool_property(w, STR("Neck Snapped")), (int)bool_property(w, STR("Arm R Dislocated")),
                     (int)bool_property(w, STR("Arm L Dislocated")), (int)bool_property(w, STR("Invulnerable")), (int)bool_property(w, STR("Dislocation Blocked")),
                     line.c_str());
        }
    }

    // Joint breaking by grappling (joint_break). The game's Dislocate Bone is emptied out since the
    // 11-17 update (extracted-2026-11-19\listing\fn_Willie_BP_Dislocate_Bone.txt: it sets Bone
    // Dislocation 0 and returns), so for a Willie you hold the mod runs the old game's rules
    // (decompiled\functions\Willie_BP\Dislocate Bone.txt), with a twist past the free range counted as a
    // bend (Matthew 2026-11-21 04:23Z). Per part, every tick:
    //   d = the bone's forward (X) in its parent bone's space . X, or cos(twist excess x gain) if lower
    //   BD = MapRangeClamped(d, 1, -1, State x 0.125, Strain + 1) x part factor (neck 0.375, arm 0.025,
    //        back 0.125, leg 0.25) x (Skeletron ? 1.5 : 1) x MapRangeClamped(Strain, 0, 1, 0.5, 5)
    //   BD >= 0.1: health -= BD x 666 x dt, pain += BD x 1000 x dt, Strain += BD x 100 x dt,
    //              State += min(BD x 666 x dt, 0.1); State >= 1: the part goes (below)
    //   else:      Strain += BD x 25 x dt, pain += BD x 10 x dt
    // The game itself still eases every Strain back to 0 (FInterpTo speed 5, UG 358852) and relocates a
    // dislocated shoulder or knee by its Restore Bone (swinging the arm, crouching), which sets the
    // joint's "Motor" profile again.
    struct JointPart
    {
        const char* bone;
        const char* twist_bones[3]; // their twists about X (each against its parent) add up
        const TCHAR* strain;
        const TCHAR* state;
        const TCHAR* health;
        const TCHAR* pain;
        const TCHAR* dislocated; // nullptr: the outcome is a game event
        const char* joint;       // its constraint, set to "Broken" when it dislocates
        double factor;
        int kind; // 0 neck, 1 arm, 2 back, 3 leg
    };
    static const JointPart k_joint_parts[] = {
        {"neck_01", {"neck_01", "neck_02", "head"}, STR("Neck Strain"), STR("Neck Dislocation State"), STR("Neck Health"), STR("Pain Neck"), nullptr, nullptr, 0.375, 0},
        {"upperarm_r", {"upperarm_r", nullptr, nullptr}, STR("Arm R Strain"), STR("Arm R Dislocation State"), STR("Arm_R Health"), STR("Pain Arm R"), STR("Arm R Dislocated"), "UserConstraint_10", 0.025, 1},
        {"upperarm_l", {"upperarm_l", nullptr, nullptr}, STR("Arm L Strain"), STR("Arm L Dislocation State"), STR("Arm_L Health"), STR("Pain Arm L"), STR("Arm L Dislocated"), "UserConstraint_14", 0.025, 1},
        {"spine_03", {"spine_03", "spine_04", "spine_05"}, STR("Back Strain"), STR("Back Dislocation State"), STR("Back Health"), STR("Pain Lower Body"), nullptr, nullptr, 0.125, 2},
        {"calf_r", {"calf_r", nullptr, nullptr}, STR("Leg R Strain"), STR("Leg R Dislocation State"), STR("Leg_R Health"), STR("Pain Leg R"), STR("Leg R Dislocated"), "UserConstraint_0", 0.25, 3},
        {"calf_l", {"calf_l", nullptr, nullptr}, STR("Leg L Strain"), STR("Leg L Dislocation State"), STR("Leg_L Health"), STR("Pain Leg L"), STR("Leg L Dislocated"), "UserConstraint_18", 0.25, 3},
    };
    constexpr int k_joint_part_count = sizeof(k_joint_parts) / sizeof(k_joint_parts[0]);

    // Per Willie held (whichever hand, or both): the twists his parts had when you took hold of him
    // (the rest the free range counts from) and the mod's own Dislocation State per part. The game's
    // "Dislocation State" variables mean something else since 11-17 (they grow from stamina burn), so
    // the old rule's State is kept here: it eases to 0 at joint_state_decay per second and the entry
    // is dropped 30 s after his last hold. The pointer is only compared, never read, once he's let go;
    // a hold that starts more than 0.5 s after the last one takes a fresh rest.
    struct JointVictim
    {
        UObject* who = nullptr;
        double seen = -100.0;
        double twist[k_joint_part_count] = {};
        double state[k_joint_part_count] = {};
        // His twist (from rest) when a hand took hold of that part: only what changes after it is yours.
        double grab_twist[k_joint_part_count] = {};
        bool held[k_joint_part_count] = {};
    };
    std::vector<JointVictim> g_joint_victims;
    constexpr double joint_state_decay = 0.05;

    JointVictim& joint_victim(UObject* w, double now, bool& fresh)
    {
        g_joint_victims.erase(std::remove_if(g_joint_victims.begin(), g_joint_victims.end(), [&](const JointVictim& v) { return now - v.seen > 30.0; }),
                              g_joint_victims.end());
        for (JointVictim& v : g_joint_victims)
            if (v.who == w)
            {
                double idle = now - v.seen;
                for (double& st : v.state) st = (std::max)(0.0, st - joint_state_decay * idle);
                fresh = idle > 0.5;
                v.seen = now;
                return v;
            }
        g_joint_victims.push_back({});
        g_joint_victims.back().who = w;
        g_joint_victims.back().seen = now;
        fresh = true;
        return g_joint_victims.back();
    }

    // A bone's forward . X and its twist about X (degrees), both in its parent bone's space.
    bool bone_bend_twist(UObject* mesh, const char* bone_text, double& dot_x, double& twist_deg)
    {
        using namespace hsvr;
        FName bone = bone_fname(bone_text);
        Call pb(mesh, STR("GetParentBone"));
        pb.name(STR("BoneName"), bone);
        pb.run();
        FProperty* rp = pb.param(STR("ReturnValue"));
        if (!rp) return false;
        FName parent = *reinterpret_cast<FName*>(pb.buffer.data() + rp->GetOffset_Internal());
        Quat rel = (socket_rotation(mesh, parent).inverse() * socket_rotation(mesh, bone)).normalized();
        dot_x = rel.rotate({1.0, 0.0, 0.0}).x;
        twist_deg = normalize_axis(2.0 * std::atan2(rel.x, rel.w) * 57.29577951308232);
        return true;
    }

    // The world X axis of a bone's parent (the axis bone_bend_twist measures its twist about).
    bool bone_parent_axis(UObject* mesh, const char* bone_text, hsvr::Vec3& axis)
    {
        using namespace hsvr;
        Call pb(mesh, STR("GetParentBone"));
        pb.name(STR("BoneName"), bone_fname(bone_text));
        pb.run();
        FProperty* rp = pb.param(STR("ReturnValue"));
        if (!rp) return false;
        FName parent = *reinterpret_cast<FName*>(pb.buffer.data() + rp->GetOffset_Internal());
        axis = normalized(socket_rotation(mesh, parent).rotate({1.0, 0.0, 0.0}));
        return length(axis) > 0.5;
    }

    // A rotation's turn about a unit axis (swing-twist split), degrees, -180..180.
    double quat_twist_deg(const hsvr::Quat& q, const hsvr::Vec3& axis)
    {
        double d = q.x * axis.x + q.y * axis.y + q.z * axis.z;
        return hsvr::normalize_axis(2.0 * std::atan2(d, q.w) * 57.29577951308232);
    }

    double map_range_clamped(double v, double in_a, double in_b, double out_a, double out_b)
    {
        double t = (v - in_a) / (in_b - in_a);
        t = (std::max)(0.0, (std::min)(1.0, t));
        return out_a + (out_b - out_a) * t;
    }

    void joint_crack_sound(UObject* mesh, const char* bone, double volume)
    {
        static UObject* gs = UObjectGlobals::StaticFindObject<UObject*>(nullptr, nullptr, STR("/Script/Engine.Default__GameplayStatics"));
        static UObject* cue = nullptr;
        if (!cue) cue = load_asset_object(STR("/Game/Sounds/Gore/Knee/sound_knee_crush_Cue.sound_knee_crush_Cue"));
        if (!gs || !cue || !mesh) return;
        Call c(gs, STR("SpawnSoundAttached"));
        c.object(STR("Sound"), cue);
        c.object(STR("AttachToComponent"), mesh);
        c.name(STR("AttachPointName"), bone_fname(bone));
        c.byte(STR("LocationType"), 0); // KeepRelativeOffset
        c.flag(STR("bStopWhenAttachedToDestroyed"), false);
        c.number(STR("VolumeMultiplier"), volume);
        c.number(STR("PitchMultiplier"), 1.0);
        c.flag(STR("bAutoDestroy"), true);
        c.run();
    }

    void joint_break_tick(UObject* pawn)
    {
        using namespace hsvr;
        const Config& cfg = config();
        if (!cfg.joint_break) return;
        static double last = -1.0;
        double now = now_seconds();
        double dt = last < 0.0 ? 0.0 : (std::min)(0.05, now - last);
        last = now;
        if (dt <= 0.0) return;
        UObject* done[3] = {};
        static double log_at[3][k_joint_part_count] = {};
        for (int side = 0; side < 3; ++side)
        {
            UObject* w = nullptr;
            if (side < 2) w = g_body_grab[side].on ? g_body_grab[side].victim : nullptr;
            else if (g_joint_torque.on) w = joint_torque_foe(pawn);
            if (!w || w == done[0] || w == done[1] || !object_alive(w) || w == pawn) continue;
            done[side] = w;
            UObject* mesh = object_property(w, STR("Mesh"));
            if (!mesh || bool_property(w, STR("Immortal"))) continue;
            bool skeletron = bool_property(w, STR("Skeletron"));
            // Which of his limbs a hand of yours is on: a twist counts only for those (his own head
            // turns while you hold his wrist are not you wrenching his neck). The torque test counts
            // as holding everything.
            bool on_limb[4] = {side == 2, side == 2, side == 2, side == 2}; // neck, arm R, arm L, back
            int hand_limb[2] = {-1, -1};
            for (int h = 0; h < 2; ++h)
            {
                if (!g_body_grab[h].on || g_body_grab[h].victim != w) continue;
                std::wstring bn = g_body_grab[h].bone.ToString();
                for (auto& ch : bn) ch = (wchar_t)towlower(ch);
                if (bn == STR("head") || bn.rfind(STR("neck"), 0) == 0) hand_limb[h] = 0;
                else if (bn == STR("upperarm_r") || bn == STR("lowerarm_r") || bn == STR("hand_r")) hand_limb[h] = 1;
                else if (bn == STR("upperarm_l") || bn == STR("lowerarm_l") || bn == STR("hand_l")) hand_limb[h] = 2;
                else if (bn.rfind(STR("spine"), 0) == 0) hand_limb[h] = 3;
                if (hand_limb[h] >= 0) on_limb[hand_limb[h]] = true;
            }
            // How well he can resist (Matthew 2026-11-22: easier as his pain rises and his consciousness
            // drops): his Consciousness 0..100 -> 0..1, times his Pain on the game's own 0..10 scale
            // (as his strength gain uses it, @470755) -> 1..0.1. A weak resistance shrinks the free twist
            // range (to joint_break_free_min of it at none) and raises the strain rate (up to x2).
            double conscious = read_number_variable(w, STR("Consciousness"));
            double pain_all = read_number_variable(w, STR("Pain"));
            double resist = map_range_clamped(conscious, 0.0, 100.0, 0.0, 1.0) * map_range_clamped(pain_all, 0.0, 10.0, 1.0, 0.1);
            double free_scale = cfg.joint_break_free_min + (1.0 - cfg.joint_break_free_min) * resist;
            double rate_scale = 2.0 - resist;
            bool fresh = false;
            JointVictim& rest = joint_victim(w, now, fresh);
            for (double& st : rest.state) st = (std::max)(0.0, st - joint_state_decay * dt);
            for (int i = 0; i < k_joint_part_count; ++i)
            {
                const JointPart& p = k_joint_parts[i];
                if (p.kind == 3 && !cfg.joint_break_legs) continue;
                // Already gone: the game owns it now (Restore Bone relocates, a snapped neck is dead).
                if (p.kind == 0 && (bool_property(w, STR("Neck Snapped")) || bool_property(w, STR("Neck Dislocated")))) continue;
                if (p.kind == 2 && bool_property(w, STR("Back Broken"))) continue;
                if (p.dislocated && bool_property(w, p.dislocated)) continue;
                double dot = 1.0, tw = 0.0, twist = 0.0;
                if (!bone_bend_twist(mesh, p.bone, dot, tw)) continue;
                for (const char* tb : p.twist_bones)
                {
                    double d2 = 1.0, t2 = 0.0;
                    if (tb && bone_bend_twist(mesh, tb, d2, t2)) twist += t2;
                }
                if (fresh) rest.twist[i] = twist;
                double free = p.kind == 0 ? cfg.joint_break_twist_free_neck_deg : p.kind == 1 ? cfg.joint_break_twist_free_arm_deg
                            : p.kind == 2 ? cfg.joint_break_twist_free_back_deg : 1e9;
                int limb = p.kind == 0 ? 0 : p.kind == 1 ? (i == 1 ? 1 : 2) : p.kind == 2 ? 3 : -1;
                if (limb < 0 || !on_limb[limb]) free = 1e9; // no hand on it: the old bend rule only
                free *= free_scale;
                // Only the twist your own wrist puts in counts (Matthew 2026-11-23 17:14/17:15 local: grabbing
                // a neck was all it took to snap it). His head flopping while you drag or choke him turned his
                // neck 47-63 deg from where it sat with your hand still; his consciousness fell to 0 in 0.5 s, so
                // the free range shrank to 40 % and the neck went in 0.15 s. Now the twist counts only in the
                // direction your controller turned (about the part's axis, since you took hold), and no further
                // than it turned. And your wrist turns him: past joint_break_wrench_from_deg, a torque on his head
                // (or upper arm) toward your wrist's turn, as strong as your grip.
                double limb_tw = normalize_axis(twist - rest.twist[i]);
                bool held_now = limb >= 0 && on_limb[limb] && side < 2;
                if (held_now && !rest.held[i]) rest.grab_twist[i] = limb_tw;
                rest.held[i] = held_now;
                // Your part of it: his twist since you took hold (test 2026-11-24 04e802e: the choke had already
                // turned his neck 24-55 deg before any wrench, so a wrench the other way never counted).
                double mine_tw = held_now ? normalize_axis(limb_tw - rest.grab_twist[i]) : limb_tw;
                double counted = limb_tw, ctl_tw = 0.0;
                bool gated = false;
                Vec3 axis;
                if (cfg.joint_break_twist_needs_wrist && side < 2 && limb >= 0 && on_limb[limb] && bone_parent_axis(mesh, p.bone, axis))
                {
                    gated = true;
                    double best = 0.0;
                    double grip_t = 121.0;
                    for (int h = 0; h < 2; ++h)
                    {
                        const BodyGrab& bg = g_body_grab[h];
                        if (hand_limb[h] != limb || !bg.on || bg.victim != w || !bg.ctl0_ok || !g_pose.hand_valid[h]) continue;
                        // In the frame your controller is tracked in (test 2026-11-24 a462c97: measured in the world,
                        // a still test hand read as a 21-49 deg wrist turn while the choke turned the player, since
                        // test hands turn with the actor; a stick turn does the same to a real one).
                        hsvr::Quat fi = hsvr::quat_from_yaw_deg(g_pose.ctl_frame_yaw[h]).inverse(), f0i = hsvr::quat_from_yaw_deg(bg.ctl0_yaw).inverse();
                        hsvr::Quat now_room = (fi * g_pose.hand_rot[h]).normalized(), then_room = (f0i * bg.ctl0).normalized();
                        double t = quat_twist_deg((now_room * then_room.inverse()).normalized(), hsvr::normalized(fi.rotate(axis)));
                        if (std::fabs(t) > std::fabs(best)) { best = t; grip_t = bg.grip_t; }
                    }
                    ctl_tw = best;
                    counted = mine_tw * ctl_tw > 0.0 ? std::copysign((std::min)(std::fabs(mine_tw), std::fabs(ctl_tw)), mine_tw) : 0.0;
                    const char* drive_bone = p.kind == 0 ? "head" : p.kind == 1 ? p.bone : nullptr;
                    if (drive_bone && cfg.joint_break_wrench_nm_per_deg > 0.0 && std::fabs(ctl_tw) >= cfg.joint_break_wrench_from_deg)
                    {
                        double cap = cfg.joint_break_wrench_max_nm * (std::max)(0.2, grip_t / 121.0);
                        double nm = (std::max)(-cap, (std::min)(cap, (ctl_tw - mine_tw) * cfg.joint_break_wrench_nm_per_deg));
                        Vec3 tq = axis * (nm * 10000.0); // N m -> kg cm^2 / s^2
                        Call c(mesh, STR("AddTorqueInRadians"));
                        c.three(STR("Torque"), tq.x, tq.y, tq.z);
                        c.name(STR("BoneName"), bone_fname(drive_bone));
                        c.flag(STR("bAccelChange"), false);
                        c.run();
                        static double wlog[3] = {};
                        if (now - wlog[(std::min)(2, (int)p.kind)] > 0.5)
                        {
                            wlog[(std::min)(2, (int)p.kind)] = now;
                            HSVR_LOG("Joints: your wrist turns %ls's %s: wrist %.0f deg, his %.0f deg since you took hold (%.0f from rest), %.0f N m on %s (cap %.0f)",
                                     w->GetName().c_str(), p.bone, ctl_tw, mine_tw, limb_tw, nm, drive_bone, cap);
                        }
                    }
                }
                double excess = (std::max)(0.0, std::fabs(counted) - free);
                // Your wrist must also have turned past joint_break_wrist_free_deg (not shrunk by his weakness):
                // an out-cold man's free range is only 16 deg, and a hand turns that much by itself.
                if (gated) excess = (std::min)(excess, (std::max)(0.0, std::fabs(ctl_tw) - cfg.joint_break_wrist_free_deg));
                double twist_dot = std::cos((std::min)(180.0, excess * cfg.joint_break_twist_gain) * kDegToRad);
                double d = (std::min)(dot, twist_dot);
                double strain = read_number_variable(w, p.strain);
                double& state = rest.state[i];
                if (strain < 0.0) continue; // no such variable
                double bd = map_range_clamped(d, 1.0, -1.0, state * 0.125, strain + 1.0) * p.factor * (skeletron ? 1.5 : 1.0) *
                            map_range_clamped(strain, 0.0, 1.0, 0.5, 5.0) * cfg.joint_break_scale * (twist_dot < dot ? rate_scale : 1.0);
                if (bd <= 0.0) continue;
                double pain = read_number_variable(w, p.pain);
                if (bd >= 0.1)
                {
                    double health = read_number_variable(w, p.health);
                    if (health >= 0.0) set_variable(w, p.health, (std::max)(0.0, (std::min)(100.0, health - bd * 666.0 * dt)));
                    if (pain >= 0.0) set_variable(w, p.pain, pain + bd * 1000.0 * dt);
                    set_variable(w, p.strain, (std::min)(1.0, strain + bd * 100.0 * dt));
                    // No quicker than joint_break_min_s from nothing to gone: a snap takes a held wrench.
                    double step = (std::min)(0.1, bd * 666.0 * dt);
                    if (cfg.joint_break_min_s > 0.0) step = (std::min)(step, dt / cfg.joint_break_min_s);
                    state = (std::min)(1.0, state + step);
                    if (state >= 1.0)
                    {
                        HSVR_LOG("Joints: %ls's %s goes (bend dot %.2f, twist %.0f deg from rest, counted %.0f, your wrist %.0f%s, strain %.2f)", w->GetName().c_str(), p.bone,
                                 dot, limb_tw, counted, ctl_tw, gated ? "" : " (not gated)", strain);
                        g_count_joint_breaks.fetch_add(1);
                        if (p.kind == 0)
                        {
                            g_count_neck_snaps.fetch_add(1);
                            Call c(w, STR("Snap Neck"));
                            c.run();
                        }
                        else if (p.kind == 2)
                        {
                            Call c(w, STR("Break Back"));
                            c.run();
                        }
                        else
                        {
                            // As the game's own breaks do: the part's Dislocation State at 1, which its
                            // Restore Bone (swinging the arm, crouching) works back down to relocate it.
                            set_variable(w, p.state, 1.0);
                            set_variable(w, p.health, 0.0);
                            if (pain >= 0.0) set_variable(w, p.pain, read_number_variable(w, p.pain) + 20.0);
                            set_bool_property(w, p.dislocated, true);
                            Call prof(mesh, STR("SetConstraintProfile"));
                            prof.name(STR("JointName"), bone_fname(p.joint));
                            prof.name(STR("ProfileName"), bone_fname(skeletron ? "Skeletron" : "Broken"));
                            prof.flag(STR("bDefaultIfNotFound"), false);
                            prof.run();
                            joint_crack_sound(mesh, p.bone, 1.0);
                        }
                    }
                }
                else
                {
                    set_variable(w, p.strain, (std::min)(1.0, strain + bd * 25.0 * dt));
                    if (pain >= 0.0) set_variable(w, p.pain, pain + bd * 10.0 * dt);
                    // The old game's crack at 0.05 (volume = BD), at most every 0.5 s per part.
                    static double crack_at[3][k_joint_part_count] = {};
                    if (bd >= 0.05 && now - crack_at[side][i] > 0.5)
                    {
                        crack_at[side][i] = now;
                        joint_crack_sound(mesh, p.bone, (std::min)(1.0, bd));
                    }
                }
                if (bd >= 0.005 && now - log_at[side][i] > 0.5)
                {
                    log_at[side][i] = now;
                    HSVR_LOG("Joints: %ls %s strains: BD %.3f (bend dot %.2f, twist %.0f deg from rest, counted %.0f, your wrist %.0f, free %.0f -> dot %.2f), strain %.2f, "
                             "state %.2f; his resistance %.2f (consciousness %.0f, pain %.1f)",
                             w->GetName().c_str(), p.bone, bd, dot, limb_tw, counted, ctl_tw, (std::min)(999.0, free), twist_dot, strain, state, resist, conscious,
                             pain_all);
                }
            }
        }
    }

    // Willie's tick re-shapes his hand joints every tick (as for weapons, @454086), so a softened body
    // grab's spring is written again right after it.
    void body_grab_after_tick(UObject* pawn)
    {
        hsvr::Config cfg = hsvr::config();
        int hold = g_body_hold_test.load() != -99 ? g_body_hold_test.load() : cfg.pose_grab_body_hold;
        if (hold != 1) return;
        for (int side = 0; side < 2; ++side)
            if (g_body_grab[side].on && g_body_grab[side].softened)
                if (UObject* joint = object_property(pawn, side == 0 ? STR("PhysicsConstraint L Hand") : STR("PhysicsConstraint R Hand")))
                    body_spring_joint(joint, cfg, body_spring_cap(cfg, g_body_grab[side].grip_t));
    }

    // Limb strikes (elbows, forearms, open hands): the struck Willie's body-hit block (UG 791446, from
    // his armour proxies' OnComponentHit -> NewFunction) damages himself (impulse capped at 1500 while
    // standing, x the hitter's surface rigidity). Test 9: the posed arm's contacts do reach it.
    // log_body_hits: every other Willie's 'Last Hit Impulse (Other Body)', Health and
    // Consciousness, logged when they change, with what hit him ('Other Comp').
    void body_hit_watch(UObject* pawn)
    {
        if (!hsvr::config().log_body_hits) return;
        static std::vector<UObject*> foes;
        static double found_at = -10.0;
        struct Seen { double impulse = -1.0, health = -1.0, conscious = -1.0; };
        static std::map<UObject*, Seen> seen;
        // Willies the game frees (a removed corpse) leave both lists at once (gc_sync); a new list
        // is also taken after every garbage collection (crash 2026-11-20: a freed Willie was used).
        static bool tracked = on_freed([] {
            erase_gone(foes);
            erase_gone_keys(seen);
        });
        static uint64_t epoch = 0;
        double now = hsvr::now_seconds();
        if (now - found_at > 1.0 || epoch != g_gc_epoch)
        {
            found_at = now;
            epoch = g_gc_epoch;
            foes.clear();
            std::vector<UObject*> all;
            UObjectGlobals::FindAllOf(STR("Willie_BP_C"), all);
            for (UObject* w : all)
                if (w && w != pawn && w->GetName().rfind(STR("Default__"), 0) != 0 && object_alive(w)) foes.push_back(w);
            std::map<UObject*, Seen> keep;
            for (UObject* w : foes) keep[w] = seen[w];
            seen.swap(keep);
        }
        for (UObject* w : foes)
        {
            if (!object_alive(w)) continue; // destroyed this second (still readable, not a fighter)
            Seen& was = seen[w];
            // Willie-on-Willie contacts go through branch H of the block, which writes 'Last Hit Impulse
            // (Other Body)' (reset after 1 s), not 'Last Hit Impulse' (ground hits only).
            double impulse = read_number_variable(w, STR("Last Hit Impulse (Other Body)"));
            double health = read_number_variable(w, STR("Health"));
            double conscious = read_number_variable(w, STR("Consciousness"));
            bool hit = was.impulse >= 0.0 && impulse != was.impulse && impulse > 0.0;
            bool hurt = was.health >= 0.0 && health < was.health - 0.01;
            if (hit || hurt)
            {
                UObject* other = object_property(w, STR("Other Comp"));
                UObject* other_owner = nullptr;
                if (other)
                {
                    Call oc(other, STR("GetOwner"));
                    oc.run();
                    other_owner = oc.object_result();
                }
                HSVR_LOG("Body hit: %ls last hit impulse %.0f, health %.1f -> %.1f, consciousness %.0f -> %.0f, hit by limbs %d, by %ls.%ls%s", w->GetName().c_str(), impulse,
                         was.health, health, was.conscious, conscious, (int)bool_property(w, STR("Beig Hit By Limbs")), other_owner ? other_owner->GetName().c_str() : STR("?"),
                         other ? other->GetName().c_str() : STR("?"), other_owner == pawn ? " (you)" : "");
            }
            was.impulse = impulse;
            was.health = health;
            was.conscious = conscious;
        }
    }

    // ---- Elbows hit like a punch (Matthew 2026-11-20) -------------------------------------------
    // Flat Half Sword has no elbow attack: a limb touching a Willie only runs his body-hit block,
    // whose self-damage is weak (rigidity 0.225-0.5 x a capped impulse). A punch instead is the fist
    // weapon calling his 'Deal Complex Damage' (BPI_ComplexCollision, ModularWeaponBP UG @41944) with
    // the fist's velocity, impulse, rigidity and cutting rate. So when the elbow (the lowerarm bone's
    // root, and 7 cm either side along the arm) meets a Willie's body at fist speed (Aim Swing Speed
    // 30, the speed the game's fist needs), the mod makes that same call with the elbow's velocity
    // and the punch's own numbers: the running mean of your last real fist hits (watched on the
    // way in), or pose_elbow_* until you have punched.
    struct PunchStats
    {
        int n = 0;
        double rigidity = 0, cut = 0, stab = 0, impulse_per_v = 0, v_per_speed = 0;
        bool have_template = false;
        double kick = 1.0, blunt_int = 1.0, draw_cut = 0.0;
        bool lower_threshold = false, damage_parent = false, extra_high = false;
    };
    PunchStats g_punch;

    double read_param_number(uint8_t* base, FProperty* p)
    {
        auto kind = p->GetClass().GetName();
        uint8_t* at = base + p->GetOffset_Internal();
        if (kind == STR("DoubleProperty")) return *reinterpret_cast<double*>(at);
        if (kind == STR("FloatProperty")) return *reinterpret_cast<float*>(at);
        if (kind == STR("IntProperty")) return *reinterpret_cast<int32_t*>(at);
        if (kind == STR("ByteProperty")) return *at;
        return 0.0;
    }
    void write_param_number(uint8_t* base, FProperty* p, double v)
    {
        auto kind = p->GetClass().GetName();
        uint8_t* at = base + p->GetOffset_Internal();
        if (kind == STR("DoubleProperty")) *reinterpret_cast<double*>(at) = v;
        else if (kind == STR("FloatProperty")) *reinterpret_cast<float*>(at) = (float)v;
        else if (kind == STR("IntProperty")) *reinterpret_cast<int32_t*>(at) = (int32_t)v;
        else if (kind == STR("ByteProperty")) *at = (uint8_t)v;
    }
    bool read_param_bool(uint8_t* base, FProperty* p)
    {
        auto* b = static_cast<FBoolProperty*>(p);
        return (*(base + p->GetOffset_Internal() + b->GetByteOffset()) & b->GetFieldMask()) != 0;
    }
    void write_param_bool(uint8_t* base, FProperty* p, bool v)
    {
        auto* b = static_cast<FBoolProperty*>(p);
        uint8_t* at = base + p->GetOffset_Internal() + b->GetByteOffset();
        if (v) *at |= b->GetFieldMask();
        else *at &= ~b->GetFieldMask();
    }
    hsvr::Vec3 read_param_vec(uint8_t* base, FProperty* p)
    {
        double v[3];
        read_three(base + p->GetOffset_Internal(), p, v);
        return {v[0], v[1], v[2]};
    }

    std::atomic<bool> g_elbow_calling{false};
    UObject* g_punch_victim = nullptr; // the blow being watched (punch_watch_post logs what it did)
    // The fist's hit assist (hit_assist): the impulse it gave the fist's contact, and when. The game
    // passes that contact on to the victim's Deal Complex Damage as NI x MRC(Cutting Rate, 0..50 -> 0..1)
    // when the weapon counts it as Sliding (ModularWeaponBP @40065-@40267), and a round fist ball
    // has a cutting rate of ~0-0.1, so a boosted 850 arrived as ~1 (playtest 2026-11-22 1329 s). The
    // victim's Deal Complex Damage is given the assisted impulse instead (pose_fist_full_impulse).
    struct FistBoost
    {
        double at = -10.0;
        hsvr::Vec3 impulse;
    };
    FistBoost g_fist_boost[2];
    double g_punch_c0 = 0.0, g_punch_h0 = 0.0;
    // Test counters: punches (a fist's contacts on one Willie less than pose_fist_new_punch_gap_s apart)
    // with a blow in them, and of those the ones where a contact took consciousness or health.
    int g_punch_serial = 0, g_punch_blow_serial = -1, g_punch_counted_serial = -1;
    // Watches every 'Deal Complex Damage' a Willie gets: the player's fist hits are learnt (and logged).
    void punch_watch_hook(Unreal::UnrealScriptFunctionCallableContext& context, void* custom_data)
    {
        gc_sync();
        HSVR_PROF(PerfPunchPre);
        if (g_elbow_calling.load()) return;
        if (g_kbm.load()) return; // mouse and keyboard: the game's own punches
        UFunction* fn = static_cast<UFunction*>(custom_data);
        uint8_t* locals = context.TheStack.Locals();
        UObject* victim = context.Context;
        UObject* pawn = live_posed_pawn();
        if (!pawn) find_pawn_mesh(&pawn); // flat mode: the player's pawn, unposed
        if (!fn || !locals || !victim || !pawn || victim == pawn) return;
        FProperty *normal_p = nullptr, *collided = nullptr, *vel = nullptr, *imp = nullptr, *cut = nullptr, *stab = nullptr, *rig = nullptr, *kick = nullptr, *blunt = nullptr,
                  *lower = nullptr, *parent = nullptr, *extra = nullptr, *draw = nullptr, *bone = nullptr;
        for (FProperty* p : fn->ForEachProperty())
        {
            std::wstring n = p->GetName();
            if (n == STR("Collided Component")) collided = p;
            else if (n == STR("Hit Velocity")) vel = p;
            else if (n == STR("Hit Impulse")) imp = p;
            else if (n == STR("Cutting Power")) cut = p;
            else if (n == STR("Stab Rate")) stab = p;
            else if (n == STR("Rigidity")) rig = p;
            else if (n == STR("Kick Power")) kick = p;
            else if (n == STR("Blunt Destruction Int")) blunt = p;
            else if (n == STR("Lower Threshold In")) lower = p;
            else if (n == STR("Damage Parent Bone?")) parent = p;
            else if (n == STR("Extra High Velocity")) extra = p;
            else if (n == STR("Draw Cut")) draw = p;
            else if (n == STR("Hit Bone")) bone = p;
            else if (n == STR("Normal")) normal_p = p;
        }
        if (!collided || !vel || !imp || !rig) return;
        UObject* comp = *reinterpret_cast<UObject**>(locals + collided->GetOffset_Internal());
        if (!comp) return;
        Call oc(comp, STR("GetOwner"));
        oc.run();
        UObject* owner = oc.object_result();
        int side = owner && owner == object_property(pawn, STR("Weapon R")) ? 1 : owner && owner == object_property(pawn, STR("Weapon L")) ? 0 : -1;
        if (side < 0 || !is_fist(owner)) return;
        using namespace hsvr;
        Vec3 v = read_param_vec(locals, vel), ni = read_param_vec(locals, imp);
        double game_ni = length(ni);
        if (config().pose_fist_full_impulse && hsvr::now_seconds() - g_fist_boost[side].at < 0.05 && length(g_fist_boost[side].impulse) > game_ni)
        {
            ni = g_fist_boost[side].impulse;
            write_three(locals + imp->GetOffset_Internal(), imp, ni.x, ni.y, ni.z);
            g_fist_boost[side].at = -10.0; // once per contact
        }
        // A new punch clears the game's "not bigger than the last hit on that bone" checks (fists only).
        static UObject* punch_last_victim[2] = {nullptr, nullptr};
        static double punch_last_t[2] = {-10.0, -10.0};
        double t_hit = hsvr::now_seconds();
        bool new_punch = victim != punch_last_victim[side] || t_hit - punch_last_t[side] > config().pose_fist_new_punch_gap_s;
        punch_last_victim[side] = victim;
        punch_last_t[side] = t_hit;
        double last_cdi = read_number_variable(victim, STR("Last Complex Damage Impulse")), last_taken = read_number_variable(victim, STR("Last Damage Taken"));
        std::string last_cdb = nested_name(victim, {STR("Last Complex Damage Bone")}), last_db = nested_name(victim, {STR("Last Damaged Bone")});
        bool cleared = false;
        if (new_punch && config().pose_fist_new_punch_counts)
        {
            set_variable(victim, STR("Last Complex Damage Impulse"), 0.0);
            set_variable(victim, STR("Last Damage Taken"), 0.0);
            cleared = true;
        }
        double speed = length(v), r = read_param_number(locals, rig), c = cut ? read_param_number(locals, cut) : 0.0, s = stab ? read_param_number(locals, stab) : 0.0;
        // The hand's own speed when it hit (to learn the fist's velocity factor).
        double hand_speed = g_swing_v[side] * 100.0;
        // Learnt only from blows at fist speed (test 12: each blow also logs 3-7 slow touches at
        // 1-11 cm/s, which made impulse per velocity 56x too big after three of them).
        Config cfg = config();
        double lo = cfg.pose_swing_speed_lo, hi = (std::max)(lo + 0.1, cfg.pose_swing_speed_hi);
        bool blow = speed >= (lo + (hi - lo) * cfg.pose_elbow_min_ass / 75.0) * 100.0;
        PunchStats& P = g_punch;
        int k = (std::min)(P.n, 19);
        auto mean = [&](double& m, double x) { m = (m * k + x) / (k + 1); };
        if (blow)
        {
            mean(P.rigidity, r);
            mean(P.cut, c);
            mean(P.stab, s);
            mean(P.impulse_per_v, length(ni) / speed);
            if (hand_speed > 50.0) mean(P.v_per_speed, speed / hand_speed);
            P.n += 1;
        }
        if (kick) P.kick = read_param_number(locals, kick);
        if (blunt) P.blunt_int = read_param_number(locals, blunt);
        if (draw) P.draw_cut = read_param_number(locals, draw);
        if (lower) P.lower_threshold = read_param_bool(locals, lower);
        if (parent) P.damage_parent = read_param_bool(locals, parent);
        if (extra) P.extra_high = read_param_bool(locals, extra);
        P.have_template = true;
        Vec3 nrm = normal_p ? read_param_vec(locals, normal_p) : Vec3{};
        double cos_ni = speed > 1.0 && length(ni) > 1e-6 ? dot(v, ni) / (speed * length(ni)) : 0.0;
        double cos_n = speed > 1.0 && length(nrm) > 1e-6 ? dot(v, nrm) / (speed * length(nrm)) : 0.0;
        g_punch_victim = victim;
        if (new_punch) ++g_punch_serial;
        if (blow && g_punch_blow_serial != g_punch_serial)
        {
            g_punch_blow_serial = g_punch_serial;
            g_count_punches.fetch_add(1);
        }
        g_punch_c0 = read_number_variable(victim, STR("Consciousness"));
        g_punch_h0 = read_number_variable(victim, STR("Health"));
        std::wstring b = bone ? reinterpret_cast<FName*>(locals + bone->GetOffset_Internal())->ToString() : STR("?");
        HSVR_LOG("Punch: %s fist %s %ls (%ls): velocity %.0f cm/s (hand %.0f), impulse %.0f (game's %.0f), rigidity %.2f, cut %.2f, stab %.2f, kick %.2f, blunt %.0f, draw %.2f, "
                 "lower %d, parent %d, extra %d, cos(velocity, impulse) %.2f, cos(velocity, normal) %.2f; learnt from %d hits: rigidity %.2f, cut %.2f, impulse/velocity %.3f, velocity/hand %.2f; "
                 "%s (game's last counted: complex impulse %.0f on %s, damage %.2f on %s; this one %.0f)",
                 side == 0 ? "left" : "right", blow ? "blow on" : "touch on", victim->GetName().c_str(), b.c_str(), speed, hand_speed, length(ni), game_ni, r, c, s, P.kick, P.blunt_int, P.draw_cut,
                 (int)P.lower_threshold, (int)P.damage_parent, (int)P.extra_high, cos_ni, cos_n, P.n, P.rigidity, P.cut, P.impulse_per_v, P.v_per_speed,
                 cleared ? "new punch, checks cleared" : new_punch ? "new punch" : "same punch", last_cdi, last_cdb.c_str(), last_taken, last_db.c_str(), length(ni) * (c + 1.0));
    }

    // After his Deal Complex Damage: what the blow (or touch) did to him.
    void punch_watch_post(Unreal::UnrealScriptFunctionCallableContext& context, void*)
    {
        gc_sync();
        HSVR_PROF(PerfPunchPost);
        if (!g_punch_victim || context.Context != g_punch_victim) return;
        UObject* w = g_punch_victim;
        g_punch_victim = nullptr;
        double h1 = read_number_variable(w, STR("Health")), c1 = read_number_variable(w, STR("Consciousness"));
        if (g_punch_blow_serial == g_punch_serial && g_punch_counted_serial != g_punch_serial && (g_punch_c0 - c1 > 1.0 || g_punch_h0 - h1 > 0.05))
        {
            g_punch_counted_serial = g_punch_serial;
            g_count_punches_counted.fetch_add(1);
        }
        // What the game now remembers (the "must beat the last hit on that bone" checks the next contact meets).
        HSVR_LOG("Punch: -> %ls health %.2f -> %.2f, consciousness %.2f -> %.2f; game now remembers complex impulse %.0f on %s, damage %.2f on %s", w->GetName().c_str(), g_punch_h0, h1,
                 g_punch_c0, c1, read_number_variable(w, STR("Last Complex Damage Impulse")), nested_name(w, {STR("Last Complex Damage Bone")}).c_str(),
                 read_number_variable(w, STR("Last Damage Taken")), nested_name(w, {STR("Last Damaged Bone")}).c_str());
    }

    void install_punch_watch()
    {
        static bool installed = false;
        static double last_try = -10.0;
        if (installed) return;
        double now = hsvr::now_seconds();
        if (now - last_try < 2.0) return;
        last_try = now;
        UFunction* fn = UObjectGlobals::StaticFindObject<UFunction*>(nullptr, nullptr, STR("/Game/Character/Blueprints/Willie_BP.Willie_BP_C:Deal Complex Damage"));
        if (!fn) return;
        installed = true;
        UObjectGlobals::RegisterHook(fn, &punch_watch_hook, &punch_watch_post, fn);
        HSVR_LOG("Punch: watching Willie's Deal Complex Damage");
    }

    // ---- Damage to the player ------------------------------------------------------------------
    // The game's Get Damage (Willie_BP) works out Root Mesh = (mesh is SK_Skeleton) OR (head has
    // mass AND mesh.IsSimulatingPhysics(head)) (Get Damage @498-@870) and multiplies every Health,
    // Consciousness, Bleeding and Force Death term by it. His posed body does not simulate, so the
    // player took hits (limb health, cuts, dismemberment) but never lost Health from them. While
    // his own Get Damage runs, IsSimulatingPhysics on his mesh answers yes: the flat game's answer.
    UFunction* g_get_damage_fn = nullptr;
    std::atomic<uint64_t> g_player_damage_overrides{0};
    int g_in_player_get_damage = 0; // game thread only: depth of his Get Damage calls
    UObject* g_pd_pawn = nullptr;   // whose Get Damage set it (compared only, never read through)
    // Counters for the "Player damage: checks" line (which test fails when no hit is counted).
    std::atomic<uint64_t> g_pd_sim_calls{0}, g_pd_sim_in_gd{0}, g_pd_sim_on_mesh{0}, g_pd_gd_calls{0}, g_pd_gd_player{0};
    std::wstring g_pd_first_in_gd;
    void player_sim_check_post(Unreal::UnrealScriptFunctionCallableContext& context, void*)
    {
        g_pd_sim_calls.fetch_add(1);
        // Only while his own Get Damage runs (set by its pre hook, cleared by its post hook). The
        // native hook's TheStack.Node() is not the calling Blueprint function (test dmg-dbg1: 0 of
        // 44792 calls), so the caller can't be read from the stack.
        if (!g_get_damage_fn || g_in_player_get_damage <= 0) return;
        g_pd_sim_in_gd.fetch_add(1);
        if (g_pd_first_in_gd.empty() && context.Context)
            g_pd_first_in_gd = context.Context->GetFullName() + (context.RESULT_DECL ? STR(" (result slot)") : STR(" (NO result slot)"));
        if (!context.Context || context.Context != g_pose.mesh || !g_pose_active.load() || !context.RESULT_DECL) return;
        g_pd_sim_on_mesh.fetch_add(1);
        if (!hsvr::config().player_takes_damage) return;
        *static_cast<bool*>(context.RESULT_DECL) = true;
        g_player_damage_overrides.fetch_add(1);
    }

    // Logs what each Get Damage on him did to his Health and Consciousness (once per hit).
    UObject* g_player_hit_pawn = nullptr;
    double g_player_hit_h0 = 0.0, g_player_hit_c0 = 0.0;
    std::wstring g_player_hit_what;
    void player_get_damage_pre(Unreal::UnrealScriptFunctionCallableContext& context, void*)
    {
        gc_sync();
        g_pd_gd_calls.fetch_add(1);
        g_player_hit_pawn = nullptr;
        UObject* pawn = context.Context;
        if (!pawn) return;
        if (g_pose_active.load())
        {
            if (pawn != g_pose.pawn) return;
        }
        else
        {
            // Unposed (pose_body=0, flat comparison runs): the player controller's pawn, logged only.
            UObject* player = nullptr;
            find_pawn_mesh(&player);
            if (pawn != player) return;
        }
        g_pd_gd_player.fetch_add(1);
        g_pd_pawn = pawn;
        ++g_in_player_get_damage;
        g_player_hit_pawn = pawn;
        // What hit him, for the "Player hit:" line.
        g_player_hit_what.clear();
        if (uint8_t* locals = context.TheStack.Locals(); locals && g_get_damage_fn)
        {
            double raw = -1.0, cut = -1.0;
            std::wstring bone = STR("?"), by = STR("?"), mesh = STR("?");
            for (FProperty* p : g_get_damage_fn->ForEachProperty())
            {
                std::wstring n = p->GetName();
                uint8_t* at = locals + p->GetOffset_Internal();
                bool dbl = p->GetClass().GetName() == STR("DoubleProperty");
                if (n == STR("Raw Damage") && dbl) raw = *reinterpret_cast<double*>(at);
                else if (n == STR("Cutting Power") && dbl) cut = *reinterpret_cast<double*>(at);
                else if (n == STR("Bone") && p->GetClass().GetName() == STR("NameProperty")) bone = reinterpret_cast<FName*>(at)->ToString();
                else if (n == STR("Hit By Component") || n == STR("Damaged Mesh"))
                {
                    UObject* o = *reinterpret_cast<UObject**>(at);
                    std::wstring s = STR("none");
                    if (o)
                    {
                        UObject* owner = nullptr;
                        Call oc(o, STR("GetOwner"));
                        if (oc.run()) owner = oc.object_result();
                        s = (owner ? owner->GetName() + STR(".") : std::wstring()) + o->GetName();
                    }
                    (n == STR("Damaged Mesh") ? mesh : by) = s;
                }
            }
            wchar_t buf[512];
            swprintf(buf, 512, L"bone %ls, raw %.0f, cut %.1f, by %ls, on %ls", bone.c_str(), raw, cut, by.c_str(), mesh.c_str());
            g_player_hit_what = buf;
        }
        g_player_hit_h0 = read_number_variable(pawn, STR("Health"));
        g_player_hit_c0 = read_number_variable(pawn, STR("Consciousness"));
    }
    void player_get_damage_post(Unreal::UnrealScriptFunctionCallableContext& context, void*)
    {
        if (g_in_player_get_damage > 0 && context.Context && context.Context == g_pd_pawn) --g_in_player_get_damage;
        UObject* pawn = g_player_hit_pawn;
        g_player_hit_pawn = nullptr;
        if (!pawn || context.Context != pawn) return;
        double h = read_number_variable(pawn, STR("Health")), c = read_number_variable(pawn, STR("Consciousness"));
        if (h == g_player_hit_h0 && c == g_player_hit_c0) return;
        HSVR_LOG("Player hit: health %.2f -> %.2f, consciousness %.2f -> %.2f (counted as the flat game: %d); %ls", g_player_hit_h0, h, g_player_hit_c0, c,
                 (int)hsvr::config().player_takes_damage, g_player_hit_what.c_str());
    }

    void install_player_damage(bool after_his_tick)
    {
        static bool installed = false;
        static double last_try = -10.0;
        double now = hsvr::now_seconds();
        // After his tick nothing of his Get Damage is running: the flag can never stay on.
        if (after_his_tick && g_in_player_get_damage != 0)
        {
            HSVR_LOG_EVERY(10.0, "Player damage: Get Damage flag was left at %d after his tick; cleared", g_in_player_get_damage);
            g_in_player_get_damage = 0;
        }
        if (installed)
        {
            // Every 10 s while anything changed: how far the checks get.
            static double next = 0.0;
            static uint64_t last_gd = 0;
            if (now < next || g_pd_gd_calls.load() == last_gd) return;
            next = now + 10.0;
            last_gd = g_pd_gd_calls.load();
            HSVR_LOG("Player damage: checks: Get Damage %llu calls (%llu on him); IsSimulatingPhysics %llu calls, %llu from Get Damage, %llu on his posed mesh, %llu "
                     "answered yes; first from Get Damage: %ls",
                     (unsigned long long)g_pd_gd_calls.load(), (unsigned long long)g_pd_gd_player.load(), (unsigned long long)g_pd_sim_calls.load(),
                     (unsigned long long)g_pd_sim_in_gd.load(), (unsigned long long)g_pd_sim_on_mesh.load(), (unsigned long long)g_player_damage_overrides.load(),
                     g_pd_first_in_gd.empty() ? STR("none") : g_pd_first_in_gd.c_str());
            return;
        }
        if (now - last_try < 2.0) return;
        last_try = now;
        UFunction* gd = UObjectGlobals::StaticFindObject<UFunction*>(nullptr, nullptr, STR("/Game/Character/Blueprints/Willie_BP.Willie_BP_C:Get Damage"));
        // The UFUNCTION is declared on SceneComponent (UE 5.4 SceneComponent.h); PrimitiveComponent and
        // SkeletalMeshComponent only override the C++ virtual, so there is no PrimitiveComponent one.
        UFunction* sim = UObjectGlobals::StaticFindObject<UFunction*>(nullptr, nullptr, STR("/Script/Engine.SceneComponent:IsSimulatingPhysics"));
        if (!sim) sim = UObjectGlobals::StaticFindObject<UFunction*>(nullptr, nullptr, STR("/Script/Engine.PrimitiveComponent:IsSimulatingPhysics"));
        if (!gd || !sim)
        {
            static int tries = 0;
            if (++tries == 5) HSVR_LOG("Player damage: not installed: Get Damage %s, IsSimulatingPhysics %s", gd ? "found" : "MISSING", sim ? "found" : "MISSING");
            return;
        }
        installed = true;
        g_get_damage_fn = gd;
        UObjectGlobals::RegisterHook(sim, [](Unreal::UnrealScriptFunctionCallableContext&, void*) {}, &player_sim_check_post, nullptr);
        UObjectGlobals::RegisterHook(gd, &player_get_damage_pre, &player_get_damage_post, nullptr);
        HSVR_LOG("Player damage: his Get Damage counts his posed body as simulating (player_takes_damage)");
    }

    // ---- His strength gains keep his body posed ----------------------------------------------------
    // When his banked training passes 0.01, the game's Event Gain Muscle reloads Muscle Rate and runs
    // Rescale Character, which turns his ragdoll back on (SetAllBodiesBelowSimulatePhysics, character_stats.md
    // §1). The pose check catches that within 0.5 s; these hooks switch it off right after either call on
    // him, so a strength gain mid-fight never lets his body drop for a moment.
    void muscle_gain_post(Unreal::UnrealScriptFunctionCallableContext& context, void* which)
    {
        if (!context.Context || context.Context != g_pose.pawn || !g_pose.mesh || !g_pose_active.load()) return;
        int was = is_simulating(g_pose.mesh, "pelvis");
        if (was == 1) set_simulate(g_pose.mesh, false);
        g_physics_watch_until = hsvr::now_seconds() + 1.5;
        HSVR_LOG("Strength: %s ran on him: Muscle Rate now %.4f, Mass Scale %.4f, physics %s", static_cast<const char*>(which),
                 read_number_variable(g_pose.pawn, STR("Muscle Rate")), read_number_variable(g_pose.pawn, STR("Mass Scale (Set in BP)")),
                 was == 1 ? "was switched on; switched off again" : "stayed off");
    }
    void install_muscle_hooks()
    {
        static bool installed = false;
        static double last_try = -10.0;
        if (installed) return;
        double now = hsvr::now_seconds();
        if (now - last_try < 2.0) return;
        last_try = now;
        UFunction* gain = UObjectGlobals::StaticFindObject<UFunction*>(nullptr, nullptr, STR("/Game/Character/Blueprints/Willie_BP.Willie_BP_C:Event Gain Muscle"));
        UFunction* rescale = UObjectGlobals::StaticFindObject<UFunction*>(nullptr, nullptr, STR("/Game/Character/Blueprints/Willie_BP.Willie_BP_C:Rescale Character"));
        if (!gain && !rescale)
        {
            static int tries = 0;
            if (++tries == 5) HSVR_LOG("Strength: Gain Muscle / Rescale Character not found; the pose check alone keeps physics off after a gain");
            return;
        }
        installed = true;
        static const char kGain[] = "Gain Muscle", kRescale[] = "Rescale Character";
        if (gain) UObjectGlobals::RegisterHook(gain, [](Unreal::UnrealScriptFunctionCallableContext&, void*) {}, &muscle_gain_post, (void*)kGain);
        if (rescale) UObjectGlobals::RegisterHook(rescale, [](Unreal::UnrealScriptFunctionCallableContext&, void*) {}, &muscle_gain_post, (void*)kRescale);
        HSVR_LOG("Strength: watching his strength gains (Gain Muscle %s, Rescale Character %s)", gain ? "hooked" : "MISSING", rescale ? "hooked" : "MISSING");
    }

    // ---- Blood at his own stumps ------------------------------------------------------------------
    // Dismember Function Delayed hides the cut-off bones on his mesh (HideBoneByName) and calls Spawn
    // Blood with the closest bone to the cut, often one of the cut-off ones (foot_r, neck_01). The
    // fountain (Blood_BP_P4) and running blood (RunningBlood_BP) are attached to that bone, which the
    // posed body keeps moving, so the blood floated where the limb would be. Each new one on a
    // hidden bone is moved to the stump (the top hidden bone's joint) and attached to the visible
    // parent bone there.
    void stump_blood_tick(UObject* pawn)
    {
        using namespace hsvr;
        static std::unordered_set<UObject*> done, logged;
        static std::unordered_map<UObject*, double> first_seen;
        static UObject* last_pawn = nullptr;
        static bool tracked = on_freed([] {
            for (auto* set : {&done, &logged})
                for (auto it = set->begin(); it != set->end();)
                    it = gone(*it) ? set->erase(it) : std::next(it);
            for (auto it = first_seen.begin(); it != first_seen.end();)
                it = gone(it->first) ? first_seen.erase(it) : std::next(it);
            if (gone(last_pawn)) last_pawn = nullptr;
        });
        (void)tracked;
        if (pawn != last_pawn)
        {
            logged.clear();
            first_seen.clear();
            last_pawn = pawn;
            done.clear();
        }
        UObject* mesh = g_pose.mesh;
        if (!pawn || !mesh || !config().player_stump_blood) return;
        // For 5 s after a move, every 0.5 s: how far each moved blood is from its stump bone (it
        // should stay put on the stump while the posed hand or foot moves on).
        struct Follow
        {
            UObject* comp;
            FName bone;
            double until, next;
        };
        static std::vector<Follow> follows;
        static bool follows_tracked = on_freed([] {
            follows.erase(std::remove_if(follows.begin(), follows.end(), [](const Follow& f) { return gone(f.comp); }), follows.end());
        });
        (void)follows_tracked;
        double now_s = now_seconds();
        for (auto it = follows.begin(); it != follows.end();)
        {
            if (now_s > it->until || gone(it->comp))
            {
                it = follows.erase(it);
                continue;
            }
            if (now_s >= it->next)
            {
                it->next = now_s + 0.5;
                Call wl(it->comp, STR("K2_GetComponentLocation"));
                wl.run();
                Vec3 at_bone = socket_location(mesh, it->bone);
                HSVR_LOG("Stump blood: %ls is %.1f cm from %ls (bone at %.0f %.0f %.0f), hand_l %.0f cm and foot_r %.0f cm from it", it->comp->GetName().c_str(),
                         length(wl.vec() - at_bone), it->bone.ToString().c_str(), at_bone.x, at_bone.y, at_bone.z,
                         length(socket_location(mesh, FName(STR("hand_l"), FNAME_Add)) - at_bone), length(socket_location(mesh, FName(STR("foot_r"), FNAME_Add)) - at_bone));
            }
            ++it;
        }
        for (const TCHAR* list : {STR("Attached Blood Emitters"), STR("Running Blood Array")})
        {
            FProperty* p = prop_chain(pawn, list);
            if (!p || p->GetClass().GetName() != STR("ArrayProperty")) continue;
            FProperty* inner = static_cast<FArrayProperty*>(p)->GetInner();
            if (!inner || inner->GetClass().GetName() != STR("ObjectProperty")) continue;
            struct RawArray
            {
                UObject** data;
                int32_t num;
                int32_t max;
            };
            auto* arr = reinterpret_cast<RawArray*>(reinterpret_cast<uint8_t*>(pawn) + p->GetOffset_Internal());
            if (!arr->data || arr->num <= 0 || arr->num > arr->max) continue;
            for (int32_t i = 0; i < arr->num; ++i)
            {
                UObject* item = arr->data[i];
                if (!item || done.count(item)) continue;
                // Checked every tick for 3 s after it first shows up (the cut may hide its bone a
                // little after the blood spawns), then left alone.
                double& first = first_seen[item];
                if (first <= 0.0) first = now_s;
                if (now_s - first > 3.0)
                {
                    done.insert(item);
                    continue;
                }
                UObject* comp = item;
                if (is_a(item, STR("Actor")))
                {
                    Call root(item, STR("K2_GetRootComponent"));
                    root.run();
                    comp = root.object_result();
                }
                if (!comp || !is_a(comp, STR("SceneComponent")))
                {
                    done.insert(item);
                    continue;
                }
                Call ap(comp, STR("GetAttachParent"));
                ap.run();
                UObject* parent = ap.object_result();
                Call sn(comp, STR("GetAttachSocketName"));
                sn.run();
                FProperty* rp = sn.param(STR("ReturnValue"));
                FName bone = rp ? *reinterpret_cast<FName*>(sn.buffer.data() + rp->GetOffset_Internal()) : FName(STR("None"), FNAME_Add);
                auto hidden = [&](FName b) {
                    Call h(mesh, STR("IsBoneHiddenByName"));
                    h.name(STR("BoneName"), b);
                    h.run();
                    FProperty* r = h.param(STR("ReturnValue"));
                    return r && read_param_bool(h.buffer.data(), r);
                };
                bool on_mesh = parent == mesh;
                bool is_hidden = on_mesh && hidden(bone);
                if (!logged.count(item))
                {
                    logged.insert(item);
                    HSVR_LOG("Stump blood: %ls (%ls) is on %ls:%ls, bone hidden %d", item->GetName().c_str(), list, parent ? parent->GetName().c_str() : STR("nothing"),
                             bone.ToString().c_str(), (int)is_hidden);
                }
                if (!on_mesh)
                {
                    done.insert(item); // on the cut-off piece or something else: not his stump
                    continue;
                }
                if (!is_hidden) continue;
                // Up the chain to the first visible bone; the last hidden one is the stump's joint.
                FName top = bone, at = parent_bone(mesh, bone);
                int guard = 0;
                while (guard++ < 40 && at.ToString() != STR("None") && hidden(at))
                {
                    top = at;
                    at = parent_bone(mesh, at);
                }
                if (at.ToString() == STR("None")) continue;
                Vec3 stump = socket_location(mesh, top);
                Call wl(comp, STR("K2_GetComponentLocation"));
                wl.run();
                Vec3 was = wl.vec();
                Call mv(comp, STR("K2_SetWorldLocation"));
                mv.three(STR("NewLocation"), stump.x, stump.y, stump.z);
                mv.flag(STR("bTeleport"), true);
                mv.run();
                Call at_call(comp, STR("K2_AttachToComponent"));
                at_call.object(STR("Parent"), mesh);
                at_call.name(STR("SocketName"), at);
                at_call.byte(STR("LocationRule"), 1); // KeepWorld
                at_call.byte(STR("RotationRule"), 1);
                at_call.byte(STR("ScaleRule"), 1);
                at_call.flag(STR("bWeldSimulatedBodies"), false);
                at_call.run();
                HSVR_LOG("Stump blood: %ls on cut-off bone %ls moved %.0f cm to the stump at %ls (attached to %ls, %.0f cm from its origin)", item->GetName().c_str(),
                         bone.ToString().c_str(), length(stump - was), top.ToString().c_str(), at.ToString().c_str(), length(stump - socket_location(mesh, at)));
                follows.push_back({comp, top, now_s + 5.0, now_s + 0.5});
                done.insert(item);
            }
        }
    }

    // ---- Test only: cut off one of his own limbs the way a stuck blade does -----------------------
    // dev_script "hsvr.player_dismember lowerarm_l|calf_r": Constraint_Weapon_Stuck_BP calls his
    // Dismember Function Initiate(Mesh, Part, Farthest Overlap Marker, Overlapped Markers, VP box,
    // VP box, Weapon, Bone), then 0.1 s later Dismember Function Delayed with the same markers. Here
    // the markers are his own "DM Sphere <part> n" spheres in the middle of the part, the two VP boxes
    // are the spheres either side of them, and the "weapon" is his capsule (only used to switch off
    // collision with the cut-off piece).
    struct DismemberTest
    {
        bool pending = false;
        double at = 0.0;
        UObject* pawn = nullptr;
        uint8_t part = 0;
        FName bone;
        std::vector<UObject*> markers;
        UObject* attach = nullptr;
        UObject* vp1 = nullptr;
        UObject* vp2 = nullptr;
        UObject* weapon = nullptr;
    } g_dismember_test;

    void put_object_array(Call& c, const TCHAR* name, std::vector<UObject*>* items)
    {
        struct RawArray
        {
            UObject** data;
            int32_t num;
            int32_t max;
        };
        if (FProperty* p = c.param(name))
        {
            auto* arr = reinterpret_cast<RawArray*>(c.buffer.data() + p->GetOffset_Internal());
            arr->data = items ? items->data() : nullptr;
            arr->num = arr->max = items ? (int32_t)items->size() : 0;
        }
    }

    void dismember_call(const TCHAR* function, bool initiate)
    {
        DismemberTest& t = g_dismember_test;
        Call c(t.pawn, function);
        if (!c.fn)
        {
            HSVR_LOG("Script: hsvr.player_dismember: no %ls on his Willie", function);
            return;
        }
        c.object(STR("Master Mesh"), g_pose.mesh);
        c.byte(STR("Dismembered Part"), t.part);
        c.object(STR("Attach Marker"), t.attach);
        put_object_array(c, STR("Overlapped Markers"), &t.markers);
        c.object(STR("VP Box Collision 1"), t.vp1);
        c.object(STR("VP Box Collision 2"), t.vp2);
        c.object(STR("Dismember Weapon"), t.weapon);
        if (initiate) c.name(STR("Dismember Bone Name"), t.bone);
        c.run();
        // The array points at our own storage: take it back out of the buffer.
        put_object_array(c, STR("Overlapped Markers"), nullptr);
        UObject* cut = object_property(t.pawn, STR("Currently Dismembered Mesh"));
        HSVR_LOG("Script: hsvr.player_dismember: %ls(part %d, bone %ls, %d markers) called; Health %.1f, Currently Dismembered Mesh %ls", function, (int)t.part,
                 t.bone.ToString().c_str(), (int)t.markers.size(), read_number_variable(t.pawn, STR("Health")), cut ? cut->GetName().c_str() : STR("none"));
    }

    void player_dismember_start(const std::string& arg)
    {
        DismemberTest& t = g_dismember_test;
        UObject* pawn = g_pose.pawn;
        if (!pawn || !g_pose.mesh)
        {
            HSVR_LOG("Script: hsvr.player_dismember: no posed player");
            return;
        }
        const TCHAR* prefix = nullptr;
        int first = 1, count = 0;
        if (arg == "lowerarm_l")
        {
            t.part = 7; // Spawn Bone lowerarm_l (Dismember Function Delayed @1472)
            prefix = STR("DM Sphere Loweararm_L "); // sic: the game's spelling; numbered 13-25
            first = 13;
            count = 13;
        }
        else if (arg == "foot_r")
        {
            t.part = 11; // Spawn Bone foot_r, Hide Bone Local None (the cut Matthew had at 392 s)
            prefix = STR("DM Sphere Foot_R "); // 1-10
            count = 10;
        }
        else if (arg == "neck")
        {
            t.part = 0; // Spawn Bone neck_01, Hide Bone Local None (beheading)
            prefix = STR("DM Sphere Neck_01 "); // 1-6
            count = 6;
        }
        else if (arg == "calf_r")
        {
            t.part = 10; // Spawn Bone calf_r
            prefix = STR("DM Sphere Calf_R "); // 1-20
            count = 20;
        }
        else
        {
            HSVR_LOG("Script: hsvr.player_dismember: use lowerarm_l, calf_r, foot_r or neck (got '%s')", arg.c_str());
            return;
        }
        auto marker = [&](int i) { return object_property(pawn, (std::wstring(prefix) + std::to_wstring(i)).c_str()); };
        int mid = first + count / 2;
        t.markers.clear();
        for (int i : {mid, mid + 1})
            if (UObject* m = marker(i)) t.markers.push_back(m);
        t.attach = marker(mid + 1);
        t.vp1 = marker(mid - 1);
        t.vp2 = marker(mid + 2);
        t.weapon = object_property(pawn, STR("CapsuleComponent"));
        t.bone = FName(std::wstring(arg.begin(), arg.end()).c_str(), FNAME_Add);
        t.pawn = pawn;
        if (t.markers.size() < 2 || !t.attach || !t.vp1 || !t.vp2 || !t.weapon)
        {
            HSVR_LOG("Script: hsvr.player_dismember: markers missing (%d found, attach %d, boxes %d %d, capsule %d)", (int)t.markers.size(), t.attach != nullptr,
                     t.vp1 != nullptr, t.vp2 != nullptr, t.weapon != nullptr);
            return;
        }
        dismember_call(STR("Dismember Function Initiate"), true);
        t.pending = true;
        t.at = hsvr::now_seconds() + 0.1;
    }

    void player_dismember_tick(UObject* pawn)
    {
        DismemberTest& t = g_dismember_test;
        if (!t.pending || hsvr::now_seconds() < t.at) return;
        t.pending = false;
        if (pawn != t.pawn || gone(t.pawn)) return;
        for (UObject* m : t.markers)
            if (gone(m)) return;
        dismember_call(STR("Dismember Function Delayed"), false);
    }

    struct ElbowState
    {
        bool have = false;
        hsvr::Vec3 last[3];
        double last_t = 0.0;
        hsvr::Vec3 vel[3];
        std::map<UObject*, double> touching_until; // a hit needs the elbow to leave him first
        double last_hit = -10.0;
    };
    ElbowState g_elbow[2];

    void elbow_tick(UObject* pawn)
    {
        using namespace hsvr;
        Config cfg = config();
        install_punch_watch();
        if (!cfg.pose_elbow_strikes || !pawn || !g_pose.mesh || !g_pose_active.load()) return;
        static std::vector<UObject*> foes;
        static double found_at = -10.0;
        // Willies the game frees (a removed corpse) leave the list and the touch marks at once
        // (gc_sync); a new list is also taken after every garbage collection (crash 2026-11-20 08:13:
        // this list still held a Willie the test room had removed and the game had freed).
        static bool tracked = on_freed([] {
            size_t before = foes.size();
            erase_gone(foes);
            if (foes.size() != before) HSVR_LOG("Elbow: %d freed Willie(s) taken off the foe list", (int)(before - foes.size()));
            for (ElbowState& e : g_elbow) erase_gone_keys(e.touching_until);
        });
        static uint64_t epoch = 0;
        double now = now_seconds();
        if (now - found_at > 1.0 || epoch != g_gc_epoch)
        {
            found_at = now;
            epoch = g_gc_epoch;
            foes.clear();
            std::vector<UObject*> all;
            UObjectGlobals::FindAllOf(STR("Willie_BP_C"), all);
            int skipped = 0;
            for (UObject* w : all)
                if (w && w != pawn && w->GetName().rfind(STR("Default__"), 0) != 0)
                {
                    if (object_alive(w)) foes.push_back(w);
                    else ++skipped;
                }
            static int skipped_logged = 0, count_logged = -1;
            if (skipped != skipped_logged || (int)foes.size() != count_logged)
                HSVR_LOG("Elbow: %d foe(s) on the list, %d Willie(s) being destroyed left off", (int)foes.size(), skipped);
            skipped_logged = skipped;
            count_logged = (int)foes.size();
        }
        for (int side = 0; side < 2; ++side)
        {
            ElbowState& E = g_elbow[side];
            std::string sx = side == 0 ? "_l" : "_r";
            Vec3 elbow = socket_location(g_pose.mesh, bone_fname("lowerarm" + sx));
            Vec3 hand = socket_location(g_pose.mesh, bone_fname("hand" + sx));
            Vec3 shoulder = socket_location(g_pose.mesh, bone_fname("upperarm" + sx));
            Vec3 pts[3] = {elbow, elbow + normalized(hand - elbow) * 7.0, elbow + normalized(shoulder - elbow) * 7.0};
            double dt = now - E.last_t;
            if (E.have && dt > 1e-4 && dt < 0.1)
                for (int i = 0; i < 3; ++i) E.vel[i] = E.vel[i] + ((pts[i] - E.last[i]) * (1.0 / dt) - E.vel[i]) * 0.5;
            else
                for (int i = 0; i < 3; ++i) E.vel[i] = {};
            for (int i = 0; i < 3; ++i) E.last[i] = pts[i];
            E.last_t = now;
            E.have = true;
            // Fist speed: the hand speed that gives the game's Aim Swing Speed 30 (the fist's spawn rule).
            double lo = cfg.pose_swing_speed_lo, hi = (std::max)(lo + 0.1, cfg.pose_swing_speed_hi);
            double min_speed = (lo + (hi - lo) * cfg.pose_elbow_min_ass / 75.0) * 100.0;
            for (UObject* w : foes)
            {
                if (!object_alive(w)) continue; // destroyed this second (still readable, not a fighter)
                UObject* mesh = object_property(w, STR("Mesh"));
                if (!mesh) continue;
                if (length(component_location(mesh) - elbow) > 200.0) continue;
                double best_d = 1e9;
                int best_i = -1;
                Vec3 best_pt;
                FName best_bone;
                for (int i = 0; i < 3; ++i)
                {
                    // His nearest physics body first: GetClosestPointOnCollision with no bone measures only
                    // his root body (the pelvis), so test 12 never saw the elbow reach his head.
                    Call fb(mesh, STR("FindClosestBone_K2"));
                    fb.three(STR("TestLocation"), pts[i].x, pts[i].y, pts[i].z);
                    fb.number(STR("IgnoreScale"), 0.0);
                    fb.flag(STR("bRequirePhysicsAsset"), true);
                    fb.run();
                    FProperty* rp = fb.param(STR("ReturnValue"));
                    if (!rp) continue;
                    FName bone = *reinterpret_cast<FName*>(fb.buffer.data() + rp->GetOffset_Internal());
                    Call cp(mesh, STR("GetClosestPointOnCollision"));
                    cp.three(STR("Point"), pts[i].x, pts[i].y, pts[i].z);
                    cp.name(STR("BoneName"), bone);
                    cp.run();
                    double d = cp.number();
                    if (d < 0.0 || d >= best_d) continue;
                    best_d = d, best_i = i, best_bone = bone;
                    best_pt = d > 0.0 ? cp.vec(STR("OutPointOnBody")) : pts[i];
                }
                static double near_log = -10.0;
                if (best_i >= 0 && best_d < 30.0 && now - near_log >= 1.0)
                {
                    near_log = now;
                    HSVR_LOG("Elbow: %s arm near %ls: %s %.1f cm from his %ls, speed %.0f cm/s (needs %.0f), in contact since last hit %d",
                             side == 0 ? "left" : "right", w->GetName().c_str(), best_i == 0 ? "elbow" : best_i == 1 ? "forearm" : "upper arm", best_d,
                             best_bone.ToString().c_str(), length(E.vel[best_i]), min_speed, (int)(E.touching_until[w] > 0.0));
                }
                double& until = E.touching_until[w];
                if (best_i < 0 || best_d > cfg.pose_elbow_radius_cm)
                {
                    if (best_i >= 0 && best_d > cfg.pose_elbow_radius_cm + 3.0) until = 0.0;
                    continue;
                }
                if (until > 0.0) continue; // still in contact since the last hit
                Vec3 v = E.vel[best_i];
                Vec3 into = best_d > 0.5 ? normalized(best_pt - pts[best_i]) : normalized(v);
                double closing = dot(v, into);
                if (closing < min_speed) continue;
                until = 1.0;
                if (now - E.last_hit < 0.1) continue; // the game's own limb-hit cooldown
                E.last_hit = now;
                // The punch's numbers (learnt from your fist hits, else the defaults).
                bool learnt = g_punch.n >= cfg.pose_elbow_learn_min_hits;
                double rig = learnt ? g_punch.rigidity : cfg.pose_elbow_rigidity;
                double cutp = learnt ? g_punch.cut : cfg.pose_elbow_cut;
                double ipv = learnt ? g_punch.impulse_per_v : cfg.pose_elbow_impulse_per_v;
                double vps = learnt && g_punch.v_per_speed > 0.0 ? g_punch.v_per_speed : cfg.pose_elbow_velocity_scale;
                Vec3 hv = v * vps;
                Vec3 hi_v = into * (length(hv) * ipv);
                Vec3 normal = into * -1.0; // his surface, facing the elbow
                Call dc(w, STR("Deal Complex Damage"));
                if (!dc.fn)
                {
                    HSVR_LOG_EVERY(10.0, "Elbow: %ls has no Deal Complex Damage", w->GetName().c_str());
                    continue;
                }
                uint8_t* base = dc.buffer.data();
                dc.object(STR("Hit Component"), mesh);
                dc.object(STR("Collided Component"), g_pose.mesh);
                dc.name(STR("Hit Bone"), best_bone);
                dc.three(STR("Location"), best_pt.x, best_pt.y, best_pt.z);
                dc.three(STR("Normal"), normal.x, normal.y, normal.z);
                dc.three(STR("Hit Velocity"), hv.x, hv.y, hv.z);
                dc.three(STR("Hit Impulse"), hi_v.x, hi_v.y, hi_v.z);
                auto num = [&](const TCHAR* n, double x) { if (FProperty* p = dc.param(n)) write_param_number(base, p, x); };
                auto flag = [&](const TCHAR* n, bool x) { if (FProperty* p = dc.param(n)) write_param_bool(base, p, x); };
                num(STR("Cutting Power"), cutp);
                num(STR("Stab Rate"), learnt ? g_punch.stab : 0.0);
                num(STR("Rigidity"), rig);
                num(STR("Blunt Destruction Int"), g_punch.have_template ? g_punch.blunt_int : 1.0);
                num(STR("Kick Power"), g_punch.have_template ? g_punch.kick : 1.0);
                num(STR("Draw Cut"), 0.0);
                flag(STR("Lower Threshold In"), g_punch.have_template && g_punch.lower_threshold);
                flag(STR("Damage Parent Bone?"), g_punch.have_template && g_punch.damage_parent);
                flag(STR("Extra High Velocity"), g_punch.have_template && g_punch.extra_high);
                double h0 = read_number_variable(w, STR("Health")), c0 = read_number_variable(w, STR("Consciousness"));
                g_elbow_calling.store(true);
                dc.run();
                g_elbow_calling.store(false);
                double dmg = -1.0, rig_out = -1.0;
                if (FProperty* p = dc.param(STR("Damage Out"))) dmg = read_param_number(base, p);
                if (FProperty* p = dc.param(STR("Rigidity Out"))) rig_out = read_param_number(base, p);
                controllers_buzz(side, 0.5f);
                const char* where[3] = {"elbow", "forearm", "upper arm"};
                HSVR_LOG("Elbow: %s %s hit %ls %ls at %.0f cm/s (%.1f cm off): velocity %.0f, impulse %.0f, rigidity %.2f, cut %.2f (%s); damage out %.1f, rigidity out %.2f; "
                         "health %.1f -> %.1f, consciousness %.0f -> %.0f",
                         side == 0 ? "left" : "right", where[best_i], w->GetName().c_str(), best_bone.ToString().c_str(), closing, best_d, length(hv), length(hi_v), rig, cutp,
                         learnt ? "learnt from your punches" : "defaults", dmg, rig_out, h0, read_number_variable(w, STR("Health")), c0,
                         read_number_variable(w, STR("Consciousness")));
            }
        }
    }

    // pose_grab_body_no_slip: right before Willie's tick (where the slip rule runs), the held hand's
    // 'Hand Block Drop' is set while his grip strength is above pose_grab_body_slip_below_t.
    bool g_body_blocking[2] = {false, false};
    // A loose object the mod itself holds (grab_drive: the game's joint is set free): the game's slip
    // rule reads that free joint and let go 0.5 s in (as soon as its own Hand Block Drop ran out), so
    // it is held off the same way while the mod carries the thing. Set each tick by grab_drive.
    double g_drive_held_until[2] = {-1.0, -1.0};
    void body_grab_before_tick(UObject* pawn)
    {
        hsvr::Config cfg = hsvr::config();
        for (int side = 0; side < 2; ++side)
        {
            const BodyGrab& b = g_body_grab[side];
            bool want = (cfg.pose_grab_body_no_slip && b.on && b.grip_t >= cfg.pose_grab_body_slip_below_t) || hsvr::now_seconds() < g_drive_held_until[side];
            const TCHAR* flag = side == 0 ? STR("L Hand Block Drop") : STR("R Hand Block Drop");
            if (want) set_bool_property(pawn, flag, true);
            else if (g_body_blocking[side]) set_bool_property(pawn, flag, false);
            if (want != g_body_blocking[side])
                HSVR_LOG("Body grab: %s hand's slip rule %s (his grip T %.0f)", side == 0 ? "left" : "right", want ? "held off" : "back to the game's", b.grip_t);
            g_body_blocking[side] = want;
        }
    }

    void body_grab_tick(UObject* pawn, const hsvr::Config& cfg_in)
    {
        using namespace hsvr;
        Config cfg = cfg_in;
        if (g_body_hold_test.load() != -99) cfg.pose_grab_body_hold = g_body_hold_test.load();
        UObject* mesh = object_property(pawn, STR("Mesh"));
        double now = now_seconds();
        for (int side = 0; side < 2; ++side)
        {
            bool L = side == 0;
            const char* hand = L ? "left" : "right";
            BodyGrab& b = g_body_grab[side];
            ObjectGrab& og = g_object_grab[side];
            bool grabbed = bool_property(pawn, L ? STR("Grabbed L") : STR("Grabbed R"));
            bool body = grabbed && og.component && og.character;
            if (!body)
            {
                if (b.on)
                    HSVR_LOG("Body grab: %s hand let go after %.2f s (Grabbed %d); last: joint force %.0f / torque %.0f, release rate %.2f, stretch %.1f cm, strangle %.2f, choke %.3f, consciousness %.0f",
                             hand, now - b.since, (int)grabbed, b.force, b.torque, b.release_rate, b.stretch, b.strangle, b.choke, b.conscious);
                b = BodyGrab{};
                continue;
            }
            Vec3 hb = mesh ? socket_location(mesh, bone_fname(L ? "hand_l" : "hand_r")) : Vec3{};
            // A hand riding the held body (hand_on_grab) is on it: the stretch is your hand's.
            if (hand_rides_grab(side) && g_pose.hand_valid[side]) hb = g_pose.target[side];
            if (!b.on)
            {
                b.on = true;
                b.since = now;
                b.comp = og.component;
                b.bone = og.bone;
                Call oc(og.component, STR("GetOwner"));
                oc.run();
                b.victim = oc.object_result();
                b.rest = length(hb - socket_location(b.comp, b.bone));
                b.ctl0_ok = g_pose.hand_valid[side];
                if (b.ctl0_ok) b.ctl0 = g_pose.hand_rot[side], b.ctl0_yaw = g_pose.ctl_frame_yaw[side];
                HSVR_LOG("Body grab: %s hand holds %ls bone %ls (%.1f cm from the hand bone)", hand, b.victim ? b.victim->GetName().c_str() : STR("?"),
                         b.bone.ToString().c_str(), b.rest);
            }
            b.stretch = length(hb - socket_location(b.comp, b.bone)) - b.rest;
            UObject* joint = object_property(pawn, L ? STR("PhysicsConstraint L Hand") : STR("PhysicsConstraint R Hand"));
            if (joint)
            {
                Call f(joint, STR("GetConstraintForce"));
                if (f.run())
                {
                    b.force = length(f.vec(STR("OutLinearForce")));
                    b.torque = length(f.vec(STR("OutAngularForce")));
                }
            }
            b.release_rate = read_number_variable(pawn, L ? STR("Grab L Release Rate") : STR("Grab R Release Rate"));
            if (b.victim)
            {
                b.strangle = read_number_variable(b.victim, STR("Strangle Rate"));
                b.choke = read_number_variable(b.victim, STR("Choke To Death Rate"));
                b.conscious = read_number_variable(b.victim, STR("Consciousness"));
            }
            // His grip strength as the game's slip rule computes it (grab_and_mass.md, UG @361596-362128;
            // the gauntlet/Mordhau/zombie/lawnmower factors left out): T = Arm Tonus x All Body Tonus x
            // Consciousness/100 x MRC(Pain, 5..10 -> 1..2) x max(MRU(Muscle Rate, 0..1 -> 1..1.5), 0.5),
            // then max(T, Arm Health). It slips while the joint force is above T.
            double tonus = read_number_variable(pawn, L ? STR("Arm L Tonus") : STR("Arm R Tonus"));
            double body_tonus = read_number_variable(pawn, STR("All Body Tonus"));
            double my_conscious = read_number_variable(pawn, STR("Consciousness"));
            double pain = read_number_variable(pawn, STR("Pain"));
            double muscle = read_number_variable(pawn, STR("Muscle Rate"));
            double arm_health = read_number_variable(pawn, L ? STR("Arm_L Health") : STR("Arm_R Health"));
            double pain_k = 1.0 + (std::max)(0.0, (std::min)(1.0, (pain - 5.0) / 5.0));
            double t_est = tonus * body_tonus * my_conscious * 0.01 * pain_k * (std::max)(1.0 + 0.5 * muscle, 0.5);
            t_est = (std::max)(t_est, arm_health);
            b.grip_t = t_est;
            if (cfg.pose_grab_body_hold == 1 && !b.softened && joint && now - b.since > 0.25)
            {
                double cap = body_spring_cap(cfg, b.grip_t);
                body_spring_joint(joint, cfg, cap);
                b.softened = true;
                HSVR_LOG("Body grab: %s hand's joint made a spring (%.0f, %.0f, cap %.0f for his grip T %.0f)", hand, cfg.pose_grab_body_spring, cfg.pose_grab_body_damper, cap, b.grip_t);
            }
            if ((cfg.pose_grab_body_hold == 1 || cfg.pose_grab_body_no_slip) && b.stretch > cfg.pose_grab_body_let_go_cm)
            {
                if (b.far_since < 0.0) b.far_since = now;
                else if (now - b.far_since > 0.3)
                {
                    HSVR_LOG("Body grab: %s hand pulled %.1f cm off its hold for 0.3 s: lets go", hand, b.stretch);
                    release_object(side, pawn);
                    continue;
                }
            }
            else
                b.far_since = -1.0;
            if (cfg.log_body_grab && now - b.last_log >= 0.1)
            {
                b.last_log = now;
                double vs = 0.0;
                if (b.victim)
                {
                    Call v(b.victim, STR("GetVelocity"));
                    if (v.run()) vs = length(v.vec());
                }
                // The slip rule's gates (UG @360189-362402): it runs only when all of these allow it.
                HSVR_LOG("Body grab: %s %.2f s: his grip T~%.0f (arm tonus %.2f, body tonus %.2f, consciousness %.0f, pain %.1f, muscle %.2f, arm health %.0f); gates: invulnerable %d, dress-up %d, block drop %d, two-handed %d, soft not attached %d, sheathing %d, unsheathing %d",
                         hand, now - b.since, b.grip_t, tonus, body_tonus, my_conscious, pain, muscle, arm_health, (int)bool_property(pawn, STR("Invulnerable")),
                         (int)bool_property(pawn, STR("DressUp")), (int)bool_property(pawn, L ? STR("L Hand Block Drop") : STR("R Hand Block Drop")),
                         (int)bool_property(pawn, L ? STR("L Two Handed Grip") : STR("R Two Handed Grip")),
                         (int)bool_property(pawn, L ? STR("L Hand Soft Not Attached") : STR("R Hand Soft Not Attached")),
                         (int)bool_property(pawn, L ? STR("L Weapon Sheathing") : STR("R Weapon Sheathing")),
                         (int)bool_property(pawn, L ? STR("Weapon UnSheathing L") : STR("Weapon UnSheathing R")));
                HSVR_LOG("Body grab: %s %.2f s: joint force %.0f / torque %.0f, release rate %.2f, stretch %.1f cm; victim strangle %.2f, choke %.3f, consciousness %.0f, throat force %.0f, being grabbed %d, moving %.0f cm/s",
                         hand, now - b.since, b.force, b.torque, b.release_rate, b.stretch, b.strangle, b.choke, b.conscious,
                         b.victim ? read_number_variable(b.victim, L ? STR("Grabbed Throat Constraint Force L") : STR("Grabbed Throat Constraint Force R")) : -1.0,
                         b.victim ? (int)bool_property(b.victim, STR("Being Grabbed")) : -1, vs);
            }
        }
    }

    // ---- Fists from your real hand ---------------------------------------------------------------
    // ---- Fingers from the real hand (Matthew 2026-11-19) ----------------------------------------
    // ABP_Willie has no finger nodes (its 22 end-of-graph Modify Bone nodes are all the arms/head),
    // so the fingers are written where his visible body takes its pose: CharacterMesh0's ABP_CopyPose1
    // copies the DriverSkeleton through a Copy Pose From Mesh node, whose PreUpdate (game thread, right
    // before BlueprintUpdateAnimation) snapshots the driver's component-space bones into the node's
    // SourceMeshTransformArray; the worker evaluation later turns each into a local transform against
    // its parent's snapshot (finger_pose_research.md section 3). So after that update the mod turns
    // each finger joint, parent first, in that snapshot. Head, armour and gore copy CharacterMesh0,
    // so gauntlets follow. Curl per joint at a full curl: the VR framework's table (ik/fingers.rs).
    // The bend axis is found from the hand's own geometry (finger direction x palm normal), not
    // assumed from the bone axes, and checked by sign each time.
    struct XForm96
    {
        double qx, qy, qz, qw;
        double tx, ty, tz, tpad;
        double sx, sy, sz, spad;
    };
    static_assert(sizeof(XForm96) == 96, "FTransform (double) is 96 bytes in UE 5.4");
    struct XFormArray
    {
        XForm96* data;
        int32_t num;
        int32_t max;
    };

    struct FingerRig
    {
        UObject* instance = nullptr; // ABP_CopyPose1 on CharacterMesh0
        UObject* driver = nullptr;
        bool looked = false;
        bool ok = false;
        int node_offset = -1;  // the copy node inside the anim instance
        int array_offset = -1; // SourceMeshTransformArray inside the node
        int bone_count = 0;
        int hand[2] = {-1, -1};
        int arm[2][2] = {{-1, -1}, {-1, -1}}; // [side][upperarm, lowerarm]
        std::vector<int> arm_sub[2][3];         // [side][upperarm, lowerarm, hand]: it and all below it
        int chain[2][5][3]; // [side][thumb..pinky][_01.._03]
        std::vector<int> parent;
            std::vector<int> subtree[2][5][3];           // bone and all its descendants
        double found_at = -1.0;
        int tries = 0;
        double next_try = 0.0;
    };
